```php
<?php

class PasswordUtility {
    private static $defaultCharacterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
    private static $defaultHashAlgorithm = 'bcrypt';
    private static $defaultSaltLength = 22;

    public static function generateRandomString($length, $characterSet = null) {
        if ($length <= 0 || empty($characterSet)) {
            throw new InvalidArgumentException('Invalid length or character set');
        }

        $characterSet = self::ensureCharacterSetIsValid($characterSet);
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characterSet[random_int(0, strlen($characterSet) - 1)];
        }

        return $randomString;
    }

    public static function hashPassword($password, $salt = null, $rounds = 4) {
        if (empty($password)) {
            throw new InvalidArgumentException('Empty password');
        }

        if ($salt === null) {
            $salt = self::generateRandomString(self::$defaultSaltLength);
        }

        if (!in_array(self::$defaultHashAlgorithm, hash_algos())) {
            throw new InvalidArgumentException('Unsupported hash algorithm');
        }

        return self::$defaultHashAlgorithm . '$rounds=' . $rounds . '$' . self::$defaultCharacterSet . '$' . $salt . '$' . hash(self::$defaultHashAlgorithm, $password . $salt);
    }

    private static function ensureCharacterSetIsValid($characterSet) {
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\da-zA-Z]).+$/', $characterSet)) {
            throw new InvalidArgumentException('Character set must include at least one uppercase letter, one lowercase letter, one digit, and one special character');
        }

        return $characterSet;
    }
}

// Example usage:
try {
    $length = 16;
    $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
    $rounds = 12;

    $randomString = PasswordUtility::generateRandomString($length, $characterSet);
    $hashedPassword = PasswordUtility::hashPassword('your_password_here', null, $rounds);

    echo "Random String: " . $randomString . PHP_EOL;
    echo "Hashed Password: " . $hashedPassword . PHP_EOL;
} catch (InvalidArgumentException $e) {
    echo "Error: " . $e->getMessage() . PHP_EOL;
}
?>
