#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ctype.h>

char* validate_and_adjust_path(const char* path, int max_buffer_size, bool is_absolute, char* error_message) {
    size_t path_length = strlen(path);
    if (path_length > max_buffer_size - 1) {
        strcpy(error_message, "Path exceeds maximum buffer size.");
        return NULL;
    }

    char* full_path = malloc(max_buffer_size * sizeof(char));
    if (!full_path) {
        strcpy(error_message, "Memory allocation failed.");
        return NULL;
    }

    if (is_absolute || path[0] == '/') {
        snprintf(full_path, max_buffer_size, "%s", path);
    } else {
        char cwd[max_buffer_size];
        if (getcwd(cwd, sizeof(cwd)) != NULL) {
            snprintf(full_path, max_buffer_size, "%s/%s", cwd, path);
        } else {
            strcpy(error_message, "Failed to get current working directory.");
            free(full_path);
            return NULL;
        }
    }

    for (size_t i = 0; full_path[i]; ++i) {
        if (full_path[i] == '~') {
            char* home_dir = getenv("HOME");
            if (home_dir != NULL) {
                size_t home_len = strlen(home_dir);
                memmove(&full_path[i + home_len], &full_path[i + 1], path_length - i);
                strncpy(full_path + i, home_dir, home_len);
                path_length += home_len - 1;
            } else {
                strcpy(error_message, "Home directory environment variable is not set.");
                free(full_path);
                return NULL;
            }
        }
    }

    return full_path;
}
