#include <vector>
#include <stdexcept>

struct Point {
    float x, y, z;
};

class SpatialHashGrid {
public:
    SpatialHashGrid(int width, int height, int depth, float bucketSize, int maxEntriesPerBucket)
        : width(width), height(height), depth(depth), bucketSize(bucketSize),
          maxEntriesPerBucket(maxEntriesPerBucket) {
        grid.resize(width * height * depth);
    }

    ~SpatialHashGrid() {
        for (auto& bucket : grid) {
            bucket.clear();
        }
    }

    void insert(const Point& point, const std::vector<float>& data) {
        if (data.size() > maxEntriesPerBucket) {
            throw std::runtime_error("Data exceeds maximum entries per bucket.");
        }
        int index = getBucketIndex(point);
        grid[index].push_back(data);
    }

    // Add query and serialization methods here

private:
    int width, height, depth;
    float bucketSize;
    int maxEntriesPerBucket;
    std::vector<std::vector<std::vector<std::vector<float>>>> grid;

    int getBucketIndex(const Point& point) {
        int x = static_cast<int>(point.x / bucketSize);
        int y = static_cast<int>(point.y / bucketSize);
        int z = static_cast<int>(point.z / bucketSize);
        return x * height * depth + y * depth + z;
    }
};
```

