import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DeserializationStressTest {
    public static void main(String[] args) throws InterruptedException {
        DynamicDeserializer deserializer = new DynamicDeserializer(new SimpleClassProvider());
        ExecutorService executor = Executors.newFixedThreadPool(10);

        for (int i = 0; i < 100; i++) {
            byte[] data = "test".getBytes();
            Class<String> clazz = String.class;

            executor.submit(() -> {
                try {
                    String result = deserializer.deserialize(data, clazz);
                    System.out.println("Deserialized: " + result);
                } catch (CustomException e) {
                    e.printStackTrace();
                }
            });
        }

        executor.shutdown();
    }
}
