```python
import hashlib
import requests

def calculate_file_sha256(file_path, expected_checksum=None):
    hash_object = hashlib.sha256()
    try:
        if file_path.startswith('http'):
            response = requests.get(file_path, stream=True)
            response.raise_for_status()  # Raise an exception for bad status codes
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:  # filter out keep-alive new chunks
                    hash_object.update(chunk)
        else:
            with open(file_path, 'rb') as file:
                for chunk in iter(lambda: file.read(4096), b''):
                    hash_object.update(chunk)

        actual_checksum = hash_object.hexdigest()
        if expected_checksum and actual_checksum == expected_checksum:
            return "Hash verification successful."
        elif expected_checksum:
            return f"Hash mismatch. Expected {expected_checksum}, got {actual_checksum}."
        else:
            return f"SHA-256 hash: {actual_checksum}"
    except FileNotFoundError:
        return "Error: File not found."
    except requests.exceptions.RequestException as e:
        return f"Error: Unable to fetch file from URL - {e}"
    except Exception as e:
        return f"An error occurred: {e}"

# Example usage
print(calculate_file_sha256('path/to/local/file', 'expected_checksum_here'))
print(calculate_file_sha256('http://example.com/largefile.zip'))
