const AWS = require('aws-sdk');
const winston = require('winston');

// Configure Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console()
  ]
});

async function uploadFileFromUrl(url, storageConfig) {
  // Extract file name from URL
  const fileName = url.split('/').pop();

  // Validate file size and type (simplified example)
  if (fileName.length > 50 * 1024 * 1024) {
    throw new Error('File size exceeds limit');
  }

  let retries = 3;
  while (retries > 0) {
    try {
      // Initialize storage client based on config
      const storageClient = new AWS.S3({
        accessKeyId: storageConfig.accessKeyId,
        secretAccessKey: storageConfig.secretAccessKey,
        region: storageConfig.region
      });

      // Generate a unique filename
      const uniqueFileName = `${Date.now()}-${fileName}`;

      // Download the file from URL and upload to S3
      const response = await fetch(url);
      if (!response.ok) throw new Error('Failed to download file');

      const body = response.body;
      const params = {
        Bucket: storageConfig.bucketName,
        Key: uniqueFileName,
        Body: body
      };

      await storageClient.upload(params).promise();
      logger.info(`File uploaded successfully: ${uniqueFileName}`);

      // Return public URL of the uploaded file
      return `https://${storageConfig.bucketName}.s3.amazonaws.com/${uniqueFileName}`;
    } catch (error) {
      retries--;
      if (!retries) throw error;
      const delay = Math.pow(2, 3 - retries) * 1000; // Exponential backoff
      logger.warn(`Upload failed. Retrying in ${delay}ms...`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  // Function should never reach here due to retries but included for completeness
