#include <iostream>
#include <fstream>
#include <unordered_map>
#include <variant>
#include <string>
#include <nlohmann/json.hpp>
#include <mutex>

using json = nlohmann::json;
using ConfigMap = std::unordered_map<std::string, std::variant<int, double, std::string, bool>>;
using ConfigReaderFunc = std::function<ConfigMap(const std::string&)>;

std::mutex configMutex;
ConfigMap readConfig(const std::string& filePath) {
    std::lock_guard<std::mutex> lock(configMutex);
    try {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open configuration file: " + filePath);
        }

        json configJson = json::parse(file);
        ConfigMap config;
        for (auto& [key, value] : configJson.items()) {
            if (value.is_number_integer()) {
                config[key] = value.get<int>();
            } else if (value.is_number_unsigned()) {
                config[key] = static_cast<int>(value.get<unsigned int>());
            } else if (value.is_number_float() || value.is_number_integer()) {
                config[key] = value.get<double>();
            } else if (value.is_string()) {
                config[key] = value.get<std::string>();
            } else if (value.is_boolean()) {
                config[key] = value.get<bool>();
            } else {
                throw std::runtime_error("Unsupported JSON type for key: " + key);
            }
        }

        return config;
    } catch (const json::parse_error& e) {
        throw std::runtime_error("Failed to parse JSON configuration file: " + filePath + ", error: " + e.what());
    } catch (const std::exception& e) {
        throw std::runtime_error("Error reading configuration file: " + filePath + ", message: " + e.what());
    }
}
```

This code defines a `readConfig` function that reads configuration settings from a JSON file and returns them as a `std::unordered_map<std::string, std::variant<int, double, std::string, bool>>`. It utilizes the nlohmann/json library for parsing the JSON file and handles potential errors gracefully. The function is thread-safe using a mutex to allow concurrent read access.

