#include <iostream>
#include <random>
#include <thread>
#include <mutex>

namespace RandomGenerator {

class MT19937Generator {
public:
    MT19937Generator(unsigned int seed)
        : mt(seed), engine(seed) {}

    ~MT19937Generator() = default;

    void setRange(int min, int max) {
        if (min > max) throw std::invalid_argument("Invalid range");
        dist = std::uniform_int_distribution<>(min, max);
    }

    int generate() {
        return dist(engine);
    }

private:
    std::mt19937 mt;
    std::mt19937 engine;
    std::uniform_int_distribution<> dist;

    MT19937Generator(const MT19937Generator&) = delete;
    MT19937Generator& operator=(const MT19937Generator&) = delete;
};

}

int main() {
    RandomGenerator::MT19937Generator generator(42);
    generator.setRange(1, 100);

    for (int i = 0; i < 10; ++i) {
        std::cout << generator.generate() << " ";
    }
    return 0;
}
