using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private float minValue;
    private float maxValue;
    private string currentDistribution = "Uniform";

    public void Initialize(float min, float max)
    {
        if (min >= max)
        {
            Debug.LogError("Invalid range. Minimum value must be less than maximum value.");
            return;
        }

        minValue = min;
        maxValue = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue);
    }

    public void SetDistribution(string distribution)
    {
        currentDistribution = distribution;
        Debug.Log("Current distribution set to: " + distribution);
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}, Current Distribution: {currentDistribution}";
    }
}
