<?php
class ClinicManager {
    private $pdo;
    private $lastUpdateTimes = [];

    public function __construct($dsn, $username, $password) {
        $this->pdo = new PDO($dsn, $username, $password);
        $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    public function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
        if ($this->isRateLimited($last_modified_ip)) {
            return "Too many updates from this IP address. Please try again later.";
        }

        $currentTime = date('Y-m-d H:i:s');
        $sql = "UPDATE clinics SET status = :new_status, last_modified_ip = :last_modified_ip, last_modified_date = :last_modified_date WHERE clinic_id = :clinic_id";
        $stmt = $this->pdo->prepare($sql);
        $params = [
            ':new_status' => $new_status,
            ':last_modified_ip' => $last_modified_ip,
            ':last_modified_date' => $currentTime,
            ':clinic_id' => $clinic_id
        ];

        try {
            $stmt->execute($params);
            file_put_contents('error_log.txt', "Success: Clinic ID $clinic_id updated successfully.\n", FILE_APPEND | LOCK_EX);
            return "Clinic status updated successfully.";
        } catch (PDOException $e) {
            file_put_contents('error_log.txt', "Error updating clinic ID $clinic_id: " . $e->getMessage() . "\n", FILE_APPEND | LOCK_EX);
            return "Failed to update clinic status.";
        }
    }

    private function isRateLimited($ip) {
        if (!isset($this->lastUpdateTimes[$ip])) {
            $this->lastUpdateTimes[$ip] = time();
            return false;
        }

        $currentTime = time();
        if ($currentTime - $this->lastUpdateTimes[$ip] < 60) {
            $this->lastUpdateTimes[$ip]++;
            if ($this->lastUpdateTimes[$ip] >= 5) {
                return true;
            }
        } else {
            $this->lastUpdateTimes[$ip] = $currentTime;
        }

        return false;
    }
}

// Usage
$clinicManager = new ClinicManager('mysql:host=localhost;dbname=your_database', 'username', 'password');
$result = $clinicManager->updateClinicStatus(123, 'Open', $_SERVER['REMOTE_ADDR']);
echo $result;
?>
