// DisjointPairFinder.java
public class DisjointPairFinder {
    private UnionFind uf;
    private long startTime;

    public DisjointPairFinder() {
        uf = new UnionFind();
    }

    public void addElement(int element) {
        uf.makeSet(element);
    }

    public boolean areDisjoint(int a, int b) {
        startTime = System.nanoTime();
        boolean result = uf.find(a) != uf.find(b);
        long endTime = System.nanoTime();
        System.out.println("Disjoint check time: " + (endTime - startTime) + " ns");
        return result;
    }

    public void union(int a, int b) {
        uf.union(a, b);
    }
}

// UnionFind.java
public class UnionFind {
    private Map<Integer, Integer> parent;

    public UnionFind() {
        parent = new HashMap<>();
    }

    public void makeSet(int element) {
        parent.put(element, element);
    }

    public int find(int x) {
        if (parent.get(x) != x) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }

    public void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA != rootB) {
            parent.put(rootA, rootB);
        }
    }
}

