// AsyncReduce.js
const ExternalService = require('./ExternalService');

class AsyncReduce {
  constructor(initialValue) {
    this.initialValue = initialValue;
    this.externalService = new ExternalService();
  }

  async reduce(numbers, callback) {
    try {
      if (!Array.isArray(numbers)) throw new Error('Input must be an array');
      if (typeof callback !== 'function') throw new Error('Callback must be a function');

      const chunkSize = Math.ceil(numbers.length / navigator.hardwareConcurrency);
      let result = this.initialValue;

      for (let i = 0; i < numbers.length; i += chunkSize) {
        const chunk = numbers.slice(i, i + chunkSize);
        const results = await Promise.all(chunk.map(async (num) => {
          const fetchedNumber = await this.externalService.fetchNumber(num);
          return callback(result, fetchedNumber);
        }));
        result = results[results.length - 1];
      }

      console.log('Reduction completed');
      return result;
    } catch (error) {
      console.error('Error during reduction:', error.message);
      throw error;
    }
  }
}

// Example usage
const asyncReduce = new AsyncReduce(0);
asyncReduce.reduce([1, 2, 3, 4, 5], (acc, num) => acc + num)
  .then(result => console.log('Final result:', result))
  .catch(error => console.error('Error:', error));
