```python
import hashlib
import requests
from urllib.parse import urlparse
import os

def calculate_file_md5(file_path, download_chunk_size=1024*1024, hash_chunk_size=64*1024):
    if urlparse(file_path).scheme:
        return calculate_remote_file_md5(file_path, download_chunk_size, hash_chunk_size)
    else:
        return calculate_local_file_md5(file_path, hash_chunk_size)

def calculate_local_file_md5(local_path, chunk_size):
    md5_hash = hashlib.md5()
    with open(local_path, 'rb') as file:
        while chunk := file.read(chunk_size):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def calculate_remote_file_md5(remote_url, download_chunk_size, hash_chunk_size):
    response = requests.get(remote_url, stream=True)
    if response.status_code != 200:
        raise Exception(f"Failed to download file from {remote_url}")

    md5_hash = hashlib.md5()
    total_length = int(response.headers.get('content-length', 0))
    downloaded = 0
    for chunk in response.iter_content(chunk_size=download_chunk_size):
        if not chunk:
            break
        downloaded += len(chunk)
        md5_hash.update(chunk)

    return md5_hash.hexdigest()
