#include <iostream>
#include <fstream>
#include <cstdlib>
#include <ctime>

enum AttackType { SLASH, FIREBALL, POISON_DART };
const std::string attackNames[] = {"Slash", "Fireball", "Poison Dart"};
const int cooldowns[] = {6, 12, 3};

class Character {
public:
    AttackType lastAttack;
    time_t lastAttackTime;
    std::ofstream logFile;

    Character() : lastAttack(SLASH), lastAttackTime(0) {
        try {
            logFile.open("character_log.txt", std::ios::app);
        } catch (std::exception& e) {
            std::cerr << "Failed to open log file: " << e.what() << std::endl;
            exit(EXIT_FAILURE);
        }
    }

    ~Character() {
        if (logFile.is_open()) {
            logFile.close();
        }
    }

    void performRandomAttack() {
        AttackType attack;
        time_t now = time(nullptr);

        do {
            attack = static_cast<AttackType>(rand() % 3);
        } while ((now - lastAttackTime) < cooldowns[attack] && attack == lastAttack);

        lastAttack = attack;
        lastAttackTime = now;

        logFile << "Character used " << attackNames[attack] << " at " << ctime(&now);
    }
};

int main() {
    srand(time(nullptr));
    Character player;

    for (int i = 0; i < 10; ++i) {
        player.performRandomAttack();
    }

    return 0;
}
