const express = require('express');
const axios = require('axios');
const redis = require('redis');
const app = express();
const client = redis.createClient();

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Middleware to handle rate limiting
const rateLimit = (req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
  client.incr(ip);
  client.expire(ip, 60); // Limit to 1 request per minute

  client.get(ip, (err, count) => {
    if (err) return next(err);

    const limit = 5; // Number of requests allowed per minute
    if (count > limit) {
      res.status(429).json({ error: 'Too many requests. Please try again later.' });
    } else {
      next();
    }
  });
};

app.use(rateLimit);

// Middleware to handle caching
const cacheMiddleware = async (req, res, next) => {
  const { location } = req.query;
  const cacheKey = `weather:${location}`;

  client.get(cacheKey, async (err, data) => {
    if (err) return next(err);
    if (data) {
      res.json(JSON.parse(data));
    } else {
      await next();
      const result = await fetchWeatherData(location);
      client.setex(cacheKey, 3600, JSON.stringify(result)); // Cache for 1 hour
    }
  });
};

app.use(cacheMiddleware);

// Route to fetch weather data
const fetchWeatherData = async (location) => {
  const [currentWeather, forecast, monthlyStatistics, historicalEvents] = await Promise.all([
    getWeatherCurrent(location),
    getWeatherForecast(location),
    getMonthlyStatistics(location),
    getHistoricalEvents(location)
  ]);

  return {
    current_weather: currentWeather,
    forecast: forecast,
    monthly_statistics: monthlyStatistics,
    historical_events: historicalEvents
  };
};

// Function to fetch current weather data from OpenWeatherMap API
const getWeatherCurrent = async (location) => {
  const apiKey = 'YOUR_OPENWEATHERMAP_API_KEY';
  const url = `https://api.openweathermap.org/data/2.5/weather?q=${location}&appid=${apiKey}`;
  const response = await axios.get(url);
  return response.data;
};

// Function to fetch weather forecast data from OpenWeatherMap API
const getWeatherForecast = async (location) => {
  const apiKey = 'YOUR_OPENWEATHERMAP_API_KEY';
  const url = `https://api.openweathermap.org/data/2.5/forecast?q=${location}&appid=${apiKey}`;
  const response = await axios.get(url);
  return response.data.list.map(item => ({
    date: item.dt_txt,
    temp_max: item.main.temp_max,
    temp_min: item.main.temp_min,
    precipitation: item.pop
  }));
};

// Function to fetch monthly statistics from Climate API
const getMonthlyStatistics = async (location) => {
  const apiKey = 'YOUR_CLIMATE_API_KEY';
  const url = `https://api.climate.com/climate/monthly_stats?location=${location}&key=${apiKey}`;
  const response = await axios.get(url);
  return response.data.monthly_stats;
};

// Function to fetch historical events from Climate API
const getHistoricalEvents = async (location) => {
  const apiKey = 'YOUR_CLIMATE_API_KEY';
  const url = `https://api.climate.com/climate/events?location=${location}&key=${apiKey}`;
  const response = await axios.get(url);
  return response.data.events;
};

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
