#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_SIZE 1000

// Function to read integers from a file into an array
int* readFileToArray(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening the file.\n");
        return NULL;
    }

    int* array = (int*)malloc(MAX_SIZE * sizeof(int));
    if (!array) {
        printf("Memory allocation failed.\n");
        fclose(file);
        return NULL;
    }

    *size = 0;
    while (fscanf(file, "%d", &array[*size]) != EOF && *size < MAX_SIZE) {
        (*size)++;
    }

    fclose(file);
    return array;
}

// Function to sort the array in ascending order
void bubbleSort(int* array, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (array[j] > array[j + 1]) {
                int temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }
}

int main() {
    const char* filename = "numbers.txt";
    int size;

    int* array = readFileToArray(filename, &size);
    if (!array || size == 0) {
        printf("No data found or file is empty.\n");
        free(array); // Clean up if no data was read
        return 1;
    }

    bubbleSort(array, size);

    printf("Largest integer in the array: %d\n", array[size - 1]);

    free(array);
    return 0;
}
