const crypto = require('crypto');
const stream = require('stream');

function encryptData(data, iv, key) {
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
  let encrypted = cipher.update(data, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
}

async function collectAndEncryptStream(inputStream, options) {
  if (!options.encrypt) {
    const dataArray = [];
    inputStream.on('data', chunk => dataArray.push(chunk));
    inputStream.on('end', () => console.log(dataArray.join('')));
    return dataArray;
  }

  const key = crypto.randomBytes(32);
  const iv = crypto.randomBytes(16);
  let encryptedData = '';
  let errorOccurred = false;

  try {
    inputStream.on('data', chunk => {
      try {
        encryptedData += encryptData(chunk, iv, key);
      } catch (error) {
        console.error("Error during encryption:", error);
        errorOccurred = true;
      }
    });

    inputStream.on('end', () => {
      if (!errorOccurred) {
        console.log("Encrypted data:", encryptedData);
        crypto.randomFillSync(key); // Securely overwrite the key
        return [encryptedData, iv];
      }
    });
  } catch (error) {
    console.error("Error during stream processing:", error);
    errorOccurred = true;
  }

  inputStream.on('error', error => {
    console.error("Stream error:", error);
    errorOccurred = true;
  });

  return new Promise((resolve, reject) => {
    if (!errorOccurred) resolve([encryptedData, iv]);
    else reject(new Error("Error occurred during stream processing or encryption"));
  });
}

// Example usage:
const input = new stream.PassThrough();
input.end('Hello, world!');

collectAndEncryptStream(input, { encrypt: true })
  .then(result => {
    console.log('Encrypted:', result[0], 'IV:', result[1].toString('hex'));
  })
  .catch(error => {
    console.error('An error occurred:', error);
  });
