import json
import requests
from typing import Dict

class ConfigError(Exception):
    pass

class ConfigLoader:
    def __init__(self, file_path: str, api_url: str):
        self.file_path = file_path
        self.api_url = api_url
        self.config = {}

    def load_config(self) -> None:
        try:
            with open(self.file_path, 'r') as file:
                self.config = json.load(file)
            print("Local config loaded successfully.")
        except FileNotFoundError:
            raise ConfigError(f"File not found: {self.file_path}")
        except json.JSONDecodeError:
            raise ConfigError(f"Invalid JSON format in the file: {self.file_path}")

    def fetch_api_config(self) -> Dict[str, any]:
        try:
            response = requests.get(self.api_url)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            raise ConfigError(f"Failed to fetch API config: {e}")

    def merge_configs(self, new_config: Dict[str, any]) -> None:
        self.config.update(new_config)
        print("Configs merged successfully.")

    def update_config(self) -> None:
        try:
            local_config = self.load_config()
            api_config = self.fetch_api_config()
            self.merge_configs(api_config)
            print("Config updated successfully.")
        except ConfigError as e:
            print(f"Failed to update config: {e}")

# Usage
config_loader = ConfigLoader('path/to/config.json', 'https://api.example.com/config')
config_loader.update_config()
print(config_loader.config)
```

