function robustAsyncReduce(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    const result = Array.isArray(initialValue) ? initialValue.map(() => Promise.resolve(undefined)) : Promise.resolve(initialValue);

    arr.reduce((accPromise, value, index) => {
      return accPromise.then(acc => {
        return callback(value, acc, index).then(nextAcc => {
          if (index === arr.length - 1) {
            return nextAcc;
          }
          result[index] = Promise.resolve(nextAcc);
          return undefined; // Prevent unnecessary chaining
        }).catch(err => {
          console.error(`Error at index ${index}:`, err);
          return acc; // Continue with the previous accumulator value
        });
      });
    }, initialValue).then(finalResult => resolve(result)).catch(reject);
  });
}

// Example usage:
const arr = [1, 2, 3, 4, 5];
const initialValue = [0, 0];
const callback = (value, acc) => {
  if (value % 2 === 0) {
    return new Promise(resolve => setTimeout(() => resolve(acc + value), 100));
  } else {
    return acc + value;
  }
};

robustAsyncReduce(arr, initialValue, callback)
  .then(results => console.log(results))
  .catch(err => console.error('Error:', err));
