import java.io.IOException;
import java.security.KeyStoreException;
import java.security.NoSuchAlgorithmException;
import java.security.UnrecoverableEntryException;
import java.security.cert.CertificateException;
import javax.crypto.BadPaddingException;
import javax.crypto.IllegalBlockSizeException;
import javax.crypto.NoSuchPaddingException;
import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.exceptions.JWTCreationException;
import com.auth0.jwt.interfaces.RSAKey;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.ExpiredJwtException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class JwtService {

    private static final Logger logger = LoggerFactory.getLogger(JwtService.class);

    public String generateToken(String username, String userRole) throws Exception {
        try {
            // Retrieve RSA key from KMS
            RSAKey rsaKey = getRsaKeyFromKms();

            // Create JWT with RSA key and predefined rules
            Algorithm algorithm = Algorithm.RSA256(rsaKey.toRSAPublicKey(), rsaKey.toPrivateKey());
            String token = JWT.create()
                    .withSubject(username)
                    .withClaim("role", userRole)
                    .sign(algorithm);

            return token;
        } catch (Exception e) {
            logger.error("Failed to generate token: ", e);
            throw new Exception("Failed to generate token", e);
        }
    }

    private RSAKey getRsaKeyFromKms() throws KeyStoreException, IOException, NoSuchAlgorithmException,
            CertificateException, UnrecoverableEntryException, BadPaddingException, IllegalBlockSizeException,
            NoSuchPaddingException {
        // Implement logic to retrieve RSA key from KMS
        return null;
    }

    public String validateToken(String token) throws Exception {
        try {
            Claims claims = Jwts.parser()
                    .setSigningKey(getRsaKeyFromKms().toRSAPublicKey())
                    .parseClaimsJws(token)
                    .getBody();

            // Validate user role and permissions
            if (!claims.get("role").equals("admin")) {
                throw new Exception("Unauthorized");
            }

            return claims.getSubject();
        } catch (ExpiredJwtException e) {
            logger.warn("Token expired: ", e);
            throw new Exception("Token expired", e);
        } catch (Exception e) {
            logger.error("Invalid token: ", e);
            throw new Exception("Invalid token", e);
        }
    }

    public String refreshToken(String oldToken) throws Exception {
        try {
            Claims claims = Jwts.parser()
                    .setSigningKey(getRsaKeyFromKms().toRSAPublicKey())
                    .parseClaimsJws(oldToken)
                    .getBody();

            // Check if token is within refresh window
            long expirationTime = claims.getExpiration().getTime();
            if (System.currentTimeMillis() < expirationTime) {
                throw new Exception("Too early to refresh token");
            }

            return generateToken(claims.getSubject(), claims.get("role").toString());
        } catch (Exception e) {
            logger.error("Failed to refresh token: ", e);
            throw new Exception("Failed to refresh token", e);
        }
    }
}
