#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    // Define the structure fields here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int allocateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures) {
    if (maxStructures > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Max structures exceeds the limit.\n");
        return -1;
    }

    *crcList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crcList == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    *listSize = maxStructures;
    return 0;
}

void populateCrcIndications(NFAPI_CRC_INDICATION_PDU_T *crcList, size_t listSize) {
    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < listSize; ++i) {
        crcList[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1; // Unique tag within the range
        crcList[i].RNTI = rand() % 1000 + 1; // Random RNTI in a valid range
        crcList[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
    }
}

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures) {
    if (allocateNfarCrcIndications(crcList, listSize, maxStructures) != 0) {
        return -1;
    }

    populateCrcIndications(*crcList, *listSize);
    return 0;
}
