// Function to find and return the largest number in an array
int findLargest(int arr[], int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to create a semaphore with the given initial value
sem_t* createSemaphore(int initialValue) {
    sem_t *sem = malloc(sizeof(sem_t));
    sem_init(sem, 0, initialValue);
    return sem;
}

// Function to delete a semaphore
void deleteSemaphore(sem_t *sem) {
    sem_destroy(sem);
    free(sem);
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    int arr[n];
    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    int largestNumber = findLargest(arr, n);
    printf("The largest number is: %d\n", largestNumber);

    // Example usage of semaphore
    sem_t *mySemaphore = createSemaphore(1);
    printf("Semaphore created.\n");

    deleteSemaphore(mySemaphore);
    printf("Semaphore deleted.\n");

    return 0;
}
