public class FileHasher
{
    private readonly HttpClient _httpClient;

    public FileHasher()
    {
        _httpClient = new HttpClient();
    }

    public async Task<string> ComputeMd5HashAsync(string filePath)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
        using (var md5 = MD5.Create())
        {
            byte[] hash;
            try
            {
                hash = await ComputeHashAsync(fileStream, md5);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error reading file: {ex.Message}");
                return null;
            }

            string fileHash = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            return await VerifyHashAsync(fileHash);
        }
    }

    private static async Task<byte[]> ComputeHashAsync(Stream stream, MD5 md5)
    {
        using (var hashStream = new MemoryStream())
        {
            await stream.CopyToAsync(hashStream);
            return md5.ComputeHash(hashStream.ToArray());
        }
    }

    private async Task<string> VerifyHashAsync(string fileHash)
    {
        // Simulate an external API call
        var response = await _httpClient.GetAsync($"https://api.example.com/verify?hash={fileHash}");
        if (response.IsSuccessStatusCode)
        {
            var result = await response.Content.ReadAsStringAsync();
            return result == "Valid" ? fileHash : null;
        }
        else
        {
            Console.Error.WriteLine("Failed to verify hash with external API.");
            return null;
        }
    }
}
