  const extname = fs.extname(filePath);
  if (!validExtensions.includes(extname)) {
    throw new Error(`${extname} is not a supported file extension.`);
  }
}

async function readFiles(filePaths) {
  if (!Array.isArray(filePaths)) {
    filePaths = [filePaths];
  }

  const results = [];

  for (const filePath of filePaths) {
    try {
      validateFileExtension(filePath);
      const metadata = await readFileMetadata(filePath);
      const content = await readFileContent(filePath);

      results.push({
        filePath,
        metadata,
        content
      });
    } catch (error) {
      results.push({ filePath, error: error.message });
    }
  }

  return results;
}

module.exports = readFiles;
```

This code provides a function `readFiles` that reads file contents synchronously from a directory and returns their contents as strings using the fs library. It also validates the file extension to ensure it is one of the following: `.txt`, `.md`, or `.json`. If the file does not match these extensions, the function throws an error.

