    public string CalculateFileMd5(string filePath, long chunkSize = 8192)
    {
        if (!File.Exists(filePath))
        {
            LogError("File does not exist: " + filePath);
            return null;
        }

        using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, (int)chunkSize, true))
        using (MD5 md5 = MD5.Create())
        {
            byte[] hashBytes = md5.ComputeHash(fs);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public async Task<string> CalculateFileMd5Async(string filePath, long chunkSize = 8192)
    {
