            return null;
        }

        using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, (int)chunkSize, true))
        using (MD5 md5 = MD5.Create())
        {
            byte[] hashBytes = await Task.Run(() => md5.ComputeHash(fs));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

