#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 100

typedef struct {
    int UserId;
    int SessionId;
    struct {
        unsigned long InBytes;
        unsigned long OutBytes;
    } TrafficStats;
} UserSession;

void generateRandomTrafficStats(UserSession *session) {
    srand(time(NULL));
    session->TrafficStats.InBytes = rand() % 1000000; // Random incoming bytes
    session->TrafficStats.OutBytes = rand() % 1000000; // Random outgoing bytes
}

UserSession* populateUserSessions(int N) {
    static UserSession sessions[MAX_SESSIONS];
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int currentSize = 0;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < N && currentSize < MAX_SESSIONS; ++i) {
        if ((sessions + currentSize)->UserId != 0 || (sessions + currentSize)->SessionId != 0) {
            sessions[currentSize].UserId = i + 1;
            sessions[currentSize].SessionId = i + 1;
            generateRandomTrafficStats(&sessions[currentSize]);
            ++currentSize;
        } else {
            break; // Stop if the array is filled with existing entries
        }
    }
    pthread_mutex_unlock(&lock);

    return sessions;
}
