using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class AesCbcDecryption
{
    public static async Task<byte[]> DecryptAsync(string ciphertextBase64, string keyBase64, string ivBase64, PaddingMode paddingMode)
    {
        // Validate input lengths
        if (keyBase64.Length != 32 * 8 && keyBase64.Length != 24 * 8 && keyBase64.Length != 16 * 8)
            throw new ArgumentException("Key must be 16, 24, or 32 bytes long.");
        if (ivBase64.Length != 16 * 8)
            throw new ArgumentException("IV must be 16 bytes long.");

        // Convert base64 strings to byte arrays
        byte[] ciphertext = Convert.FromBase64String(ciphertextBase64);
        byte[] key = Convert.FromBase64String(keyBase64);
        byte[] iv = Convert.FromBase64String(ivBase64);

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.KeySize = key.Length * 8;
            aesAlg.Padding = paddingMode;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(key, iv);
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                return await ReadFullyAsync(csDecrypt);
            }
        }
    }

    private static async Task<byte[]> ReadFullyAsync(Stream input)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            await input.CopyToAsync(ms);
            return ms.ToArray();
        }
    }
}

// Example usage:
public class Program
{
    public static async Task Main(string[] args)
    {
        string ciphertextBase64 = "your_ciphertext_base64";
        string keyBase64 = "your_key_base64";
        string ivBase64 = "your_iv_base64";

        try
        {
            byte[] decryptedData = await AesCbcDecryption.DecryptAsync(ciphertextBase64, keyBase64, ivBase64, PaddingMode.PKCS7);
            // Process the decrypted data
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error decrypting data: {ex.Message}");
        }
    }
}
