<?php
function updateClinicStatus($clinic_id, $new_status, $last_modified_ip, $stakeholder_api_key) {
    // Database connection details
    $host = 'localhost';
    $dbname = 'clinics_db';
    $username = 'root';
    $password = '';

    // External API endpoint
    $api_url = 'https://stakeholders.example.com/notify';

    try {
        // Connect to the database
        $pdo = new PDO("mysql:host=$host;dbname=$dbname", $username, $password);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Prepare and execute the update statement
        $stmt = $pdo->prepare("UPDATE clinics SET status = :new_status, last_modified_ip = :last_modified_ip, last_modified_date = NOW() WHERE clinic_id = :clinic_id");
        $stmt->bindParam(':new_status', $new_status);
        $stmt->bindParam(':last_modified_ip', $last_modified_ip);
        $stmt->bindParam(':clinic_id', $clinic_id);

        // Check for rate limiting
        if (!checkRateLimit($last_modified_ip)) {
            throw new Exception("Too many updates from this IP address.");
        }

        // Execute the update
        if ($stmt->execute()) {
            // Validate stakeholder API key before sending notification
            if (validateApiKey($stakeholder_api_key)) {
                $ch = curl_init();
                curl_setopt($ch, CURLOPT_URL, $api_url);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query(array('clinic_id' => $clinic_id, 'status' => $new_status)));
                $response = curl_exec($ch);
                curl_close($ch);

                if ($response === 'success') {
                    return "Update successful and notification sent.";
                } else {
                    throw new Exception("Error sending notification.");
                }
            } else {
                throw new Exception("Invalid stakeholder API key.");
            }
        } else {
            throw new Exception("Failed to update clinic status.");
        }
    } catch (PDOException $e) {
        // Log the error
        file_put_contents('error_log.txt', date('Y-m-d H:i:s') . ' - Error: ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
        return "Database error: " . $e->getMessage();
    } catch (Exception $e) {
        // Log the error
        file_put_contents('error_log.txt', date('Y-m-d H:i:s') . ' - Error: ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
        return "Error: " . $e->getMessage();
    }
}

function checkRateLimit($ip) {
    // Implement rate limiting logic here
    // Example:
    $file = 'rate_limit_' . $ip . '.txt';
    if (file_exists($file)) {
        $last_update = filemtime($file);
        if ((time() - $last_update) < 60) {
            return false;
        }
    }
    file_put_contents($file, time());
    return true;
}

function validateApiKey($api_key) {
    // Implement API key validation logic here
    // Example:
    $valid_keys = ['key1', 'key2', 'key3'];
    return in_array($api_key, $valid_keys);
}
