<?php

// Define constants for the character set
define('UPPERCASE', 'ABCDEFGHIJKLMNOPQRSTUVWXYZ');
define('LOWERCASE', 'abcdefghijklmnopqrstuvwxyz');
define('DIGITS', '0123456789');
define('SPECIAL_CHARS', '!@#$%^&*()_+-=[]{}|;:,.<>?');

// Function to generate a random string
function generateRandomString($length) {
    $charSet = UPPERCASE . LOWERCASE . DIGITS . SPECIAL_CHARS;
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= substr($charSet, mt_rand(0, strlen($charSet) - 1), 1);
    }
    return $randomString;
}

// Function to securely hash a password
function secureHashPassword($password, $rounds = 10) {
    if (version_compare(PHP_VERSION, '7.2.0', '>=')) {
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => $rounds]);
    } else {
        die('BCRYPT is not supported in this PHP version.');
    }
}

// Function to verify a hashed password
function verifyHashedPassword($password, $hashedPassword) {
    return password_verify($password, $hashedPassword);
}

// Example usage
$randomString = generateRandomString(12);
echo "Random String: $randomString\n";

$password = 'mySecurePassword';
$hashedPassword = secureHashPassword($password);
echo "Hashed Password: $hashedPassword\n";

$isCorrect = verifyHashedPassword('mySecurePassword', $hashedPassword);
echo "Verification Result: " . ($isCorrect ? 'Success' : 'Failure') . "\n";
?>
