    double timestamp;
    char** tags;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

void load_records(int server_id) {
    SQLHENV env;
    SQLHDBC dbc;
    SQLHSTMT stmt;
    SQLRETURN ret;

    ret = SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &env);
    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) return;

    ret = SQLSetEnvAttr(env, SQL_ATTR_ODBC_VERSION, (SQLPOINTER)SQL_OV_ODBC3, 0);
    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
        SQLFreeHandle(SQL_HANDLE_ENV, env);
        return;
    }

    ret = SQLAllocHandle(SQL_HANDLE_DBC, env, &dbc);
    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
        SQLFreeHandle(SQL_HANDLE_ENV, env);
        return;
    }

    // Connect to the server
    char conn_str[256];
    snprintf(conn_str, sizeof(conn_str), "DRIVER={SQL Server};SERVER=server%d;UID=user;PWD=password", server_id);
    ret = SQLDriverConnect(dbc, NULL, (SQLCHAR*)conn_str, strlen(conn_str),
                            NULL, 0, NULL, SQL_DRIVER_NOPROMPT);
    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
        SQLDisconnect(dbc);
        SQLFreeHandle(SQL_HANDLE_DBC, dbc);
        SQLFreeHandle(SQL_HANDLE_ENV, env);
        return;
    }

    ret = SQLAllocHandle(SQL_HANDLE_STMT, dbc, &stmt);
    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
        SQLDisconnect(dbc);
        SQLFreeHandle(SQL_HANDLE_DBC, dbc);
        SQLFreeHandle(SQL_HANDLE_ENV, env);
        return;
    }

    // Execute query
    const char* query = "SELECT offset, key, timestamp, tag FROM records";
    ret = SQLExecDirect(stmt, (SQLCHAR*)query, SQL_NTS);
    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
        SQLFreeHandle(SQL_HANDLE_STMT, stmt);
        SQLDisconnect(dbc);
        SQLFreeHandle(SQL_HANDLE_DBC, dbc);
        SQLFreeHandle(SQL_HANDLE_ENV, env);
        return;
    }

    // Fetch results
    while ((ret = SQLFetch(stmt)) == SQL_SUCCESS || ret == SQL_SUCCESS_WITH_INFO) {
        Record* record = (Record*)malloc(sizeof(Record));
        SQLINTEGER offset_len, key_len, timestamp_len, tag_count;
        char* offset_value, *key_value, *timestamp_value;

        SQLGetData(stmt, 1, SQL_C_LONG, &record->offset, sizeof(long), &offset_len);
        SQLGetData(stmt, 2, SQL_C_ULONG, &record->key, sizeof(int), &key_len);
        SQLGetData(stmt, 3, SQL_C_DOUBLE, &record->timestamp, sizeof(double), &timestamp_len);

        // Get tag count and allocate memory
        ret = SQLGetData(stmt, 4, SQL_C_LONG, &tag_count, sizeof(int), NULL);
        if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
            free(record);
            continue;
        }

        record->tags = (char**)malloc(tag_count * sizeof(char*));
        for (int i = 0; i < tag_count; ++i) {
            ret = SQLGetData(stmt, 4, SQL_C_CHAR, NULL, 0, &tag_len);
            if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) break;

            record->tags[i] = (char*)malloc(tag_len + 1);
            ret = SQLGetData(stmt, 4, SQL_C_CHAR, record->tags[i], tag_len + 1, NULL);
        }

        pthread_mutex_lock(&records_lock);
        records[record_count++] = record;
        pthread_mutex_unlock(&records_lock);
    }

    // Clean up
    SQLFreeHandle(SQL_HANDLE_STMT, stmt);
    SQLDisconnect(dbc);
    SQLFreeHandle(SQL_HANDLE_DBC, dbc);
    SQLFreeHandle(SQL_HANDLE_ENV, env);
}

void* worker_thread(void* arg) {
    int server_id = *(int*)arg;
    load_records(server_id);
    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[MAX_SERVERS];
    int server_ids[MAX_SERVERS];

    // Initialize record structures
    for (int i = 0; i < MAX_RECORDS; ++i) records[i] = NULL;

    // Create worker threads for each server
    for (int i = 0; i < MAX_SERVERS; ++i) {
        server_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, &server_ids[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_SERVERS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up records and tags
    for (int i = 0; i < record_count; ++i) {
        free(records[i]->tags);
        free(records[i]);
    }

    return 0;
}
