import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;
import org.json.JSONArray;
import org.json.JSONObject;

public class PokemonService {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/";

    public static void main(String[] args) {
        try {
            int pokemonId = 25; // Example Pokemon ID for Pikachu
            JSONObject pokemonData = getPokemonData(pokemonId);
            if (pokemonData != null) {
                System.out.println(pokemonData.toString(4));
            } else {
                System.out.println("Failed to retrieve Pokemon data.");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static JSONObject getPokemonData(int pokemonId) throws IOException {
        URL url = new URL(API_URL + pokemonId);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder content = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
            connection.disconnect();

            return new JSONObject(content.toString());
        } else {
            System.err.println("Failed to retrieve data. Response code: " + responseCode);
            return null;
        }
    }

    public static JSONArray getWeaknesses(JSONObject pokemonData) {
        JSONArray weaknesses = new JSONArray();
        if (pokemonData.has("types")) {
            JSONArray types = pokemonData.getJSONArray("types");
            for (int i = 0; i < types.length(); i++) {
                JSONObject type = types.getJSONObject(i).getJSONObject("type");
                String typeName = type.getString("name");
                weaknesses.put(typeName);
            }
        }
        return weaknesses;
    }

    public static JSONObject getNextEvolution(JSONObject pokemonData) {
        if (pokemonData.has("species") && pokemonData.getJSONObject("species").has("url")) {
            try {
                URL evolutionUrl = new URL(pokemonData.getJSONObject("species").getString("url"));
                HttpURLConnection evolConnection = (HttpURLConnection) evolutionUrl.openConnection();
                evolConnection.setRequestMethod("GET");

                int responseCode = evolConnection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    BufferedReader in = new BufferedReader(new InputStreamReader(evolConnection.getInputStream()));
                    String inputLine;
                    StringBuilder content = new StringBuilder();
                    while ((inputLine = in.readLine()) != null) {
                        content.append(inputLine);
                    }
                    in.close();
                    evolConnection.disconnect();

                    JSONObject speciesData = new JSONObject(content.toString());
                    if (speciesData.has("evolves_from_species") && speciesData.getJSONObject("evolves_from_species").has("url")) {
                        URL evolvesFromUrl = new URL(speciesData.getJSONObject("evolves_from_species").getString("url"));
                        HttpURLConnection fromConnection = (HttpURLConnection) evolvesFromUrl.openConnection();
                        fromConnection.setRequestMethod("GET");

                        int fromResponseCode = fromConnection.getResponseCode();
                        if (fromResponseCode == HttpURLConnection.HTTP_OK) {
                            BufferedReader fromIn = new BufferedReader(new InputStreamReader(fromConnection.getInputStream()));
                            String fromInputLine;
                            StringBuilder fromContent = new StringBuilder();
                            while ((fromInputLine = fromIn.readLine()) != null) {
                                fromContent.append(fromInputLine);
                            }
                            fromIn.close();
                            fromConnection.disconnect();

                            JSONObject evolvesFromData = new JSONObject(fromContent.toString());
                            if (evolvesFromData.has("id") && evolvesFromData.has("name")) {
                                return new JSONObject()
                                    .put("name", evolvesFromData.getString("name"))
                                    .put("level", 1); // Assuming level is always 1 for simplicity
                            }
                        } else {
                            System.err.println("Failed to retrieve next evolution data. Response code: " + fromResponseCode);
                        }
                    }
                } else {
                    System.err.println("Failed to retrieve species data. Response code: " + responseCode);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return new JSONObject().put("name", "None").put("level", 0);
    }
}
