using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlParser
{
    private string cacheFilePath;
    private int cacheDuration; // in minutes

    public XmlParser(string cacheFilePath, int cacheDuration)
    {
        this.cacheFilePath = cacheFilePath;
        this.cacheDuration = cacheDuration;
    }

    public async Task<string> GetFirstMatchingElement(string xmlUrl, string xpathExpression)
    {
        string cachedXmlContent = await FetchAndCacheXml(xmlUrl);
        XPathDocument document = new XPathDocument(new StringReader(cachedXmlContent));
        XPathNavigator navigator = document.CreateNavigator();

        try
        {
            XPathNodeIterator nodes = navigator.Select(xpathExpression);
            if (nodes.MoveNext())
            {
                return nodes.Current.OuterXml;
            }
            else
            {
                Log("No matching element found for the given XPath expression.");
                return null;
            }
        }
        catch (Exception ex)
        {
            Log($"Error evaluating XPath expression: {ex.Message}");
            return null;
        }
    }

    private async Task<string> FetchAndCacheXml(string xmlUrl)
    {
        if (IsCachedContentValid())
        {
            return File.ReadAllText(cacheFilePath);
        }

        using (HttpClient client = new HttpClient())
        {
            try
            {
                string xmlContent = await client.GetStringAsync(xmlUrl);
                CacheXmlContent(xmlContent);
                return xmlContent;
            }
            catch (HttpRequestException ex)
            {
                Log($"Network error while fetching XML from {xmlUrl}: {ex.Message}");
                throw;
            }
        }
    }

    private bool IsCachedContentValid()
    {
        if (!File.Exists(cacheFilePath))
        {
            return false;
        }

        FileInfo fileInfo = new FileInfo(cacheFilePath);
        TimeSpan timeSinceCache = DateTime.Now - fileInfo.LastWriteTime;
        return timeSinceCache.TotalMinutes <= cacheDuration;
    }

    private void CacheXmlContent(string xmlContent)
    {
        File.WriteAllText(cacheFilePath, xmlContent);
    }

    private static void Log(string message)
    {
        Console.WriteLine($"[LOG] {DateTime.Now}: {message}");
    }
}
