using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class SecureFileHasher
{
    private static readonly HttpClient _httpClient = new HttpClient();
    private static readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
    private const string ApiUrl = "https://api.example.com/verifyHash";
    private const int ChunkSize = 8192; // 8KB
    private const int MaxConcurrentDownloads = 5;

    public async Task ComputeAndVerifyFileHashAsync(string filePath)
    {
        try
        {
            string hash = await ComputeMd5HashAsync(filePath);
            if (hash != null)
            {
                bool isVerified = await VerifyHashAsync(hash);
                if (isVerified)
                {
                    Console.WriteLine($"File {filePath} verified successfully.");
                }
                else
                {
                    Console.WriteLine($"File {filePath} verification failed.");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
        }
    }

    private async Task<string> ComputeMd5HashAsync(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = File.OpenRead(filePath))
        {
            byte[] hashBytes;
            await ReadStreamInChunksAsync(stream, async chunk =>
            {
                md5.TransformBlock(chunk, 0, chunk.Length, null, 0);
            });
            md5.TransformFinalBlock(new byte[0], 0, 0);
            hashBytes = md5.Hash;
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    private async Task ReadStreamInChunksAsync(Stream stream, Func<byte[], Task> processChunk)
    {
        var buffer = new byte[ChunkSize];
        int bytesRead;
        while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            await processChunk(new ArraySegment<byte>(buffer, 0, bytesRead).ToArray());
        }
    }

    private async Task<bool> VerifyHashAsync(string hash)
    {
        if (_cache.TryGetValue(hash, out var cachedResult))
        {
            return cachedResult == "true";
        }

        try
        {
            var content = new StringContent($"hash={hash}", System.Text.Encoding.UTF8, "application/x-www-form-urlencoded");
            using (var response = await _httpClient.PostAsync(ApiUrl, content))
            {
                if (response.IsSuccessStatusCode)
                {
                    var result = await response.Content.ReadAsStringAsync();
                    bool isVerified = result.Equals("true", StringComparison.OrdinalIgnoreCase);
                    _cache[hash] = isVerified.ToString().ToLowerInvariant();
                    return isVerified;
                }
                else
                {
                    Console.WriteLine($"API request failed with status code {response.StatusCode}");
                    return false;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error verifying hash: {ex.Message}");
            return false;
        }
    }

    public static async Task Main(string[] args)
    {
        var hasher = new SecureFileHasher();
        var tasks = new List<Task>();

        foreach (var file in args)
        {
            tasks.Add(hasher.ComputeAndVerifyFileHashAsync(file));
        }

        await Task.WhenAll(tasks);
    }
}
