<?php

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    // Database connection details for each node
    $nodes = [
        'node1' => ['host' => 'db_node_1_host', 'port' => 3306],
        'node2' => ['host' => 'db_node_2_host', 'port' => 3306],
        // Add more nodes as needed
    ];

    $logService = new ELKStackLogger();
    $rateLimiter = new RateLimiter();

    if (!$rateLimiter->allowUpdate($last_modified_ip)) {
        return "Rate limit exceeded. Please try again later.";
    }

    foreach ($nodes as $node) {
        try {
            $mysqli = new mysqli($node['host'], 'username', 'password', 'database_name', $node['port']);

            if ($mysqli->connect_error) {
                throw new Exception("Connection failed: " . $mysqli->connect_error);
            }

            // Use prepared statements to prevent SQL injection
            $stmt = $mysqli->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=NOW() WHERE clinic_id=?");
            $stmt->bind_param("ssi", $new_status, $last_modified_ip, $clinic_id);

            if ($stmt->execute()) {
                $stmt->close();
                $mysqli->close();
                continue;
            } else {
                throw new Exception("Error updating clinic status: " . $stmt->error);
            }
        } catch (Exception $e) {
            // Log error to ELK Stack
            $logService->logError($e->getMessage(), [
                'clinic_id' => $clinic_id,
                'new_status' => $new_status,
                'last_modified_ip' => $last_modified_ip,
                'node_host' => $node['host'],
                'node_port' => $node['port']
            ]);
        }
    }

    return "Clinic status updated successfully.";
}

class ELKStackLogger {
    public function logError($message, $context) {
        // Code to log error to ELK Stack
    }
}

class RateLimiter {
    private $redis;

    public function __construct() {
        $this->redis = new Redis();
        $this->redis->connect('localhost', 6379);
    }

    public function allowUpdate($ip) {
        $key = "rate_limit:$ip";
        $currentCount = $this->redis->incr($key);

        if ($currentCount == 1) {
            $this->redis->expire($key, 60); // Set expiration for 1 minute
        }

        return $currentCount <= 5;
    }
}

