using System;
using System.Xml.XPath;

public class XmlParser {
    public static XPathNavigator GetSingleElement(string xmlContent, string elementName) {
        XPathDocument doc = new XPathDocument(new System.IO.StringReader(xmlContent));
        XPathNavigator nav = doc.CreateNavigator();
        XPathNodeIterator nodes = nav.Select($"//{elementName}");

        if (nodes.Count == 0) {
            throw new Exception("No element found.");
        } else if (nodes.Count > 1) {
            throw new Exception("Multiple elements found.");
        }

        return nodes.Current;
    }
}

public class StringModifier {
    public static string AppendSlashIfWithinLimit(string input, int limit) {
        if (input.Length <= limit) {
            return $"{input}/";
        } else {
            return null;
        }
    }
}
