            synchronized (cache) {
                bitmap = cache.get(themeName);
                if (bitmap == null) {
                    File cacheFile = new File(context.getCacheDir(), CACHE_DIR + "/" + themeName);
                    if (!cacheFile.exists()) {
                        downloadTheme(themeName, cacheFile);
