```java
import java.io.*;
import java.util.logging.Logger;

public class ObjectDeserializer {

    private static final Logger logger = Logger.getLogger(ObjectDeserializer.class.getName());

    public static <T> T deserialize(byte[] byteArray, Class<T> clazz) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(byteArray);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Deserialization failed: " + e.getMessage());
            throw new RuntimeException("Failed to deserialize object", e);
        }
    }

    // Fallback mechanism for older class versions
    public static <T> T deserializeWithFallback(byte[] byteArray, Class<T> clazz, Class<?> fallbackClass) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(byteArray);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return clazz.cast(ois.readObject());
        } catch (IOException e) {
            logger.severe("Deserialization failed: " + e.getMessage());
            throw new RuntimeException("Failed to deserialize object", e);
        } catch (ClassNotFoundException e) {
            try (ByteArrayInputStream bis = new ByteArrayInputStream(byteArray);
                 ObjectInputStream ois = new ObjectInputStream(bis)) {
                return fallbackClass.cast(ois.readObject());
            } catch (Exception ex) {
                logger.severe("Deserialization with fallback failed: " + ex.getMessage());
                throw new RuntimeException("Failed to deserialize object using fallback", ex);
            }
        }
    }

}
