import os
import re
from datetime import datetime
import logging

# Configure logging settings
logging.basicConfig(filename='process_log_file.log', level=logging.INFO)

def find_log_files(directory):
    """Recursively search for log files in the specified directory."""
    log_files = []
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.log') or file.endswith('.txt'):
                log_files.append(os.path.join(root, file))
    return log_files

def extract_timestamp(line, timestamp_format):
    """Extract a timestamp from the given line using the specified format."""
    match = re.search(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}', line)
    if match:
        return datetime.strptime(match.group(), timestamp_format)

def process_log_file(directory, timestamp_format='%Y-%m-%d %H:%M:%S'):
    """Process log files in the specified directory."""
    log_files = find_log_files(directory)
    sorted_lines = []

    for log_file in log_files:
        try:
            with open(log_file, 'r') as file:
                lines = file.readlines()
                if lines:
                    last_line = lines[-1]
                    timestamp = extract_timestamp(last_line, timestamp_format)
                    if timestamp:
                        sorted_lines.append((log_file, timestamp, last_line))
        except Exception as e:
            logging.error(f"Error processing {log_file}: {e}")

    # Sort by timestamp
    sorted_lines.sort(key=lambda x: x[1])

    # Perform additional operations on the last line
    if sorted_lines:
        _, _, last_line = sorted_lines[-1]
        # Example operation: print the sequence number from the last line
        try:
            match = re.search(r'sequence (\d+)', last_line)
            if match:
                sequence_number = int(match.group(1))
                logging.info(f"Sequence number from the last line: {sequence_number}")
            else:
                logging.warning("No sequence number found in the last line.")
        except Exception as e:
            logging.error(f"Error extracting sequence number: {e}")

# Unit test
def test_process_log_file():
    test_directory = 'path/to/test/logs'
    process_log_file(test_directory)
    # Add assertions or checks to validate the function's behavior

test_process_log_file()
