#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER *cipher;
    EVP_MD *digest;
} SecureCrypto;

SecureCrypto* init_secure_library(const char *config, const char *log_file) {
    FILE *log = fopen(log_file, "w");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file);
        return NULL;
    }

    SecureCrypto *lib = malloc(sizeof(SecureCrypto));
    if (!lib) {
        fprintf(log, "Memory allocation failed\n");
        fclose(log);
        return NULL;
    }

    // Parse config string and load algorithms
    if (strstr(config, "AES-256")) {
        lib->cipher = EVP_aes_256_cbc();
    } else if (strstr(config, "ChaCha20")) {
        lib->cipher = EVP_chacha20_poly1305();
    } else {
        fprintf(log, "Unsupported cipher\n");
        free(lib);
        fclose(log);
        return NULL;
    }

    if (strstr(config, "SHA-256")) {
        lib->digest = EVP_sha256();
    } else if (strstr(config, "SHA-384")) {
        lib->digest = EVP_sha384();
    } else if (strstr(config, "SHA-512")) {
        lib->digest = EVP_sha512();
    } else {
        fprintf(log, "Unsupported digest\n");
        EVP_CIPHER_free(lib->cipher);
        free(lib);
        fclose(log);
        return NULL;
    }

    fclose(log);
    return lib;
}

void cleanup_library(SecureCrypto *lib) {
    EVP_CIPHER_free(lib->cipher);
    EVP_MD_free(lib->digest);
    free(lib);
}
