        if (currentDepth >= maxDepth) return;

        try {
            if (node.matches(selector)) {
                if (testFunc(node)) {
                    result.push(node);
                }
            }

            for (let child of node.children) {
                traverse(child, currentDepth + 1);
            }
        } catch (error) {
            console.error("Error during DOM traversal:", error);
        }
    }

    traverse(root, 0);
    return result;
}
