    // ...

    // Allocate memory for arrays
    int num_records = 1000;
    void* offsets = allocate_memory(num_records);
    void* keys = allocate_memory(num_records);
    void* timestamps = allocate_memory(num_records);

    // Handle concurrent operations
    concurrent_operations(num_servers, &offsets, &keys, &timestamps);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(timestamps);

    return 0;
}
