        storage_nodes.remove(node)
        # Logic to remove the node from the system

# File management
file_store = {}

@app.route('/upload', methods=['POST'])
@auth0.require_login
def upload_file():
    file = request.files['file']
    user_id = auth0.user.get('sub')
    file_store[user_id, file.filename] = file.read()
    return jsonify({'message': 'File uploaded successfully'}), 201

@app.route('/download/<filename>', methods=['GET'])
@auth0.require_login
def download_file(filename):
    user_id = auth0.user.get('sub')
    if (user_id, filename) in file_store:
        return file_store[user_id, filename], 200
    else:
        return jsonify({'message': 'File not found'}), 404

@app.route('/delete/<filename>', methods=['DELETE'])
@auth0.require_login
def delete_file(filename):
    user_id = auth0.user.get('sub')
    if (user_id, filename) in file_store:
        del file_store[user_id, filename]
        return jsonify({'message': 'File deleted successfully'}), 200
    else:
        return jsonify({'message': 'File not found'}), 404

