} Connection;

// Define the callback function type
typedef void (*Callback)(void);

// Define the main structure containing pointers to a string, a connection, and a callback function
typedef struct {
    char *password;
    Connection *conn;
    Callback cb;
} SecurityContext;

// Define error codes
#define ERR_PASSWORD_EMPTY 1
#define ERR_CONNECTION_TITLE_NULL 2
#define ERR_CALLBACK_NULL 3
#define ERR_SUCCESS 0

// Function to check the security context
int checkSecurityContext(SecurityContext *ctx) {
    if (ctx == NULL || ctx->password == NULL || *ctx->password == '\0') {
        return ERR_PASSWORD_EMPTY;
    }
    if (ctx->conn != NULL && ctx->conn->title == NULL) {
        return ERR_CONNECTION_TITLE_NULL;
    }
    if (ctx->cb == NULL) {
        return ERR_CALLBACK_NULL;
    }
    // If all checks pass, return success
    return ERR_SUCCESS;
}

// Example usage
int main() {
    SecurityContext ctx = { .password = "securePass123", .conn = malloc(sizeof(Connection)), .cb = (Callback)printf };
    ctx.conn->title = "SecureConnection";

    int result = checkSecurityContext(&ctx);
    if (result != ERR_SUCCESS) {
        printf("Error: %d\n", result);
    } else {
        printf("Success!\n");
    }

    free(ctx.conn);
    return 0;
}
