        return CompletableFuture.supplyAsync(() -> {
            for (int attempt = 0; attempt < maxRetries; attempt++) {
                try {
                    PokemonData data = classProvider.getPokemonData(pokemonName);
                    if (data != null && validateData(data)) {
                        return data;
                    }
                } catch (Exception e) {
                    handleFailure(e, pokemonName, attempt);
                }
                try {
                    TimeUnit.MILLISECONDS.sleep(timeoutMs);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Fetch operation interrupted", ie);
                }
            }
            return null; // Fallback data or error handling
        });
    }

