using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Xml.Linq;
using System.Threading.Tasks;

public class CryptoXmlParser
{
    private static readonly HttpClient client = new HttpClient();
    private static Dictionary<string, XDocument> cache = new Dictionary<string, XDocument>();
    private static object cacheLock = new object();

    public async Task<XDocument> FetchAndParseXmlAsync(string url)
    {
        lock (cacheLock)
        {
            if (cache.ContainsKey(url) && !IsCacheExpired(cache[url]))
                return cache[url];
        }

        try
        {
            var response = await client.GetAsync(url);
