public class ObjectDeserializer {

    private final Map<String, Constructor<?>> classCache = new LinkedHashMap<>(16, 0.75f, true) {
        protected boolean removeEldestEntry(Map.Entry<String, Constructor<?>> eldest) {
            return size() > 100; // Limit cache to 100 entries
        }
    };

    public <T> T deserialize(byte[] byteArray, Class<T> clazz) throws CustomDeserializationException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(byteArray);
             ObjectInputStream ois = new ObjectInputStream(bais)) {

            String className = ois.readUTF();
            Constructor<?> constructor = classCache.computeIfAbsent(className, this::getConstructorFromExternalSource);

            return (T) constructor.newInstance(ois);
        } catch (IOException | ClassNotFoundException e) {
            logError(e.getMessage());
            throw new CustomDeserializationException("Failed to deserialize object", e);
        }
    }

    private Constructor<?> getConstructorFromExternalSource(String className) throws IOException, ClassNotFoundException {
        URL url = new URL("https://api.example.com/class?name=" + className);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
