        {
            Console.WriteLine("Error: Invalid directory path.");
            return;
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            Console.WriteLine("Error: web.config file is missing.");
            return;
        }

        foreach (var operation in operations)
        {
            try
            {
                await PerformOperation(operation, siteName);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error performing {operation}: {ex.Message}");
            }
        }
    }

    private async Task PerformOperation(string operation, string siteName)
    {
        // Rate limiting logic here if needed

        for (int attempt = 0; attempt < _retryCount; attempt++)
        {
            try
            {
                var response = await MakeApiCall(operation, siteName);
                Console.WriteLine($"Successfully performed {operation} on {siteName}: {response}");
                return;
            }
            catch (Exception)
            {
                if (attempt == _retryCount - 1)
                    throw;

                await Task.Delay(_retryDelay);
            }
        }
    }

