using System;
using UnityEngine;

public class DynamicValueGenerator : MonoBehaviour
{
    private DistributionType _currentDistribution = DistributionType.Uniform;
    private float _minRange, _maxRange;
    private Cache<string, Func<float>> _distributionCache;

    public void Initialize(float minRange, float maxRange)
    {
        if (minRange >= maxRange)
            throw new ArgumentException("Max range must be greater than min range.");

        _minRange = minRange;
        _maxRange = maxRange;
        _distributionCache = new Cache<string, Func<float>>();
    }

    public void SetDistribution(DistributionType distribution, params object[] parameters)
    {
        switch (distribution)
        {
            case DistributionType.Uniform:
                SetUniformDistribution((float)parameters[0], (float)parameters[1]);
                break;
            // Add cases for other distributions
            default:
                throw new ArgumentException("Invalid distribution type.");
        }
    }

    public float GetRandomFloat()
    {
        switch (_currentDistribution)
        {
            case DistributionType.Uniform:
                return GetUniformRandom();
            // Handle other distribution types
            default:
                throw new InvalidOperationException("No distribution set.");
        }
    }

    public int GetRandomInt(int min, int max)
    {
        if (min >= max)
            throw new ArgumentException("Max range must be greater than min range.");

        switch (_currentDistribution)
        {
            case DistributionType.Uniform:
                return UnityEngine.Random.Range(min, max);
            // Handle other distribution types
            default:
                throw new InvalidOperationException("No distribution set.");
        }
    }

    public override string ToString()
    {
        return $"Range: {_minRange}-{_maxRange}, Distribution: {_currentDistribution}";
    }

    private void SetUniformDistribution(float min, float max)
    {
        _currentDistribution = DistributionType.Uniform;
        _distributionCache["Uniform"] = () => GetUniformRandom();
    }

    private float GetUniformRandom()
    {
        return UnityEngine.Random.Range(_minRange, _maxRange);
    }

    // Add methods for other distribution types and their implementations
}

public enum DistributionType
{
    Uniform,
    Gaussian,
    Exponential
}
