import requests
from time import sleep
import logging
from threading import Lock

class APIResponseValidator:
    def __init__(self):
        self.services = {}
        self.lock = Lock()

    def add_service(self, service_name, validation_rules):
        with self.lock:
            if service_name in self.services:
                raise ValueError(f"Service {service_name} already exists.")
            self.services[service_name] = {
                'validation_rules': validation_rules,
                'retries': 0
            }

    def validate_response(self, service_name, response):
        with self.lock:
            if service_name not in self.services:
                raise ValueError(f"Service {service_name} does not exist.")

            for _ in range(3):  # Retry up to 3 times
                try:
                    data = response.json()
                    self.check_required_fields(data, service_name)
                    mapped_profile = self.map_to_unified_format(data, service_name)
                    return mapped_profile
                except (requests.exceptions.RequestException, ValueError) as e:
                    if isinstance(e, requests.exceptions.RequestException):
                        logging.error(f"API call failed: {e}")
                    else:
                        logging.error(f"JSON parsing error: {e}")

                    sleep(2 ** self.services[service_name]['retries'])  # Exponential backoff
                    self.services[service_name]['retries'] += 1

            raise Exception(f"Failed to validate response from {service_name} after multiple attempts.")

    def check_required_fields(self, data, service_name):
        validation_rules = self.services[service_name]['validation_rules']
        for field in validation_rules['required']:
            if field not in data:
                raise ValueError(f"Missing required field: {field}")

    def map_to_unified_format(self, data, service_name):
        validation_rules = self.services[service_name]['validation_rules']
        mapped_profile = {
            'access_token': data.get(validation_rules['mapping'].get('access_token', 'access_token')),
            'user_id': data.get(validation_rules['mapping'].get('user_id', 'user_id'))
        }

        optional_fields = validation_rules.get('optional', {})
        for local_field, remote_field in optional_fields.items():
            mapped_profile[local_field] = data.get(remote_field)

        return mapped_profile

# Example usage
validator = APIResponseValidator()
validator.add_service(
    'service1',
    {
        'required': ['access_token', 'user_id'],
        'mapping': {'access_token': 'access_token', 'user_id': 'user_id'},
        'optional': {'email': 'email'}
    }
)

# Simulate response
response = requests.Response()
response.status_code = 200
response._content = b'{"access_token": "token1", "user_id": "id1"}'
validator.validate_response('service1', response)
