#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define MAX_COMMAND_LENGTH 256

void logMessage(const char* message) {
    // Implement logging functionality here
    printf("%s\n", message);
}

int runCommandBackground(const char* command, int timeout, int retries) {
    pid_t pid;
    time_t start_time = time(NULL);
    int result = 0;

    for (int i = 0; i < retries; i++) {
        pid = fork();
        if (pid == -1) {
            logMessage("Error: Fork failed");
            return 0;
        } else if (pid == 0) {
            // Child process
            execl("/bin/sh", "sh", "-c", command, NULL);
            _exit(EXIT_FAILURE);
        }

        // Parent process
        time_t current_time = time(NULL);
        while (current_time - start_time < timeout && waitpid(pid, NULL, WNOHANG) == 0) {
            sleep(1); // Check every second
            current_time = time(NULL);
        }

        if (waitpid(pid, NULL, WNOHANG) != 0) {
            logMessage("Command started successfully in background");
            return 1;
        } else {
            logMessage("Error: Command failed to start within the specified timeout");
        }
    }

    logMessage("Error: Failed to start command after retries");
    return 0;
}

int main() {
    const char* command = "sleep 5";
    int timeout = 3;
    int retries = 2;

    if (runCommandBackground(command, timeout, retries)) {
        printf("Command started successfully.\n");
    } else {
        printf("Failed to start command.\n");
    }

    return 0;
}
