// Import necessary modules and libraries
const axios = require('axios');
const { WorkerPool } = require('workerpool');

// Define a class to handle the reduction logic
class AsyncReduce {
  constructor(serviceUrl) {
    this.serviceUrl = serviceUrl;
    this.workerPool = new WorkerPool('./reduceWorker.js', { maxWorkers: 4 });
  }

  async fetchNumber(index) {
    try {
      const response = await axios.get(`${this.serviceUrl}/${index}`);
      return response.data.number;
    } catch (error) {
      console.error(`Error fetching number at index ${index}:`, error.message);
      throw new Error('Failed to fetch number');
    }
  }

  async reduceArray(array, initialValue, callback) {
    if (!Array.isArray(array)) throw new Error('Input must be an array');
    if (typeof initialValue !== 'number') throw new Error('Initial value must be a number');

    const chunkSize = Math.ceil(array.length / this.workerPool.maxWorkers);
    let result = initialValue;

    for (let i = 0; i < array.length; i += chunkSize) {
      const chunk = array.slice(i, i + chunkSize);
      await Promise.all(chunk.map(async (num, index) => {
        try {
          const fetchedNum = await this.fetchNumber(index);
          result = callback(result, fetchedNum);
          console.log(`Processed number at index ${index}:`, fetchedNum);
        } catch (error) {
          console.error('Error processing chunk:', error.message);
          throw new Error('Failed to process chunk');
        }
      }));
    }

    return result;
  }

  async shutdown() {
    await this.workerPool.shutdown();
  }
}

// Worker script (reduceWorker.js)
module.exports = function(index) {
  // Simulate fetching number from an external service
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (index % 2 === 0) {
        resolve({ number: index * 2 });
      } else {
        reject(new Error('Failed to fetch number'));
      }
    }, 100);
  });
};

// Example usage
(async () => {
  const serviceUrl = 'http://example.com/api/numbers';
  const asyncReduce = new AsyncReduce(serviceUrl);

  try {
    const array = [1, 2, 3, 4, 5];
    const initialValue = 0;
    const callback = (acc, num) => acc + num;

    const result = await asyncReduce.reduceArray(array, initialValue, callback);
    console.log('Final reduced value:', result);
  } catch (error) {
    console.error('Error during reduction:', error.message);
  } finally {
    await asyncReduce.shutdown();
  }
})();
```

