        perror("Error opening directory");
        return -1;
    }

    size_t count = 0, converted = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg")) {
            char jpegFile[256], pdfFile[256];
            snprintf(jpegFile, sizeof(jpegFile), "%s/%s", inputDir, entry->d_name);
            snprintf(pdfFile, sizeof(pdfFile), "%s/%zu.pdf", outputDir, count / maxPagesPerPdf);

            result = convertJpegToPdf(jpegFile, pdfFile);
            if (result != 0) {
                fprintf(stderr, "Conversion failed for %s\n", jpegFile);
                break;
            }

            converted++;
            displayProgressBar(converted, count);
        }
    }

    closedir(dir);
    printf("\n");
    return result == 0 ? 0 : -1;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_directory> <output_directory> <max_pages_per_pdf>\n", argv[0]);
        return 1;
    }

    const char *inputDir = argv[1];
    const char *outputDir = argv[2];
    size_t maxPagesPerPdf = atoi(argv[3]);

    if (maxPagesPerPdf == 0) {
        fprintf(stderr, "Invalid maximum pages per PDF\n");
        return 1;
    }

    int result = batchConvertJpegToPdf(inputDir, outputDir, maxPagesPerPdf);
    if (result != 0) {
        fprintf(stderr, "Batch conversion failed\n");
        return 1;
    }

    printf("Batch conversion completed successfully\n");
    return 0;
}
