    {
        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            LogError($"Missing web.config file at {directoryPath}");
            return "ERROR: Missing web.config file.";
        }

        try
        {
            // Simulate API call to add website
            await AddWebsiteToServer(siteName, configSettings);
            LogInfo($"Successfully added website {siteName}.");
        }
        catch (Exception ex)
        {
            LogError($"Failed to add website: {ex.Message}");
            return $"ERROR: Failed to add website. Error: {ex.Message}";
        }

        return "Website added and started successfully.";
    }

    public async Task<string> CalculateFileMd5(string filePath, long? resumeFromByte = null)
    {
        if (string.IsNullOrEmpty(filePath))
        {
            LogError("Invalid file path.");
            return null;
        }

        using (var md5 = MD5.Create())
        using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 4096, true))
        {
            if (resumeFromByte.HasValue && resumeFromByte.Value > 0)
            {
                await stream.SeekAsync(resumeFromByte.Value, SeekOrigin.Begin);
            }

            using (var hashStream = new HashAlgorithmStream(md5))
            {
                await stream.CopyToAsync(hashStream);
            }

            return BitConverter.ToString(hashStream.MD5Hash).Replace("-", "").ToLower();
        }
    }

