    {
        // Simulate API call
        await Task.Delay(1000); // Simulating a delay
    }

    private static void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    private static void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}

public class HashAlgorithmStream : Stream
{
    private readonly MD5 _hash;
    private byte[] _buffer = new byte[4096];
    public byte[] MD5Hash { get; private set; }

    public HashAlgorithmStream(MD5 hash)
    {
        _hash = hash;
    }

    public override bool CanRead => true;
    public override bool CanSeek => false;
    public override bool CanWrite => false;
    public override long Length => throw new NotSupportedException();
    public override long Position
    {
        get => throw new NotSupportedException();
        set => throw new NotSupportedException();
    }

    public override void Flush()
    {
    }

    public override int Read(byte[] buffer, int offset, int count)
    {
        throw new NotSupportedException();
    }

    public override long Seek(long offset, SeekOrigin origin)
    {
        throw new NotSupportedException();
    }

    public override void SetLength(long value)
    {
        throw new NotSupportedException();
    }

    public override void Write(byte[] buffer, int offset, int count)
    {
        _hash.TransformBlock(buffer, offset, count, null, 0);
        Array.Copy(buffer, offset, _buffer, 0, Math.Min(count, _buffer.Length));
        int remaining = count - _buffer.Length;
        while (remaining > 0)
        {
            _hash.TransformBlock(_buffer, 0, Math.Min(4096, remaining), null, 0);
            remaining -= 4096;
        }
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            MD5Hash = _hash.TransformFinalBlock(new byte[0], 0, 0);
        }
        base.Dispose(disposing);
    }
}
