import java.io.*;
import java.net.*;
import javax.net.ssl.*;

public class SecureClient {

    public static void establishSecureConnection(String serverAddress, int port) {
        try (SSLSocketFactory sslSocketFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
             SSLSocket sslSocket = (SSLSocket) sslSocketFactory.createSocket(serverAddress, port)) {

            // Start TLS handshake
            sslSocket.startHandshake();

            // Set up input and output streams for secure communication
            try (
                BufferedReader in = new BufferedReader(new InputStreamReader(sslSocket.getInputStream()));
                PrintWriter out = new PrintWriter(sslSocket.getOutputStream(), true)
            ) {
                // Send a message to the server
                out.println("Hello, Server!");

                // Read response from the server
                String response;
                while ((response = in.readLine()) != null) {
                    System.out.println("Server: " + response);
                }
            }

        } catch (SSLException e) {
            System.err.println("SSL handshake failed.");
            e.printStackTrace();
        } catch (IOException e) {
            System.err.println("I/O error occurred.");
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String serverAddress = "example.com";
        int port = 443; // Default HTTPS port
        establishSecureConnection(serverAddress, port);
    }
}
```

