// Define the disjoint set class using Union-Find data structure
class DisjointSet {
public:
    DisjointSet(size_t size) : m_parents(size), m_ranks(size, 0) {
        for (size_t i = 0; i < size; ++i) {
            m_parents[i] = i;
        }
    }

    int find(int u) {
        if (m_parents[u] != u) {
            m_parents[u] = find(m_parents[u]);
        }
        return m_parents[u];
    }

    void unionSet(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (m_ranks[rootU] > m_ranks[rootV]) {
                m_parents[rootV] = rootU;
            } else if (m_ranks[rootU] < m_ranks[rootV]) {
                m_parents[rootU] = rootV;
            } else {
                m_parents[rootV] = rootU;
                ++m_ranks[rootU];
            }
        }
    }

private:
    std::vector<int> m_parents;
    std::vector<int> m_ranks;
};

