public class ChatApplication {
    private ExecutorService pool;
    private List<MessageAdapter> adapters;

    public ChatApplication() {
        this.pool = Executors.newCachedThreadPool();
        this.adapters = new ArrayList<>();
        loadAdapters();
    }

    // Method to load and initialize message adapters
    private void loadAdapters() {
        // Load SMS adapter
        adapters.add(new SMSMessageAdapter());

        // Load Email adapter
        adapters.add(new EmailMessageAdapter());

        // Load Social Media adapter
        adapters.add(new SocialMediaMessageAdapter());
    }

    // Method to send a message using an external service
    public void sendMessage(String message, String recipient) {
        for (MessageAdapter adapter : adapters) {
            if (adapter.supports(recipient)) {
                pool.execute(() -> adapter.sendMessage(message, recipient));
                break;
            }
        }
    }

    // Main method to start the chat application
    public static void main(String[] args) {
        ChatApplication app = new ChatApplication();
        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.println("Enter message (or 'exit' to quit):");
            String message = scanner.nextLine();
            if ("exit".equalsIgnoreCase(message)) break;

            System.out.println("Enter recipient:");
            String recipient = scanner.nextLine();

            app.sendMessage(message, recipient);
        }
    }
}

