// Import necessary modules
const WebSocket = require('ws');
const express = require('express');
const bodyParser = require('body-parser');
const cassandra = require('cassandra-driver');

// Initialize Cassandra client
const client = new cassandra.Client({ contactPoints: ['127.0.0.1'], keyspace: 'iot_data' });
client.connect();

// Initialize WebSocket server and express app
const wss = new WebSocket.Server({ port: 8080 });
const app = express();
app.use(bodyParser.json());

// Function to handle sensor data storage
async function storeData(deviceId, timestamp, data) {
    try {
        await client.execute('INSERT INTO sensor_data (device_id, timestamp, data) VALUES (?, ?, ?)', [deviceId, timestamp, data]);
    } catch (error) {
        console.error('Error storing data:', error);
    }
}

// WebSocket connection handler
wss.on('connection', async function connection(ws) {
    ws.on('message', async function incoming(message) {
        const { deviceId, timestamp, data } = JSON.parse(message);
        await storeData(deviceId, timestamp, data);
    });

    ws.on('close', function close() {
        console.log('Client disconnected');
    });
});

// RESTful API for data retrieval
app.get('/data', async (req, res) => {
    try {
        const result = await client.execute('SELECT * FROM sensor_data ALLOW FILTERING');
        res.json(result.rows);
    } catch (error) {
        console.error('Error fetching data:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Start the WebSocket server and express app
wss.on('listening', () => {
    console.log('WebSocket server started on port 8080');
});
app.listen(3000, () => {
    console.log('Express server started on port 3000');
});
