public interface ICmsProvider
{
    string Name { get; }
    Task<string> FetchContentAsync(string elementId);
    Task<bool> UpdateElementAsync(string elementId, string newHtml);
}

public class WordPressCms : ICmsProvider
{
    public string Name => "WordPress";
    private readonly HttpClient _httpClient;

    public WordPressCms(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<string> FetchContentAsync(string elementId)
    {
        // Implement logic to fetch content from WordPress
        return await _httpClient.GetStringAsync($"https://example.com/wp-json/wp/v2/posts?element_id={elementId}");
    }

    public async Task<bool> UpdateElementAsync(string elementId, string newHtml)
    {
        // Implement logic to update content in WordPress
        var request = new HttpRequestMessage(HttpMethod.Put, $"https://example.com/wp-json/wp/v2/posts/{elementId}")
        {
            Content = new StringContent(newHtml, System.Text.Encoding.UTF8, "application/json")
        };
        var response = await _httpClient.SendAsync(request);
        return response.IsSuccessStatusCode;
    }
