public class CustomCms : ICmsProvider
{
    public string Name => "Custom";
    private readonly HttpClient _httpClient;

    public CustomCms(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<string> FetchContentAsync(string elementId)
    {
        // Implement logic to fetch content from custom CMS
        return await _httpClient.GetStringAsync($"https://example.com/custom/api/content/{elementId}");
    }

    public async Task<bool> UpdateElementAsync(string elementId, string newHtml)
    {
        // Implement logic to update content in custom CMS
        var request = new HttpRequestMessage(HttpMethod.Post, $"https://example.com/custom/api/update")
        {
            Content = new StringContent($"{{\"element_id\": \"{elementId}\", \"html\": \"{newHtml}\"}}", System.Text.Encoding.UTF8, "application/json")
        };
        var response = await _httpClient.SendAsync(request);
        return response.IsSuccessStatusCode;
    }
}

public class CmsMiddleware
{
    private readonly Dictionary<string, ICmsProvider> _cmsProviders;

    public CmsMiddleware()
    {
        _cmsProviders = new Dictionary<string, ICmsProvider>
        {
            { "WordPress", new WordPressCms(new HttpClient()) },
            { "Drupal", new DrupalCms(new HttpClient()) },
            { "Custom", new CustomCms(new HttpClient()) }
        };
    }

    public async Task<string> UpdateElementAsync(string cmsName, string elementId, string newHtml)
    {
        if (!_cmsProviders.ContainsKey(cmsName))
        {
            throw new ArgumentException($"CMS provider '{cmsName}' not supported.");
        }

        var cmsProvider = _cmsProviders[cmsName];
        try
        {
            bool updateSuccess = await cmsProvider.UpdateElementAsync(elementId, newHtml);
            if (updateSuccess)
            {
                return $"Content updated successfully on {cmsProvider.Name}.";
            }
            else
            {
                return $"Failed to update content on {cmsProvider.Name}.";
            }
        }
        catch (Exception ex)
        {
            // Log exception details for debugging
            Console.WriteLine($"Error updating content: {ex.Message}");
            return $"An error occurred while updating content on {cmsProvider.Name}: {ex.Message}";
        }
    }
}
