public class WeatherDataUpdaterMiddleware
{
    private string latitude;
    private string longitude;
    private Random random = new Random();
    private Dictionary<string, Func<double>> weatherGenerators = new Dictionary<string, Func<double>>();

    public WeatherDataUpdaterMiddleware(string latitude, string longitude)
    {
        this.latitude = latitude;
        this.longitude = longitude;
        InitializeWeatherGenerators();
    }

    private void InitializeWeatherGenerators()
    {
        // Initialize with default ranges and distributions
        weatherGenerators["Temperature"] = () => random.NextDouble() * 40 - 10; // Range: -10 to 30 degrees Celsius
        weatherGenerators["Humidity"] = () => random.NextDouble() * 60 + 40; // Range: 40% to 100%
        weatherGenerators["WindSpeed"] = () => random.NextDouble() * 25; // Range: 0 to 25 km/h
        weatherGenerators["Precipitation"] = () => random.NextDouble() * 10; // Range: 0 to 10 mm
    }

    public void SetWeatherGenerator(string condition, Func<double> generator)
    {
        if (weatherGenerators.ContainsKey(condition))
        {
            weatherGenerators[condition] = generator;
        }
    }

    public double GetWeatherCondition(string condition)
    {
