        {
            var value = GetWeatherCondition(condition);
            // Simulate updating an HTML element with the weather value
            Console.WriteLine($"Updating {elementId} with {condition}: {value}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error updating element {elementId}: {ex.Message}");
        }
    }

    public override string ToString()
    {
        var currentWeather = new Dictionary<string, double>();
        foreach (var condition in weatherGenerators.Keys)
        {
            currentWeather[condition] = GetWeatherCondition(condition);
        }
        return $"Current Weather: {string.Join(", ", currentWeather)} | Data Source: Simulated";
    }
