    private ConcurrentDictionary<string, Func<float>> _distributionCache = new ConcurrentDictionary<string, Func<float>>();
    private string _currentDistribution;
    private object _lockObject = new object();

    public void SetDistribution(string distributionType, params float[] parameters)
    {
        lock (_lockObject)
        {
            if (!_distributionCache.ContainsKey(distributionType))
            {
                _distributionCache[distributionType] = GenerateRandomValue(distributionType, parameters);
            }
            _currentDistribution = distributionType;
        }
    }

    public float GetRandomFloat()
    {
        lock (_lockObject)
        {
            return _distributionCache[_currentDistribution]();
        }
    }

    public int GetRandomInt(int min, int max)
    {
        lock (_lockObject)
        {
            switch (_currentDistribution)
            {
                case "Uniform":
                    return UnityEngine.Random.Range(min, max);
                default:
                    throw new InvalidOperationException("Unsupported distribution type for integer generation.");
            }
        }
    }

    public override string ToString()
    {
        lock (_lockObject)
        {
            return $"Range: {0}-{int.MaxValue}, Distribution: {_currentDistribution}";
        }
    }

    private Func<float> GenerateRandomValue(string distributionType, float[] parameters)
    {
        switch (distributionType)
        {
            case "Uniform":
                return () => UnityEngine.Random.Range(parameters[0], parameters[1]);
            case "Gaussian":
