```php
<?php

function generateSecurePassword($length = 10, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $algorithm = PASSWORD_DEFAULT) {
    // Validate input length
    if ($length < 8 || $length > 64) {
        throw new InvalidArgumentException("Length must be between 8 and 64 characters.");
    }

    // Validate character set
    if (strlen($charset) < $length) {
        throw new InvalidArgumentException("Character set is too small for the specified length.");
    }

    // Generate a random salt
    $salt = substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 1, $length);

    try {
        // Hash the password using the provided algorithm and salt
        $hashedPassword = password_hash($salt . $salt, $algorithm);
    } catch (Exception $e) {
        error_log("Error hashing password: " . $e->getMessage());
        throw new Exception("Failed to hash password.");
    }

    return [
        'salt' => $salt,
        'password' => $hashedPassword
    ];
}

function checkPassword($providedPassword, $storedHashedPassword, $storedSalt) {
    try {
        // Verify the provided password against the stored hashed password and salt
        return password_verify($storedSalt . $providedPassword, $storedHashedPassword);
    } catch (Exception $e) {
        error_log("Error verifying password: " . $e->getMessage());
        throw new Exception("Failed to verify password.");
    }
}

?>
