#[derive(Debug)]
enum HttpClientError {
    Reqwest(ReqwestError),
    AuthenticationFailed,
    // Add other custom error types here
}

struct HttpClientConfig {
    disable_certificate_validation: bool,
    retries: usize,
    retry_interval: Duration,
    timeout: Duration,
    custom_headers: HashMap<String, String>,
}

fn create_http_client(config: HttpClientConfig) -> Result<RequestBuilder, HttpClientError> {
    let mut client_builder = Client::builder()
        .timeout(config.timeout)
        .tcp_keepalive(None);

    if config.disable_certificate_validation {
        client_builder = client_builder.dangerously_disable_hostname_verification();
    }

    for (key, value) in &config.custom_headers {
        client_builder = client_builder.header(key.clone(), value.clone());
    }

    let client = client_builder.build().map_err(HttpClientError::Reqwest)?;

    Ok(client.request(reqwest::Method::GET, "https://example.com"))
}

fn main() -> Result<(), HttpClientError> {
    let config = HttpClientConfig {
        disable_certificate_validation: true,
        retries: 3,
        retry_interval: Duration::from_secs(2),
        timeout: Duration::from_secs(10),
        custom_headers: HashMap::new(),
    };

    let request_builder = create_http_client(config)?;
    // Continue with the HTTP request and handling logic
    Ok(())
}
