#include <openssl/conf.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <fstream>
#include <memory>
#include <vector>
#include <string>

class SecureMessagingLibrary {
public:
    SecureMessagingLibrary(const std::string& config, const std::string& logFile) {
        if (!initOpenSSL(config)) {
            logError("Failed to initialize OpenSSL.");
        }
        openLogFile(logFile);
    }

    ~SecureMessagingLibrary() {
        closeLogFile();
        EVP_cleanup();
        CONF_modules_free();
    }

    void copyBytesToBuffer(std::vector<std::unique_ptr<uint8_t[]>>& dataChunks, uint8_t* newBuffer, size_t bytesToCopy) {
        size_t totalBytes = 0;
        for (auto& chunk : dataChunks) {
            if (totalBytes + chunk.get()[bytesToCopy - totalBytes] <= bytesToCopy) {
                std::copy(chunk.get(), chunk.get() + chunk.size(), newBuffer);
                totalBytes += chunk->size();
            } else {
                std::copy(chunk.get(), chunk.get() + bytesToCopy - totalBytes, newBuffer);
                break;
            }
        }
    }

private:
    bool initOpenSSL(const std::string& config) {
        if (CONF_modules_load_file(config.c_str(), NULL) <= 0) {
            return false;
        }
        OpenSSL_add_all_algorithms();
        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_cipher(EVP_chacha20_poly1305());
        EVP_add_digest(EVP_sha256());
        EVP_add_digest(EVP_sha384());
        EVP_add_digest(EVP_sha512());
        return true;
    }

    void openLogFile(const std::string& logFile) {
        logStream.open(logFile, std::ios::app);
    }

    void closeLogFile() {
        if (logStream.is_open()) {
            logStream.close();
        }
    }

    void logError(const std::string& error) {
        if (logStream.is_open()) {
            logStream << "ERROR: " << error << "\n";
        } else {
            // Fallback to standard error in case file opening fails
            std::cerr << "ERROR: " << error << "\n";
        }
    }

    std::ofstream logStream;
};
```

