const express = require('express');
const axios = require('axios');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Configuration for external APIs
const weatherAPIKey = 'your_openweathermap_api_key';
const climateAPIKey = 'your_climateapi_api_key';

// External API endpoints
const openWeatherMapURL = `https://api.openweathermap.org/data/2.5/weather`;
const climateDataURL = `https://api.climateapi.com/v1/monthly`;

// Function to fetch weather data from OpenWeatherMap
async function getWeatherData(location) {
  try {
    const response = await axios.get(openWeatherMapURL, {
      params: {
        q: location,
        appid: weatherAPIKey,
        units: 'metric'
      }
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching weather data:', error);
    throw new Error('Failed to fetch weather data');
  }
}

// Function to fetch climate data from Climate API
async function getClimateData(location, month, year) {
  try {
    const response = await axios.get(climateDataURL, {
      params: {
        location,
        month,
        year,
        appid: climateAPIKey
      }
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching climate data:', error);
    throw new Error('Failed to fetch climate data');
  }
}

// Route to get weather and climate data for a given location
app.get('/data', async (req, res) => {
  try {
    const { location } = req.query;
    const [weatherData, climateData] = await Promise.all([
      getWeatherData(location),
      getClimateData(location, new Date().getMonth() + 1, new Date().getFullYear())
    ]);
    res.status(200).json({ weather: weatherData, climate: climateData });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Secure messaging library using C++ and OpenSSL
const cryptoLib = require('./cryptoLibrary'); // Assume this is your C++ library wrapper

// Encryption function
function encryptMessage(message, key, algorithm) {
  const cipher = crypto.createCipheriv(algorithm, Buffer.from(key), iv);
  let encrypted = cipher.update(message, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
}

// Hashing function
function hashData(data, algorithm) {
  const hash = crypto.createHash(algorithm).update(data).digest('hex');
  return hash;
}

// Rate limiting middleware (using Express-rate-limit)
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
