```java
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;

public class CommandExecutor {

    public static void main(String[] args) {
        File logFile = new File("errorLog.txt");
        try {
            executeCommand(logFile, "ls -l /nonexistent_directory");
        } catch (IOException e) {
            System.err.println("Error occurred while executing command: " + e.getMessage());
        }
    }

    public static void executeCommand(File logFile, String command) throws IOException {
        File dir = new File("/path/to/directory"); // Replace with actual directory
        if (dir.exists()) {
            deleteDirectory(dir);
        }
        Process process = Runtime.getRuntime().exec(command, null, dir);

        logStream(process.getInputStream(), "stdout", logFile);
        logStream(process.getErrorStream(), "stderr", logFile);

        try {
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Process interrupted");
        }
    }

    private static void deleteDirectory(File dir) throws IOException {
        File[] files = dir.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    deleteDirectory(file);
                } else {
                    if (!file.delete()) {
                        throw new IOException("Failed to delete file: " + file.getAbsolutePath());
                    }
                }
            }
        }
        if (!dir.delete()) {
            throw new IOException("Failed to delete directory: " + dir.getAbsolutePath());
        }
    }

    private static void logStream(BufferedReader reader, String streamName, File logFile) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(logFile, true))) {
            String line;
            while ((line = reader.readLine()) != null) {
                writer.write(String.format("%s [%s]: %s%n", java.time.LocalDateTime.now(), streamName, line));
                System.out.println(line);
            }
        }
    }
}
```

This Java program includes a `CommandExecutor` class with a `main` method to demonstrate the functionality. It defines an `executeCommand` method that logs messages to an error log if a given condition is met using `snprintf`-like formatting. The method first checks and deletes a file if it exists, then executes a command using `Runtime.getRuntime().exec(String, String, File)`. The output and error streams of the executed command are read and logged using the `logStream` method. The logging function is coherent and integrated into the overall structure of the Java program.

