public class WebSiteManager
{
    private readonly string _configFilePath;
    private readonly List<string> _siteNames;
    private readonly HashSet<string> _operations;
    private readonly HttpClient _httpClient;

    public WebSiteManager(string configFilePath, List<string> siteNames, HashSet<string> operations)
    {
        _configFilePath = configFilePath;
        _siteNames = siteNames;
        _operations = operations;
        _httpClient = new HttpClient();
    }

    public async Task ManageWebsiteLifecycleAsync()
    {
        foreach (var siteName in _siteNames)
        {
            if (!Directory.Exists(siteName))
            {
                Console.WriteLine($"Error: Directory {siteName} does not exist.");
                continue;
            }

            var configFilePath = Path.Combine(siteName, "web.config");
            if (!File.Exists(configFilePath))
            {
                Console.WriteLine($"Error: web.config file missing in directory {siteName}.");
                continue;
            }

            foreach (var operation in _operations)
            {
                try
                {
                    await PerformOperationAsync(siteName, operation);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error performing {operation} on {siteName}: {ex.Message}");
                }
            }
        }
    }

    private async Task PerformOperationAsync(string siteName, string operation)
    {
        var url = $"https://api.example.com/websites/{siteName}/{operation}";
        var response = await _httpClient.GetAsync(url);

        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"API call failed with status code: {response.StatusCode}");
        }
    }

    public static void Main(string[] args)
    {
        // Command-line parsing and validation
