using System;
using System.Collections.Concurrent;
using UnityEngine;

public class DynamicValueGenerator
{
    private static readonly ConcurrentDictionary<string, object> distributionCache = new ConcurrentDictionary<string, object>();
    private string currentDistribution;
    private object[] distributionParameters;

    public DynamicValueGenerator(string distributionType, params object[] parameters)
    {
        SetDistribution(distributionType, parameters);
    }

    public float GetRandomFloat(float min, float max)
    {
        switch (currentDistribution)
        {
            case "Uniform":
                return UnityEngine.Random.Range(min, max);
            // Add cases for Gaussian and Exponential distributions here
            default:
                throw new ArgumentException("Invalid distribution type");
        }
    }

    public int GetRandomInt(int min, int max)
    {
        switch (currentDistribution)
        {
            case "Uniform":
                return UnityEngine.Random.Range(min, max + 1);
            // Add cases for Gaussian and Exponential distributions here
            default:
                throw new ArgumentException("Invalid distribution type");
        }
    }

    public void SetDistribution(string distributionType, params object[] parameters)
    {
        if (!distributionCache.TryGetValue(distributionType, out var distribution))
        {
            switch (distributionType)
            {
                case "Uniform":
                    distribution = new UniformDistribution();
                    break;
                // Add cases for Gaussian and Exponential distributions here
                default:
                    throw new ArgumentException("Invalid distribution type");
            }
            distributionCache.TryAdd(distributionType, distribution);
        }

        currentDistribution = distributionType;
        distributionParameters = parameters;
    }

    public override string ToString()
    {
        return $"Range: ({currentDistribution}) {string.Join(", ", distributionParameters)}";
    }
}

public interface IDistribution
{
    float GenerateFloat(float min, float max);
    int GenerateInt(int min, int max);
}

public class UniformDistribution : IDistribution
{
    public float GenerateFloat(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }

    public int GenerateInt(int min, int max)
    {
        return UnityEngine.Random.Range(min, max + 1);
    }
}
