// This is a high-level overview and cannot be run as-is.
// It serves as a starting point for designing a scalable inventory management system.

import java.util.concurrent.ConcurrentHashMap;
import java.util.List;

public class InventoryManager {

    private ConcurrentHashMap<String, Integer> inventoryCache = new ConcurrentHashMap<>();
    private List<Warehouse> warehouses;
    private PaymentGateway paymentGateway;
    private Logger logger;

    public InventoryManager(List<Warehouse> warehouses, PaymentGateway paymentGateway, Logger logger) {
        this.warehouses = warehouses;
        this.paymentGateway = paymentGateway;
        this.logger = logger;
    }

    public synchronized void updateStock(String productId, int quantity) {
        // Update inventory in real-time across multiple warehouses
        for (Warehouse warehouse : warehouses) {
            warehouse.updateStock(productId, quantity);
        }
        // Update cache with the latest stock levels
        inventoryCache.put(productId, getCombinedStockLevels(productId));
    }

    public boolean processTransaction(String productId, int quantity, String paymentMethod) {
        try {
            if (inventoryCache.get(productId) >= quantity) {
                // Process payment through external gateway
                paymentGateway.processPayment(quantity * getPricePerUnit(productId), paymentMethod);
                // Update inventory
                updateStock(productId, -quantity);
                logger.log("Transaction successful for product: " + productId);
                return true;
            } else {
                logger.log("Insufficient stock for product: " + productId);
                return false;
            }
        } catch (Exception e) {
            logger.log("Error processing transaction for product: " + productId, e);
            return false;
        }
    }

    public int getCombinedStockLevels(String productId) {
        // Calculate combined stock levels from all warehouses
        int totalStock = 0;
        for (Warehouse warehouse : warehouses) {
            totalStock += warehouse.getStockLevel(productId);
        }
        return totalStock;
    }

    private double getPricePerUnit(String productId) {
        // Retrieve price per unit from database or external API
        return 10.99; // Example hardcoded value
    }
}

interface Warehouse {
    void updateStock(String productId, int quantity);
    int getStockLevel(String productId);
}

interface PaymentGateway {
    boolean processPayment(double amount, String paymentMethod) throws Exception;
}

interface Logger {
    void log(String message);
    void log(String message, Throwable throwable);
}
