def render_script_tags(script_objects):
    html = []
    for script in script_objects:
        if not isinstance(script, dict) or 'src' not in script:
            continue  # Skip invalid script objects

        async_attr = 'async' if script['src'].startswith('http') else ''
        type_attr = f'type="{script.get("type", "text/javascript")}"' if 'type' in script else ''

        html.append(f'<script src="{script["src"]}" {type_attr} {async_attr}></script>')

    return '\n'.join(html)
