using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using YourNamespace.Services;

[ApiController]
[Route("api/[controller]")]
public class HtmlController : ControllerBase
{
    private readonly IHtmlService _htmlService;
    private readonly ILogger<HtmlController> _logger;

    public HtmlController(IHtmlService htmlService, ILogger<HtmlController> logger)
    {
        _htmlService = htmlService;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent, int? versionId)
    {
        try
        {
            // Validate input IDs
            if (pageSectionId <= 0 || elementId <= 0)
                return BadRequest("Invalid page section or element ID.");

            // Check user permissions
            if (!await _htmlService.HasPermissionAsync(pageSectionId, elementId))
                return Forbid();

            // Update element HTML content atomically
            var updateResult = await _htmlService.UpdateHtmlContentAsync(pageSectionId, elementId, htmlContent, versionId);
            if (updateResult)
            {
                _logger.LogInformation($"Element {elementId} in page section {pageSectionId} updated successfully.");
                return StatusCode(204); // No Content - Successful update
            }
            else
            {
                _logger.LogWarning($"Failed to update element {elementId} in page section {pageSectionId}. Conflict detected.");
                return Conflict(); // Conflict - Concurrent update detected
            }
        }
        catch (ServiceException ex)
        {
            _logger.LogError(ex, "Service error occurred while updating HTML content.");
            return StatusCode(500, "Internal server error.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unexpected error occurred while updating HTML content.");
            return StatusCode(500, "Internal server error.");
        }
    }
}
