    private readonly IDatabaseContext _databaseContext;

    public HtmlService(ICachingService cachingService, IDatabaseContext databaseContext)
    {
        _cachingService = cachingService;
        _databaseContext = databaseContext;
    }

    public async Task<bool> HasPermissionAsync(int pageSectionId, int elementId)
    {
        // Implement permission check logic
        return true; // Placeholder
    }

    public async Task<bool> UpdateHtmlContentAsync(int pageSectionId, int elementId, string htmlContent, int? versionId)
    {
        try
        {
            using (var transaction = await _databaseContext.Database.BeginTransaction())
            {
                var element = await _databaseContext.Elements.FindAsync(elementId);
                if (element == null || (versionId.HasValue && element.VersionId != versionId.Value))
                    return false;

                element.HtmlContent = htmlContent;
                element.VersionId++;
                await _databaseContext.SaveChangesAsync();

                // Invalidate cache for the updated element
                await _cachingService.RemoveAsync($"element_{elementId}");

                await transaction.CommitAsync();
                return true;
            }
        }
        catch (Exception)
        {
            await _databaseContext.Database.RollbackTransactionAsync();
            throw;
        }
    }
}
