```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <windows.h>
#include <sql.h>
#include <sqlext.h>

#define MAX_LINE_LENGTH 256
#define MAX_RECORDS 1000000

typedef struct {
    int id;
    long offset1, offset2;
    int key;
    double average;
} Record;

void processTextFile(const char* filePath, SQLHENV hEnv, SQLHDBC hDbc) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open the text file.\n");
        return;
    }

    Record records[MAX_RECORDS];
    int recordCount = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        Record* newRecord = realloc(records, (recordCount + 1) * sizeof(Record));
        if (!newRecord) {
            fprintf(stderr, "Memory allocation failed.\n");
            fclose(file);
            return;
        }
        records = newRecord;

        // Assuming the text file format: id offset1 offset2 key
        sscanf(line, "%d %ld %ld %d", &records[recordCount].id, 
               &records[recordCount].offset1, &records[recordCount].offset2, &records[recordCount].key);

        // Calculate average of the last two fields
        records[recordCount].average = (double)(records[recordCount].offset1 + records[recordCount].offset2) / 2.0;

        recordCount++;
    }

    fclose(file);

    // Process records and interact with SQL server here
    for (int i = 0; i < recordCount; i++) {
        // Example SQL query to insert or update records in the database
        char sqlQuery[1024];
        sprintf(sqlQuery, "INSERT INTO MyTable (id, offset1, offset2, key, average) VALUES (%d, %ld, %ld, %d, %.2f)",
                records[i].id, records[i].offset1, records[i].offset2, records[i].key, records[i].average);

        SQLHSTMT hStmt;
        if (SQLAllocHandle(SQL_HANDLE_STMT, hDbc, &hStmt) != SQL_SUCCESS) {
            fprintf(stderr, "Failed to allocate statement handle.\n");
            continue;
        }

        if (SQLExecDirect(hStmt, (SQLCHAR*)sqlQuery, SQL_NTS) != SQL_SUCCESS) {
            fprintf(stderr, "SQL error: %s\n", sqlQuery);
        }

        SQLFreeHandle(SQL_HANDLE_STMT, hStmt);
    }
}

int main() {
    // Initialize ODBC environment and connection
    SQLHENV hEnv;
    SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &hEnv);
    SQLSetEnvAttr(hEnv, SQL_ATTR_ODBC_VERSION, (SQLPOINTER)SQL_OV_ODBC3, 0);

    SQLHDBC hDbc;
    SQLAllocHandle(SQL_HANDLE_DBC, hEnv, &hDbc);
    // Set up connection attributes and connect to the SQL server
    // SQLConnect(hDbc, ...);

    processTextFile("data.txt", hEnv, hDbc);

    // Free handles and disconnect
    SQLDisconnect(hDbc);
    SQLFreeHandle(SQL_HANDLE_DBC, hDbc);
    SQLFreeHandle(SQL_HANDLE_ENV, hEnv);

    return 0;
}
```

