// FinancialApiService.js
class FinancialApiService {
  async fetchTransactionAmount(transactionId) {
    // Simulate network latency and rate limiting
    await new Promise(resolve => setTimeout(resolve, Math.random() * 100));

    if (Math.random() < 0.1) {
      throw new Error('Network error');
    }

