// TransactionReducer.js
const MAX_CONCURRENT_WORKERS = 5;
const FETCH_TIMEOUT = 5000;

class WorkerPool {
  constructor(service, maxConcurrentWorkers) {
    this.service = service;
    this.maxConcurrentWorkers = maxConcurrentWorkers;
    this.workers = [];
  }

  async processTransactions(transactionIds) {
    for (let i = 0; i < transactionIds.length; i += this.maxConcurrentWorkers) {
      const chunk = transactionIds.slice(i, i + this.maxConcurrentWorkers);
      await Promise.all(chunk.map(id => this.fetchTransactionAmount(id)));
    }
  }

  async fetchTransactionAmount(transactionId) {
    try {
      console.log(`Processing transaction ID: ${transactionId}`);
      const amount = await Promise.race([
        this.service.fetchTransactionAmount(transactionId),
        new Promise((_, reject) => setTimeout(reject, FETCH_TIMEOUT, 'Request timed out'))
      ]);
      console.log(`Processed transaction ID: ${transactionId}, Amount: ${amount}`);
      return amount;
    } catch (error) {
      console.error(`Failed to process transaction ID: ${transactionId}`, error);
      return 0; // Fallback mechanism for invalid or missing data
    }
  }
}

class TransactionReducer {
  constructor(transactionIds, maxConcurrentWorkers = MAX_CONCURRENT_WORKERS) {
    this.transactionIds = transactionIds;
    this.maxConcurrentWorkers = maxConcurrentWorkers;
    this.service = new FinancialApiService();
    this.workerPool = new WorkerPool(this.service, this.maxConcurrentWorkers);
  }

  async reduce() {
    console.log('Starting transaction reduction...');
    const startTime = Date.now();

    await this.workerPool.processTransactions(this.transactionIds);

    const endTime = Date.now();
    console.log(`Transaction reduction completed in ${endTime - startTime}ms`);

    return 'Total amount processed';
  }
}

// Usage
(async () => {
  const transactionReducer = new TransactionReducer(Array.from({ length: 10000 }, (_, i) => `id${i}`));
  await transactionReducer.reduce();
})();
```

