using System.Security.Cryptography;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly PaddingMode _paddingMode;

    public AesCbcDecryptor(byte[] key, byte[] iv, PaddingMode paddingMode)
    {
        ValidateKeyAndIV(key, iv);
        _key = key;
        _iv = iv;
        _paddingMode = paddingMode;
    }

    private void ValidateKeyAndIV(byte[] key, byte[] iv)
    {
        if (key.Length != 16 && key.Length != 24 && key.Length != 32)
            throw new ArgumentException("Invalid key length. Must be 16, 24, or 32 bytes.");

        if (iv.Length != 16)
            throw new ArgumentException("Invalid IV length. Must be 16 bytes.");
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext)
    {
        using var aes = Aes.Create();
        aes.Key = _key;
        aes.IV = _iv;
        aes.Padding = _paddingMode;

        using var msDecrypt = new MemoryStream(ciphertext);
        using var csDecrypt = new CryptoStream(msDecrypt, aes.CreateDecryptor(), CryptoStreamMode.Read);
        using var memoryStream = new MemoryStream();

        await csDecrypt.CopyToAsync(memoryStream);

        return memoryStream.ToArray();
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        byte[] key = new byte[32]; // Example key, replace with actual key retrieval logic
        byte[] iv = new byte[16];  // Example IV, replace with actual IV retrieval logic
        byte[] ciphertext = new byte[] { /* Replace with actual ciphertext */ };

        var decryptor = new AesCbcDecryptor(key, iv, PaddingMode.PKCS7);
        var plaintext = await decryptor.DecryptAsync(ciphertext);

        Console.WriteLine("Decrypted Text: " + Convert.ToBase64String(plaintext));
    }
}
