using Microsoft.Extensions.Logging;

public class WebServerManager
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<WebServerManager> _logger;
    private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private const int MaxRetries = 3;
    private const int RetryBackoffMilliseconds = 500;

    public WebServerManager(HttpClient httpClient, ILogger<WebServerManager> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> DeployWebsite(string directoryPath, string siteName, List<KeyValuePair<string, string>> environmentVariables)
    {
        if (!directoryPath.Contains("web.config") || !directoryPath.Contains("appsettings.json"))
        {
            return "Error: Missing web.config or appsettings.json file.";
        }

        if (!environmentVariables.All(IsValidEnvironmentVariable))
        {
            return "Error: Invalid environment variable format.";
        }

        for (int attempt = 1; attempt <= MaxRetries; attempt++)
        {
            try
            {
                await _semaphore.WaitAsync();
                await DeployToServer(directoryPath, siteName, environmentVariables);
                _logger.LogInformation($"Deployment successful: {siteName}");
                return "Deployment successful.";
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Attempt {attempt} failed: {ex.Message}");
                if (attempt < MaxRetries)
                {
                    await Task.Delay(RetryBackoffMilliseconds);
                }
                else
                {
                    return $"Error: Deployment failed after {MaxRetries} attempts.";
                }
            }
            finally
            {
                _semaphore.Release();
            }
        }

        throw new InvalidOperationException("Deployment failed.");
    }

    private async Task DeployToServer(string directoryPath, string siteName, List<KeyValuePair<string, string>> environmentVariables)
    {
        // Simulate API call to deploy website
        var content = new StringContent(JsonConvert.SerializeObject(new
        {
            DirectoryPath = directoryPath,
            SiteName = siteName,
            EnvironmentVariables = environmentVariables
        }));

        using (var response = await _httpClient.PostAsync("https://api.webserver.com/deploy", content))
        {
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"API error: {response.StatusCode} - {await response.Content.ReadAsStringAsync()}");
            }
        }
    }

    private bool IsValidEnvironmentVariable(KeyValuePair<string, string> envVar)
    {
        // Simple validation example
        return !string.IsNullOrEmpty(envVar.Key) && !string.IsNullOrEmpty(envVar.Value);
    }
}
