            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            logError("Deserialization error: ", e);
            throw e;
        }
    }

    public <T> void registerCustomDeserializer(Class<T> clazz, Object deserializer) {
