#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ITEMS 1000

typedef struct Resource {
    int id;
    char name[256];
} Resource;

typedef struct ResourceBundle {
    Resource items[MAX_ITEMS];
    int count;
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle* load_resource_bundle(const char* filename) {
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        perror("Failed to allocate memory for resource bundle");
        return NULL;
    }
    bundle->count = 0;
    pthread_mutex_init(&bundle->lock, NULL);

    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open resource bundle file");
        free(bundle);
        return NULL;
    }

    while (bundle->count < MAX_ITEMS && fscanf(file, "%d %255s", &bundle->items[bundle->count].id, bundle->items[bundle->count].name) == 2) {
        bundle->count++;
    }

    fclose(file);

    if (bundle->count == 0) {
        fprintf(stderr, "No items loaded from resource bundle file\n");
        free(bundle);
        return NULL;
    }

    return bundle;
}

void free_resource_bundle(ResourceBundle* bundle) {
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}
