import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SystemCommandExecutor {

    private static final String LOG_FILE_PATH = "path/to/logfile.log";
    private static final int MAX_CONCURRENT_COMMANDS = 10;
    private static final ExternalAPIClient apiClient = new ExternalAPIClient();

    public void executeCommands(String[] commands, String userId) {
        // Check if log file exists and delete it if necessary
        deleteLogFile(LOG_FILE_PATH);

        ExecutorService executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_COMMANDS);
        for (String command : commands) {
            executorService.submit(() -> {
                try {
                    executeCommand(command, userId);
                } catch (IOException | InterruptedException e) {
                    apiClient.logError("Error executing command: " + command, e.getMessage(), userId);
                }
            });
        }

        // Shutdown the executor service and wait for all tasks to complete
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private void deleteLogFile(String filePath) {
        // Implement file deletion logic here
    }

    private void executeCommand(String command, String userId) throws IOException, InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        processBuilder.redirectErrorStream(true);
        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            apiClient.logInfo(line, command, userId);
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            apiClient.logError("Command failed with exit code: " + exitCode, command, userId);
        }
    }
}

class ExternalAPIClient {
    public void logInfo(String message, String command, String userId) {
        // Implement API logging logic here
    }

    public void logError(String message, String errorDetails, String userId) {
        // Implement API logging logic here
    }
}
