class OffsetManager {
private:
    std::unordered_map<int, Record> records;
    HTMLService htmlService;
    DatabaseAPI dbAPI;
    std::mutex recordsMutex;
    std::condition_variable updateCV;
    int currentVersion = 0;

public:
    void handlePOSTRequest(int userID, int id, const std::string& content) {
        std::unique_lock<std::mutex> lock(recordsMutex);
        while (currentVersion != records[id].key) {
            updateCV.wait(lock);
        }
        if (!dbAPI.connect() || !dbAPI.validateInputID(id) || !dbAPI.checkUserPermissions(userID)) {
            throw std::runtime_error("Failed to handle POST request");
        }
        records[id].offset++;
        records[id].key = currentVersion;
        htmlService.updateElement(id, content);
        currentVersion++;
        lock.unlock();
        updateCV.notify_all();
    }

    void initRecords(const std::string& configPath) {
        if (!dbAPI.retrieveInitialValues(configPath, records)) {
            throw std::runtime_error("Failed to retrieve initial values from configuration file");
        }
    }
};

