        std::thread t2(&OffsetManager::handlePOSTRequest, &offsetManager, 1, 1001, "Updated content");

        t1.join();
        t2.join();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
