// Example: JavaScript module for collecting, storing, and analyzing real-time sensor data

const WebSocket = require('ws');
const cassandra = require('cassandra-driver');
const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');

// Configuration
const config = {
  wsUrl: 'wss://sensor.iot.com/data',
  databaseHost: '127.0.0.1',
  alertThreshold: 80,
  encryptionKey: 'your_encryption_key_here',
  apiPort: 3000,
};

// Initialize WebSocket and Cassandra connections
const ws = new WebSocket(config.wsUrl);
const client = new cassandra.Client({ contactPoints: [config.databaseHost] });

// Express app for RESTful API
const app = express();
app.use(bodyParser.json());

// Middleware for authentication and authorization
function authenticate(req, res, next) {
  // Implement JWT/OAuth2/basic HTTP auth validation here
  if (req.headers.authorization && req.headers.authorization.startsWith('Bearer ')) {
    const token = req.headers.authorization.split(' ')[1];
    try {
      // Validate JWT token
      jwt.verify(token, 'your_secret_key', (err, decoded) => {
        if (err) {
          return res.status(401).json({ message: 'Invalid token' });
        }
        req.user = decoded;
        next();
      });
    } catch (error) {
      res.status(500).json({ message: 'Internal server error' });
    }
  } else {
    res.status(401).json({ message: 'Unauthorized' });
  }
}

// Data validation middleware
function validateData(req, res, next) {
  const data = req.body;
  if (!data || !data.sensorId || !data.value) {
    return res.status(400).json({ message: 'Invalid data format' });
  }
  // Add more validation rules as needed
  next();
}

// Route to store sensor data and trigger alerts
app.post('/api/data', authenticate, validateData, async (req, res) => {
  const { sensorId, value } = req.body;

  try {
    await client.execute('INSERT INTO sensor_data (sensor_id, value) VALUES (?, ?)', [sensorId, value]);

    if (value > config.alertThreshold) {
      // Trigger real-time alert
      await axios.post('http://alert-service.com/send', { sensorId, value });
    }

    res.status(201).json({ message: 'Data stored successfully' });
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Start the WebSocket connection
ws.on('open', () => {
  console.log('WebSocket connection established');

  ws.on('message', async (data) => {
    try {
      const sensorData = JSON.parse(data);
      await client.execute('INSERT INTO sensor_data (sensor_id, value) VALUES (?, ?)', [sensorData.sensorId, sensorData.value]);

      if (sensorData.value > config.alertThreshold) {
        // Trigger real-time alert
        await axios.post('http://alert-service.com/send', { sensorId: sensorData.sensorId, value: sensorData.value });
      }
    } catch (error) {
      console.error(error);
    }
  });

  ws.on('close', () => {
    console.log('WebSocket connection closed');
  });
});

// Start the Express server
app.listen(config.apiPort, () => {
  console.log(`RESTful API listening on port ${config.apiPort}`);
});
