public class UserProfileUpdater
{
    private readonly Dictionary<string, string> _userCache = new Dictionary<string, string>();
    private readonly Dictionary<string, bool> _directoryValidationCache = new Dictionary<string, bool>();

    public async Task UpdateUserProfile(string configFilePath, List<string> userIds, Dictionary<string, object> profileDetails)
    {
        // Validate inputs
        if (!File.Exists(configFilePath))
        {
            throw new ArgumentException("Configuration file not found.");
        }

        foreach (var id in userIds)
        {
            if (!_userCache.ContainsKey(id) && !await ValidateUserIdAsync(id))
            {
                throw new ArgumentException($"Invalid user ID: {id}");
            }
        }

        // Cache directory paths
        foreach (var detail in profileDetails)
        {
            if (!detail.Key.StartsWith("Address"))
                continue;
            var path = detail.Value.ToString();
            if (!_directoryValidationCache.ContainsKey(path) && !await ValidateDirectoryPathAsync(path))
            {
                throw new ArgumentException($"Invalid directory path: {path}");
            }
        }

        // Update user profiles concurrently
        using (var httpClient = new HttpClient())
        {
            var tasks = userIds.Select(id => UpdateUserApiAsync(httpClient, id, profileDetails)).ToList();
            await Task.WhenAll(tasks);
        }

        // Log actions and errors
        LogAction("UserProfileUpdated", $"Updated {userIds.Count} user profiles.");
    }

    private async Task<bool> ValidateUserIdAsync(string userId)
    {
        if (_userCache.ContainsKey(userId))
            return _userCache[userId];

        var result = await CheckUserIdInDatabase(userId);
        _userCache[userId] = result;
        return result;
    }

    private async Task<bool> ValidateDirectoryPathAsync(string path)
    {
        if (_directoryValidationCache.ContainsKey(path))
            return _directoryValidationCache[path];

        var result = await CheckDirectoryExistsAsync(path);
        _directoryValidationCache[path] = result;
        return result;
    }

