import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private static final String ERROR_LOG = "error.log";
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        File config = new File("config.txt");
        if (config.exists()) {
            config.delete();
        }

        String[] commands = {"command1", "command2", "command3"};
        for (String command : commands) {
            executeCommandWithRetry(command);
        }
    }

    private static void executeCommandWithRetry(String command) {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                Process process = Runtime.getRuntime().exec(command);
                logStream(process.getInputStream(), "stdout");
                logStream(process.getErrorStream(), "stderr");
                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    break; // Command executed successfully
                }
            } catch (IOException | InterruptedException e) {
                logError(e);
            }
            retryCount++;
            try {
                TimeUnit.SECONDS.sleep((long) Math.pow(2, retryCount));
            } catch (InterruptedException e) {
                logError(e);
            }
        }
    }

    private static void logStream(InputStream stream, String streamType) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logMessage(line, streamType);
            }
        } catch (IOException e) {
            logError(e);
        }
    }

    private static void logMessage(String message, String streamType) {
        // Use snprintf-like formatting for the log message
        String formattedMessage = String.format("[%s] %s", streamType, message);
        // Log the formatted message to an error file or console
        System.out.println(formattedMessage);
        writeToFile(ERROR_LOG, formattedMessage + "\n");
    }

    private static void logError(Throwable e) {
        // Handle and log errors here
        e.printStackTrace();
    }

    private static void writeToFile(String filePath, String content) {
        try {
            // Implement file writing logic to append or overwrite the error log
        } catch (IOException e) {
            logError(e);
        }
    }
}
