<?php

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    // Database connection parameters
    $host = 'localhost';
    $dbname = 'healthcare_system';
    $username = 'root';
    $password = '';

    try {
        // Establish database connection
        $pdo = new PDO("mysql:host=$host;dbname=$dbname", $username, $password);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // External API for clinic details verification
        $api_url = "https://api.healthcare.com/verify_clinic/$clinic_id";
        $ch = curl_init($api_url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        $response = curl_exec($ch);
        $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);

        if ($http_code == 200) {
            // Parse API response
            $clinic_details = json_decode($response, true);
            if (empty($clinic_details)) {
                throw new Exception("No clinic details found for ID: $clinic_id");
            }
        } else {
            throw new Exception("API error: Unable to verify clinic details (HTTP code $http_code)");
        }

        // Rate limiting using token bucket algorithm
        $rate_limit_file = 'rate_limit.txt';
        $current_time = time();
        if (!file_exists($rate_limit_file)) {
            file_put_contents($rate_limit_file, serialize(array('last_reset' => $current_time, 'tokens' => 5)));
        }
        $rate_limit_data = unserialize(file_get_contents($rate_limit_file));

        if ($current_time - $rate_limit_data['last_reset'] > 60) {
            // Reset token bucket every minute
            $rate_limit_data['last_reset'] = $current_time;
            $rate_limit_data['tokens'] = 5;
        }

        if ($rate_limit_data['tokens'] <= 0) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        } else {
            // Consume a token
            $rate_limit_data['tokens']--;
            file_put_contents($rate_limit_file, serialize($rate_limit_data));
        }

        // Prepare SQL statement for updating clinic status
        $stmt = $pdo->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
        $stmt->bindParam(':status', $new_status);
        $stmt->bindParam(':ip', $last_modified_ip);
        $stmt->bindParam(':id', $clinic_id);

        // Execute the update statement
        if ($stmt->execute()) {
            return "Clinic status updated successfully.";
        } else {
            throw new Exception("Failed to update clinic status.");
        }
    } catch (PDOException | Exception $e) {
        // Log errors to error_log.txt
        file_put_contents('error_log.txt', date('Y-m-d H:i:s') . ' - Error: ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
        return "An error occurred. Please try again later.";
    }
}

