<?php

class SecurePasswordGenerator {
    private $redis;
    private $rateLimit;

    public function __construct($redis, $rateLimit) {
        $this->redis = $redis;
        $this->rateLimit = $rateLimit;
    }

    public function generateSecurePassword($length, $charset, $algorithm = PASSWORD_DEFAULT, $saltPrefix = '', $saltSuffix = '') {
        if ($length < 8 || $length > 64) {
            throw new Exception("Length must be between 8 and 64 characters.");
        }

        // Validate character set
        if (!preg_match('/^[a-zA-Z0-9_\-\.]+$/', $charset)) {
            throw new Exception("Invalid character set.");
        }

        // Check if the algorithm is supported
        if (!in_array($algorithm, [PASSWORD_DEFAULT, PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
            throw new Exception("Unsupported algorithm.");
        }

        // Rate limiting
        if (!$this->checkRateLimit('generatePassword')) {
            return "Too many requests. Please try again later.";
        }

        $salt = $this->generateRandomString($length, $charset) . $saltPrefix . $saltSuffix;
        $hashedPassword = password_hash($salt, $algorithm);

        // Store salt and hash in Redis
        $this->redis->set('salt:' . $salt, $hashedPassword);
        $this->redis->expire('salt:' . $salt, 3600); // 1 hour expiration

        return ['salt' => $salt, 'hash' => $hashedPassword];
    }

    public function checkPassword($password, $salt) {
        if (!isset($salt)) {
            throw new Exception("Salt is required.");
        }

        $storedHash = $this->redis->get('salt:' . $salt);
        if ($storedHash === false) {
            return false;
        }

        return password_verify($password, $storedHash);
    }

    public function validatePasswordStrength($password) {
        $minLength = 8;
        $hasDigits = preg_match('/\d/', $password) > 0;
        $hasUppercase = preg_match('/[A-Z]/', $password) > 0;
        $hasLowercase = preg_match('/[a-z]/', $password) > 0;
        $hasSpecialChars = preg_match('/[\W_]/', $password) > 0;

        return strlen($password) >= $minLength && $hasDigits && $hasUppercase && $hasLowercase && $hasSpecialChars;
    }

    private function generateRandomString($length, $charset) {
        $bytes = random_bytes($length);
        $result = '';
        $charArray = str_split($charset);

        for ($i = 0; $i < $length; $i++) {
            $result .= $charArray[ord($bytes[$i]) % count($charArray)];
        }

        return $result;
    }

    private function checkRateLimit($action) {
        $key = 'rate_limit:' . $action;
        $currentCount = (int)$this->redis->get($key);
        $currentTime = time();

        if ($currentCount === 0 || $currentTime > (int)$this->redis->get('rate_limit_last_time:' . $action)) {
            $this->redis->set('rate_limit_last_time:' . $action, $currentTime);
            $this->redis->set($key, 1);
        } else if ($currentCount < $this->rateLimit) {
            $this->redis->incr($key);
        } else {
            return false;
        }

        return true;
    }
}

// Example usage:
$redis = new Redis();
$redis->connect('127.0.0.1', 6379);

$generator = new SecurePasswordGenerator($redis, 10); // Rate limit of 10 requests per minute

