#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <stdio.h>
#include <stdlib.h>

#define SALT_LENGTH 16
#define KEY_LENGTH 32
#define IV_LENGTH 12

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_LENGTH];
    unsigned char iv[IV_LENGTH];
} AESContext;

int init_aes_cipher(AESContext *ctx, const char *password, const unsigned char *salt) {
    if (ctx == NULL || password == NULL || salt == NULL) return 0;

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (ctx->ctx == NULL) return 0;

    // Derive key using PBKDF2
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, SALT_LENGTH, 10000, EVP_sha256(), KEY_LENGTH, ctx->key)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return 0;
    }

    // Generate IV
    if (!RAND_bytes(ctx->iv, IV_LENGTH)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return 0;
    }

    // Initialize encryption context
    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return 0;
    }

    // Set IV length
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IVLEN, IV_LENGTH, NULL)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return 0;
    }

    return 1;
}

void cleanup_aes_cipher(AESContext *ctx) {
    if (ctx == NULL || ctx->ctx == NULL) return;

    EVP_CIPHER_CTX_free(ctx->ctx);
    memset(ctx, 0, sizeof(AESContext));
}

// External key management system integration functions
int store_key(const unsigned char *key, size_t length) {
    // Implementation to store key in external key management system
    return 1; // Return success
}

int retrieve_key(unsigned char **key, size_t *length) {
    // Implementation to retrieve key from external key management system
    *key = malloc(KEY_LENGTH);
    if (*key == NULL) return 0;
    // Simulate key retrieval
    memset(*key, 'K', KEY_LENGTH);
    *length = KEY_LENGTH;
    return 1; // Return success
}

int main() {
    AESContext ctx;
    unsigned char salt[SALT_LENGTH];
    unsigned char *retrieved_key = NULL;
    size_t retrieved_key_length;

    if (!RAND_bytes(salt, SALT_LENGTH)) {
        fprintf(stderr, "Failed to generate salt\n");
        return 1;
    }

    // Simulate external key management system
    if (!store_key(ctx.key, KEY_LENGTH)) {
        fprintf(stderr, "Failed to store key\n");
        return 1;
    }

    if (!retrieve_key(&retrieved_key, &retrieved_key_length)) {
        fprintf(stderr, "Failed to retrieve key\n");
        return 1;
    }

    if (!init_aes_cipher(&ctx, (const char *)retrieved_key, salt)) {
        fprintf(stderr, "Failed to initialize AES cipher\n");
        free(retrieved_key);
        return 1;
    }

    // Perform encryption and decryption operations...

    cleanup_aes_cipher(&ctx);
    free(retrieved_key);

    return 0;
}
