const axios = require('axios');
const { Worker, isMainThread, parentPort } = require('worker_threads');

class TransactionReducer {
    constructor(apiUrl, workerPoolSize) {
        this.apiUrl = apiUrl;
        this.workerPoolSize = workerPoolSize;
        this.workers = [];
        this.initializeWorkers();
    }

    initializeWorkers() {
        for (let i = 0; i < this.workerPoolSize; i++) {
            const worker = new Worker(__filename, { workerData: { id: i } });
            worker.on('message', this.handleWorkerMessage.bind(this));
            worker.on('error', this.handleWorkerError.bind(this));
            worker.on('exit', (code) => {
                if (code !== 0)
                    console.error(`Worker ${i} stopped with exit code ${code}`);
            });
            this.workers.push(worker);
        }
    }

    async processTransactions(transactionIds) {
        const results = [];
        for (let i = 0; i < transactionIds.length; i++) {
            const worker = this.workers[i % this.workerPoolSize];
            worker.postMessage({ type: 'process', id: transactionIds[i] });
            const result = await new Promise((resolve, reject) => {
                worker.on('message', (msg) => {
                    if (msg.type === 'result') resolve(msg.data);
                    else if (msg.type === 'error') reject(new Error(msg.error));
                });
            });
            results.push(result);
        }
        return results;
    }

    handleWorkerMessage(msg) {
        // Log worker message or update UI
        console.log(`Worker ${msg.id}: ${msg.message}`);
    }

    handleWorkerError(err) {
        // Handle worker error
        console.error('Worker Error:', err);
    }
}

// Example usage:
(async () => {
    const reducer = new TransactionReducer('https://api.example.com/transactions', 50);
    try {
        const results = await reducer.processTransactions([1, 2, 3, 4, 5]);
        console.log(results);
    } catch (error) {
        console.error(error);
    }
})();
```

This code snippet provides a basic structure for the `TransactionReducer` class, using Node.js worker threads to manage concurrent processing. The actual implementation of fetching transaction details from the API and handling errors would need to be added in the worker thread's message event handler.

