import requests
from bs4 import BeautifulSoup
import time
import json
import logging
from threading import Thread, Lock

# Configure logging
logging.basicConfig(level=logging.INFO)

class WebScraper:
    def __init__(self, data_sources):
        self.data_sources = data_sources
        self.lock = Lock()

    def fetch_data(self, url):
        response = requests.get(url)
        if response.status_code == 200:
            return response.text
        else:
            logging.error(f"Failed to fetch data from {url}: HTTP {response.status_code}")
            return None

    def parse_data(self, html_content):
        soup = BeautifulSoup(html_content, 'html.parser')
        # Custom parsing logic goes here
        return [item.text for item in soup.find_all('div', class_='data-item')]

    def save_to_database(self, data):
        with self.lock:
            try:
                # Database connection and insert logic goes here
                logging.info("Data saved to database")
            except Exception as e:
                logging.error(f"Failed to save data: {e}")

class DataCollector(Thread):
    def __init__(self, scraper, url):
        super().__init__()
        self.scraper = scraper
        self.url = url

    def run(self):
        html_content = self.scraper.fetch_data(self.url)
        if html_content:
            data = self.scraper.parse_data(html_content)
            self.scraper.save_to_database(data)

def main():
    data_sources = {
        "source1": "http://example.com/data1",
        "source2": "http://example.com/data2"
    }
    scraper = WebScraper(data_sources)

    threads = []
    for source, url in data_sources.items():
        thread = DataCollector(scraper, url)
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

if __name__ == "__main__":
    main()
```

This code provides a basic structure for a web scraping service with concurrent processing and database synchronization. It includes logging for progress and errors, as well as a lock to ensure thread safety when accessing shared resources (the database). The `DataCollector` class extends `Thread`, allowing for parallel execution of data collection tasks from different sources.

