using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicWeatherUpdaterMiddleware
{
    private double latitude;
    private double longitude;
    private string weatherSource;
    private Dictionary<string, object> cachedWeatherData;

    public DynamicWeatherUpdaterMiddleware(double latitude, double longitude)
    {
        this.latitude = latitude;
        this.longitude = longitude;
        this.weatherSource = "Real-Time Sensors"; // Default source
        this.cachedWeatherData = new Dictionary<string, object>();
    }

    public void SetWeatherSource(string source)
    {
        weatherSource = source;
    }

    public async Task<Dictionary<string, object>> GetWeatherDataAsync()
    {
        if (cachedWeatherData.ContainsKey("lastUpdated") && DateTime.Now.Subtract((DateTime)cachedWeatherData["lastUpdated"]).TotalMinutes < 5)
        {
            return cachedWeatherData;
        }

        var weatherData = await FetchWeatherFromSource();
        cachedWeatherData = weatherData;
        cachedWeatherData["lastUpdated"] = DateTime.Now;
        return weatherData;
    }

    private async Task<Dictionary<string, object>> FetchWeatherFromSource()
    {
        var httpClient = new HttpClient();
        string url = GetWeatherServiceUrl(weatherSource);

        try
        {
            HttpResponseMessage response = await httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            string responseBody = await response.Content.ReadAsStringAsync();

            // Simulate parsing JSON response for weather data
            Dictionary<string, object> parsedData = new Dictionary<string, object>
            {
                { "temperature", 25 },
                { "humidity", 70 },
                { "windSpeed", 10 },
                { "precipitation", 0 }
            };

            return parsedData;
        }
        catch (HttpRequestException e)
        {
            Console.WriteLine($"Request error: {e.Message}");
            throw;
        }
    }

    private string GetWeatherServiceUrl(string source)
    {
        // Return the URL for fetching weather data based on the source
        switch (source)
        {
            case "Real-Time Sensors":
                return "https://api.realtimesensors.com/weather";
            case "Historical Records":
                return "https://api.historicalweather.com/data";
            default:
                throw new ArgumentException("Invalid weather data source");
        }
    }

    public string GetWeatherUpdateHtml()
    {
        var weatherData = GetWeatherDataAsync().Result;

        // Simulate HTML update based on weather data
        string htmlUpdate = $@"
            <div id=""weather-update"">
                <p>Temperature: {weatherData["temperature"]}°C</p>
                <p>Humidity: {weatherData["humidity"]}%</p>
                <p>Wind Speed: {weatherData["windSpeed"]} km/h</p>
                <p>Precipitation: {weatherData["precipitation"]} mm</p>
            </div>";

        return htmlUpdate;
    }

    public override string ToString()
    {
        var weatherData = GetWeatherDataAsync().Result;

        return $@"
            Current Weather Conditions:
            - Temperature: {weatherData["temperature"]}°C
            - Humidity: {weatherData["humidity"]}%
            - Wind Speed: {weatherData["windSpeed"]} km/h
            - Precipitation: {weatherData["precipitation"]} mm
            Selected Data Source: {weatherSource}";
    }
}
