const fs = require('fs');
const stream = require('stream');

function createBufferedDataConsumer(sourceStreams, targetSize) {
  const buffer = Buffer.alloc(targetSize);
  let bytesRead = 0;

  function consumeStream(stream) {
    return new Promise((resolve, reject) => {
      stream.on('data', (chunk) => {
        if (bytesRead + chunk.length > targetSize) {
          resolve(buffer.slice(0, targetSize));
        } else {
          buffer.copy(chunk, bytesRead);
          bytesRead += chunk.length;
        }
      });

      stream.on('end', () => resolve(buffer.slice(0, bytesRead)));
      stream.on('error', (err) => reject(err));
    });
  }

  return Promise.all(sourceStreams.map(consumeStream))
    .then(() => buffer)
    .catch((error) => {
      console.error("Error during data consumption:", error);
      throw error;
    });
}

// Example usage:
const source1 = fs.createReadStream('source1.txt');
const source2 = fs.createReadStream('source2.txt');

createBufferedDataConsumer([source1, source2], 4096)
  .then((buffer) => {
    console.log("Data consumption successful:", buffer);
  })
  .catch((error) => {
    console.error("Failed to consume data:", error);
  });
