using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

[Route("api/[controller]")]
public class FileUploadController : ControllerBase
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly IMemoryCache _cache;
    private readonly ILogger<FileUploadController> _logger;

    public FileUploadController(IHttpClientFactory httpClientFactory, IMemoryCache cache, ILogger<FileUploadController> logger)
    {
        _httpClientFactory = httpClientFactory;
        _cache = cache;
        _logger = logger;
    }

    [HttpPost("upload")]
    public async Task<IActionResult> UploadFile(IFormFile file)
    {
        if (file == null || file.Length == 0)
            return BadRequest("No file uploaded.");

        string remoteHashUrl = "https://api.example.com/verifyHash";
        string localFilePath = Path.Combine(Path.GetTempPath(), file.FileName);
        await file.CopyToAsync(new FileStream(localFilePath, FileMode.Create));

        try
        {
            string md5Hash = await ComputeMd5HashAsync(localFilePath);
            string cachedHash;

            if (_cache.TryGetValue(md5Hash, out cachedHash))
                return Ok("File already verified.");

            using (var client = _httpClientFactory.CreateClient())
            {
                var content = new StringContent(md5Hash);
                var response = await client.PostAsync(remoteHashUrl, content);

                if (response.IsSuccessStatusCode)
                {
                    _cache.Set(md5Hash, md5Hash, TimeSpan.FromHours(1));
                    return Ok("File verified successfully.");
                }
                else
                {
                    _logger.LogError("API call failed with status code: {statusCode}", response.StatusCode);
                    return StatusCode((int)response.StatusCode, "Failed to verify file hash.");
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while processing the file upload.");
            return StatusCode(500, "Internal server error.");
        }
        finally
        {
            File.Delete(localFilePath);
        }
    }

    private async Task<string> ComputeMd5HashAsync(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
        {
            byte[] hashBytes = await md5.ComputeHashAsync(stream);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}
