typedef struct ResourceBundle {
    char *name;
    void *data;
    size_t dataSize;
} ResourceBundle;

ResourceBundle* loadResourceFromZip(const char *zipPath, const char *resourceName) {
    zip *z = zip_open(zipPath, 0, NULL);
    if (!z)
        return NULL;

    int errnum;
    struct zip_stat st;
    if (zip_stat(z, resourceName, 0, &st) != 0 || st.valid != ZIP_STAT_VALID) {
        zip_close(z);
        return NULL;
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        zip_close(z);
        return NULL;
    }

    bundle->name = strdup(resourceName);
    bundle->dataSize = st.size;

    bundle->data = malloc(st.size);
    if (!bundle->data) {
        free(bundle->name);
        free(bundle);
        zip_close(z);
        return NULL;
    }

    if (zip_fread(zip_fopen_index(z, st.index, 0), bundle->data, st.size) != st.size) {
        free(bundle->data);
        free(bundle->name);
        free(bundle);
        zip_close(z);
        return NULL;
    }

    zip_close(z);
    return bundle;
}

void freeResourceBundle(ResourceBundle *bundle) {
    if (bundle) {
        free(bundle->name);
        free(bundle->data);
        free(bundle);
    }
}

int updateResource(ResourceBundle *bundle, const char *newData, size_t newSize) {
    void *newDataCopy = realloc(bundle->data, newSize);
    if (!newDataCopy)
        return -1;

    bundle->data = newDataCopy;
    memcpy(bundle->data, newData, newSize);
    bundle->dataSize = newSize;

    return 0;
}

