### Python Script for Processing IoT Logs

```python
import json
import os
from concurrent.futures import ThreadPoolExecutor
import sqlite3
from functools import wraps

# Decorator to handle database connection
def with_db_connection(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        conn = sqlite3.connect('iot_logs.db')
        try:
            return func(conn, *args, **kwargs)
        finally:
            conn.close()
    return wrapper

# Function to process and store log data
@with_db_connection
def process_log_file(file_path, conn):
    with open(file_path, 'r') as file:
        for line in file:
            data = json.loads(line)
            if not is_anomaly(data):
                cursor = conn.cursor()
                cursor.execute("INSERT INTO sensor_data VALUES (?, ?, ?)", 
                               (data['timestamp'], data['sensor_id'], data['value']))
                conn.commit()

# Function to check for anomalies
def is_anomaly(data):
    # Simple anomaly detection logic
    return abs(data['value']) > 100

# Main function to process all log files concurrently
def main():
    log_files = ['device1.log', 'device2.log', 'device3.log']
    with ThreadPoolExecutor(max_workers=3) as executor:
        for file_path in log_files:
            executor.submit(process_log_file, file_path)

if __name__ == "__main__":
    main()
```

