async function fetchWeatherData(cities, updateUI) {
    const apiKey = 'YOUR_API_KEY';
    let requests = [];

    cities.forEach(city => {
        requests.push(fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}`)
            .then(response => response.json())
            .catch(error => console.error('Error fetching weather data:', error))
        );
    });

    try {
        const responses = await Promise.all(requests);
        responses.forEach((response, index) => {
            if (response.cod === 200) {
                updateUI(cities[index], response.weather[0].description);
            } else {
                console.log('Failed to fetch weather data for:', cities[index]);
            }
        });
    } catch (error) {
        console.error('Error in fetching weather data:', error);
    }
}

// Example usage
const cities = ['New York', 'London', 'Tokyo'];
fetchWeatherData(cities, (city, description) => {
    document.getElementById(city).innerText = description;
});
