using System;
using System.Collections.Generic;
using UnityEngine;

public class DynamicValueGenerator : IDisposable
{
    private Random _random = new Random();
    private Dictionary<string, Distribution> _distributions;
    private Queue<Distribution> _lruCache;
    private int _cacheSize;

    public DynamicValueGenerator(int cacheSize)
    {
        _cacheSize = cacheSize;
        _distributions = new Dictionary<string, Distribution>();
        _lruCache = new Queue<Distribution>(cacheSize);
    }

    public void SetDistribution(string type, params object[] parameters)
    {
        if (_distributions.ContainsKey(type))
        {
            _distributions[type].UpdateParameters(parameters);
        }
        else
        {
            _distributions[type] = DistributionFactory.CreateDistribution(type, parameters);
        }

        EvictLRU();
    }

    public float GetRandomFloat(float min, float max)
    {
        return _distributions["Uniform"].GetRandomFloat(min, max);
    }

    public int GetRandomInt(int min, int max)
    {
        return (int)_distributions["Uniform"].GetRandomFloat(min, max);
    }

    public override string ToString()
    {
        // Implement the ToString method to display range and distribution details
        return $"Range: {min} to {max}, Distribution Type: {type}, Parameters: {parameters}";
    }

    private void EvictLRU()
    {
        if (_lruCache.Count >= _cacheSize)
        {
            var evictedDistribution = _lruCache.Dequeue();
            _distributions.Remove(evictedDistribution.Type);
        }
    }

    public void Dispose()
    {
        // Implement proper resource cleanup
    }
}

public abstract class Distribution
{
    public string Type { get; private set; }

    protected Distribution(string type)
    {
        Type = type;
    }

    public abstract float GetRandomFloat(float min, float max);

    public virtual void UpdateParameters(params object[] parameters)
    {
        // Implement parameter update logic if needed
    }
}

public class UniformDistribution : Distribution
{
    public UniformDistribution() : base("Uniform") { }

    public override float GetRandomFloat(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }
}

public static class DistributionFactory
{
    public static Distribution CreateDistribution(string type, params object[] parameters)
    {
        switch (type.ToLower())
        {
            case "uniform":
                return new UniformDistribution();
            // Add other distribution types here
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }
}
