import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor

class FileHashService:
    def calculate_hash(self, file_path):
        if file_path.startswith('http'):
            return self._hash_remote_file(file_path)
        else:
            return self._hash_local_file(file_path)

    def _hash_local_file(self, file_path):
        hash_sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_sha256.update(chunk)
        return hash_sha256.hexdigest()

    def _hash_remote_file(self, file_url):
        response = requests.get(file_url, stream=True)
        hash_sha256 = hashlib.sha256()
        for chunk in response.iter_content(4096):
            hash_sha256.update(chunk)
        return hash_sha256.hexdigest()

def main():
    service = FileHashService()
    file_path = 'http://example.com/largefile.zip'  # Replace with actual URL or local path
    print(service.calculate_hash(file_path))

if __name__ == "__main__":
    main()
```

