public class LogAnalyzer {
    private static final Logger logger = Logger.getLogger(LogAnalyzer.class.getName());
    private List<String> directoriesToScan;
    private Set<String> keywords;
    private Map<String, String> filteringCriteria;
    private String outputFormat;
    private int maxRetries;

    public LogAnalyzer(List<String> directories, Set<String> keywords, Map<String, String> criteria, String format, int retries) {
        this.directoriesToScan = directories;
        this.keywords = keywords;
        this.filteringCriteria = criteria;
        this.outputFormat = format;
        this.maxRetries = retries;
    }

    public void analyzeLogs() {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletionService<String> completionService = new ExecutorCompletionService<>(executor);

        for (String dir : directoriesToScan) {
            Path path = Paths.get(dir);
            try {
                Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
                    @Override
                    public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                        if (file.toString().endsWith(".txt")) {
                            completionService.submit(() -> readFile(file));
                        }
                        return FileVisitResult.CONTINUE;
                    }
                });
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error scanning directory: " + dir, e);
            }
        }

        List<String> reportLines = new ArrayList<>();
        for (int i = 0; i < directoriesToScan.size(); i++) {
            try {
                Future<String> future = completionService.take();
                String result = future.get();
                if (result != null) {
                    reportLines.add(result);
                }
            } catch (InterruptedException | ExecutionException e) {
                logger.log(Level.SEVERE, "Error processing file", e);
            }
        }

        generateSummaryReport(reportLines);

        executor.shutdown();
    }

    private String readFile(Path filePath) {
        try {
            List<String> lines = Files.readAllLines(filePath, detectEncoding(filePath));
            StringBuilder result = new StringBuilder();
            for (String line : lines) {
                if (containsKeywords(line)) {
                    result.append(line).append("\n");
                }
            }
            return result.toString();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error reading file: " + filePath, e);
            return null;
        }
    }

    private Charset detectEncoding(Path filePath) throws IOException {
        // Simple heuristic to detect encoding based on BOM or first few characters
        byte[] firstBytes = Files.readAllBytes(filePath);
        if (firstBytes.length > 3 && (firstBytes[0] == (byte) 0xEF && firstBytes[1] == (byte) 0xBB && firstBytes[2] == (byte) 0xBF)) {
            return Charset.forName("UTF-8");
        } else if (firstBytes.length > 2 && (firstBytes[0] == (byte) 0xFE && firstBytes[1] == (byte) 0xFF)) {
            return Charset.forName("UTF-16BE");
        } else if (firstBytes.length > 3 && (firstBytes[0] == (byte) 0xFF && firstBytes[1] == (byte) 0xFE)) {
            return Charset.forName("UTF-16LE");
        } else {
            return Charset.defaultCharset();
        }
    }

    private boolean containsKeywords(String line) {
        for (String keyword : keywords) {
            if (line.toLowerCase().contains(keyword)) {
                return true;
            }
        }
        return false;
    }

    private void generateSummaryReport(List<String> reportLines) {
        StringBuilder summary = new StringBuilder();
        for (String line : reportLines) {
            summary.append(line).append("\n");
        }

        if ("JSON".equals(outputFormat)) {
            // Convert summary to JSON format
            logger.info("Generating JSON report...");
        } else if ("XML".equals(outputFormat)) {
            // Convert summary to XML format
            logger.info("Generating XML report...");
        } else {
            // Default plain text format
            logger.info("Generating plain text report...");
        }

        uploadReport(summary.toString());
    }

    private void uploadReport(String report) {
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try {
                externalReportingAPI.upload(report);
                logger.info("Report uploaded successfully.");
                break;
            } catch (Exception e) {
                if (attempt == maxRetries) {
                    logger.log(Level.SEVERE, "Failed to upload report after " + maxRetries + " attempts.", e);
                    return;
                }
                logger.warning("Upload failed. Retrying in 5 seconds...");
                Thread.sleep(5000);
            }
        }
    }

    // Simulated external reporting API
    private static class ExternalReportingAPI {
        public void upload(String report) throws IOException {
            // Logic to upload report to the external system
        }
    }

    private ExternalReportingAPI externalReportingAPI = new ExternalReportingAPI();

    public static void main(String[] args) {
        List<String> directories = Arrays.asList("path/to/logs1", "path/to/logs2");
        Set<String> keywords = Collections.singleton("error");
        Map<String, String> criteria = new HashMap<>();
        criteria.put("include", "*.txt");
        LogAnalyzer analyzer = new LogAnalyzer(directories, keywords, criteria, "JSON", 3);
        analyzer.analyzeLogs();
    }
}
