```java
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.Properties;

public class ObjectDeserializer {
    private Properties configProperties;

    public ObjectDeserializer(String configFilePath) {
        try (var inputStream = new FileInputStream(configFilePath)) {
            this.configProperties = new Properties();
            this.configProperties.load(inputStream);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration file: " + configFilePath, e);
        }
    }

    public Object deserialize(byte[] byteArray) {
        String className = configProperties.getProperty("class.name");
        if (className == null) {
            throw new RuntimeException("Class name not specified in configuration.");
        }

        try (var inputStream = new ByteArrayInputStream(byteArray)) {
            var objectInputStream = new ObjectInputStream(inputStream);
            return objectInputStream.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize byte array to class: " + className, e);
        }
    }
}
