public class CacheLoader<T>
{
    private string filePath;
    private string backupFilePath;
    private long cacheOutdatedThreshold;
    private readonly BinaryFormatter formatter = new BinaryFormatter();
    private readonly ReaderWriterLockSlim lockObject = new ReaderWriterLockSlim();
    private Timer refreshTimer;
    private DateTime lastModifiedTime;

    public CacheLoader(string filePath, string backupFilePath, long cacheOutdatedThreshold)
    {
        this.filePath = filePath;
        this.backupFilePath = backupFilePath;
        this.cacheOutdatedThreshold = cacheOutdatedThreshold;
        LoadCacheAsync();
    }

    public void InsertString(List<string> forwardList, string searchString, string insertString)
    {
        lockObject.EnterWriteLock();
        try
        {
            int index = forwardList.IndexOf(searchString);
            if (index == -1)
            {
                forwardList.Add(insertString);
            }
            else
            {
                forwardList.Insert(index + 1, insertString);
            }
        }
        finally
        {
            lockObject.ExitWriteLock();
        }
    }

    private async void LoadCacheAsync()
    {
        while (true)
        {
            await Task.Delay(5000); // Check every 5 seconds

            lockObject.EnterReadLock();
            try
            {
                if (File.Exists(filePath))
                {
                    lastModifiedTime = File.GetLastWriteTime(filePath);
                    if ((DateTime.Now - lastModifiedTime).TotalMilliseconds > cacheOutdatedThreshold)
                    {
                        LoadCacheFromFile(true);
                    }
                }
                else
                {
                    LoadCacheFromDatabase();
                }
            }
            finally
            {
                lockObject.ExitReadLock();
            }
        }
    }

    private void LoadCacheFromFile(bool forceUpdate = false)
    {
        try
        {
            using (FileStream fileStream = File.Open(filePath, FileMode.OpenOrCreate, FileAccess.Read))
            {
                using (var decompressionStream = new MemoryStream())
                {
                    DecompressStream(fileStream, decompressionStream);
                    lockObject.EnterWriteLock();
                    try
                    {
                        T cacheData = (T)formatter.Deserialize(decompressionStream);
                        // Update the in-memory cache here
                    }
                    finally
                    {
                        lockObject.ExitWriteLock();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogException(ex); // Use the third-party logging library to log exceptions
            LoadCacheFromDatabase(); // Fallback to database on error
        }
    }

    private void LoadCacheFromDatabase()
    {
        lockObject.EnterWriteLock();
        try
        {
            // Retrieve cache data from the database and update the in-memory cache here
        }
        finally
        {
            lockObject.ExitWriteLock();
        }
    }

    private static void DecompressStream(Stream compressed, Stream output)
    {
        using (var gzipStream = new GZipStream(compressed, CompressionMode.Decompress))
        {
            gzipStream.CopyTo(output);
        }
    }

    private static void LogException(Exception ex)
    {
        // Implement the logging logic here
    }
}

