// WeatherService.java
import retrofit2.Call;
import retrofit2.http.GET;
import retrofit2.http.Query;

public interface WeatherService {
    @GET("weather")
    Call<WeatherResponse> getWeather(@Query("q") String location);
}

// WeatherResponse.java
public class WeatherResponse {
    private double temperature;
    // other fields and methods
}

// WeatherFetcher.java
import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;

import java.util.concurrent.TimeUnit;

public class WeatherFetcher {
    private final WeatherService weatherService;
    private final Cache<String, WeatherResponse> cache;
    private int apiRequestCount = 0;
    private int cacheHitCount = 0;
    private int cacheMissCount = 0;

    public WeatherFetcher(WeatherService weatherService) {
        this.weatherService = weatherService;
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(100)
                .expireAfterWrite(24, TimeUnit.HOURS)
                .build();
    }

    public WeatherResponse getWeather(String location) throws Exception {
        try {
            if (cache.getIfPresent(location) != null) {
                cacheHitCount++;
                return cache.getIfPresent(location);
            } else {
                Call<WeatherResponse> call = weatherService.getWeather(location);
                WeatherResponse response = call.execute().body();
                if (response == null) throw new Exception("No data returned");
                apiRequestCount++;
                cacheMissCount++;
                cache.put(location, response);
                return response;
            }
        } catch (Exception e) {
            System.out.println("API request failed. Falling back to cached data.");
            WeatherResponse fallback = cache.getIfPresent(location);
            if (fallback == null) throw e;
            cacheHitCount++;
            return fallback;
        }
    }

    public int getApiRequestCount() {
        return apiRequestCount;
    }

    public int getCacheHitCount() {
        return cacheHitCount;
    }

    public int getCacheMissCount() {
        return cacheMissCount;
    }
}

// WeatherFetcherTest.java
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.io.IOException;

import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

public class WeatherFetcherTest {
    @Mock
    private WeatherService weatherService;

    private WeatherFetcher weatherFetcher;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);
        weatherFetcher = new WeatherFetcher(weatherService);
    }

    @Test
    public void testGetWeather() throws IOException {
        when(weatherService.getWeather(anyString())).thenReturn(mock(Response.class));

        WeatherResponse response1 = weatherFetcher.getWeather("New York");
        WeatherResponse response2 = weatherFetcher.getWeather("New York");

        assertTrue(response1 == response2); // Same instance from cache
        assertEquals(1, weatherFetcher.getApiRequestCount());
        assertEquals(0, weatherFetcher.getCacheHitCount());
        assertEquals(1, weatherFetcher.getCacheMissCount());

        when(weatherService.getWeather(anyString())).thenThrow(new IOException("Network error"));

        WeatherResponse response3 = weatherFetcher.getWeather("New York");

        assertTrue(response3 == response2); // Fallback to cached data
        assertEquals(1, weatherFetcher.getApiRequestCount());
        assertEquals(0, weatherFetcher.getCacheHitCount());
        assertEquals(1, weatherFetcher.getCacheMissCount());
    }
}
