const crypto = require('crypto');
const kafka = require('kafka-node');
const fs = require('fs');

// Configuration
const kafkaHost = 'localhost:9092';
const topicName = 'real-time-data';
const encryptionKeyLength = 32;
const ivLength = 16;

// Kafka consumer setup
const client = new kafka.KafkaClient({kafkaHost});
const consumer = new kafka.Consumer(client, [{topic: topicName}], {encoding: 'utf8'});

// Encryption utility function
function generateEncryptionKey() {
  return crypto.randomBytes(encryptionKeyLength);
}

function encryptData(data, key) {
  const iv = crypto.randomBytes(ivLength);
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
  let encrypted = cipher.update(data, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return iv.toString('hex') + ':' + encrypted;
}

// Error handling and graceful shutdown
process.on('SIGINT', () => {
  consumer.close();
  client.close(() => process.exit(0));
});

// Command-line arguments for encryption settings
const program = require('commander');
program.option('--key <key>', 'Encryption key (hex)').option('--iv <iv>', 'Initialization Vector (hex)');
program.parse(process.argv);
const {key, iv} = program;

// Kafka consumer event handling
consumer.on('message', async message => {
  try {
    if (!key || !iv) {
      const encryptionKey = generateEncryptionKey();
      key = encryptionKey.toString('hex');
      iv = crypto.randomBytes(ivLength).toString('hex');
      console.log(`Generated new encryption key: ${key}`);
      console.log(`Generated new initialization vector: ${iv}`);
    }

    const encryptedData = encryptData(message.value, key);
    console.log(`Encrypted data: ${encryptedData}`);
  } catch (error) {
    console.error(`Error processing message: ${error.message}`);
  }
});

// Unit tests
const assert = require('assert');

function testEncryption() {
  const originalData = 'Hello, world!';
  const encryptionKey = generateEncryptionKey();
  const encryptedData = encryptData(originalData, encryptionKey);
  const [iv, data] = encryptedData.split(':');
  const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(encryptionKey), Buffer.from(iv, 'hex'));
  let decrypted = decipher.update(data, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  assert.strictEqual(originalData, decrypted);
}

testEncryption();
