```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <atomic>
#include <zlib.h> // For decompression
#include <openssl/evp.h> // For encryption
#include "nlohmann/json.hpp" // For JSON parsing

using json = nlohmann::json;

// Function to parse JSON configuration file
std::map<std::string, std::function<void(int*)>> parseConfig(const std::string& configFile) {
    std::ifstream configStream(configFile);
    json config;
    configStream >> config;
    std::map<std::string, std::function<void(int*)>> parsingRules;
    for (auto& [ruleName, rule] : config.items()) {
        // Dynamically create lambda functions based on JSON configuration
        auto lambda = [&rule](int* array) { rule(array); };
        parsingRules[ruleName] = lambda;
    }
    return parsingRules;
}

// Function to decompress binary data
std::vector<char> decompressData(const std::vector<char>& compressedData) {
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    inflateInit(&stream);
    stream.avail_in = compressedData.size();
    stream.next_in = (unsigned char*)compressedData.data();

    std::vector<char> output(1024); // Initial buffer size
    do {
        stream.avail_out = output.size();
        stream.next_out = (unsigned char*)&output[0];
        inflate(&stream, Z_FINISH);
        if (stream.msg) throw std::runtime_error("Decompression error: " + std::string(stream.msg));
        if (stream.total_out == output.size()) output.resize(output.size() * 2); // Increase buffer size
    } while (stream.avail_out == 0);

    output.resize(stream.total_out);
    inflateEnd(&stream);
    return output;
}

// Function to encrypt data using OpenSSL
std::vector<char> encryptData(const std::vector<char>& input, const std::string& key) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)key.c_str(), (unsigned char*)key.c_str());

    std::vector<char> output(input.size() + EVP_CIPHER_BLOCK_SIZE);
    int len;
    EVP_EncryptUpdate(ctx, &output[0], &len, (unsigned char*)input.data(), input.size());
    output.resize(len);
    int finalLen;
    EVP_EncryptFinal_ex(ctx, &output[len], &finalLen);
    output.resize(len + finalLen);

    EVP_CIPHER_CTX_free(ctx);
    return output;
}

// Union-Find data structure for disjoint pair identification
class UnionFind {
private:
    std::vector<int> parent;
public:
    UnionFind(int size) : parent(size, -1) {}
    int find(int u) {
        if (parent[u] < 0) return u; // Root node
        return parent[u] = find(parent[u]); // Path compression
    }
    void unite(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu != pv) {
            if (parent[pu] < parent[pv]) {
                parent[pu] += parent[pv];
                parent[pv] = pu;
            } else {
                parent[pv] += parent[pu];
                parent[pu] = pv;
            }
        }
    }
};

// Function to process array of integers
void processArray(int* array, std::map<std::string, std::function<void(int*)>>& parsingRules) {
    for (auto& [ruleName, rule] : parsingRules) {
        rule(array);
    }
}

int main() {
    // Example usage
    std::vector<char> compressedData = { /* ... */ }; // Read from file
    std::map<std::string, std::function<void(int*)>> parsingRules = parseConfig("config.json");

    std::vector<char> decompressedData = decompressData(compressedData);
    int* array = reinterpret_cast<int*>(&decompressedData[0]);

    processArray(array, parsingRules);

    std::string encryptionKey = "0123456789abcdef0123456789abcdef"; // 32 bytes for AES-256
    std::vector<char> encryptedData = encryptData(decompressedData, encryptionKey);

    // Write to output file
    std::ofstream outputFile("output.enc");
    outputFile.write(encryptedData.data(), encryptedData.size());

    return 0;
}
```

