#include <stdio.h>
#include <stdlib.h>

typedef struct State {
    int id;
    struct State* next;
} State;

State* generate_state_list(int* states, int num_states, State* fsa, int last_state_id) {
    if (states == NULL || fsa == NULL) {
        perror("Invalid input parameters");
        return NULL;
    }

    State* new_head = NULL;
    State** current = &new_head;

    for (int i = 0; i < num_states; i++) {
        State* new_state = malloc(sizeof(State));
        if (new_state == NULL) {
            perror("Failed to allocate memory");
            return free_list(new_head);
        }
        new_state->id = states[i];
        new_state->next = NULL;
        *current = new_state;
        current = &(*current)->next;
    }

    if (last_state_id >= 0 && fsa[last_state_id].next != NULL) {
        perror("Invalid last state ID");
        return free_list(new_head);
    }

    fsa[last_state_id].next = new_head;

    return new_head;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

State* free_list(State* head) {
    State* current = head;
    while (current != NULL) {
        State* next = current->next;
        free(current);
        current = next;
    }
    return NULL;
}
