<?php

require_once 'vendor/autoload.php';

use Symfony\Component\Yaml\Yaml;
use Kubernetes\Client\KubernetesClient;

class DeploymentScript
{
    private $config;
    private $client;

    public function __construct($configFile)
    {
        $this->config = Yaml::parse(file_get_contents($configFile));
        $this->client = new KubernetesClient($this->config['kubernetes']['api_url'], $this->config['kubernetes']['token']);
    }

    public function deploy($environmentVariables, $overrides = [])
    {
        try {
            $this->loadVendorAutoloader();
            $this->configureApplication($overrides);
            $this->deployToKubernetes($environmentVariables);

            echo "Deployment successful!\n";
        } catch (\Exception $e) {
            echo "Error: " . $e->getMessage() . "\n";
        }
    }

    private function loadVendorAutoloader()
    {
        require_once 'vendor/autoload.php';
    }

    private function configureApplication($overrides)
    {
        // Load and override application configuration
        $config = Yaml::parse(file_get_contents('config/app.yaml'));
        foreach ($overrides as $key => $value) {
            if (array_key_exists($key, $config)) {
                $config[$key] = $value;
            }
        }

        // Write updated configuration to file or use it in the application
    }

    private function deployToKubernetes($environmentVariables)
    {
        // Build Kubernetes deployment YAML
        $deploymentYaml = [
            'apiVersion' => 'apps/v1',
            'kind' => 'Deployment',
            'metadata' => [
                'name' => $this->config['application']['name'],
            ],
            'spec' => [
                'replicas' => $this->config['kubernetes']['replicas'],
                'template' => [
                    'metadata' => [
                        'labels' => [
                            'app' => $this->config['application']['name'],
                        ],
                    ],
                    'spec' => [
                        'containers' => [
                            [
                                'name' => $this->config['application']['name'],
                                'image' => $this->config['application']['image'],
                                'env' => array_map(function ($key, $value) {
                                    return ['name' => $key, 'value' => $value];
                                }, array_keys($environmentVariables), $environmentVariables),
                            ],
                        ],
                    ],
                ],
            ],
        ];

        // Deploy to Kubernetes
        $response = $this->client->createDeployment($deploymentYaml);
        if ($response['status'] == 201) {
            echo "Deployment created successfully.\n";
        } else {
            throw new \Exception("Failed to create deployment: " . json_encode($response));
        }
    }

    public static function main()
    {
        $script = new DeploymentScript('config/deployment.yaml');
        $environmentVariables = [
            'DB_HOST' => $_ENV['DB_HOST'] ?? 'localhost',
            'DB_USER' => $_ENV['DB_USER'] ?? 'root',
            'DB_PASSWORD' => $_ENV['DB_PASSWORD'] ?? '',
            // Add more environment variables as needed
        ];

        if (isset($_SERVER['argv'][1])) {
            $overrides = Yaml::parse(file_get_contents($_SERVER['argv'][1]));
            $script->deploy($environmentVariables, $overrides);
        } else {
            $script->deploy($environmentVariables);
        }
    }
}

DeploymentScript::main();
