```java
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.concurrent.*;

public class FileUploaderService {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final Cache<String, String> cache = Caffeine.newBuilder().maximumSize(1000).build();

    public void uploadFile(String filePath, String bucketName, String directoryPath, CloudStorageService service) {
        try {
            Path file = Paths.get(filePath);
            if (!Files.exists(file)) {
                throw new FileNotFoundException("File not found: " + filePath);
            }

            String sha256Hash = calculateSHA256Hash(file);
            if (cache.getIfPresent(sha256Hash) != null) {
                System.out.println("File already uploaded.");
                return;
            }

            if (!service.fileExists(bucketName, directoryPath, sha256Hash)) {
                service.uploadFile(file, bucketName, directoryPath, sha256Hash);
                cache.put(sha256Hash, filePath);
                System.out.println("File uploaded successfully.");
            } else {
                System.out.println("File already exists in the specified location.");
            }
        } catch (Exception e) {
            System.err.println("Failed to upload file: " + e.getMessage());
        }
    }

    private String calculateSHA256Hash(Path file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream inputStream = Files.newInputStream(file)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    interface CloudStorageService {
        boolean fileExists(String bucketName, String directoryPath, String sha256Hash);
        void uploadFile(Path file, String bucketName, String directoryPath, String sha256Hash) throws IOException;
    }

    // Unit tests and additional functionality would be implemented here
}
