use pest::{Parser, Rule};
use llvm_ir::*;

fn generate_llvm_ir(file_path: &str) {
    let input = std::fs::read_to_string(file_path).expect("Failed to read file");

    let mut parser = MyGrammarParser::new();
    match parser.parse(Rule::file, &input) {
        Ok(pairs) => {
            for pair in pairs {
                match pair.as_rule() {
                    Rule::node => println!("Parsed Node: {:?}", pair),
                    // Handle other rules and generate LLVM IR code
                    _ => {}
                }
            }

            // Generate LLVM IR code
            let llvm_module = Module::new("my_module");
            let function_type = FunctionType::new(BasicBlockType::Int32, vec![]);
            let function = Function::with_name_and_type(&llvm_module, "main", &function_type);
            llvm_module.add_function(&function);

            // Output LLVM IR code
            println!("{}", llvm_module.to_string());
        }

        Err(e) => {
            eprintln!("Error parsing input: {:?}", e);
        }
    }
}

