#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONCURRENT_CONVERSIONS 10

typedef struct {
    char *input_file;
    char *output_dir;
} ConversionJob;

void fetch_metadata(const char *file_name) {
    // Simulated external REST API call to fetch metadata
    printf("Fetching metadata for %s\n", file_name);
}

int convert_to_pdf(const char *input_file, const char *output_dir) {
    // Simulated conversion process
    printf("Converting %s to PDF in %s\n", input_file, output_dir);
    return 0; // Return 0 on success, non-zero on failure
}

void* worker_thread(void *arg) {
    ConversionJob *job = (ConversionJob *) arg;
    fetch_metadata(job->input_file);
    int result = convert_to_pdf(job->input_file, job->output_dir);
    if (result != 0) {
        printf("Error converting %s to PDF\n", job->input_file);
    }
    free(job);
    return NULL;
}

void convert_images(const char *file_names[], const char *output_dirs[], int num_files) {
    pthread_t threads[MAX_CONCURRENT_CONVERSIONS];
    sem_t sem;
    sem_init(&sem, 0, MAX_CONCURRENT_CONVERSIONS);

    for (int i = 0; i < num_files; ++i) {
        ConversionJob *job = malloc(sizeof(ConversionJob));
        job->input_file = strdup(file_names[i]);
        job->output_dir = strdup(output_dirs[i]);

        sem_wait(&sem);
        pthread_create(&threads[i], NULL, worker_thread, (void *) job);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
        sem_post(&sem);
    }

    sem_destroy(&sem);
}

int main() {
    const char *file_names[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    const char *output_dirs[] = {"/path/to/output1", "/path/to/output2", "/path/to/output3"};

    int num_files = sizeof(file_names) / sizeof(file_names[0]);
    convert_images(file_names, output_dirs, num_files);

    return 0;
}
```

