import java.util.concurrent.CompletableFuture;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class OrderProcessor {
    private static final Logger logger = LoggerFactory.getLogger(OrderProcessor.class);
    private final InventoryService inventoryService;
    private final FinancialService financialService;
    private final UserService userService;
    private final MetricsService metricsService;
    private final CircuitBreaker circuitBreaker;

    public OrderProcessor(InventoryService inventoryService, FinancialService financialService,
                         UserService userService, MetricsService metricsService, CircuitBreaker circuitBreaker) {
        this.inventoryService = inventoryService;
        this.financialService = financialService;
        this.userService = userService;
        this.metricsService = metricsService;
        this.circuitBreaker = circuitBreaker;
    }

    public CompletableFuture<String> processOrder(String orderId, String userId, Map<String, Integer> productQuantities) {
        return circuitBreaker.runAsync(() -> {
            try {
                // Validate order and product IDs
                userService.validateUser(userId);
                productService.validateProducts(productQuantities.keySet());

                // Check inventory and financial credits
                if (!inventoryService.checkInventory(productQuantities) ||
                    !financialService.hasSufficientCredits(userId, calculateTotalOrderValue(productQuantities))) {
                    throw new InsufficientResourcesException("Insufficient inventory or funds");
                }

                // Update inventory and financial records atomically
                inventoryService.updateInventory(productQuantities);
                financialService.adjustCredits(userId, -calculateTotalOrderValue(productQuantities));

                // Notify user of order status
                userService.notifyUser(orderId, "Order processed successfully");

                // Recalculate credit limit in the background
                CompletableFuture.runAsync(() -> {
                    try {
                        userService.recalculateCreditLimit(userId);
                    } catch (Exception e) {
                        logger.error("Failed to recalculate credit limit for user {}", userId, e);
                    }
                });

                metricsService.logOrderProcessingTime(System.currentTimeMillis() - startTime);

                return "Order processed successfully";
            } catch (Exception e) {
                metricsService.incrementErrorCount();
                throw new OrderProcessingException("Failed to process order", e);
            }
        });
    }

    private double calculateTotalOrderValue(Map<String, Integer> productQuantities) {
        // Calculate total order value based on product prices
        return productQuantities.entrySet().stream()
                               .mapToDouble(entry -> productService.getProductPrice(entry.getKey()) * entry.getValue())
                               .sum();
    }
}
