using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;

public class HashUtility
{
    private readonly ConcurrentQueue<Action> _hashQueue = new ConcurrentQueue<Action>();
    private readonly int _maxConcurrentHashes;

    public HashUtility(int maxConcurrentHashes)
    {
        _maxConcurrentHashes = maxConcurrentHashes;
    }

    public string GetMD5Hash(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));
        return MD5.Create().ComputeHash(System.Text.Encoding.UTF8.GetBytes(input)).ToHexString();
    }

    public bool ValidateHashAgainstSalt(string input, string salt, string hashedValueWithSalt)
    {
        if (string.IsNullOrEmpty(salt)) throw new ArgumentException("Salt cannot be null or empty", nameof(salt));
        if (string.IsNullOrEmpty(hashedValueWithSalt)) throw new ArgumentException("Hashed value with salt cannot be null or empty", nameof(hashedValueWithSalt));

        string computedHash = GetMD5Hash(input + salt);
        return computedHash.Equals(hashedValueWithSalt, StringComparison.OrdinalIgnoreCase);
    }

    private static string ToHexString(byte[] bytes)
    {
        using (var sb = new StringBuilder(bytes.Length * 2))
        {
            foreach (byte b in bytes)
                sb.AppendFormat("{0:x2}", b);
            return sb.ToString();
        }
    }

    public void EnqueueHashAction(Action action)
    {
        _hashQueue.Enqueue(action);

        if (_hashQueue.Count <= _maxConcurrentHashes)
        {
            _hashQueue.TryDequeue(out var currentAction);
            _ = Task.Run(currentAction, CancellationToken.None);
        }
    }
}
