        // Custom claims validation logic
        try {
            String keyId = JWTUtils.getKeyId(jwt);
            String token = kmsTokenCache.get(keyId);
            if (token == null) {
                token = kmsProvider.fetchToken(keyId);
                kmsTokenCache.put(keyId, token);
            }
            return JWTUtils.validateJWT(jwt, token);
        } catch (Exception e) {
            // Handle exception
            return false;
        }
    }

