def _download_file_in_chunks(iterator, total_size, progress_bar):
    data = BytesIO()
    with tqdm(total=total_size, unit='B', desc='Downloading', disable=not progress_bar) as pbar:
        for chunk in iterator:
            data.write(chunk)
            pbar.update(len(chunk))
    return data.getvalue()

def _read_file_in_chunks(file, total_size, chunk_size, progress_bar):
    data = BytesIO()
    with tqdm(total=total_size, unit='B', desc='Reading', disable=not progress_bar) as pbar:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            data.write(chunk)
            pbar.update(len(chunk))
    return data.getvalue()

