// Thread function for processing a single compressed file
void *process_file(void *arg) {
    FileProcessingData *file_data = (FileProcessingData *)arg;

    if (read_compressed_file(file_data->input_path, &file_data->data, &file_data->size) == 0) {
        parse_data(file_data->data, file_data->size, file_data->config_file);

        if (write_output_file(file_data->output_path, file_data->transformed_data, file_data->transformed_size) != 0) {
            log_error("Error writing output file: %s", file_data->output_path);
        }
    } else {
        log_error("Error reading compressed file: %s", file_data->input_path);
    }

    free(file_data->data);
    free(file_data->transformed_data);
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <config_file> <output_directory> <file_pattern>\n", argv[0]);
        return 1;
    }

    const char *config_file = argv[1];
    const char *output_dir = argv[2];
    const char *file_pattern = argv[3];

    // Initialize logging service
    log_init();

    // Populate file list based on file_pattern
    FileList files = get_files_matching_pattern(file_pattern);

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    for (int i = 0; i < files.count; i++) {
        FileProcessingData *file_data = malloc(sizeof(FileProcessingData));

        if (file_data == NULL) {
            log_error("Failed to allocate memory for file processing data");
            continue;
        }

        strcpy(file_data->input_path, files.paths[i]);
        snprintf(file_data->output_path, MAX_PATH_LENGTH, "%s/%s", output_dir, basename(files.paths[i]));

        if (pthread_create(&threads[thread_count], NULL, process_file, file_data) != 0) {
            log_error("Failed to create thread for processing file: %s", files.paths[i]);
            free(file_data);
        } else {
            thread_count++;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up and exit
    log_cleanup();
    free_file_list(&files);

    return 0;
}
