<?php
// Function to authenticate users via OAuth 2.0 with multiple providers and store access tokens securely
function authenticateUser($provider, $code) {
    // Initialize session
    if (session_status() == PHP_SESSION_NONE) {
        session_start();
    }

    // Define providers and their respective configuration
    $providers = [
        'google' => [
            'client_id'     => 'your_google_client_id',
            'client_secret' => 'your_google_client_secret',
            'redirect_uri'  => urlencode('http://yourdomain.com/authenticate.php')
        ],
        'facebook' => [
            'client_id'     => 'your_facebook_client_id',
            'client_secret' => 'your_facebook_client_secret',
            'redirect_uri'  => urlencode('http://yourdomain.com/authenticate.php')
        ],
        'github'   => [
            'client_id'     => 'your_github_client_id',
            'client_secret' => 'your_github_client_secret',
            'redirect_uri'  => urlencode('http://yourdomain.com/authenticate.php')
        ]
    ];

    // Check if the provider is supported
    if (!array_key_exists($provider, $providers)) {
        return [
            'status' => 'error',
            'message' => 'Unsupported provider'
        ];
    }

    // Initialize provider configuration
    $config = $providers[$provider];

    // Fetch access token from OAuth provider
    try {
        $tokenResponse = file_get_contents("https://$provider.com/oauth2/v3/token", false, stream_context_create([
            'http' => [
                'method'  => 'POST',
                'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                'content' => http_build_query([
                    'client_id'     => $config['client_id'],
                    'client_secret' => $config['client_secret'],
                    'grant_type'    => 'authorization_code',
                    'code'          => $code,
                    'redirect_uri'  => $config['redirect_uri']
                ])
            ]
        ]));

        // Decode token response
        $tokenData = json_decode($tokenResponse, true);

        // Check for errors in token response
        if (isset($tokenData['error'])) {
            return [
                'status' => 'error',
                'message' => 'Token error: ' . $tokenData['error'] . ($tokenData['error_description'] ? ' (' . $tokenData['error_description'] . ')' : '')
            ];
        }

        // Store access token in session
        $_SESSION[$provider . '_access_token'] = $tokenData['access_token'];

        // Call external token storage service
        storeAccessTokenInExternalService($tokenData['access_token'], $provider, $tokenData['expires_in']);

        return [
            'status' => 'success',
            'message' => 'User authenticated successfully'
        ];
    } catch (Exception $e) {
        return [
            'status' => 'error',
            'message' => 'Network error: ' . $e->getMessage()
        ];
    }
}

// Function to store access token in external token storage service
function storeAccessTokenInExternalService($accessToken, $provider, $expiresIn) {
    // External token storage service URL and credentials
    $storageUrl = 'https://yourtokenstorage.com/store';
    $storageCreds = ['username' => 'your_username', 'password' => 'your_password'];

    // Call external token storage service to store access token
    try {
        file_get_contents($storageUrl . '?' . http_build_query([
            'access_token' => $accessToken,
            'provider'     => $provider,
            'expires_in'   => $expiresIn
        ]), false, stream_context_create([
            'http' => [
                'header'  => "Authorization: Basic " . base64_encode($storageCreds['username'] . ':' . $storageCreds['password']) . "\r\n"
            ]
        ]));
    } catch (Exception $e) {
        // Handle error in storing access token
    }
}

// Example usage:
$result = authenticateUser('google', $_GET['code']);
echo json_encode($result);
?>
