import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import os

class StorageBackend:
    def store_hash(self, file_path, hash_value):
        raise NotImplementedError("Subclasses should implement this!")

class FileHasher:
    @staticmethod
    def calculate_file_md5(file_path, chunk_size=8192, progress_callback=None, storage_backend=None):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} does not exist.")

        def process_chunk(chunk):
            return hashlib.md5(chunk).digest()

        def report_progress(future):
            try:
                result = future.result()
                if progress_callback:
                    # Calculate progress based on chunk size and total file size
                    progress_callback(int((future.index + 1) * chunk_size / os.path.getsize(file_path) * 100))
            except Exception as e:
                print(f"Error processing chunk: {e}")

        with open(file_path, 'rb') as f:
            chunks = [f.read(chunk_size) for _ in range((os.path.getsize(file_path) + chunk_size - 1) // chunk_size)]

        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(process_chunk, chunk, index=i) for i, chunk in enumerate(chunks)]

            total_md5_digest = hashlib.md5()
            for future in as_completed(futures):
                try:
                    chunk_md5 = future.result()
                    total_md5_digest.update(chunk_md5)
                except Exception as e:
                    print(f"Error processing chunk: {e}")

                if progress_callback:
                    report_progress(future)

        if storage_backend:
            storage_backend.store_hash(file_path, total_md5_digest.hexdigest())

        return total_md5_digest.hexdigest()
