#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct {
    char *device_name;
    char ip_address[INET_ADDRSTRLEN];
    int port_number;
    void *config_settings;
} NetworkDevice;

typedef struct {
    int bandwidth_limit;
    int priority_level;
    void (*callback_function)(void *);
} ConfigSettings;

typedef enum {
    DEVICE_LIST_EMPTY,
    INVALID_IP_FORMAT,
    PORT_NUMBER_OUT_OF_RANGE,
    CONFIG_SETTINGS_NULL,
    CALLBACK_FUNCTION_FAILURE,
    MEMORY_ALLOCATION_FAILURE,
    LOGGING_FAILURE,
    CONCURRENT_ACCESS_ERROR,
    TIMEOUT_EXPIRED,
    ERROR_UNKNOWN
} ErrorCode;

ErrorCode process_device_list(NetworkDevice **devices, int device_count) {
    // Check if the device list is empty or NULL
    if (device_count <= 0 || devices == NULL) {
        return DEVICE_LIST_EMPTY;
    }

    for (int i = 0; i < device_count; i++) {
        NetworkDevice *device = devices[i];
        ConfigSettings *config = device->config_settings;

        // Validate the IP address format
        struct sockaddr_in sa;
        if (inet_pton(AF_INET, device->ip_address, &(sa.sin_addr)) != 1) {
            return INVALID_IP_FORMAT;
        }

        // Validate the port number range
        if (device->port_number < 0 || device->port_number > 65535) {
            return PORT_NUMBER_OUT_OF_RANGE;
        }

        // Ensure the configuration settings pointer is not NULL
        if (config == NULL) {
            return CONFIG_SETTINGS_NULL;
        }

        // Call the callback function for each device
        if (config->callback_function != NULL) {
            config->callback_function(config);
        } else {
            return CALLBACK_FUNCTION_FAILURE;
        }
    }

    return SUCCESS;
}
