import time
import json

class NetworkResourceOptimizer:
    def __init__(self, urls):
        self.urls = urls
        self.retry_intervals = [1, 2, 4, 8]
        self.max_retries = 5
        self.num_threads = 10

    def add_url(self, url):
        self.urls.append(url)

    def check_availability(self, url):
        try:
            start_time = time.time()
            response = requests.get(url)
            response.raise_for_status()
            end_time = time.time()
            return True, end_time - start_time
        except requests.RequestException as e:
            return False, str(e)

    def fetch_metadata(self, urls):
        with ThreadPoolExecutor(max_workers=self.num_threads) as executor:
            future_to_url = {executor.submit(self.check_availability, url): url for url in urls}
            metadata = {}
            for future in as_completed(future_to_url):
                url = future_to_url[future]
                try:
                    is_available, response_time = future.result()
                    metadata[url] = {'available': is_available, 'response_time': response_time}
                except Exception as exc:
                    metadata[url] = {'error': str(exc)}
        return metadata

