```java
import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.regex.Pattern;

public class LogAnalyzer {

    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private Pattern errorPattern = Pattern.compile("error|warning", Pattern.CASE_INSENSITIVE);
    private Cache<String, List<String>> cache = new Cache<>();

    public void analyzeLogs(String directoryPath) {
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isFile() && file.getName().endsWith(".log")) {
                    executorService.submit(() -> processFile(file));
                }
            }
        }
    }

    private void processFile(File file) {
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (errorPattern.matcher(line).find()) {
                    cache.put(file.getName(), line);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
