using System;
using System.Collections.Generic;
using System.Xml.Linq;

public class ConfigurationLoader
{
    private Dictionary<string, object> _settings = new Dictionary<string, object>();
    private static readonly object _lock = new object();

    public void LoadConfiguration(string filePath)
    {
        lock (_lock)
        {
            try
            {
                var doc = XDocument.Load(filePath);
                foreach (var element in doc.Root.Elements())
                {
                    if (!_settings.ContainsKey(element.Name.LocalName))
                        _settings[element.Name.LocalName] = Convert.ChangeType(element.Value, Type.GetTypeCode(Type.GetType(element.Name.LocalName).UnderlyingSystemType));
                    else
                        // Handle overriding logic here
                        Console.WriteLine($"Warning: Overriding setting '{element.Name.LocalName}' with value '{element.Value}'.");
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to load configuration from {filePath}: {ex.Message}");
            }
        }
    }

    public void UpdateConfiguration(string key, object value)
    {
        lock (_lock)
        {
            if (_settings.ContainsKey(key))
            {
                _settings[key] = value;
                LogInfo($"Updated setting '{key}' to '{value}'.");
            }
            else
                LogWarning($"Attempted to update non-existent setting '{key}'.");
        }
    }

    public T GetConfiguration<T>(string key)
    {
        if (_settings.ContainsKey(key))
            return (T)_settings[key];
        else
        {
            LogError($"Failed to retrieve configuration for key '{key}'.");
            throw new KeyNotFoundException($"Key '{key}' not found in configuration settings.");
        }
    }

    private void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    private void LogWarning(string message)
    {
        Console.WriteLine($"WARNING: {message}");
    }

    private void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}

