// Main function to process the network stream and upload files
int main(int argc, char *argv[]) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];
    ParsingRule *rules = NULL;
    int rule_count = 0;

    // Initialize the socket and connect to the server
    memset(&servaddr, 0, sizeof(servaddr));
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(8080);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        exit(EXIT_FAILURE);
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connection with the server failed");
        exit(EXIT_FAILURE);
    }

    // Load parsing rules from an external API endpoint
    loadParsingRules("http://example.com/api/rules", &rules, &rule_count);

    while (1) {
        // Read data from the network stream
        int n = readNetworkStream(sockfd, buffer, sizeof(buffer));
        if (n <= 0) {
            break;
        }

        // Apply parsing rules to the data
        for (int i = 0; i < rule_count; i++) {
            applyParsingRule(rules[i], buffer);
        }

        // Upload the processed file using a third-party logging service
        char *upload_url = NULL;
        uploadFile("processed_file.txt", &upload_url);
        printf("Uploaded file URL: %s\n", upload_url);
    }

    free(rules);
    close(sockfd);
    return 0;
}
