```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class DecryptionService : IDisposable
{
    private readonly Aes _aes;

    public DecryptionService()
    {
        _aes = Aes.Create();
    }

    public byte[] Decrypt(byte[] ciphertext, CipherMode mode, byte[] key, byte[] iv)
    {
        using (var decryptor = _aes.CreateDecryptor(key, iv))
        {
            var decryptedData = new MemoryStream();
            using (var cryptoStream = new CryptoStream(decryptedData, decryptor, CryptoStreamMode.Write))
            {
                try
                {
                    cryptoStream.Write(ciphertext, 0, ciphertext.Length);
                }
                catch (CryptographicException ex)
                {
                    throw new InvalidOperationException("Decryption failed.", ex);
                }
            }

            return decryptedData.ToArray();
        }
    }

    public byte[] DecryptAesCbc(byte[] ciphertext, byte[] key, byte[] iv)
    {
        _aes.Mode = CipherMode.CBC;
        return Decrypt(ciphertext, _aes.Mode, key, iv);
    }

    public byte[] DecryptAesGcm(byte[] ciphertext, byte[] tag, byte[] additionalAuthenticatedData, byte[] key, byte[] nonce)
    {
        _aes.Mode = CipherMode.GCM;
        using (var decryptor = _aes.CreateDecryptor(key, nonce))
        {
            var decryptedData = new MemoryStream();
            using (var cryptoStream = new CryptoStream(decryptedData, decryptor, CryptoStreamMode.Write))
            {
                try
                {
                    cryptoStream.Write(ciphertext, 0, ciphertext.Length);
                    decryptor.Tag = tag;
                }
                catch (CryptographicException ex)
                {
                    throw new InvalidOperationException("Decryption failed.", ex);
                }
            }

            return decryptedData.ToArray();
        }
    }

    public void Dispose()
    {
        _aes.Dispose();
    }
}

// Example usage:
public class Program
{
    public static void Main()
    {
        var decryptionService = new DecryptionService();

        // AES-CBC decryption example
        byte[] aesCbcKey = GetRandomBytes(32);
        byte[] aesCbcIv = GetRandomBytes(16);
        byte[] aesCbcCiphertext = ...; // Your ciphertext here

        try
        {
            byte[] decryptedAesCbcData = decryptionService.DecryptAesCbc(aesCbcCiphertext, aesCbcKey, aesCbcIv);
            Console.WriteLine("Decrypted AES-CBC data: " + Convert.ToBase64String(decryptedAesCbcData));
        }
        catch (Exception ex)
        {
            Console.WriteLine("AES-CBC decryption error: " + ex.Message);
        }

        // AES-GCM decryption example
        byte[] aesGcmKey = GetRandomBytes(32);
        byte[] aesGcmNonce = GetRandomBytes(12);
        byte[] aesGcmCiphertext = ...; // Your ciphertext here
        byte[] aesGcmTag = ...; // Your tag here

        try
        {
            byte[] decryptedAesGcmData = decryptionService.DecryptAesGcm(aesGcmCiphertext, aesGcmTag, null, aesGcmKey, aesGcmNonce);
            Console.WriteLine("Decrypted AES-GCM data: " + Convert.ToBase64String(decryptedAesGcmData));
        }
        catch (Exception ex)
        {
            Console.WriteLine("AES-GCM decryption error: " + ex.Message);
        }

        decryptionService.Dispose();
    }

    private static byte[] GetRandomBytes(int length)
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var bytes = new byte[length];
            rng.GetBytes(bytes);
            return bytes;
        }
    }
}
