```java
import java.io.*;
import java.util.Properties;

public class ObjectDeserializer {

    private static final String CONFIG_FILE = "deserialization_config.properties";
    private Properties configProperties;

    public ObjectDeserializer() {
        loadConfig();
    }

    private void loadConfig() {
        configProperties = new Properties();
        try (InputStream input = getClass().getClassLoader().getResourceAsStream(CONFIG_FILE)) {
            if (input == null) {
                throw new RuntimeException("Configuration file not found: " + CONFIG_FILE);
            }
            configProperties.load(input);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration file", e);
        }
    }

    public Object deserialize(byte[] byteArray) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(byteArray);
             ObjectInputStream ois = new ObjectInputStream(bis)) {

            String className = configProperties.getProperty("class.name");
            if (className == null || className.isEmpty()) {
                throw new RuntimeException("Class name not specified in the configuration file");
            }

            Class<?> clazz = Class.forName(className);
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }
}
