#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_LINE_LENGTH 1024

typedef struct {
    char *timestamp;
    char *clientIP;
    char *requestMethod;
    char *url;
    char *httpVersion;
    int responseStatus;
    long long responseSize;
} LogEntry;

LogEntry* parseLogLine(char* line) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    // Assuming the format is fixed and does not require dynamic memory allocation for each field
    return entry;
}

void freeLogEntry(LogEntry* entry) {
    free(entry->timestamp);
    free(entry->clientIP);
    free(entry->requestMethod);
    free(entry->url);
    free(entry->httpVersion);
    free(entry);
}

double calculateAverageResponseSize(LogEntry** entries, int count) {
    double sum = 0;
    for (int i = max(0, count - 2); i < count; i++) {
        sum += entries[i]->responseSize;
    }
    return count > 1 ? sum / min(count, 2) : 0;
}

void processLogFiles(char** filePaths, int fileCount) {
    LogEntry** entries = (LogEntry**)malloc(fileCount * sizeof(LogEntry*));
    for (int i = 0; i < fileCount; i++) {
        FILE* file = fopen(filePaths[i], "r");
        if (file == NULL) {
            fprintf(stderr, "Error opening file: %s\n", filePaths[i]);
            continue;
        }
        char line[MAX_LOG_LINE_LENGTH];
        while (fgets(line, MAX_LOG_LINE_LENGTH, file)) {
            entries[i] = parseLogLine(line);
            // Process each log entry here
        }
        fclose(file);
    }

    double averageResponseSize = calculateAverageResponseSize(entries, fileCount);
    printf("Average response size over last two entries: %.2f\n", averageResponseSize);

    for (int i = 0; i < fileCount; i++) {
        freeLogEntry(entries[i]);
    }
    free(entries);
}

