    } else {
        printf("Executing database query.\n");
        execute_query(db_conn, query);

        // Cache the result
        cache_manager->set_cache(cache_manager, query, /* result */);
    }

    // Cleanup resources
    close_db_connection(db_conn);
    destroy_cache_manager(cache_manager);
    TIFFClose(tif);
}

