}

int main() {
    pthread_t threads[MAX_THREADS];
    FileProcessingParams params[MAX_THREADS];
    ParsingRule* parsing_rules;
    int rule_count;

    load_parsing_rules(&parsing_rules, &rule_count);
    initialize_logging_service();

