using System;
using System.Data;
using System.IO;
using System.IO.Compression;
using System.Net.Sockets;
using System.Threading.Tasks;

public class DatabaseClient
{
    private readonly string _serverAddress;
    private readonly int _port;

    public DatabaseClient(string serverAddress, int port)
    {
        _serverAddress = serverAddress;
        _port = port;
    }

    public async Task<DataTableReader> ExecuteQueryAsync(string query)
    {
        var watch = new System.Diagnostics.Stopwatch();
        watch.Start();

        using (var connection = new TcpClient(_serverAddress, _port))
        using (var stream = connection.GetStream())
        using (var memoryStream = new MemoryStream())
        {
            byte[] data = CompressData(Encoding.UTF8.GetBytes(query));

            try
            {
                await stream.WriteAsync(data, 0, data.Length);
                watch.Stop();
                LogCompressionRatio((double)data.Length / query.Length);
                LogTransmissionTime(watch.Elapsed);

                // Assuming the server sends a DataTable in binary format
                await stream.CopyToAsync(memoryStream);
                memoryStream.Seek(0, SeekOrigin.Begin);

                var dataTable = new DataTable();
                dataTable.ReadXml(memoryStream);

                return dataTable.CreateDataReader();
            }
            catch (SocketException ex)
            {
                LogError(ex.Message);
                throw;
            }
        }
    }

    private byte[] CompressData(byte[] data)
    {
        using (var compressedStream = new MemoryStream())
        {
            using (var gzipStream = new GZipStream(compressedStream, CompressionMode.Compress))
            {
                gzipStream.Write(data, 0, data.Length);
            }
            return compressedStream.ToArray();
        }
    }

    private void LogCompressionRatio(double ratio)
    {
        Console.WriteLine($"Compression Ratio: {ratio:F2}");
    }

    private void LogTransmissionTime(TimeSpan timeSpan)
    {
        Console.WriteLine($"Transmission Time: {timeSpan.TotalSeconds} seconds");
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine(message);
    }
}
