extern crate reqwest;
use reqwest::ClientBuilder;
use std::fs;

// Function to create an HTTP client with optional certificate validation
fn create_http_client(disable_ssl: bool) -> ClientBuilder {
    if disable_ssl {
        ClientBuilder::new().danger_accept_invalid_certs(true)
    } else {
        ClientBuilder::new()
    }
}

// Logging function using a similar approach to snprintf for formatting messages
fn log_message(format: &str, args: std::fmt::Arguments<'_>) -> String {
    format!("{}", args).to_string() // Simplified for demonstration
}

// Main program structure
fn main() {
    let url = "https://example.com";
    let disable_ssl = false; // Set to true if SSL should be disabled

    // Create HTTP client
    let client = create_http_client(disable_ssl);

    // Define the file path
    let file_path = "example.txt";

    // Check and delete the file if it exists
    if fs::metadata(file_path).is_ok() {
        fs::remove_file(file_path).expect("Failed to remove file");
        log_message("File deleted successfully.", &format_args!("Deleted: {}", file_path));
    }

    // Create a RequestBuilder using the client
    let request = client.get(url);

    // Send HTTP request and handle response
    match request.send() {
        Ok(mut response) => {
            // Read the output stream
            let body = response.text().expect("Failed to read response");
            log_message("Response received:", &format_args!("{}", body));

            // Optionally, handle error stream if needed
        }
        Err(e) => {
            log_message("Error occurred:", &format_args!("Error: {}", e));
        }
    }
}
