#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

Record* records;
int record_count;
int next_key = 0;
pthread_mutex_t mutex;

void initialize_records(int count, FILE* config_file) {
    pthread_mutex_init(&mutex, NULL);
    records = (Record*)malloc(count * sizeof(Record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    record_count = count;

    // Load initial random values from the configuration file
    for (int i = 0; i < count; i++) {
        if (fscanf(config_file, "%d %ld", &records[i].key, &records[i].offset) != 2) {
            fprintf(stderr, "Failed to read initial values from config file\n");
            exit(EXIT_FAILURE);
        }
    }

    // Log initialization details
    printf("Records initialized with %d entries\n", count);
}

void* update_record(void* arg) {
    int key = *(int*)arg;
    pthread_mutex_lock(&mutex);

    // Find the record and update its offset value
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            records[i].offset += rand() % 1000; // Simulate an update
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* retrieve_record(void* arg) {
    int key = *(int*)arg;
    pthread_t threads[record_count];
    int thread_ids[record_count];

    for (int i = 0; i < record_count; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, update_record, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < record_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log retrieval details
    printf("Record with key %d updated and retrieved\n", key);

    return NULL;
}

int main() {
    FILE* config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        perror("Failed to open configuration file");
        exit(EXIT_FAILURE);
    }

    initialize_records(1000, config_file); // Initialize with 1000 records
    fclose(config_file);

    int key_to_update = rand() % record_count; // Simulate a random key

    retrieve_record(&key_to_update); // Retrieve and update the record

    pthread_mutex_destroy(&mutex);
    free(records);
    return 0;
}
