using Newtonsoft.Json.Linq;

public class HtmlElementUpdaterMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string _cmsApiUrl;
    private readonly ICmsApiClient _cmsApiClient;
    private readonly IDesEncryptor _desEncryptor;

    public HtmlElementUpdaterMiddleware(RequestDelegate next, string cmsApiUrl, ICmsApiClient cmsApiClient, IDesEncryptor desEncryptor)
    {
        _next = next;
        _cmsApiUrl = cmsApiUrl;
        _cmsApiClient = cmsApiClient;
        _desEncryptor = desEncryptor;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method == "POST" && context.Request.Path.StartsWithSegments("/update-element"))
        {
            var requestBody = await new StreamReader(context.Request.Body).ReadToEndAsync();
            var requestData = JObject.Parse(requestBody);

            string pageSectionId = requestData["page_section_id"].ToString();
            string elementId = requestData["element_id"].ToString();
            string htmlContent = requestData["html_content"].ToString();

            // Fetch updated HTML content from CMS
            var updatedHtml = await _cmsApiClient.GetUpdatedHtmlAsync(_cmsApiUrl, pageSectionId, elementId);

            if (!string.IsNullOrEmpty(updatedHtml))
            {
                // Encrypt the updated HTML content using DES algorithm
                string encryptedHtml = _desEncryptor.Encrypt(updatedHtml, "your-secret-key", DesMode.CFB);

                // Apply the encrypted HTML to the webpage
                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(JsonConvert.SerializeObject(new { success = true, encrypted_html = encryptedHtml }));
            }
            else
            {
                context.Response.StatusCode = StatusCodes.Status404NotFound;
                await context.Response.WriteAsync(JsonConvert.SerializeObject(new { success = false, message = "Element not found" }));
            }
        }
        else
        {
            await _next(context);
        }
    }
}

public interface ICmsApiClient
{
    Task<string> GetUpdatedHtmlAsync(string apiUrl, string pageSectionId, string elementId);
}

public class CmsApiClient : ICmsApiClient
{
    private readonly HttpClient _httpClient;

    public CmsApiClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<string> GetUpdatedHtmlAsync(string apiUrl, string pageSectionId, string elementId)
    {
        // Implement logic to fetch updated HTML content from CMS API
        var response = await _httpClient.GetAsync($"{apiUrl}/fetch?section={pageSectionId}&element={elementId}");
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsStringAsync();
        }
        else
        {
            return null;
        }
    }
}

public interface IDesEncryptor
{
    string Encrypt(string data, string key, DesMode mode);
}

public class DesEncryptor : IDesEncryptor
{
    public enum DesMode { ECB, EDE, EDE3, CFB }

    private readonly SymmetricAlgorithm _des;

    public DesEncryptor()
    {
        _des = Aes.Create();
    }

    public string Encrypt(string data, string key, DesMode mode)
    {
        byte[] keyBytes = Encoding.UTF8.GetBytes(key);
        _des.Key = keyBytes;
        _des.Mode = (CipherMode)Enum.Parse(typeof(CipherMode), mode.ToString());

        ICryptoTransform encryptor = _des.CreateEncryptor();
        using (MemoryStream msEncrypt = new MemoryStream())
        {
            using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
            {
                using (StreamWriter swEncrypt = new StreamWriter(csEncrypt))
                {
                    swEncrypt.Write(data);
                }
                return Convert.ToBase64String(msEncrypt.ToArray());
            }
        }
    }
}
