        return EXIT_FAILURE;
    }

    const char *input_path = argv[1];
    const char *output_path = argv[2];
    json_object *rules;

    read_config_file(argv[3], &rules);

    if (!rules) {
        fprintf(stderr, "Error: Invalid configuration file.\n");
        return EXIT_FAILURE;
    }

    process_log_file(input_path, output_path, rules);

    json_object_put(rules);
    return EXIT_SUCCESS;
}

void read_config_file(const char *config_path, json_object **rules) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Error opening config file");
        *rules = NULL;
        return;
    }

    fseek(file, 0L, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0L, SEEK_SET);

    char *buffer = (char *)malloc((file_size + 1) * sizeof(char));
    if (!buffer) {
        perror("Error allocating memory for config buffer");
        fclose(file);
        *rules = NULL;
        return;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        perror("Error reading config file");
        free(buffer);
        fclose(file);
        *rules = NULL;
        return;
    }
    buffer[bytes_read] = '\0';

    *rules = json_tokener_parse(buffer);

    free(buffer);
    fclose(file);
}

