#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <libcurl/curl.h>

#define MAX_CONCURRENT_CONVERSIONS 10

typedef struct {
    char* input_file;
    char* output_dir;
    int urgency_level;
} ConversionJob;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    ConversionJob jobs[MAX_CONCURRENT_CONVERSIONS];
    int job_count;
    int available_slots;
} JobQueue;

void* worker_thread(void* arg) {
    JobQueue* queue = (JobQueue*)arg;

    while (1) {
        pthread_mutex_lock(&queue->lock);
        while (queue->job_count == 0 && queue->available_slots > 0) {
            pthread_cond_wait(&queue->cond, &queue->lock);
        }

        if (queue->job_count == 0) {
            pthread_mutex_unlock(&queue->lock);
            break;
        }

        ConversionJob job = queue->jobs[--queue->job_count];
        pthread_mutex_unlock(&queue->lock);

        // Simulate metadata fetching and conversion
        printf("Processing %s\n", job.input_file);
        sleep(2);  // Simulating time taken for processing

        // Log completion
        printf("Converted %s to PDF in %s\n", job.input_file, job.output_dir);
    }

    return NULL;
}

void submit_job(JobQueue* queue, ConversionJob job) {
    pthread_mutex_lock(&queue->lock);

    while (queue->job_count >= MAX_CONCURRENT_CONVERSIONS && queue->available_slots == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }

    if (queue->job_count < MAX_CONCURRENT_CONVERSIONS) {
        queue->jobs[queue->job_count++] = job;
        queue->available_slots--;
        pthread_cond_signal(&queue->cond);
    }

    pthread_mutex_unlock(&queue->lock);
}

int main() {
    JobQueue queue;
    pthread_t threads[MAX_CONCURRENT_CONVERSIONS];
    int num_threads = MAX_CONCURRENT_CONVERSIONS;

    pthread_mutex_init(&queue.lock, NULL);
    pthread_cond_init(&queue.cond, NULL);

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &queue);
    }

    // Simulate submitting jobs
    ConversionJob job1 = {"image1.jpg", "output_dir1", 1};
    ConversionJob job2 = {"image2.jpg", "output_dir2", 3};

    submit_job(&queue, job1);
    submit_job(&queue, job2);

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&queue.lock);
    pthread_cond_destroy(&queue.cond);

    return 0;
}
```

