#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <string>
#include <memory>

class DistributedDBManager {
public:
    struct Record {
        int id;
        double timestamp;
        std::vector<std::string> tags;
    };

private:
    std::vector<long*> offsetArray;
    std::vector<int*> keyArray;
    std::vector<double*> timestampArray;
    std::vector<Record> records;
    std::mutex mutex;
    std::condition_variable cv;
    bool paused = false;

public:
    DistributedDBManager(int numRecords) {
        for (int i = 0; i < numRecords; ++i) {
            offsetArray.push_back(new long(0));
            keyArray.push_back(new int(i));
            timestampArray.push_back(new double(0.0));
        }
    }

    ~DistributedDBManager() {
        for (auto& ptr : offsetArray) delete ptr;
        for (auto& ptr : keyArray) delete ptr;
        for (auto& ptr : timestampArray) delete ptr;
    }

    void addRecord(const Record& record) {
        std::lock_guard<std::mutex> lock(mutex);
        records.push_back(record);
        cv.notify_one();
    }

    void pause() {
        std::unique_lock<std::mutex> lock(mutex);
        paused = true;
    }

    void resume() {
        std::unique_lock<std::mutex> lock(mutex);
        paused = false;
        cv.notify_all();
    }

    void processRecords() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !paused || records.empty(); });

            if (records.empty()) break;

            Record record = records.front();
            records.erase(records.begin());

            // Simulate database write operation
            std::cout << "Writing record: ID=" << record.id << ", Timestamp=" << record.timestamp 
                      << ", Tags=" << record.tags.size() << std::endl;
        }
    }

    void connectToDatabase() {
        // Simulate database connection logic
        std::cout << "Connecting to database..." << std::endl;
    }

    void disconnectFromDatabase() {
        // Simulate database disconnection logic
        std::cout << "Disconnecting from database..." << std::endl;
    }
};

int main() {
    DistributedDBManager dbManager(10);
    dbManager.connectToDatabase();

    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back(&DistributedDBManager::processRecords, &dbManager);
    }

    // Simulate adding records
    for (int i = 0; i < 10; ++i) {
        DistributedDBManager::Record record = {i, static_cast<double>(i), {"tag" + std::to_string(i)}};
        dbManager.addRecord(record);
    }

    dbManager.pause();
    dbManager.resume();

    for (auto& thread : threads) thread.join();

    dbManager.disconnectFromDatabase();

    return 0;
}
```

