import asyncio
import aiohttp
from functools import wraps
import redis.asyncio as aioredis
from datetime import datetime
import logging

# Initialize Redis client
redis_client = await aioredis.create_redis_pool('redis://localhost')

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def rate_limiter(max_calls, period):
    def decorator(func):
        calls = []
        @wraps(func)
        async def wrapper(*args, **kwargs):
            current_time = time.time()
            calls = [call for call in calls if current_time - call < period]
            if len(calls) >= max_calls:
                logger.warning("Rate limit exceeded. Retrying after 1 second.")
                await asyncio.sleep(1)
            calls.append(current_time)
            return await func(*args, **kwargs)
        return wrapper
    return decorator

def retry_on_failure(max_retries=3):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            retries = 0
            while retries < max_retries:
                try:
                    return await func(*args, **kwargs)
                except Exception as e:
                    logger.warning(f"Request failed with {e}. Retrying...")
                    retries += 1
                    if retries == max_retries:
                        raise
        return wrapper
    return decorator

def cache_data(cache_key):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            cached_data = await redis_client.get(cache_key)
            if cached_data:
                logger.info("Fetching data from cache")
                return cached_data.decode()
            else:
                result = await func(*args, **kwargs)
                await redis_client.setex(cache_key, 3600, result)  # Cache for 1 hour
                return result
        return wrapper
    return decorator

async def fetch_stock_data(api_url):
    session = aiohttp.ClientSession()
    try:
        async with session.get(api_url) as response:
            data = await response.json()
            if 'Time Series (Daily)' in data:  # Example for Alpha Vantage
                daily_data = data['Time Series (Daily)']
                return {date: {'open': entry['1. open'], 'close': entry['4. close']} for date, entry in daily_data.items()}
            elif 'chart' in data:  # Example for Yahoo Finance
                chart_data = data['chart']['result'][0]['indicators']['quote'][0]
                return {entry['date']: {'open': entry['open'], 'close': entry['close']} for entry in chart_data}
            else:
                raise ValueError("Unsupported API response format")
    except aiohttp.ClientError as e:
        logger.error(f"API request failed: {e}")
        raise

async def process_stock_data(api_url, cache_key):
    @rate_limiter(max_calls=5, period=60)
    @retry_on_failure()
    @cache_data(cache_key)
    async def fetch_and_cache():
        return await fetch_stock_data(api_url)

    return await fetch_and_cache()

async def main():
    apis = [
        ("https://www.alphavantage.co/query?function=DAILY&symbol=AAPL&apikey=YOUR_API_KEY", "AAPL_daily"),
        ("https://finance.yahoo.com/quote/AAPL/history?p=AAPL", "AAPL_yahoo")
    ]

    tasks = [process_stock_data(api_url, cache_key) for api_url, cache_key in apis]
    results = await asyncio.gather(*tasks)

    for result in results:
        logger.info(result)

# Run the main function
asyncio.run(main())
```

This code provides a basic structure for processing real-time stock market data from multiple financial APIs. It uses asynchronous programming with `aiohttp` for concurrent requests, Redis for caching, and logging for tracking the status of operations. The code includes decorators for rate limiting, retrying failed requests, and caching data. The `fetch_stock_data` function handles parsing responses from different API formats.

To use this code, you'll need to replace placeholders like `YOUR_API_KEY` with actual API keys and adjust the cache keys according to your needs. You can also extend or modify the `process_stock_data` and `fetch_stock_data` functions to support additional APIs and data processing logic.

