#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <limits.h>

// Function to get the current working directory from the system
char* get_current_working_directory() {
    char *cwd = (char *)malloc(4096);
    if (getcwd(cwd, 4096) != NULL)
        return cwd;
    free(cwd);
    return NULL;
}

// Function to resolve symbolic links to their canonical form
char* resolve_symlink(const char *path) {
    char resolved_path[PATH_MAX];
    ssize_t len = readlink(path, resolved_path, sizeof(resolved_path) - 1);
    if (len != -1) {
        resolved_path[len] = '\0';
        return strdup(resolved_path);
    }
    return strdup(path);
}

// Function to expand environment variables in the path
char* expand_environment_variables(const char *path) {
    char *expanded_path = getenv("HOME");
    if (!expanded_path)
        expanded_path = "~";
    const char *user_home = getenv(expanded_path);
    if (user_home && user_home[0] != '\0') {
        size_t len = strlen(user_home) + strlen(path) - 1;
        char *new_path = (char *)malloc(len + 1);
        snprintf(new_path, len + 1, "%s%s", user_home, path + 1);
        return new_path;
    }
    return strdup(path);
}

// Main function to process the file path
char* process_file_path(const char *path, int max_buffer_size, bool is_absolute, char *error_message) {
    // Allocate memory for the full path
    char *full_path = (char *)malloc(max_buffer_size + 1);
    if (!full_path) {
        snprintf(error_message, max_buffer_size, "Memory allocation failed");
        return NULL;
    }

    // Expand environment variables
    char *expanded_path = expand_environment_variables(path);

    // Resolve symbolic links
    char *resolved_path = resolve_symlink(expanded_path);

    // Check if the path exceeds the maximum buffer size
    if (strlen(resolved_path) >= max_buffer_size) {
        free(full_path);
        free(expanded_path);
        free(resolved_path);
        snprintf(error_message, max_buffer_size, "Path exceeds the maximum buffer size");
        return NULL;
    }

    // Append the current working directory if not absolute
    if (!is_absolute) {
        char *cwd = get_current_working_directory();
        if (cwd) {
            snprintf(full_path, max_buffer_size, "%s/%s", cwd, resolved_path);
            free(cwd);
        } else {
            snprintf(error_message, max_buffer_size, "Failed to retrieve current working directory");
            free(full_path);
            free(expanded_path);
            free(resolved_path);
            return NULL;
        }
    } else {
        strncpy(full_path, resolved_path, max_buffer_size - 1);
        full_path[max_buffer_size - 1] = '\0';
    }

    // Clean up allocated memory
    free(expanded_path);
    free(resolved_path);

    return full_path;
}

int main() {
    char error_message[256];
    char *full_path = process_file_path("~/.config/settings.conf", 4096, false, error_message);
    if (full_path) {
        printf("Full Path: %s\n", full_path);
        free(full_path);
    } else {
        printf("Error: %s\n", error_message);
    }
    return 0;
}
