#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t *sem;
    unsigned int count_acquire;
    unsigned int count_release;
} SemaphoreManager;

SemaphoreManager* create_semaphore(unsigned int initial_value) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!manager) {
        perror("Failed to allocate memory for semaphore manager");
        return NULL;
    }

    manager->sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_value);
    if (manager->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }
    manager->count_acquire = 0;
    manager->count_release = 0;

    return manager;
}

void delete_semaphore(SemaphoreManager *manager) {
    if (manager->sem != SEM_FAILED) {
        sem_close(manager->sem);
        sem_unlink("/my_semaphore");
    }
    free(manager);
}

int acquire_semaphore(SemaphoreManager *manager) {
    if (sem_wait(manager->sem) == -1) {
        perror("Failed to acquire semaphore");
        return -1;
    }
    manager->count_acquire++;
    return 0;
}

int release_semaphore(SemaphoreManager *manager) {
    if (sem_post(manager->sem) == -1) {
        perror("Failed to release semaphore");
        return -1;
    }
    manager->count_release++;
    return 0;
}
