import subprocess
from threading import Thread
from time import sleep

class CommandExecutor:
    def __init__(self, max_concurrent=5):
        self.max_concurrent = max_concurrent
        self.active_processes = []

    def execute_command(self, command, timeout=None):
        if len(self.active_processes) >= self.max_concurrent:
            raise Exception("Maximum number of concurrent processes reached")

        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        self.active_processes.append(process)

        output_thread = Thread(target=self.stream_output, args=(process,))
        output_thread.start()

        try:
            return process.communicate(timeout=timeout)
        except TimeoutExpired:
            process.terminate()
            raise Exception("Command execution timed out")
        finally:
            self.active_processes.remove(process)

    def stream_output(self, process):
        while True:
            output = process.stdout.readline()
            if output == b'' and process.poll() is not None:
                break
            if output:
                # Integrate with external monitoring system here
                print(output.decode())

        rc = process.poll()
        return rc

    def chain_commands(self, commands):
        result = None
        for command in commands:
            result = self.execute_command(command)
        return result

# Example usage
executor = CommandExecutor(max_concurrent=3)

try:
    result = executor.chain_commands([
        "echo Hello",
        "ls -la /tmp"
    ])
    print("Command execution completed with result:", result)
except Exception as e:
    print("Error executing command:", str(e))
