    private HttpClient _httpClient;
    private Dictionary<string, string> _siteConfigurations;
    private Dictionary<string, DateTime> _cache;

    public WebsiteManager(string configFilePath) {
        Initialize(configFilePath);
        _httpClient = new HttpClient();
        _cache = new Dictionary<string, DateTime>();
    }

    private void Initialize(string configFilePath) {
