using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;
using YamlDotNet.Serialization;
using Newtonsoft.Json;
using Serilog;

class WebsiteManager
{
    private readonly ConcurrentDictionary<string, Website> _cache = new ConcurrentDictionary<string, Website>();
    private readonly ILogger _logger;
    private readonly WebServerManagementApi _api;

    public WebsiteManager(ILogger logger, WebServerManagementApi api)
    {
        _logger = logger;
        _api = api;
    }

    public async Task ManageWebsiteLifecycleAsync(string configFilePath, string outputJsonPath)
    {
        try
        {
            var configuration = LoadConfiguration(configFilePath);
            var sites = ParseSites(configuration);

            foreach (var site in sites)
            {
                if (!_cache.TryGetValue(site.Name, out var cachedSite))
                {
                    _logger.Information("Fetching {SiteName} from API", site.Name);
                    cachedSite = await _api.GetWebsiteAsync(site.Name);
                    _cache.TryAdd(site.Name, cachedSite);
                }

                switch (site.Operation)
                {
                    case "add":
                        if (!cachedSite.Exists)
                        {
                            await _api.AddWebsiteAsync(site);
                            _logger.Information("Added {SiteName}", site.Name);
                        }
                        break;
                    case "remove":
                        if (cachedSite.Exists)
                        {
                            await _api.RemoveWebsiteAsync(site);
                            _logger.Information("Removed {SiteName}", site.Name);
                        }
                        break;
                    case "start":
                        if (!cachedSite.IsRunning)
                        {
                            await _api.StartWebsiteAsync(site);
                            _logger.Information("Started {SiteName}", site.Name);
                        }
                        break;
                    case "stop":
                        if (cachedSite.IsRunning)
                        {
                            await _api.StopWebsiteAsync(site);
                            _logger.Information("Stopped {SiteName}", site.Name);
                        }
                        break;
                    case "restart":
                        if (!cachedSite.IsRunning)
                        {
                            await _api.StartWebsiteAsync(site);
                            _logger.Information("Restarted {SiteName}", site.Name);
                        }
                        else
                        {
                            await _api.StopWebsiteAsync(site);
                            await _api.StartWebsiteAsync(site);
                            _logger.Information("Restarted {SiteName}", site.Name);
                        }
                        break;
                }
            }

            var output = JsonConvert.SerializeObject(sites, Formatting.Indented);
            File.WriteAllText(outputJsonPath, output);
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "An error occurred while managing website lifecycle");
            throw;
        }
    }

