```javascript
class TransactionReducer {
  constructor(apiUrl, maxConnections = 10) {
    this.apiUrl = apiUrl;
    this.maxConnections = maxConnections;
    this.workerPool = [];
    this.transactionQueue = [];
    this.processing = false;
  }

  async fetchTransactionDetails(id) {
    try {
      const response = await fetch(`${this.apiUrl}/transactions/${id}`);
      if (!response.ok) throw new Error('Failed to fetch transaction details');
      return await response.json();
    } catch (error) {
      console.error(`Error fetching transaction ${id}:`, error);
      // Retry logic with exponential backoff
      const delay = Math.pow(2, this.retryCount++) * 100;
      return new Promise(resolve => setTimeout(() => resolve(this.fetchTransactionDetails(id)), delay));
    }
  }

  async validateAndReduce(transaction) {
    // Simulate validation and reduction logic
    return { ...transaction, weightedAverage: calculateWeightedAverage(transaction.keyValuePairs) };
  }

  addTransactions(transactions) {
    this.transactionQueue.push(...transactions);
    if (!this.processing) this.startProcessing();
  }

  async startProcessing() {
    this.processing = true;
    while (this.transactionQueue.length > 0 && this.workerPool.length < this.maxConnections) {
      const transactionId = this.transactionQueue.shift();
      this.workerPool.push(this.fetchTransactionDetails(transactionId).then(this.validateAndReduce.bind(this)).finally(() => {
        this.workerPool.splice(this.workerPool.indexOf(null), 1);
        if (this.transactionQueue.length > 0) this.startProcessing();
      }));
    }
    if (this.workerPool.length === 0) this.processing = false;
  }
}

function calculateWeightedAverage(keyValuePairs) {
