<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIP, $timeout = 30) {
    $mysqli = new mysqli("localhost", "username", "password", "database");

    if ($mysqli->connect_error) {
        die('Connect Error (' . $mysqli->connect_errno . ') ' . $mysqli->connect_error);
    }

    $mysqli->set_charset("utf8mb4");

    $query = "UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=? WHERE id=?";
    $stmt = $mysqli->prepare($query);

    if ($stmt === false) {
        die('Prepare Error (' . $mysqli->errno . ') ' . $mysqli->error);
    }

    $lastModifiedDate = date('Y-m-d H:i:s');
    $stmt->bind_param("sssi", $newStatus, $lastModifiedIP, $lastModifiedDate, $clinicId);

    if (!$stmt->execute()) {
        die('Execute Error (' . $stmt->errno . ') ' . $stmt->error);
    }

    $stmt->close();
    $mysqli->close();

    return "Update successful";
}
?>
