using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public class UserProfileUpdater
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, string> _connectionStrings;
    private readonly int _rateLimit;

    public UserProfileUpdater(string configFilePath)
    {
        var config = LoadConfig(configFilePath);
        _connectionStrings = new Dictionary<string, string>
        {
            { "LocalDatabase", config["LocalDatabaseConnectionString"] },
            { "ExternalDatabase", config["ExternalDatabaseConnectionString"] }
        };
        _rateLimit = int.Parse(config["RateLimit"]);
        _httpClient = new HttpClient();
    }

    private Dictionary<string, string> LoadConfig(string filePath)
    {
        var config = new Dictionary<string, string>();
        using (var reader = new StreamReader(filePath))
        {
            while (!reader.EndOfStream)
            {
                var line = reader.ReadLine().Trim();
                if (!string.IsNullOrEmpty(line) && !line.StartsWith("//"))
                {
                    var parts = line.Split('=');
                    config[parts[0].Trim()] = parts[1].Trim();
                }
            }
        }
        return config;
    }

    public async Task UpdateUserProfiles(List<UserProfile> profiles)
    {
        foreach (var profile in profiles)
        {
            await ValidateAndProcessProfile(profile);
        }
    }

    private async Task ValidateAndProcessProfile(UserProfile profile)
    {
        if (!IsValidEmail(profile.Email))
        {
            throw new ArgumentException("Invalid email format.");
        }

        if (!IsValidPhoneNumber(profile.PhoneNumber))
        {
            throw new ArgumentException("Invalid phone number format.");
        }

        // Check for duplicates
        if (IsDuplicateEmail(profile.Email) || IsDuplicatePhoneNumber(profile.PhoneNumber))
        {
            throw new InvalidOperationException("Duplicate email or phone number.");
        }

        // Update local database
        using (var db = new UserProfileDbContext(_connectionStrings["LocalDatabase"]))
        {
            await db.UpdateProfileAsync(profile);
        }

        // Update external API
        try
        {
            var response = await _httpClient.PutAsJsonAsync("https://api.example.com/users", profile);
            response.EnsureSuccessStatusCode();
        }
        catch (HttpRequestException ex)
        {
            // Handle HTTP request errors and retry as needed
            Console.WriteLine($"API update failed: {ex.Message}");
        }

        // Update external database if API call is successful
        using (var db = new UserProfileDbContext(_connectionStrings["ExternalDatabase"]))
        {
            await db.UpdateProfileAsync(profile);
        }
    }

    private bool IsValidEmail(string email)
    {
        // Implement email validation logic
        return true;
    }

    private bool IsValidPhoneNumber(string phoneNumber)
    {
        // Implement phone number validation logic
        return true;
    }

    private bool IsDuplicateEmail(string email)
    {
        // Check for duplicate emails in the local database
        using (var db = new UserProfileDbContext(_connectionStrings["LocalDatabase"]))
        {
            return db.UserProfiles.Any(p => p.Email == email);
        }
    }

    private bool IsDuplicatePhoneNumber(string phoneNumber)
    {
        // Check for duplicate phone numbers in the local database
        using (var db = new UserProfileDbContext(_connectionStrings["LocalDatabase"]))
        {
            return db.UserProfiles.Any(p => p.PhoneNumber == phoneNumber);
        }
    }
