```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <future>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <sqlite3.h>

// External metadata API function prototype
std::string fetchMetadata(int id);

// Function to resize dynamic array
void resizeArray(std::vector<int>& data, int newSize) {
    data.resize(newSize);
}

// Asynchronous task for processing each integer
void processInteger(int id, std::vector<int>& dataArray, std::queue<int>& tasksQueue, std::mutex& queueMutex, std::condition_variable& conditionVariable, sqlite3* db) {
    std::unique_lock<std::mutex> lock(queueMutex);
    tasksQueue.push(id);
    conditionVariable.notify_one();

    while (true) {
        conditionVariable.wait(lock, []{ return !tasksQueue.empty(); });
        int id = tasksQueue.front();
        tasksQueue.pop();
        lock.unlock();

        // Fetch metadata from API
        std::string metadata = fetchMetadata(id);

        // Store data in database
        sqlite3_stmt* stmt;
        sqlite3_prepare_v2(db, "INSERT INTO metadata (id, metadata) VALUES (?, ?)", -1, &stmt, nullptr);
        sqlite3_bind_int(stmt, 1, id);
        sqlite3_bind_text(stmt, 2, metadata.c_str(), metadata.size(), SQLITE_STATIC);
        sqlite3_step(stmt);
        sqlite3_finalize(stmt);

        // Log API interaction
        std::cout << "Processed ID: " << id << ", Metadata: " << metadata << std::endl;
    }
}

int main() {
    const int MAX_THREADS = 10;
    std::vector<int> dataArray;
    std::queue<int> tasksQueue;
    std::mutex queueMutex;
    std::condition_variable conditionVariable;

    sqlite3* db;
    sqlite3_open("metadata.db", &db);
    sqlite3_exec(db, "CREATE TABLE IF NOT EXISTS metadata (id INTEGER PRIMARY KEY, metadata TEXT)", nullptr, nullptr, nullptr);

    // Resize array dynamically as data is fetched
    resizeArray(dataArray, 1000000); // Assuming up to 1 million integers

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < MAX_THREADS; ++i) {
        workers.emplace_back(processInteger, i, std::ref(dataArray), std::ref(tasksQueue), std::ref(queueMutex), std::ref(conditionVariable), db);
    }

    // Simulate fetching and processing data
    for (int i = 0; i < dataArray.size(); ++i) {
        dataArray[i] = i; // Populate array with sample data
        std::unique_lock<std::mutex> lock(queueMutex);
        tasksQueue.push(i);
        conditionVariable.notify_one();
    }

    // Join worker threads
    for (auto& worker : workers) {
        worker.join();
    }

    sqlite3_close(db);

    return 0;
}
```

