    }

    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $characters[rand(0, strlen($characters) - 1)];
    }

    return $randomString;
}

function hashPassword($password, $algorithm = 'bcrypt', $rounds = 12) {
    if (!in_array($algorithm, ['bcrypt', 'sha256'])) {
        throw new InvalidArgumentException('Unsupported hash algorithm');
    }

    $salt = password_hash($password, PASSWORD_BCRYPT);
    return hash($algorithm, $password . $salt, false);
}

function main() {
    try {
        $length = 10;
        $characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_=+[]{}|;:,.<>?';
        $password = 'secure_password';

        $randomString = generateRandomString($length, $characters);
        $hashedPassword = hashPassword($password);

        echo "Random String: " . $randomString . "\n";
        echo "Hashed Password: " . $hashedPassword . "\n";
    } catch (InvalidArgumentException $e) {
        echo "Error: " . $e->getMessage() . "\n";
