# Python function for generating HTTP requests and storing data in InfluxDB

import os
import time
from requests import get, post,.exceptions
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
from influxdb_client import InfluxDBClient, Point

def fetch_and_store_data():
    # Configure environment variables
    api_urls = os.getenv('API_URLS').split(',')
    client_id = os.getenv('CLIENT_ID')
    client_secret = os.getenv('CLIENT_SECRET')
    kms_token_url = os.getenv('KMS_TOKEN_URL')

    influx_host = os.getenv('INFLUX_HOST')
    influx_org = os.getenv('INFLUX_ORG')
    influx_bucket = os.getenv('INFLUX_BUCKET')

    # Set up OAuth2 session
    client = BackendApplicationClient(client_id=client_id)
    oauth = OAuth2Session(client=client)
    token = oauth.fetch_token(token_url=kms_token_url, client_id=client_id, client_secret=client_secret)

    # Connect to InfluxDB
    influx_client = InfluxDBClient(url=influx_host, org=influx_org, token=token['access_token'])
    write_api = influx_client.write_api()

    for url in api_urls:
        try:
            response = get(url, headers={'Authorization': f'Bearer {token["access_token"]}'})
            data = response.json()

            # Process and store data
            point = Point('api_data').tag('url', url).fields(data)
            write_api.write(bucket=influx_bucket, org=influx_org, record=point)

        except (requests.exceptions.RequestException, ValueError) as e:
            print(f"Error fetching or processing data from {url}: {e}")

    influx_client.close()

# Call the function to fetch and store data
fetch_and_store_data()
