// C++ code for processing geospatial data

#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

struct GeospatialData {
    double latitude;
    double longitude;
    long timestamp;
};

class DataProcessor {
public:
    void addData(const GeospatialData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_.push_back(data);
        cv_.notify_one();
    }

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !data_.empty(); });

            GeospatialData data = data_.back();
            data_.pop_back();

            lock.unlock();

            // Process data here
            std::cout << "Processing data: Lat=" << data.latitude << ", Lon=" << data.longitude << ", Timestamp=" << data.timestamp << std::endl;
        }
    }

private:
    std::vector<GeospatialData> data_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    DataProcessor processor;

    // Simulate adding data from IoT devices
    for (int i = 0; i < 10; ++i) {
        GeospatialData data = {37.421998, -122.084, time(nullptr)};
        processor.addData(data);
    }

    // Start processing thread
    std::thread processThread(&DataProcessor::processData, &processor);

    // Join the processing thread (in a real application, this would be more complex)
    processThread.join();

    return 0;
}
