```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/err.h>

// Define the maximum buffer size for cryptographic operations
#define MAX_BUFFER_SIZE 4096

// Function to initialize OpenSSL library
void init_openssl() {
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();
}

// Function to cleanup OpenSSL library
void cleanup_openssl() {
    EVP_cleanup();
    ERR_free_strings();
}

// Function to generate a random key using OpenSSL
int generate_key(unsigned char *key, int key_length) {
    return RAND_bytes(key, key_length);
}

// Function to encrypt data using AES-256-GCM cipher suite
int aes_gcm_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, const unsigned char *iv, unsigned char *ciphertext, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    ciphertext += len;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext, &len)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    ciphertext += len;
    int ct_len = len + plaintext_len;
    if (1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) { EVP_CIPHER_CTX_free(ctx); return -1; }

    EVP_CIPHER_CTX_free(ctx);
    return ct_len;
}

// Function to decrypt data using AES-256-GCM cipher suite
int aes_gcm_decrypt(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *tag, const unsigned char *key, const unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    if (1 != EVP_GCM_Init_ex(ctx, tag, NULL, 16)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    plaintext += len;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext, &len)) { EVP_CIPHER_CTX_free(ctx); return -1; }

    EVP_CIPHER_CTX_free(ctx);
    return len;
}

// Function to generate an RSA key pair using OpenSSL
int generate_rsa_key_pair(unsigned char *private_key, unsigned char *public_key) {
    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);

    if (RSA_generate_key_ex(rsa, 2048, e, NULL) != 1) return -1;

    BIO *private_pem = BIO_new(BIO_s_mem());
    BIO *public_pem = BIO_new(BIO_s_mem());

    PEM_write_bio_RSAPrivateKey(private_pem, rsa, NULL, NULL, 0, NULL, NULL);
    PEM_write_bio_RSA_PUBKEY(public_pem, rsa);

    int len = BIO_get_mem_data(private_pem, (char **)&private_key);
    BIO_free_all(private_pem);
    len = BIO_get_mem_data(public_pem, (char **)&public_key);
    BIO_free_all(public_pem);

    RSA_free(rsa);
    BN_free(e);

    return len;
}

// Function to encrypt data using RSA-OAEP cipher suite
int rsa_oaep_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *public_key, unsigned char *ciphertext) {
    EVP_PKEY *pkey = NULL;
    BIO *bio_public_key = BIO_new(BIO_s_mem());
    PEM_write_bio_RSAPUBKEY(bio_public_key, public_key);
    pkey = d2i_PUBKEY_bio(bio_public_key, &public_key);
    BIO_free_all(bio_public_key);

    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, pkey->pkey.rsa->d, pkey->pkey.rsa->n)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    ciphertext += len;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext, &len)) { EVP_CIPHER_CTX_free(ctx); return -1; }

    EVP_CIPHER_CTX_free(ctx);
    EVP_PKEY_free(pkey);

    return len;
}

// Function to decrypt data using RSA-OAEP cipher suite
int rsa_oaep_decrypt(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *private_key, unsigned char *plaintext) {
    EVP_PKEY *pkey = NULL;
    BIO *bio_private_key = BIO_new(BIO_s_mem());
    PEM_write_bio_RSAPrivateKey(bio_private_key, private_key, NULL, NULL, 0, NULL, NULL);
    pkey = d2i_PrivateKey_bio(bio_private_key, &private_key);
    BIO_free_all(bio_private_key);

    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, pkey->pkey.rsa->d, pkey->pkey.rsa->n)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) { EVP_CIPHER_CTX_free(ctx); return -1; }
    plaintext += len;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext, &len)) { EVP_CIPHER_CTX_free(ctx); return -1; }

    EVP_CIPHER_CTX_free(ctx);
    EVP_PKEY_free(pkey);

    return len;
}

// Function to handle key exchange with a Key Management Service (KMS)
