// Main function to demonstrate cryptographic operations
int main() {
    init_openssl();

    unsigned char key[MAX_BUFFER_SIZE];
    generate_key(key, sizeof(key));

    unsigned char iv[16];
    generate_key(iv, sizeof(iv));

    unsigned char plaintext[MAX_BUFFER_SIZE] = "Hello, World!";
    int plaintext_len = strlen((char *)plaintext);

    unsigned char ciphertext[MAX_BUFFER_SIZE];
    int ciphertext_len;

    unsigned char tag[16];
    aes_gcm_encrypt(plaintext, plaintext_len, key, iv, ciphertext, tag);
    printf("Ciphertext: ");
    BIO_dump_fp(stdout, (const char *)ciphertext, ciphertext_len);

    unsigned char decrypted_text[MAX_BUFFER_SIZE];
    int decrypted_text_len = aes_gcm_decrypt(ciphertext, ciphertext_len, tag, key, iv, decrypted_text);
    printf("Decrypted text: %s\n", decrypted_text);

    unsigned char private_key[MAX_BUFFER_SIZE], public_key[MAX_BUFFER_SIZE];
    generate_rsa_key_pair(private_key, public_key);

    unsigned char rsa_ciphertext[MAX_BUFFER_SIZE];
    int rsa_ciphertext_len = rsa_oaep_encrypt(plaintext, plaintext_len, public_key, rsa_ciphertext);
    printf("RSA ciphertext: ");
    BIO_dump_fp(stdout, (const char *)rsa_ciphertext, rsa_ciphertext_len);

    unsigned char rsa_decrypted_text[MAX_BUFFER_SIZE];
