const axios = require('axios');
const { WorkerPool } = require('./WorkerPool');
const { CircuitBreaker } = require('./CircuitBreaker');

class PaymentProcessor {
  constructor(workerCount, paymentGateways) {
    this.workerPool = new WorkerPool(workerCount);
    this.paymentGateways = paymentGateways.map(gateway => ({
      ...gateway,
      circuitBreaker: new CircuitBreaker()
    }));
  }

  async processPayments(paymentIds) {
    const results = [];
    for (const paymentId of paymentIds) {
      const result = await this.workerPool.execute(() => this.fetchPaymentDetails(paymentId));
      if (result.success) {
        results.push(result.data);
      } else {
        console.error(`Failed to fetch payment details for ID ${paymentId}: ${result.error}`);
      }
    }
    return results;
  }

  async fetchPaymentDetails(paymentId) {
    const provider = this.selectProvider();
    try {
      await provider.circuitBreaker.execute(async () => {
        const response = await axios.get(provider.url, { timeout: provider.timeout });
        if (response.data.status === 'success') {
          return response.data.paymentDetails;
        } else {
          throw new Error(`Payment status ${response.data.status}`);
        }
      });
    } catch (error) {
      console.error(`Error fetching payment details for ID ${paymentId}: ${error.message}`);
      return { success: false, error };
    }
  }

  selectProvider() {
    // Logic to select a provider based on load balancing and availability
    return this.paymentGateways[0];
  }
}

// Example usage:
const paymentProcessor = new PaymentProcessor(10, [
  { url: 'https://providerA.com/api', timeout: 5000 },
  { url: 'https://providerB.com/api', timeout: 7000 }
]);

(async () => {
  const paymentIds = Array.from({ length: 2000 }, (_, i) => `paymentId${i}`);
  const results = await paymentProcessor.processPayments(paymentIds);
  console.log('Processed Payments:', results);
})();
