```javascript
const http = require('http');
const net = require('net');
const ssh2 = require('ssh2');
const async = require('async');

module.exports = class RemoteShellExecutor {
  constructor(options) {
    this.options = options;
    this.sshClientPool = [];
    this.initSSHClientPool();
  }

  initSSHClientPool() {
    for (let i = 0; i < this.options.maxConcurrentTasks; i++) {
      const client = new ssh2.Client();
      client.on('ready', () => {
        this.sshClientPool.push(client);
      }).on('error', (err) => {
        console.error('SSH Client Error:', err);
      });
    }
  }

  async executeCommand(server, command) {
    return new Promise((resolve, reject) => {
      const client = this.sshClientPool.shift();
      if (!client) {
        reject(new Error('No available SSH clients'));
        return;
      }

      client.connect({
        host: server.host,
        port: server.port,
        username: server.username,
        privateKey: server.privateKey
      }).then(() => {
        const stream = client.shell();
        let output = '';
        stream.on('data', (chunk) => {
          output += chunk.toString();
          this.logExecutionStatus(server, command, 'running');
        });
        stream.on('end', () => {
          resolve(output);
          this.logExecutionStatus(server, command, 'completed');
          client.end();
          this.sshClientPool.push(client);
        });
        stream.on('error', (err) => {
          reject(err);
          this.logExecutionStatus(server, command, 'failed');
          client.end();
          this.sshClientPool.push(client);
        });
        stream.write(command + '\n');
      }).catch(reject);
    });
  }

  async executeTasks(tasks) {
    return new Promise((resolve, reject) => {
      async.eachLimit(tasks, this.options.maxConcurrentTasks, async (task, callback) => {
        try {
          const result = await this.executeCommand(task.server, task.command);
          callback(null, { server: task.server, command: task.command, result });
        } catch (error) {
          callback(error);
        }
      }, (err, results) => {
        if (err) {
          reject(err);
        } else {
          resolve(results);
        }
      });
    });
  }

  logExecutionStatus(server, command, status) {
    const timestamp = new Date().toISOString();
