// Define the Union-Find data structure
class UnionFind {
public:
    UnionFind(size_t size) : parent(size), rank(size, 0) {
        for (size_t i = 0; i < size; ++i) {
            parent[i] = i;
        }
    }

    int find(int u) {
        if (parent[u] != u) {
            parent[u] = find(parent[u]);
        }
        return parent[u];
    }

    void unite(int u, int v) {
        int pu = find(u);
        int pv = find(v);
        if (pu == pv) return;

        if (rank[pu] > rank[pv]) {
            parent[pv] = pu;
        } else if (rank[pu] < rank[pv]) {
            parent[pu] = pv;
        } else {
            parent[pu] = pv;
            ++rank[pv];
        }
    }

private:
    std::vector<int> parent;
    std::vector<int> rank;
};

// Function to parse JSON file
void parseJson(const std::string& filePath, std::unordered_map<std::string, Json::Value>& config) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open JSON configuration file");
    }
    Json::Reader reader;
    if (!reader.parse(file, config)) {
        throw std::runtime_error("Failed to parse JSON configuration file");
    }
}

