void fetchMetadata(const std::string& url, const std::unordered_map<std::string, Json::Value>& config, std::atomic<int>& successCount, std::atomic<int>& failureCount) {
    // Simulated API call
    if (config["api"]["endpoint"].asString() == url) {
        ++successCount;
    } else {
        ++failureCount;
    }
}

