    size_t arraySize = config["array_size"].asUInt();
    UnionFind uf(arraySize);
    std::atomic<int> successCount(0), failureCount(0);
    std::mutex mtx;
    std::condition_variable cv;
    bool done = false;

    // Simulate parsing and processing array
    for (size_t i = 0; i < arraySize; ++i) {
        uf.unite(i, (i + 1) % arraySize); // Simplified union operation
    }

    // Fetch metadata from external API in parallel
    std::vector<std::thread> threads;
    for (int i = 0; i < config["api"]["concurrency"].asInt(); ++i) {
        threads.emplace_back(fetchMetadata, config["api"]["endpoint"].asString(), std::ref(config), std::ref(successCount), std::ref(failureCount));
    }

    // Join all threads
    for (auto& thread : threads) {
        thread.join();
