function fetchAndUploadFile(url, metadata, providerConfig, retries = 3, delay = 1000) {
  return axios({
    method: 'GET',
    url,
    responseType: 'stream'
  })
  .then(response => {
    const fileSize = parseInt(response.headers['content-length'], 10);
    if (fileSize > 50 * 1024 * 1024) {
      throw new Error('File size exceeds the limit of 50MB');
    }

    return response.data;
  })
  .then(fileStream => {
    return providerConfig.uploadFile(fileStream, metadata);
  })
  .catch(error => {
    if (retries > 0) {
      logger.warn(`Upload failed. Retrying in ${delay}ms...`);
      return new Promise(resolve => setTimeout(resolve, delay))
        .then(() => fetchAndUploadFile(url, metadata, providerConfig, retries - 1, delay * 2));
    } else {
      throw error;
    }
  });
}

