import concurrent.futures
from abc import ABC, abstractmethod
import requests
import json
import time

class DataFetcher(ABC):
    @abstractmethod
    def fetch_data(self) -> dict:
        pass

class APIDataFetcher(DataFetcher):
    def __init__(self, api_url: str):
        self.api_url = api_url

    def fetch_data(self) -> dict:
        try:
            response = requests.get(self.api_url)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error fetching data from API: {e}")
            return {}

class DatabaseFetcher(DataFetcher):
    def __init__(self, db_query: str):
        self.db_query = db_query

    def fetch_data(self) -> dict:
        try:
            # Simulate database query
            time.sleep(1)
            return json.loads(self.db_query)
        except Exception as e:
            print(f"Error fetching data from database: {e}")
            return {}

class DataTransformer:
    @staticmethod
    def transform(data: dict) -> dict:
        transformed_data = {}
        # Add your transformation logic here
        return transformed_data

class HTMLReportGenerator:
    def __init__(self, template_path: str):
        self.template_path = template_path

    def generate_report(self, data: dict) -> str:
        with open(self.template_path, 'r') as file:
            template = file.read()
        # Add your report generation logic here
        return f"<html>{data}</html>"

class ReportService:
    def __init__(self):
        self.fetchers = []
        self.transformer = DataTransformer()
        self.report_generator = HTMLReportGenerator('template.html')
        self.cache = {}

    def add_fetcher(self, fetcher: DataFetcher):
        self.fetchers.append(fetcher)

    def generate_reports_concurrently(self) -> list:
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(fetcher.fetch_data) for fetcher in self.fetchers]
            data_list = [future.result() for future in concurrent.futures.as_completed(futures)]

        transformed_data = []
        for data in data_list:
            transformed_data.append(self.transformer.transform(data))

        reports = []
        for data in transformed_data:
            report = self.report_generator.generate_report(json.dumps(data))
            reports.append(report)

        return reports

# Example usage
api_fetcher = APIDataFetcher('https://api.example.com/data')
db_fetcher = DatabaseFetcher('SELECT * FROM example_table')
report_service = ReportService()
report_service.add_fetcher(api_fetcher)
