    if (json_object_object_get_ex(parsed_json, "access_token", &token.access_token_obj)) {
        token.access_token = json_object_get_string(token.access_token_obj);
    } else {
        fprintf(stderr, "Missing access_token field\n");
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_object_get_ex(parsed_json, "expires_in", &token.expires_in_obj)) {
        int expires_in_value = json_object_get_int(token.expires_in_obj);
        token.expires_in = time(NULL) + expires_in_value;
    } else {
        fprintf(stderr, "Missing expires_in field\n");
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_object_get_ex(parsed_json, "token_type", &token.token_type_obj)) {
        token.token_type = json_object_get_string(token.token_type_obj);
    } else {
