        token.scope = json_object_get_string(token.scope_obj);
        // Check if the scope matches the allowed scopes
        bool valid_scope = false;
        for (int i = 0; allowed_scopes[i] != NULL; i++) {
            if (!strcmp(token.scope, allowed_scopes[i])) {
                valid_scope = true;
                break;
            }
        }
        if (!valid_scope) {
            fprintf(stderr, "Invalid scope: %s\n", token.scope);
            json_object_put(parsed_json);
            return false;
