public static XPathNavigator ParseXmlElement(string xml, string elementName)
{
    var doc = new XPathDocument(xml);
    var nav = doc.CreateNavigator();

    if (nav.SelectSingleNode($"//{elementName}") == null)
        throw new Exception("No elements found.");
    if (nav.SelectNodes($"//{elementName}").Count > 1)
        throw new Exception("Multiple matching elements found.");

    return nav.SelectSingleNode($"//{elementName}");
}
