#include <stdio.h>
#include <string.h>

char* appendSlash(char* str, int maxLength) {
    if (str == NULL || *str == '\0') return NULL;

    int len = strlen(str);
    if (len >= maxLength) return NULL;

    char* newStr = (char*)realloc(str, len + 2);
    if (newStr == NULL) return NULL;

    strcat(newStr, "/");
    return newStr;
}
