const express = require('express');
const axios = require('axios');
const cache = require('memory-cache');

const app = express();
app.use(express.json());

// External API URLs
const weatherAPI = 'https://api.weather.com/current';
const forecastAPI = 'https://api.weather.com/forecast';
const climateAPI = 'https://api.weather.com/climate';

// Cache settings
const cacheTime = 3600 * 1000; // 1 hour

// Fallback API URL
const fallbackWeatherAPI = 'https://fallback.api.com/weather';

app.get('/weather', async (req, res) => {
  const { latitude, longitude } = req.query;

  try {
    // Check cache
    let cachedData = cache.get(`${latitude}-${longitude}`);
    if (cachedData) {
      return res.json(cachedData);
    }

    // Fetch data from APIs
    const weatherResponse = await axios.get(weatherAPI, { params: { latitude, longitude } });
    const forecastResponse = await axios.get(forecastAPI, { params: { latitude, longitude } });
    const climateResponse = await axios.get(climateAPI, { params: { latitude, longitude } });

    // Merge data
    const weatherData = weatherResponse.data;
    const forecastData = forecastResponse.data;
    const climateData = climateResponse.data;

    // Get satellite image link (this is pseudo code)
    const satelliteImageLink = await getSatelliteImage(latitude, longitude);

    // Create response object
    const response = {
      currentTemperature: weatherData.temperature,
      weatherConditions: weatherData.conditions,
      hourlyForecast: forecastData.forecast,
      monthlyClimateStatistics: climateData.statistics,
      satelliteImageLink
    };

    // Cache the data
    cache.put(`${latitude}-${longitude}`, response, cacheTime);

    res.json(response);
  } catch (error) {
    // Handle errors and provide fallback
    if (error.response && error.response.status === 429) {
      return res.status(503).json({ error: 'Service unavailable, try again later.' });
    }

    const fallbackResponse = await axios.get(fallbackWeatherAPI, { params: { latitude, longitude } });
    res.json(fallbackResponse.data);
  }
});

