using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;
using ThirdPartyLoggingLibrary;

[Serializable]
public class UserPreferences
{
    public string Theme { get; set; }
    public bool DarkMode { get; set; }
}

public class PreferenceCache
{
    private static PreferenceCache _instance;
    private readonly BinaryFormatter _formatter = new BinaryFormatter();
    private readonly object _lock = new object();
    private Dictionary<string, UserPreferences> _cache = new Dictionary<string, UserPreferences>();
    private string _binaryFilePath;
    private int _healthCheckInterval;
    private int _updateThreshold;

    public static PreferenceCache Instance
    {
        get
        {
            if (_instance == null)
            {
                lock (_lock)
                {
                    if (_instance == null)
                    {
                        _instance = new PreferenceCache();
                    }
                }
            }
            return _instance;
        }
    }

    private PreferenceCache()
    {
        LoadSettingsFromConfig();
        Task.Run(async () => await StartHealthCheck());
        Task.Run(async () => await MonitorDatabaseForChanges());
    }

    private void LoadSettingsFromConfig()
    {
        // Load settings from configuration file
        _binaryFilePath = "path/to/binary/file";
        _healthCheckInterval = 60; // in seconds
        _updateThreshold = 10; // number of changes to trigger update
    }

    public UserPreferences GetUserPreferences(string userId)
    {
        lock (_lock)
        {
            if (!_cache.ContainsKey(userId))
            {
                _cache[userId] = LoadFromBinaryFile(userId);
            }
            return _cache[userId];
        }
    }

    private UserPreferences LoadFromBinaryFile(string userId)
    {
        try
        {
            using (FileStream fs = new FileStream(_binaryFilePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                // Deserialize the binary file
                var data = _formatter.Deserialize(fs) as Dictionary<string, UserPreferences>;
                return data[userId];
            }
        }
        catch (Exception ex)
        {
            Logger.LogError($"Failed to load preferences for user {userId}: {ex.Message}");
            return LoadFromDatabase(userId);
        }
    }

    private UserPreferences LoadFromDatabase(string userId)
    {
        // Retrieve from database
        var dbService = new DatabaseService();
        return dbService.GetUserPreferences(userId);
    }

    private async Task StartHealthCheck()
    {
        while (true)
        {
            await Task.Delay(_healthCheckInterval * 1000);
            CheckBinaryFileHealth();
        }
    }

    private void CheckBinaryFileHealth()
    {
        try
        {
            using (FileStream fs = new FileStream(_binaryFilePath, FileMode.Open))
            {
                // Check if the file is accessible
            }
        }
        catch (Exception ex)
        {
            Logger.LogError($"Binary file health check failed: {ex.Message}");
            SendAlert();
        }
    }

    private void SendAlert()
    {
        // Notify system administrator or take appropriate action
    }

    private async Task MonitorDatabaseForChanges()
    {
        var dbService = new DatabaseService();
        int changesDetected = 0;

        while (true)
        {
            if (dbService.CheckForChanges())
            {
                changesDetected++;
                if (changesDetected >= _updateThreshold)
                {
                    UpdateCacheFromDatabase();
                    changesDetected = 0;
                }
            }

            await Task.Delay(1000); // Check every second
        }
    }

    private void UpdateCacheFromDatabase()
    {
        var dbService = new DatabaseService();
        var preferences = dbService.GetAllUserPreferences();

        lock (_lock)
        {
            _cache.Clear();
            foreach (var preference in preferences)
            {
                _cache[preference.UserId] = preference;
            }
        }

        Logger.LogInformation("Cache updated from database.");
    }
}
