#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <string.h>

// Define a structure for log entries
typedef struct {
    char message[1024];
} LogEntry;

// Define a structure for thread pool tasks
typedef struct {
    void (*function)(void*);
    void* argument;
} ThreadPoolTask;

// Initialize the error log and thread pool
LogEntry error_log[100];
int log_index = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
ThreadPoolTask task_queue[100];
int task_index = 0, next_task = 0, num_tasks = 0;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;

// Function to log a message with variable arguments
void log_message(const char* format, ...) {
    pthread_mutex_lock(&log_mutex);
    if (log_index < 100) {
        va_list args;
        va_start(args, format);
        snprintf(error_log[log_index].message, sizeof(error_log[log_index].message), format, args);
        log_index++;
        va_end(args);
    }
    pthread_mutex_unlock(&log_mutex);
}

// Function to add a task to the thread pool
void add_task(void (*function)(void*), void* argument) {
    pthread_mutex_lock(&queue_mutex);
    while (num_tasks == 100) {
        pthread_cond_wait(&queue_not_full, &queue_mutex);
    }
    if (task_index < 100) {
        task_queue[task_index].function = function;
        task_queue[task_index].argument = argument;
        task_index++;
        num_tasks++;
        pthread_cond_signal(&queue_not_empty);
    }
    pthread_mutex_unlock(&queue_mutex);
}

// Thread pool worker function
void* thread_pool_worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue_mutex);
        while (num_tasks == 0) {
            pthread_cond_wait(&queue_not_empty, &queue_mutex);
        }
        ThreadPoolTask task = task_queue[next_task];
        next_task++;
        num_tasks--;
        if (next_task == task_index) {
            next_task = 0;
            task_index = 0;
        }
        pthread_cond_signal(&queue_not_full);
        pthread_mutex_unlock(&queue_mutex);

        task.function(task.argument);
    }
}

// Function to initialize the thread pool
void init_thread_pool(int num_threads) {
    for (int i = 0; i < num_threads; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, thread_pool_worker, NULL);
    }
}
