import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class InventorySystem {

    private CassandraDatabase cassandraDB;
    private RedisCache redisCache;
    private StripePaymentGateway stripeGateway;
    private ApacheKafkaMessageQueue kafkaQueue;
    private ExecutorService executorService;

    public InventorySystem() {
        this.cassandraDB = new CassandraDatabase();
        this.redisCache = new RedisCache();
        this.stripeGateway = new StripePaymentGateway();
        this.kafkaQueue = new ApacheKafkaMessageQueue();
        this.executorService = Executors.newFixedThreadPool(10);
    }

    public void updateStock(String productId, int quantity) {
        // Update stock in Cassandra and cache
        cassandraDB.updateStock(productId, quantity);
        redisCache.updateStock(productId, quantity);

        // Publish update to Kafka for asynchronous processing
        kafkaQueue.publishUpdate(productId, quantity);
    }

    public boolean processTransaction(String productId, int amount) {
        // Check stock availability in Redis first for fast response
        if (!redisCache.hasSufficientStock(productId, amount)) {
            return false;
        }

        // Process payment through Stripe
        if (stripeGateway.processPayment(amount)) {
            // Deduct stock from Cassandra and update cache asynchronously
            executorService.submit(() -> cassandraDB.deductStock(productId, amount));
            redisCache.deductStock(productId, amount);
            kafkaQueue.publishTransaction(productId, amount);
            return true;
        }

        return false;
    }
}

