import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Properties;

public class CommandExecutor {

    private static final Properties CONFIG = loadConfig();

    public static void main(String[] args) {
        File logDir = new File(CONFIG.getProperty("logDirectory"));
        if (logDir.exists()) {
            try {
                Files.delete(logDir.toPath());
            } catch (IOException e) {
                logError("Failed to delete existing log directory: " + e.getMessage());
            }
        }

        String[] commands = CONFIG.getProperty("commands").split(",");
        for (String command : commands) {
            executeCommand(command, logDir);
        }
    }

    private static Properties loadConfig() {
        Properties properties = new Properties();
        try (InputStream input = CommandExecutor.class.getClassLoader().getResourceAsStream("config.properties")) {
            if (input == null) {
                throw new IOException("Config file not found");
            }
            properties.load(input);
        } catch (IOException e) {
            System.err.println("Failed to load config: " + e.getMessage());
        }
        return properties;
    }

    private static void executeCommand(String command, File logDir) {
        try {
            String[] cmdArray = command.split("\\s+");
            Process process = Runtime.getRuntime().exec(cmdArray, null, logDir);

            StreamGobbler errorGobbler = new StreamGobbler(process.getErrorStream(), "ERROR", logDir);
            StreamGobbler outputGobbler = new StreamGobbler(process.getInputStream(), "OUTPUT", logDir);

            errorGobbler.start();
            outputGobbler.start();

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                logError("Command execution failed with exit code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            logError("Failed to execute command: " + e.getMessage());
        }
    }

    private static void log(String level, String message, File logDir) {
        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(logDir.getAbsolutePath(), level + ".log"), java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.APPEND)) {
            writer.write(snprintf("[%s] %s\n", new java.util.Date().toString(), message));
        } catch (IOException e) {
            System.err.println("Failed to log: " + e.getMessage());
        }
    }

    private static void logError(String message) {
        log("ERROR", message, new File(CONFIG.getProperty("logDirectory")));
    }

    // Simulate snprintf function for formatting messages
    public static String snprintf(String format, Object... args) {
        return java.text.MessageFormat.format(format, args);
    }
}

class StreamGobbler extends Thread {
    private InputStream inputStream;
    private String level;
    private File logDir;

    public StreamGobbler(InputStream is, String level, File logDir) {
        this.inputStream = is;
        this.level = level;
        this.logDir = logDir;
    }

    @Override
    public void run() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                CommandExecutor.log(level, line, logDir);
            }
        } catch (IOException e) {
            System.err.println("Failed to read stream: " + e.getMessage());
        }
    }
}
