```javascript
const WebSocket = require('ws');
const crypto = require('crypto');

class DataCollector {
  constructor(config) {
    this.wsUrl = config.wsUrl;
    this.filterCriteria = config.filterCriteria;
    this.encryptionKey = null;
    this.salt = config.salt;
    this.iv = crypto.randomBytes(16);
    this.dataArray = [];
    this.isPaused = false;
    this.connectWebSocket();
  }

  connectWebSocket() {
    this.ws = new WebSocket(this.wsUrl);

    this.ws.on('open', () => {
      console.log('Connected to WebSocket');
    });

    this.ws.on('message', (data) => {
      if (!this.isPaused) {
        try {
          const message = JSON.parse(data);
          if (this.filterCriteria.includes(message.type)) {
            this.dataArray.push(message);
            this.encryptData();
          }
        } catch (error) {
          console.error('Error parsing WebSocket message:', error);
        }
      }
    });

    this.ws.on('close', () => {
      console.log('Disconnected from WebSocket');
      setTimeout(() => this.connectWebSocket(), 5000); // Reconnect after 5 seconds
    });

    this.ws.on('error', (error) => {
      console.error('WebSocket error:', error);
    });
  }

  encryptData() {
    if (this.encryptionKey === null) {
      this.encryptionKey = crypto.scryptSync(this.salt, 'salt', 32); // Derive key using scrypt
    }

    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(this.encryptionKey), this.iv);
    let encryptedData = cipher.update(JSON.stringify(this.dataArray), 'utf8', 'hex');
    encryptedData += cipher.final('hex');

    console.log('Encrypted Data:', encryptedData);

    // Reset data array and IV after encryption
    this.dataArray = [];
    this.iv = crypto.randomBytes(16);
  }

  pause() {
    this.isPaused = true;
    console.log('Data collection paused');
  }

  resume() {
    this.isPaused = false;
    console.log('Data collection resumed');
  }
}

