EVP_CIPHER *select_cipher(const char *mode, int key_length) {
    EVP_CIPHER *cipher = NULL;
    if (strcmp(mode, "ECB") == 0) {
        switch (key_length) {
            case 56: cipher = EVP_des_cbc(); break;
            default: fprintf(stderr, "Unsupported key length for ECB mode\n"); return NULL;
        }
    } else if (strcmp(mode, "EDE") == 0) {
        // Implement EDE
    } else if (strcmp(mode, "EDE3") == 0) {
        // Implement EDE3
    } else if (strcmp(mode, "CFB") == 0) {
        switch (key_length) {
            case 56: cipher = EVP_des_cfb1(); break;
            default: fprintf(stderr, "Unsupported key length for CFB mode\n"); return NULL;
        }
    } else if (strcmp(mode, "NULL") == 0) {
        // Implement null encryption
    } else {
        fprintf(stderr, "Unsupported cipher mode\n");
    }
    return cipher;
}

// Function to perform encryption/decryption using selected cipher
int encrypt_decrypt(EVP_CIPHER *cipher, int operation, unsigned char *key, unsigned char *iv, unsigned char *in, unsigned char *out, size_t len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, operation)) {
        fprintf(stderr, "Error initializing cipher context\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int outlen, tmplen;
    if (!EVP_EncryptUpdate(ctx, out, &outlen, in, len) || !EVP_EncryptFinal_ex(ctx, out + outlen, &tmplen)) {
        fprintf(stderr, "Error encrypting/decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *out += outlen + tmplen;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

