package com.pokemon.evolutions.service;

import com.pokemon.evolutions.config.CacheConfig;
import com.pokemon.evolutions.config.RetryConfig;
import com.pokemon.evolutions.model.Pokemon;
import com.pokemon.evolutions.repository.EvolutionRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.retry.support.RetryTemplate;
import org.springframework.stereotype.Service;

@Service
public class PokemonService {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private EvolutionRepository repository;

    @Autowired
    private RetryTemplate retryTemplate;

    @Cacheable(value = CacheConfig.POKEMON_CACHE, key = "#id")
    public Pokemon getPokemon(String id) {
        return retryTemplate.execute(context -> {
            String apiUrl = "https://api.pokemon.com/v2/pokemon/" + id;
            Pokemon pokemon = restTemplate.getForObject(apiUrl, Pokemon.class);
            if (pokemon == null) {
                throw new RuntimeException("Failed to retrieve Pokemon data");
            }
            repository.save(pokemon);
            return pokemon;
        });
    }

    public void updatePokemon(String id, Pokemon updatedData) {
        retryTemplate.execute(context -> {
            String apiUrl = "https://api.pokemon.com/v2/pokemon/" + id;
            restTemplate.put(apiUrl, updatedData);
            return null;
        });
    }
}
