import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ImageCompressionService {

    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void compressImage(String source, String destination) {
        executorService.submit(() -> {
            try {
                BufferedImage image = loadImage(source);
                if (image != null) {
                    saveCompressedImage(image, destination);
                }
            } catch (IOException e) {
                handleException(e);
            }
        });
    }

    private BufferedImage loadImage(String source) throws IOException {
        if (source.startsWith("http")) {
            return ImageIO.read(new URL(source));
        } else if (source.endsWith(".jpg") || source.endsWith(".jpeg") ||
                   source.endsWith(".png") || source.endsWith(".bmp")) {
            return ImageIO.read(new File(source));
        }
        throw new IllegalArgumentException("Unsupported image format");
    }

    private void saveCompressedImage(BufferedImage image, String destination) throws IOException {
        // Implement lossless compression logic here
        ImageIO.write(image, "jpg", new File(destination));
