    class ConfigLoader {
    public:
        static ConfigLoader& getInstance() {
            static ConfigLoader instance;
            return instance;
        }

        void loadConfig(const std::string& filePath) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (config_.empty()) {
                try {
                    std::ifstream file(filePath);
                    config_ = nlohmann::json::parse(file);
                    lastLoadTime_ = std::chrono::steady_clock::now();
                    logSuccess("Configuration loaded successfully.");
                } catch (const nlohmann::json::exception& e) {
                    logError("Failed to parse JSON: " + std::string(e.what()));
                } catch (...) {
                    logError("An unexpected error occurred while loading configuration.");
                }
            }
        }

        ConfigMap getConfig() const {
            if (!config_.empty()) {
                return config_;
            } else {
                loadConfig(defaultFilePath_);
                return config_;
            }
        }

    private:
