#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* appendSlashIfSmall(char* str, size_t maxSize) {
    if (str == NULL || strlen(str) >= maxSize) return NULL;

    char* newStr = realloc(str, maxSize + 2);
    if (newStr == NULL) return NULL;

    strcat(newStr, "/");
    return newStr;
}
