public class WebsiteManager
{
    private readonly ILogger<WebsiteManager> _logger;
    private readonly IConfiguration _configuration;

    public WebsiteManager(ILogger<WebsiteManager> logger, IConfiguration configuration)
    {
        _logger = logger;
        _configuration = configuration;
    }

    public async Task<string> AddAndStartSiteAsync(string directoryPath, string siteName)
    {
        if (string.IsNullOrEmpty(directoryPath))
        {
            _logger.LogError("Directory path cannot be empty.");
            return null;
        }

        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError($"Directory {directoryPath} does not exist.");
            return null;
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogError("Web.config file is missing in the directory.");
            return null;
        }

        if (IsSiteRunning(siteName))
        {
            _logger.LogInformation($"Site {siteName} is already running.");
            return null;
        }

        string webServerExecutable = GetWebServerExecutable(directoryPath);
        if (string.IsNullOrEmpty(webServerExecutable))
        {
            _logger.LogError("Unsupported web server detected.");
            return null;
        }

        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = webServerExecutable,
            Arguments = $"-config {webConfigPath} -siteName {siteName}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (Process process = new Process { StartInfo = startInfo })
        {
            try
            {
                _logger.LogInformation($"Starting site {siteName} with web server {webServerExecutable}.");
                await process.StartAsync();

                _configuration["Sites"] += $"{siteName},{directoryPath};";

                return $"Site {siteName} started successfully.";
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to start site {siteName}: {ex.Message}");
                return null;
            }
        }
    }

    private bool IsSiteRunning(string siteName)
    {
        // Implement logic to check if the site is already running
        return false;
    }

    private string GetWebServerExecutable(string directoryPath)
    {
        if (File.Exists(Path.Combine(directoryPath, "applicationHost.config")))
        {
            return "iisexpress";
        }
        else if (File.Exists(Path.Combine(directoryPath, "httpd.conf")))
