```java
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class DynamicDeserializer {

    private final ClassProvider classProvider;
    private final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();
    private int cacheSizeLimit = 100; // Default cache size limit

    public DynamicDeserializer(ClassProvider classProvider) {
        this.classProvider = classProvider;
    }

    public <T> T deserialize(byte[] byteArray) throws CustomDeserializationException {
        if (byteArray == null || byteArray.length == 0) {
            throw new CustomDeserializationException("Invalid byte array for deserialization");
        }

        String checksum = calculateChecksum(byteArray);
        Class<?> clazz = loadClass(checksum);

        try (InputStream inputStream = new ByteArrayInputStream(byteArray)) {
            return (T) java.io.ObjectInputStream.readObject(inputStream);
        } catch (IOException | ClassNotFoundException e) {
            throw new CustomDeserializationException("Failed to deserialize byte array", e);
        }
    }

    private String calculateChecksum(byte[] byteArray) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(byteArray);
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private Class<?> loadClass(String checksum) throws CustomDeserializationException {
        return classCache.computeIfAbsent(checksum, key -> {
            try {
                return classProvider.getClass(key);
            } catch (ClassNotFoundException e) {
                throw new CustomDeserializationException("Failed to load class for checksum: " + key, e);
            }
        });
    }

    // Setters and getters for configuration settings
    public void setCacheSizeLimit(int cacheSizeLimit) {
        this.cacheSizeLimit = cacheSizeLimit;
    }

    public int getCacheSizeLimit() {
        return cacheSizeLimit;
    }
}

class CustomDeserializationException extends RuntimeException {
    public CustomDeserializationException(String message, Throwable cause) {
        super(message, cause);
    }

    public CustomDeserializationException(String message) {
        super(message);
    }
}

interface ClassProvider {
    Class<?> getClass(String checksum) throws ClassNotFoundException;
}
