define('ENV_PRODUCTION', 'production');

// Default environment if not set
$defaultEnv = ENV_DEVELOPMENT;

// Get the current environment from APP_ENV or use default
$currentEnv = getenv('APP_ENV') ?: $defaultEnv;

// Define paths to configuration files
$configPath = __DIR__ . '/config';
$devConfigFile = $configPath . '/' . $currentEnv . '.json';

// Check if the configuration file exists and is readable
if (!file_exists($devConfigFile) || !is_readable($devConfigFile)) {
    error_log('Configuration file not found or not readable: ' . $devConfigFile);
    die('Configuration file not found or not readable.');
}

// Cache mechanism using filemtime to check if the config has changed
$configCacheFile = __DIR__ . '/config_cache';
$lastModifiedTime = isset($_ENV['CONFIG_LAST_MODIFIED']) ? $_ENV['CONFIG_LAST_MODIFIED'] : null;

if ($lastModifiedTime === null || $lastModifiedTime != filemtime($devConfigFile)) {
    // Read and parse the JSON configuration file
    $configContent = file_get_contents($devConfigFile);
    if (json_last_error() !== JSON_ERROR_NONE) {
        error_log('Malformed JSON in configuration file: ' . $devConfigFile);
        die('Malformed JSON in configuration file.');
    }

    // Decode the JSON content into an associative array
    $config = json_decode($configContent, true);

    // Set environment variables based on the configuration
    foreach ($config as $key => $value) {
        putenv("$key=$value");
    }

    // Update the cache with the last modified time of the config file
    $_ENV['CONFIG_LAST_MODIFIED'] = filemtime($devConfigFile);
}

// Log the current environment and loaded configuration
error_log('Current Environment: ' . $currentEnv);
error_log('Loaded Configuration: ' . print_r($_ENV, true));

// Load Composer autoloader if it exists
$composerAutoloadPath = __DIR__ . '/vendor/autoload.php';
if (file_exists($composerAutoloadPath)) {
    require_once $composerAutoloadPath;
} else {
    error_log('Composer autoload file not found: ' . $composerAutoloadPath);
    die('Composer autoload file not found.');
}

// Main application logic here
