import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.CacheManager;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class PokemonController {

    @Autowired
    private PokemonService pokemonService;

    @Autowired
    private CacheManager cacheManager;

    @GetMapping("/pokemon/{id}")
    public ResponseEntity<PokemonDetails> getPokemonDetails(@PathVariable Long id) {
        String cacheKey = "pokemon:" + id;
        PokemonDetails cachedData = (PokemonDetails) cacheManager.getCache("pokemon").get(cacheKey).get();

        if (cachedData != null) {
            return ResponseEntity.ok(cachedData);
        }

        try {
            PokemonDetails pokemonDetails = pokemonService.getPokemonDetailsFromAPI(id);
            cacheManager.getCache("pokemon").put(cacheKey, pokemonDetails);
            return ResponseEntity.ok(pokemonDetails);
        } catch (Exception e) {
            // Handle exceptions and fallback to database if needed
            // Log error details for debugging purposes
            return ResponseEntity.status(500).body(null);
        }
    }
}
