using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Xml.XPath;
using MongoDB.Bson;
using MongoDB.Driver;

public class SensorDataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly IMongoClient _mongoClient;
    private readonly string _databaseName;
    private readonly string _collectionName;

    public SensorDataProcessor(HttpClient httpClient, IMongoClient mongoClient, string databaseName, string collectionName)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _mongoClient = mongoClient ?? throw new ArgumentNullException(nameof(mongoClient));
        _databaseName = databaseName;
        _collectionName = collectionName;
    }

    public async Task ProcessSensorDataAsync(string baseUrl)
    {
        try
        {
            var devices = await GetDeviceListAsync(baseUrl);

            foreach (var device in devices)
            {
                try
                {
                    var xmlContent = await FetchSensorDataAsync(device.Url);
                    var sensorData = ExtractMostRecentReading(xmlContent);
                    var deviceId = device.Id;
                    await StoreInDatabaseAsync(deviceId, sensorData);
                }
                catch (Exception ex)
                {
                    // Handle exceptions for individual devices
                    Console.WriteLine($"Error processing device {device.Id}: {ex.Message}");
                }
            }
        }
        catch (Exception ex)
        {
            // Handle network or other errors
            Console.WriteLine($"Network error: {ex.Message}");
        }
    }

    private async Task<List<Device>> GetDeviceListAsync(string baseUrl)
    {
        var response = await _httpClient.GetAsync(baseUrl);
        response.EnsureSuccessStatusCode();
        var deviceListJson = await response.Content.ReadAsStringAsync();
        // Parse JSON to get the list of devices
        return JsonConvert.DeserializeObject<List<Device>>(deviceListJson);
    }

    private async Task<string> FetchSensorDataAsync(string url)
    {
        var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }

    private SensorReading ExtractMostRecentReading(string xmlContent)
    {
        using (var reader = XmlReader.Create(new StringReader(xmlContent)))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == "SensorData")
                {
                    var dateTime = reader.GetAttribute("Timestamp");
                    var value = reader.GetAttribute("Value");
                    return new SensorReading(dateTime, double.Parse(value));
                }
            }
        }

        throw new InvalidOperationException("No sensor data found in the XML.");
    }

    private async Task StoreInDatabaseAsync(string deviceId, SensorReading sensorData)
    {
        var database = _mongoClient.GetDatabase(_databaseName);
        var collection = database.GetCollection<BsonDocument>(_collectionName);

        var document = new BsonDocument
        {
            { "DeviceId", deviceId },
            { "Timestamp", sensorData.Timestamp },
            { "Value", sensorData.Value }
        };

        await collection.InsertOneAsync(document);
    }
}

public class Device
{
    public string Id { get; set; }
    public string Url { get; set; }
}

public class SensorReading
{
    public DateTime Timestamp { get; }
    public double Value { get; }

    public SensorReading(string timestamp, double value)
    {
        Timestamp = DateTime.Parse(timestamp);
        Value = value;
    }
}
