import java.io.IOException;
import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class DynamicCloudStorageManager {
    private Map<String, CloudStorageProvider> providers = new HashMap<>();
    private Cache cache = new Cache();

    public void addProvider(String name, CloudStorageProvider provider) {
        providers.put(name, provider);
    }

    public boolean uploadFile(String providerName, String filePath, String destinationPath) throws IOException {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider == null) {
            throw new IllegalArgumentException("Provider not found");
        }
        return provider.uploadFile(filePath, destinationPath);
    }

    public byte[] downloadFile(String providerName, String filePath) throws IOException {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider == null) {
            throw new IllegalArgumentException("Provider not found");
        }
        return provider.downloadFile(filePath);
    }

    private boolean validateMetadata(File file, String expectedHash) throws IOException, NoSuchAlgorithmException {
        byte[] actualHash = calculateSHA256(file);
        return expectedHash.equals(bytesToHex(actualHash));
    }

    private byte[] calculateSHA256(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new FileInputStream(file)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return digest.digest();
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

interface CloudStorageProvider {
    boolean uploadFile(String filePath, String destinationPath) throws IOException;
    byte[] downloadFile(String filePath) throws IOException;
}
