using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class WebAppManager
{
    private readonly List<IWebServerAPI> _apis;
    private readonly IConfigurationProvider _configProvider;
    private readonly ILoggerService _logger;
    private readonly ICacheService _cacheService;

    public WebAppManager(List<IWebServerAPI> apis, IConfigurationProvider configProvider, ILoggerService logger, ICacheService cacheService)
    {
        _apis = apis;
        _configProvider = configProvider;
        _logger = logger;
        _cacheService = cacheService;
    }

    public async Task AddWebApplicationAsync(string appName)
    {
        var config = await _configProvider.GetConfigurationAsync(appName);
        var api = GetApiForApp(config);
        await api.AddApplicationAsync(appName, config);
        _logger.LogInfo($"Added {appName} with configuration: {config}");
    }

    public async Task RemoveWebApplicationAsync(string appName)
    {
        var api = GetApiForApp(await _cacheService.GetConfigurationAsync(appName));
        await api.RemoveApplicationAsync(appName);
        _logger.LogInfo($"Removed {appName}");
    }

    public async Task StartWebApplicationAsync(string appName)
    {
        var api = GetApiForApp(await _cacheService.GetConfigurationAsync(appName));
        await api.StartApplicationAsync(appName);
        _logger.LogInfo($"Started {appName}");
    }

    public async Task StopWebApplicationAsync(string appName)
    {
        var api = GetApiForApp(await _cacheService.GetConfigurationAsync(appName));
        await api.StopApplicationAsync(appName);
        _logger.LogInfo($"Stopped {appName}");
    }

    public async Task RestartWebApplicationAsync(string appName)
    {
        await StopWebApplicationAsync(appName);
        await StartWebApplicationAsync(appName);
        _logger.LogInfo($"Restarted {appName}");
    }

    private IWebServerAPI GetApiForApp(AppConfiguration config)
    {
        return _apis.FirstOrDefault(api => api.SupportedConfigurations.Contains(config.Type)) ?? throw new InvalidOperationException("No API supports the given configuration type.");
    }
}

public interface IWebServerAPI
{
    string Name { get; }
    HashSet<string> SupportedConfigurations { get; }

    Task AddApplicationAsync(string appName, AppConfig config);
    Task RemoveApplicationAsync(string appName);
    Task StartApplicationAsync(string appName);
    Task StopApplicationAsync(string appName);
}

public class AppConfig
{
    public string Type { get; set; }
    // Other configuration properties...
}

public interface IConfigurationProvider
{
    Task<AppConfig> GetConfigurationAsync(string appName);
}

public interface ILoggerService
{
    void LogInfo(string message);
    void LogError(Exception ex, string message);
}

public interface ICacheService
{
    Task<AppConfig> GetConfigurationAsync(string appName);
}
