int safeStringCopy(const char *src, char *dest, size_t destSize) {
    if (src == NULL || dest == NULL || destSize == 0) {
        logError("Invalid input parameters"); // Log error for invalid inputs
        return -1;
    }

    size_t srcLength = strlen(src);

    if (srcLength >= destSize) {
        strncpy(dest, src, destSize - 1);
        dest[destSize - 1] = '\0'; // Ensure null termination
        logWarning("String was truncated"); // Log warning for truncation
    } else {
        strcpy(dest, src); // Copy the string as is
    }

    return strlen(dest) + 1; // Return number of characters including null terminator
}
