// app.js

const express = require('express');
const axios = require('axios');
const crypto = require('crypto');
const redis = require('redis');
const totp = require('totp-generator');
const Worker = require('worker_threads').Worker;
const cluster = require('cluster');

if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  const app = express();

  // Middleware for rate limiting
  const rateLimit = require('express-rate-limit');
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100 // limit each IP to 100 requests per windowMs
  });
  app.use(limiter);

  // Middleware for caching data with Redis
  const client = redis.createClient();

  // Route for fetching weather and climate data
  app.get('/data', async (req, res) => {
    try {
      const { location } = req.query;

      // Fetch weather data from OpenWeatherMap API
      const weatherResponse = await axios.get('https://api.openweathermap.org/data/2.5/weather', {
        params: {
          q: location,
          appid: 'your_openweathermap_api_key',
          units: 'metric'
        }
      });

      // Fetch climate data from Climate API
      const climateResponse = await axios.get('https://climateapi.com/api/v1/climate', {
        params: {
          location: location,
          token: 'your_climate_api_token'
        }
      });

      // Cache the data in Redis
      client.setex(`data:${location}`, 3600, JSON.stringify({ weather: weatherResponse.data, climate: climateResponse.data }));

      res.json({ weather: weatherResponse.data, climate: climateResponse.data });
    } catch (error) {
      console.error(error);
      res.status(500).json({ error: 'Failed to fetch data' });
    }
  });

  // Start the server
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
  });
}
```

This code snippet sets up a basic Node.js microservice using Express for handling HTTP requests and Axios for making API calls. It includes middleware for rate limiting and caching data with Redis. The `/data` route fetches weather and climate data from external APIs, caches the result in Redis, and returns it to the client. The server runs on port 3000 or an environment-specified port.

