import requests
from threading import Lock
from typing import Dict, Any, Optional

class RemoteConfigManager:
    def __init__(self, base_url: str, api_key: str):
        self.base_url = base_url
        self.api_key = api_key
        self.config_cache: Dict[str, Any] = {}
        self.lock = Lock()
        self.version_history: List[Tuple[int, Dict[str, Any]]] = []
        self.logger = Logger()

    def fetch_config(self, endpoint: str) -> Optional[Dict[str, Any]]:
        url = f"{self.base_url}/{endpoint}"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        try:
            response = requests.get(url, headers=headers)
            response.raise_for_status()
            config_data = response.json()
            self.cache_config(endpoint, config_data)
            return config_data
        except requests.RequestException as e:
            self.logger.error(f"Failed to fetch config from {url}: {e}")
            return None

    def update_config(self, endpoint: str, new_config: Dict[str, Any]) -> bool:
        url = f"{self.base_url}/{endpoint}"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        try:
            response = requests.post(url, headers=headers, json=new_config)
            response.raise_for_status()
            self.apply_config(new_config)
            self.version_history.append((response.json().get('version', 0), new_config))
            return True
        except requests.RequestException as e:
            self.logger.error(f"Failed to update config at {url}: {e}")
            return False

    def cache_config(self, endpoint: str, config_data: Dict[str, Any]) -> None:
        with self.lock:
            self.config_cache[endpoint] = config_data
            self.logger.info(f"Cached config for {endpoint}")

    def apply_config(self, new_config: Dict[str, Any]) -> None:
        # Logic to apply the new configuration to the application
        pass

    def get_cached_config(self, endpoint: str) -> Optional[Dict[str, Any]]:
        with self.lock:
            return self.config_cache.get(endpoint)

    def revert_to_version(self, version: int) -> bool:
        for v, config in reversed(self.version_history):
            if v == version:
                self.apply_config(config)
                return True
        return False

class Logger:
    def info(self, message: str) -> None:
        print(f"INFO: {message}")

    def error(self, message: str) -> None:
        print(f"ERROR: {message}")
