const fs = require('fs').promises;
const path = require('path');

async function readDirectoryContents(directory) {
    try {
        const entries = await fs.readdir(directory);
        const filteredEntries = entries.filter(entry => !entry.startsWith('.'));

        const filePromises = filteredEntries.map(async entry => {
            const fullPath = path.join(directory, entry);

            try {
                const stats = await fs.stat(fullPath);
                if (stats.isDirectory()) {
                    return { [entry]: 'Directory' };
                } else if (stats.size > 1024 * 1024) {
                    console.warn(`Skipping large file: ${fullPath}`);
                    return { [entry]: 'Skipped due to size' };
                }

                const content = await fs.readFile(fullPath, 'utf8');
                return { [entry]: content };
            } catch (error) {
                console.error(`Error reading file: ${fullPath}`, error);
                return { [entry]: 'Read error' };
            }
        });

        return Promise.all(filePromises);
    } catch (error) {
        console.error('Error reading directory:', error);
        return [];
    }
}

// Example usage:
readDirectoryContents('/path/to/directory')
    .then(results => console.log(results))
    .catch(error => console.error('Failed to read directory contents', error));
```

