```csharp
using Microsoft.AspNetCore.Http;
using System.Threading.Tasks;

public class ClinicStatusUpdateMiddleware
{
    private readonly RequestDelegate _next;

    public ClinicStatusUpdateMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context, ICmsService cmsService, IErrorLogger errorLogger, IAuditSystem auditSystem, IRateLimiter rateLimiter, IClinicRepository clinicRepository, INotificationService notificationService)
    {
        if (context.Request.Method == "POST" && context.Request.Path.StartsWithSegments("/updateClinicStatus"))
        {
            var clinicId = context.Request.Form["clinicId"];
            var newStatus = context.Request.Form["newStatus"];
            var lastModifiedIP = context.Connection.RemoteIpAddress?.ToString();
            var lastModifiedByUserId = context.User.Identity.Name;

            if (await rateLimiter.AllowRequest(lastModifiedIP))
            {
                try
                {
                    var clinic = await clinicRepository.GetClinicByIdAsync(clinicId);
                    if (clinic == null)
                    {
                        context.Response.StatusCode = StatusCodes.Status404NotFound;
                        return;
                    }

                    var oldStatus = clinic.Status;

                    clinic.Status = newStatus;

                    using (var transaction = await clinicRepository.BeginTransactionAsync())
                    {
                        await clinicRepository.UpdateClinicAsync(clinic);
                        await cmsService.ApplyStatusUpdateAsync(clinicId, newStatus);

                        await auditSystem.LogAuditAsync(lastModifiedByUserId, clinicId, oldStatus, newStatus);

                        await notificationService.SendEmailNotificationAsync(clinicId, oldStatus, newStatus, lastModifiedByUserId);

                        transaction.Commit();
                    }

                    context.Response.StatusCode = StatusCodes.Status200OK;
                    var response = new
                    {
                        success = true,
                        clinicDetails = clinic
                    };
                    await context.Response.WriteAsJsonAsync(response);
                }
                catch (Exception ex)
                {
                    errorLogger.LogError(ex, "Failed to update clinic status");
                    context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                    var response = new
                    {
                        success = false,
                        errorMessages = new[] { "Internal server error" }
                    };
                    await context.Response.WriteAsJsonAsync(response);
                }
            }
            else
            {
                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                var response = new
                {
                    success = false,
                    errorMessages = new[] { "Rate limit exceeded" }
                };
                await context.Response.WriteAsJsonAsync(response);
            }
        }
        else
        {
            context.Response.StatusCode = StatusCodes.Status405MethodNotAllowed;
        }

        await _next(context);
    }
}
```

