use std::fs;
use std::io::{self, Write};
use std::process::{Command, Stdio};
use std::sync::Arc;
use std::time::{Instant, Duration};

const MAX_RSS: u64 = 1024 * 1024 * 512; // 512 MB
const COMPILER_TIMEOUT: Duration = Duration::from_secs(60);

fn compile_rust_file(source_path: &str) -> io::Result<i32> {
    let source_name = source_path.split('/').last().unwrap_or(source_path);
    let start_time = Instant::now();

    // Check if the source file exists
    if !fs::metadata(source_path).is_ok() {
        return Err(io::Error::new(io::ErrorKind::NotFound, format!("Source file not found: {}", source_name)));
    }

    // Spawn the Rust compiler process
    let mut child = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg(source_path)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;

    let pid = child.id().unwrap();
    log_info(&format!("Compiling: {}", source_name));

    // Set up RSS monitoring
    let mut rss_monitor = Arc::new(SyncLazy::new(|| RssMonitor::new(pid, MAX_RSS)));

    // Wait for the compiler process to finish or timeout
    match child.wait_timeout(COMPILER_TIMEOUT) {
        Ok(Some(status)) => {
            log_info(&format!("Compilation finished in {}ms", start_time.elapsed().as_millis()));
            log_info(&format!("Exit code: {}", status.code().unwrap_or(-1)));
            let rss_usage = rss_monitor.get_rss_usage();
            log_info(&format!("RSS usage: {:.2} MB", rss_usage / 1024.0 / 1024.0));
            Ok(status.code().unwrap_or(-1))
        }
        Ok(None) => {
            child.kill()?;
            log_error(&format!("Compilation timed out after {} seconds for {}", COMPILER_TIMEOUT.as_secs(), source_name));
            Err(io::Error::new(io::ErrorKind::TimedOut, format!("Compilation timed out for {}", source_name)))
        }
        Err(e) => {
            log_error(&format!("Failed to wait on compiler process: {}", e));
            Err(e)
        }
    }
}

fn log_info(message: &str) {
    println!("{}", message);
}

fn log_error(message: &str) {
    eprintln!("Error: {}", message);
}
