        printf("ERROR: %s\n", message);
    } else if (strcmp(level, "DEBUG") == 0) {
        printf("%s: %s\n", message, get_current_time());
    }
}

// Function to initialize the thread pool
void init_thread_pool() {
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_request, NULL);
    }
}

// Function to add a request to the queue
void enqueue_request(int request_id) {
    pthread_mutex_lock(&queue_lock);
    request_queue[request_count++] = request_id;
    pthread_mutex_unlock(&queue_lock);
}

// Function to start processing requests from the queue
void start_processing() {
    while (1) {
        int request_id;

        // Wait for a request to be available
        pthread_mutex_lock(&queue_lock);
        if (request_count > 0) {
            request_id = request_queue[--request_count];
        } else {
            pthread_mutex_unlock(&queue_lock);
            continue;
        }
        pthread_mutex_unlock(&queue_lock);

        // Process the request in a separate thread
        enqueue_request(request_id);
    }
}

// Function to get the current time as a string
const char* get_current_time() {
    // Placeholder for actual time retrieval logic
    return "YYYY-MM-DD HH:MM:SS";
}

int main() {
