// Import necessary libraries
import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileProcessor {

    private static final String DIRECTORY_TO_SCAN = "/path/to/directory";
    private static final String[] KEYWORDS = {"error", "warning"};
    private static final int THREAD_POOL_SIZE = 10;
    private static final String REPORT_FORMAT = "HTML"; // or JSON, CSV, etc.
    private static final String REPORT_API_URL = "https://api.example.com/report";

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

        File directory = new File(DIRECTORY_TO_SCAN);
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isFile() && file.getName().endsWith(".txt")) {
                    executorService.submit(new FileScanner(file));
                }
            }
        }

        // Shutdown and wait for all tasks to complete
        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    static class FileScanner implements Runnable {

        private final File file;

        public FileScanner(File file) {
            this.file = file;
        }

        @Override
        public void run() {
            try (BufferedReader br = new BufferedReader(new FileReader(file))) {
                String line;
                StringBuilder summary = new StringBuilder();

                while ((line = br.readLine()) != null) {
                    for (String keyword : KEYWORDS) {
                        if (line.toLowerCase().contains(keyword)) {
                            summary.append(line).append("\n");
                            break;
                        }
                    }
                }

                // Generate report based on the configured format
                String report = generateReport(summary.toString(), REPORT_FORMAT);

                // Send the report to the external API
                sendToAPI(report, REPORT_API_URL);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        private String generateReport(String content, String format) {
            switch (format.toUpperCase()) {
                case "HTML":
                    return "<html><body>" + content.replace("\n", "<br>") + "</body></html>";
                // Add cases for other formats like JSON, CSV
                default:
                    return content;
            }
        }

        private void sendToAPI(String report, String url) {
            // Code to send the report to the external API using HTTP POST request
        }
    }
}
