    private readonly ILogger<UserProfileUpdateService> _logger;
    private readonly Dictionary<string, TenantConfig> _tenantConfigs;
    private readonly ICache _cache;

    public UserProfileUpdateService(HttpClient httpClient, ILogger<UserProfileUpdateService> logger, IEnumerable<TenantConfig> tenantConfigs, ICache cache)
    {
        _httpClient = httpClient;
        _logger = logger;
        _tenantConfigs = tenantConfigs.ToDictionary(t => t.TenantId);
        _cache = cache;
    }

    public async Task UpdateUserProfilesAsync(string configFilePath, List<int> userIds, UserProfileDetails newProfile)
    {
        var tenants = LoadTenants(configFilePath);

        foreach (var tenant in tenants)
        {
            if (!_tenantConfigs.ContainsKey(tenant.TenantId))
            {
                _logger.LogError("Invalid tenant configuration for {TenantId}", tenant.TenantId);
                continue;
            }

            var config = _tenantConfigs[tenant.TenantId];
            var client = new HttpClient(new TenantHandler(config.ApiUrl, config.ApiKey));

            foreach (var userId in userIds)
            {
                await UpdateUserProfileAsync(client, config, userId, newProfile);
            }
        }
    }

    private async Task UpdateUserProfileAsync(HttpClient client, TenantConfig config, int userId, UserProfileDetails newProfile)
    {
        var cacheKey = $"profile_{userId}";
        if (_cache.TryGetValue(cacheKey, out var cachedProfile))
        {
            var updatedProfile = MergeProfiles(cachedProfile, newProfile);
            await SendUpdateRequestAsync(client, config, userId, updatedProfile);
        }
        else
        {
            _logger.LogError("Cached profile not found for user {UserId}", userId);
        }
    }

    private UserProfileDetails MergeProfiles(UserProfileDetails current, UserProfileDetails updates)
    {
        // Implement logic to merge current and updates profiles
        return new UserProfileDetails
        {
            Email = updates.Email,
            PhoneNumber = updates.PhoneNumber,
            Address = updates.Address,
            DateOfBirth = updates.DateOfBirth,
            EmploymentStatus = updates.EmploymentStatus
        };
