        var url = $"{config.ApiUrl}/users/{userId}";
        var json = JsonSerializer.Serialize(updatedProfile);
        var content = new StringContent(json, System.Text.Encoding.UTF8, "application/json");

        try
        {
            var response = await client.PutAsync(url, content);
            response.EnsureSuccessStatusCode();
            _logger.LogInformation("User profile updated successfully for user {UserId}", userId);
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to update user profile for user {UserId}", userId);
        }
    }

