```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

#define MAX_CIPHER_SUITES 5

typedef enum {
    NULL_ENCRYPTION,
    DES_ECB,
    DES_EDE,
    DES_EDE3,
    CFB_MODE,
    AES_256_GCM,
    CHACHA20_POLY1305,
    RSA_OAEP
} CipherSuite;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    CipherSuite suite;
    pthread_mutex_t lock;
} CryptoContext;

CryptoContext crypto_contexts[MAX_CIPHER_SUITES];

void init_crypto_context(CipherSuite suite) {
    crypto_contexts[suite].ctx = EVP_CIPHER_CTX_new();
    crypto_contexts[suite].suite = suite;
    pthread_mutex_init(&crypto_contexts[suite].lock, NULL);
}

void cleanup_crypto_context(CipherSuite suite) {
    EVP_CIPHER_CTX_free(crypto_contexts[suite].ctx);
    pthread_mutex_destroy(&crypto_contexts[suite].lock);
}

int encrypt_data(CipherSuite suite, unsigned char *key, unsigned char *iv, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    pthread_mutex_lock(&crypto_contexts[suite].lock);
    EVP_EncryptInit_ex(crypto_contexts[suite].ctx, NULL, NULL, key, iv);
    if (EVP_EncryptUpdate(crypto_contexts[suite].ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len) != 1) {
        pthread_mutex_unlock(&crypto_contexts[suite].lock);
        return -1;
    }
    if (EVP_EncryptFinal_ex(crypto_contexts[suite].ctx, ciphertext + ciphertext_len, &ciphertext_len) != 1) {
        pthread_mutex_unlock(&crypto_contexts[suite].lock);
        return -1;
    }
    pthread_mutex_unlock(&crypto_contexts[suite].lock);
    return 0;
}

int decrypt_data(CipherSuite suite, unsigned char *key, unsigned char *iv, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    pthread_mutex_lock(&crypto_contexts[suite].lock);
    EVP_DecryptInit_ex(crypto_contexts[suite].ctx, NULL, NULL, key, iv);
    if (EVP_DecryptUpdate(crypto_contexts[suite].ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len) != 1) {
        pthread_mutex_unlock(&crypto_contexts[suite].lock);
        return -1;
    }
    if (EVP_DecryptFinal_ex(crypto_contexts[suite].ctx, plaintext + ciphertext_len, &ciphertext_len) != 1) {
        pthread_mutex_unlock(&crypto_contexts[suite].lock);
        return -1;
    }
    pthread_mutex_unlock(&crypto_contexts[suite].lock);
    return 0;
}

int main() {
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128];
    int ciphertext_len;

    for (CipherSuite suite = NULL_ENCRYPTION; suite <= RSA_OAEP; suite++) {
        init_crypto_context(suite);
        if (encrypt_data(suite, key, iv, plaintext, sizeof(plaintext) - 1, ciphertext) != 0) {
            fprintf(stderr, "Encryption failed for cipher suite %d\n", suite);
        } else {
            printf("Encrypted with cipher suite %d: %s\n", suite, ciphertext);
        }
        if (decrypt_data(suite, key, iv, ciphertext, sizeof(ciphertext), plaintext) != 0) {
            fprintf(stderr, "Decryption failed for cipher suite %d\n", suite);
        } else {
            printf("Decrypted with cipher suite %d: %s\n", suite, plaintext);
        }
        cleanup_crypto_context(suite);
    }

    return 0;
}
```

This code provides a basic structure for a C library to support dynamic cryptographic operations using OpenSSL. It includes initialization and cleanup functions for different cipher suites, as well as encryption and decryption functions with thread safety using mutexes. The `main` function demonstrates how to use the library with various cipher suites. Note that this is a simplified example and does not include error handling, logging, integration with a KMS or CA, or support for multiple operating systems and cloud providers.

