import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor

def calculate_sha256(file_path):
    hasher = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(4096):  # Read in chunks of 4KB
                hasher.update(chunk)
        return hasher.hexdigest()
    except IOError as e:
        print(f"Error reading file {file_path}: {e}")
        return None

def verify_hash(file_path, expected_hash):
    actual_hash = calculate_sha256(file_path)
    if actual_hash and actual_hash == expected_hash:
        print(f"Hash verified for {file_path}.")
    else:
        print(f"Error verifying hash for {file_path}.")

def main():
    file_paths = ['file1.txt', 'file2.txt']  # List of files to process
    expected_hashes = {'file1.txt': 'expected_hash_1', 'file2.txt': 'expected_hash_2'}  # Dictionary of expected hashes

    with ThreadPoolExecutor(max_workers=4) as executor:
        start_time = time.time()
        for file_path in file_paths:
            executor.submit(calculate_sha256, file_path)
        end_time = time.time()

    total_time = end_time - start_time
    print(f"Total time taken to calculate SHA-256 hashes: {total_time:.2f} seconds")

    for file_path, expected_hash in expected_hashes.items():
        verify_hash(file_path, expected_hash)

if __name__ == "__main__":
    main()
