// Define a class to handle API requests and logging
class PaymentGatewayManager {
    private $apiKey;
    private $logFilePath;

    public function __construct($apiKey, $logFilePath) {
        $this->apiKey = $apiKey;
        $this->logFilePath = $logFilePath;
    }

    public function sendConfirmationToPaymentGateway($transaction_id, $new_status) {
        $url = "https://paymentgateway.com/api/confirm";
        $data = array('api_key' => $this->apiKey, 'transaction_id' => $transaction_id, 'status' => $new_status);
        $options = array(
            'http' => array(
                'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                'method'  => 'POST',
                'content' => http_build_query($data)
            )
        );
        $context  = stream_context_create($options);
        $result = file_get_contents($url, false, $context);

        // Log the API response
        error_log("API Response: " . $result, 3, $this->logFilePath);

        return $result === 'success';
    }

    public function logActivity($message) {
        error_log($message, 3, $this->logFilePath);
    }
}

function processPaymentTransaction($transaction_id, $new_status, $customer_id, $payment_gateway_api_key, $log_file_path) {
    try {
        // Validate API key
        if (empty($payment_gateway_api_key)) {
            throw new Exception("API key is required");
        }

        // Setup database and payment gateway managers
        $dbManager = new DatabaseManager('localhost', 'username', 'password', 'database');
        $paymentGatewayManager = new PaymentGatewayManager($payment_gateway_api_key, $log_file_path);

        // Serialize concurrent access to the same transaction_id
        if ($lock = flock(fopen(__FILE__, 'r'), LOCK_EX)) {
            try {
                // Update transaction status in the database
                if ($dbManager->updateTransactionStatus($transaction_id, $new_status, $customer_id)) {
                    // Send confirmation to payment gateway
                    if ($paymentGatewayManager->sendConfirmationToPaymentGateway($transaction_id, $new_status)) {
                        // Log successful activity
                        $paymentGatewayManager->logActivity("Transaction updated and confirmed: ID=$transaction_id, Status=$new_status");
                        return "Transaction processed successfully";
                    } else {
                        throw new Exception("Failed to confirm transaction with payment gateway");
                    }
                } else {
                    throw new Exception("Failed to update transaction in the database");
                }
            } finally {
                // Release lock
                flock($lock, LOCK_UN);
            }
        } else {
            throw new Exception("Failed to acquire lock for transaction ID: $transaction_id");
        }

    } catch (Exception $e) {
        // Log error and return error message
        $paymentGatewayManager->logActivity("Error processing transaction ID=$transaction_id: " . $e->getMessage());
        return "Error processing transaction: " . $e->getMessage();
    }
}

// Example usage:
$apiKey = "your_api_key_here";
$logFilePath = "/path/to/logfile.log";
echo processPaymentTransaction(12345, 'paid', 67890, $apiKey, $logFilePath);
