void initializeSecureMessagingLibrary(const std::string& config, const std::string& logFile) {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_chacha20_poly1305());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_sha384());
    EVP_add_digest(EVP_sha512());

    FILE* log = fopen(logFile.c_str(), "w");
    if (!log) {
        std::cerr << "Failed to open log file: " << logFile << std::endl;
        return;
    }

    // Initialize OpenSSL and handle errors
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();

    // Log initialization message
    fprintf(log, "Secure messaging library initialized successfully.\n");

    fclose(log);
}

void sendGetRequests(boost::sandesh::Client& client, const std::vector<std::string>& urls) {
    for (const auto& url : urls) {
        boost::sandesh::Request request(url);
        boost::sandesh::Response response;
        if (client.send(request, response)) {
            // Handle successful response
            std::cout << "Request to " << url << " succeeded." << std::endl;
        } else {
            // Handle failed response
            std::cerr << "Request to " << url << " failed." << std::endl;
        }
    }
}

