    if (!log) {
        std::cerr << "Failed to open log file: " << logFile << std::endl;
        return;
    }

    fprintf(log, "Total API requests: %d\n", totalRequests);
    fprintf(log, "Successful responses: %d\n", successfulResponses);
    fprintf(log, "Failed responses: %d\n", failedResponses);
    fprintf(log, "Proxy sessions established: %d\n", proxySessions);
