import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DynamicDeserializer {
    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();

    public String deserialize(int pokemonId) throws Exception {
        // Validate input
        if (pokemonId <= 0) {
            throw new IllegalArgumentException("Invalid Pokemon ID");
        }

        // Check cache
        String key = "pokemon_" + pokemonId;
        if (cache.containsKey(key)) {
            return (String) cache.get(key);
        }

        // Fetch data from APIs asynchronously
        Future<String> weaknessesFuture = executorService.submit(() -> fetchWeaknesses(pokemonId));
        Future<String> evolutionFuture = executorService.submit(() -> fetchEvolutionDetails(pokemonId));
        Future<String> habitatFuture = executorService.submit(() -> fetchHabitatInfo(pokemonId));

        // Combine results
        String name = fetchPokemonName(pokemonId);
        String type = fetchPokemonType(pokemonId);
        String weaknesses = weaknessesFuture.get();
        String evolutionDetails = evolutionFuture.get();
        String habitat = habitatFuture.get();

        // Construct JSON response
        StringBuilder jsonResponse = new StringBuilder();
        jsonResponse.append("{");
        jsonResponse.append("\"name\": \"").append(name).append("\",");
        jsonResponse.append("\"type\": \"").append(type).append("\",");
        jsonResponse.append("\"weaknesses\": ").append(weaknesses).append(",");
        jsonResponse.append("\"evolutionDetails\": ").append(evolutionDetails).append(",");
        jsonResponse.append("\"habitat\": ").append(habitat);
        jsonResponse.append("}");

        // Store in cache
