import json
from typing import Any, Dict, Callable, Optional

class JSONParser:
    _registry: Dict[str, Callable[[Any], 'JSONParser']] = {}

    @classmethod
    def register_factory(cls, key: str, factory_function: Callable[[Any], 'JSONParser']):
        cls._registry[key] = factory_function

    @classmethod
    def unregister_factory(cls, key: str):
        if key in cls._registry:
            del cls._registry[key]

    @classmethod
    def create_instance(cls, data: Any, key: str) -> Optional['JSONParser']:
        if key not in cls._registry:
            print(f"Error: Factory function for '{key}' not registered.")
            return None
        factory_function = cls._registry[key]
        instance = factory_function(data)
        instance.validate(data)
        return instance

    def __init__(self, data: Any):
        self.data = data

    def validate(self, data: Any) -> bool:
        # Implement validation logic here
        print("Validating JSON data...")
        return True

    @staticmethod
    def serialize(obj: 'JSONParser') -> str:
        return json.dumps(obj.data)

    @staticmethod
    def deserialize(json_str: str) -> Dict[str, Any]:
        return json.loads(json_str)

# Example usage:
class User(JSONParser):
    def validate(self, data: Any) -> bool:
        # Custom validation logic for User
        print("Validating User data...")
        if "name" not in data or "age" not in data:
            raise ValueError("User data must contain 'name' and 'age'")
        return True

# Register factory function
JSONParser.register_factory('user', lambda data: User(data))

# Create instance using factory function
user_data = {'name': 'John Doe', 'age': 30}
user_instance = JSONParser.create_instance(user_data, 'user')

if user_instance:
    print("User instance created successfully.")
