void logMessage(const char *message, LogLevel level) {
    // Simulate logging to a file or console
    printf("[%s] %s\n", (level == LOG_ERROR ? "ERROR" : (level == LOG_WARNING ? "WARNING" : "INFO")), message);
}

// Function to format and log messages based on a condition
void logCondition(int condition, const char *format, ...) {
    if (!format) {
        return; // Handle null format string gracefully
    }

    va_list args;
    va_start(args, format);

    // Allocate a buffer for the formatted string
    static char buffer[256];
    int result = snprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    if (result < 0) {
        logMessage("Failed to format log message", LOG_ERROR);
        return;
    }

    if (result >= sizeof(buffer)) {
        logMessage("Formatted log message too long for buffer", LOG_WARNING);
        result = sizeof(buffer) - 1; // Ensure null-termination
    }

    // Log the formatted message with a conditional level
    if (condition) {
        logMessage(buffer, LOG_INFO);
    } else {
        logMessage(buffer, LOG_WARNING);
    }
}
