```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SecureMessageProcessor : IDisposable
{
    private readonly ConcurrentDictionary<string, string> _decryptedCache = new ConcurrentDictionary<string, string>();
    private readonly object _lockObject = new object();
    private ICryptoTransform _decryptor;

    public SecureMessageProcessor(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 24) throw new ArgumentException("Key must be exactly 24 bytes long");
        if (iv == null || iv.Length != 8) throw new ArgumentException("IV must be exactly 8 bytes long");

        using (var des = new TripleDESManaged())
        {
            des.Key = key;
            des.IV = iv;
            _decryptor = des.CreateDecryptor(key, iv);
        }
    }

    public string DecryptMessage(string encodedMessage)
    {
        if (string.IsNullOrEmpty(encodedMessage)) return null;

        var cacheKey = $"{encodedMessage}{_decryptor.KeySequence}";
        if (_decryptedCache.TryGetValue(cacheKey, out var decryptedMessage))
            return decryptedMessage;

        try
        {
            lock (_lockObject)
            {
                if (!_decryptedCache.TryGetValue(cacheKey, out decryptedMessage))
                {
                    var encryptedBytes = Convert.FromBase64String(encodedMessage);
                    using (var msDecrypt = new MemoryStream(encryptedBytes))
                    {
                        using (var csDecrypt = new CryptoStream(msDecrypt, _decryptor, CryptoStreamMode.Read))
                        {
                            using (var srDecrypt = new StreamReader(csDecrypt))
                            {
                                decryptedMessage = srDecrypt.ReadToEnd();
                                _decryptedCache.TryAdd(cacheKey, decryptedMessage);
                            }
                        }
                    }
                }
            }

            return decryptedMessage;
        }
        catch (Exception ex)
        {
            LogException(ex);
            throw;
        }
    }

    public byte[] EncryptMessage(string message, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(message)) return null;

        try
        {
            using (var des = new TripleDESManaged())
            {
                des.Key = key;
                des.IV = iv;
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, des.CreateEncryptor(key, iv), CryptoStreamMode.Write))
                    {
                        using (var swEncrypt = new StreamWriter(csEncrypt))
                        {
                            swEncrypt.Write(message);
                        }
                        return msEncrypt.ToArray();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogException(ex);
            throw;
        }
    }

    private void LogException(Exception ex)
    {
        // External logging implementation
        Console.WriteLine($"Error: {ex.Message}");
    }

    public void Dispose()
    {
        _decryptor?.Dispose();
        foreach (var key in _decryptedCache.Keys.ToList())
        {
            if (_decryptedCache.TryRemove(key, out var _))
                GC.SuppressFinalize(decryptedMessage); // Simulate garbage collection
        }
    }
}
