using Microsoft.AspNetCore.Http;
using System.Threading.Tasks;

public class ClinicStatusMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IClinicStatusService _clinicStatusService;
    private readonly ICMSService _cmsService;
    private readonly ILogger<ClinicStatusMiddleware> _logger;

    public ClinicStatusMiddleware(RequestDelegate next, IClinicStatusService clinicStatusService, ICMSService cmsService, ILogger<ClinicStatusMiddleware> logger)
    {
        _next = next;
        _clinicStatusService = clinicStatusService;
        _cmsService = cmsService;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method == "POST" && context.Request.Path.StartsWithSegments("/updateClinicStatus"))
        {
            var clinicId = context.Request.Query["clinicId"].ToString();
            var newStatus = context.Request.Query["newStatus"].ToString();
            var lastModifiedIp = context.Connection.RemoteIpAddress.ToString();
            var lastModifiedByUserId = context.Request.Query["lastModifiedByUserId"].ToString();

            try
            {
                var updatedClinic = await _clinicStatusService.UpdateClinicStatusAsync(clinicId, newStatus, lastModifiedIp, lastModifiedByUserId);
                await _cmsService.ApplyUpdatedStatusToCMS(updatedClinic);

                var response = new
                {
                    Success = true,
                    UpdatedClinic = updatedClinic
                };

                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(System.Text.Json.JsonSerializer.Serialize(response));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating clinic status");
                var response = new
                {
                    Success = false,
                    ErrorMessage = ex.Message
                };

                context.Response.ContentType = "application/json";
                context.Response.StatusCode = 500;
                await context.Response.WriteAsync(System.Text.Json.JsonSerializer.Serialize(response));
            }
        }

        else
        {
            await _next(context);
        }
    }
}
```

This code defines a middleware component for updating clinic statuses in a web application. It checks if the request is an HTTP POST request to the "/updateClinicStatus" endpoint, extracts the necessary parameters from the query string, and then calls the `_clinicStatusService` to update the clinic status. If successful, it applies the updated status to multiple external CMS systems using the `_cmsService`. The response contains a success status and the updated clinic details or an error message if an exception occurs.

