import java.util.*;
import java.net.HttpURLConnection;
import java.io.IOException;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.client.RestTemplate;

@Service
public class EvolutionDataFetcher {

    @Value("${api.base.url}")
    private String apiUrl;

    @Value("${cache.size}")
    private int cacheSize;

    private Map<String, PokemonData> cache = new LinkedHashMap<>(cacheSize + 1) {
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > cacheSize;
        }
    };

    private RestTemplate restTemplate = new RestTemplate();

    public PokemonData fetchEvolutionData(String pokemonName) {
        if (cache.containsKey(pokemonName)) {
            return cache.get(pokemonName);
        }

        PokemonData data = fetchDataFromAPIs(pokemonName);

        // Cache the result
        cache.put(pokemonName, data);

        return data;
    }

    private PokemonData fetchDataFromAPIs(String pokemonName) {
        PokemonData data = new PokemonData();

        try {
            String weaknessesUrl = apiUrl + "/weaknesses/" + pokemonName;
            String evolutionUrl = apiUrl + "/evolution/" + pokemonName;

            WeaknessesResponse weaknessesResponse = restTemplate.getForObject(weaknessesUrl, WeaknessesResponse.class);
            EvolutionResponse evolutionResponse = restTemplate.getForObject(evolutionUrl, EvolutionResponse.class);

            data.setWeaknesses(weaknessesResponse.getWeaknesses());
            data.setCurrentEvolutionStage(evolutionResponse.getCurrentStage());
            data.setNextEvolutionStage(evolutionResponse.getNextStage());

        } catch (IOException e) {
            // Handle network errors or unexpected responses
            System.err.println("Error fetching data for " + pokemonName + ": " + e.getMessage());
            return new PokemonData(); // Return default data
        }

        return data;
    }

    public List<PokemonData> fetchEvolutionDataBulk(List<String> pokemonNames) {
        List<PokemonData> results = new ArrayList<>();

        for (String name : pokemonNames) {
            results.add(fetchEvolutionData(name));
        }

        return results;
    }
}

class PokemonData {
    private List<String> weaknesses;
    private String currentEvolutionStage;
    private String nextEvolutionStage;

    // Getters and setters
}

class WeaknessesResponse {
    private List<String> weaknesses;

    // Getters and setters
}

class EvolutionResponse {
    private String currentStage;
    private String nextStage;

    // Getters and setters
}
