import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class UpdateClinicStatusFetcher {

    private final Connection dbConnection;
    private final ClassProvider classProvider;
    private final ConcurrentHashMap<String, String> cache;
    private final ScheduledExecutorService rateLimiter;
    private final int maxUpdatesPerMinute;
    private final int cacheSize;
    private final long timeoutMs;

    public UpdateClinicStatusFetcher(Connection dbConnection, ClassProvider classProvider, int maxUpdatesPerMinute, int cacheSize, long timeoutMs) {
        this.dbConnection = dbConnection;
        this.classProvider = classProvider;
        this.cache = new ConcurrentHashMap<>(cacheSize);
        this.rateLimiter = Executors.newScheduledThreadPool(1);
        this.maxUpdatesPerMinute = maxUpdatesPerMinute;
        this.cacheSize = cacheSize;
        this.timeoutMs = timeoutMs;

        rateLimiter.scheduleAtFixedRate(this::clearExpiredCache, 60, 60, TimeUnit.SECONDS);
    }

    public void fetchAndUpdateClinicStatus(String clinicId, String newStatus, String lastModifiedIp, EnvironmentVariables environmentVariables) {
        if (!rateLimiter.tryAcquire(lastModifiedIp)) {
            throw new RuntimeException("Too many updates from the same IP address");
        }

        try {
            // Check cache
            String cachedData = cache.get(clinicId);
            if (cachedData == null) {
                cachedData = classProvider.fetchClinicDetails(clinicId, environmentVariables);
                if (cachedData == null || !validateClinicDetails(cachedData)) {
                    throw new RuntimeException("Invalid clinic details");
                }
                cache.put(clinicId, cachedData);
            }

            // Update database
