char* generateSecureRandomString(size_t length, const char* charset) {
    char *string = malloc(length + 1);
    RAND_bytes((unsigned char*)string, length);
    for (size_t i = 0; i < length; i++) {
        string[i] = charset[string[i] % strlen(charset)];
    }
    string[length] = '\0';
    return string;
}

void hashPassword(const char *password, const char *salt, int algorithm, char **hash) {
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL)) {
        fprintf(stderr, "Error initializing Digest\n");
        exit(EXIT_FAILURE);
    }
    if (!EVP_DigestUpdate(mdctx, password, strlen(password))) {
        fprintf(stderr, "Error updating Digest\n");
        exit(EXIT_FAILURE);
    }
    if (!EVP_DigestUpdate(mdctx, salt, strlen(salt))) {
        fprintf(stderr, "Error updating Digest\n");
        exit(EXIT_FAILURE);
    }
    unsigned char digest[EVP_MAX_MD_SIZE];
    int digest_len;
    if (!EVP_DigestFinal_ex(mdctx, digest, &digest_len)) {
        fprintf(stderr, "Error finalizing Digest\n");
        exit(EXIT_FAILURE);
    }
    *hash = malloc(digest_len * 2 + 1);
    for (int i = 0; i < digest_len; i++) {
        sprintf(*hash + (i * 2), "%02x", digest[i]);
    }
    EVP_MD_CTX_free(mdctx);
}

