import requests
from jsonschema import validate, ValidationError
from functools import wraps
import time
import concurrent.futures
import logging

# Define JSON schema for user profile update
user_profile_schema = {
    "type": "object",
    "properties": {
        "email": {"type": "string", "format": "email"},
        "phone_number": {"type": "string"}
    },
    "required": ["email", "phone_number"],
    "additionalProperties": False
}

# Setup logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def validate_input(schema):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            data = args[0]
            try:
                validate(instance=data, schema=schema)
            except ValidationError as e:
                logger.error(f"Input validation error: {e}")
                raise ValueError("Invalid user profile data") from e
            return func(*args, **kwargs)
        return wrapper
    return decorator

def handle_rate_limit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        max_retries = 5
        for i in range(max_retries + 1):
            try:
                response = func(*args, **kwargs)
                if response.status_code == 429:  # Rate limit exceeded
                    wait_time = int(response.headers.get('Retry-After', 1))
                    logger.warning(f"Rate limit exceeded. Retrying in {wait_time} seconds.")
                    time.sleep(wait_time)
                else:
                    return response
            except requests.exceptions.RequestException as e:
                logger.error(f"Network error: {e}")
        raise Exception("Failed to update user profile after multiple retries")
    return wrapper

def async_task(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            future = executor.submit(func, *args, **kwargs)
            try:
                result = future.result()
                logger.info(f"Task completed successfully: {result}")
                return result
            except Exception as e:
                logger.error(f"Task failed: {e}")
    return wrapper

@async_task
@handle_rate_limit
@validate_input(user_profile_schema)
def update_user_profile(user_id, new_data):
    url = f"https://api.example.com/users/{user_id}"
    headers = {
        "Authorization": "Bearer your_api_token",
        "Content-Type": "application/json"
    }
    response = requests.put(url, json=new_data, headers=headers)
    response.raise_for_status()
    return response.json()

def bulk_update_user_profiles(user_updates):
    with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
        futures = [executor.submit(update_user_profile, user_id, new_data) for user_id, new_data in user_updates.items()]
        results = [future.result() for future in concurrent.futures.as_completed(futures)]
    return results
