#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <string>
#include <nlohmann/json.hpp>

// Define a union-find data structure with path compression and union by rank
struct UnionFind {
    std::vector<int> parent, rank;
    int count;

    UnionFind(int size) : count(size), parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int p) {
        return parent[p] == p ? p : (parent[p] = find(parent[p]));
    }

    void unionSet(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);

        if (rootP != rootQ) {
            if (rank[rootP] > rank[rootQ])
                parent[rootQ] = rootP;
            else if (rank[rootP] < rank[rootQ])
                parent[rootP] = rootQ;
            else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
            --count;
        }
    }
