```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Xml.XPath;
using MongoDB.Driver;

public class IoTDataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly IMongoClient _mongoClient;
    private readonly IConcurrentDictionary<string, string> _deviceMetadataCache;
    private readonly ILogger _logger;

    public IoTDataProcessor(HttpClient httpClient, MongoClient mongoClient, ConcurrentDictionary<string, string> deviceMetadataCache, ILogger logger)
    {
        _httpClient = httpClient;
        _mongoClient = mongoClient;
        _deviceMetadataCache = deviceMetadataCache;
        _logger = logger;
    }

    public async Task ProcessSensorDataAsync(string xmlDocumentUrl, CancellationToken cancellationToken)
    {
        try
        {
            var xmlContent = await GetXmlDocumentAsync(xmlDocumentUrl, cancellationToken);
            var sensorReadings = ExtractSensorReadings(xmlContent);

            foreach (var reading in sensorReadings)
            {
                if (!_deviceMetadataCache.ContainsKey(reading.DeviceId))
                {
                    _logger.LogWarning($"Device metadata not found for device ID: {reading.DeviceId}");
                    continue;
                }

                var deviceId = _deviceMetadataCache[reading.DeviceId];
                await StoreSensorReadingAsync(deviceId, reading.Value);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while processing sensor data.");
        }
    }

    private async Task<string> GetXmlDocumentAsync(string url, CancellationToken cancellationToken)
    {
        try
        {
            var response = await _httpClient.GetAsync(url, cancellationToken);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync(cancellationToken);
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to retrieve XML document.");
            throw;
        }
    }

    private SensorReading[] ExtractSensorReadings(string xmlContent)
    {
        var sensorReadings = new List<SensorReading>();

        using (var xpathDocument = XPathDocument.Create(new StringReader(xmlContent)))
        {
            var nav = xpathDocument.CreateNavigator();
            var nodes = nav.Select("//sensor/reading[last()]");

            foreach (XPathNavigator node in nodes)
            {
                var deviceId = node.SelectSingleNode("../@id").Value;
                var value = double.Parse(node.Value);
                sensorReadings.Add(new SensorReading { DeviceId = deviceId, Value = value });
            }
        }

        return sensorReadings.ToArray();
    }

    private async Task StoreSensorReadingAsync(string deviceId, double reading)
    {
        var collection = _mongoClient.GetDatabase("IoTData").GetCollection<BsonDocument>("Readings");

        var document = new BsonDocument
        {
            { "DeviceId", deviceId },
            { "Value", reading },
            { "Timestamp", DateTime.UtcNow }
        };

        await collection.InsertOneAsync(document);
    }
}

public class SensorReading
{
    public string DeviceId { get; set; }
    public double Value { get; set; }
}
