#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    char *id;
    int offset;
    int key;
    double average;
} Record;

Record* read_and_process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    // Dynamically allocate memory for records
    Record *records = (Record *)malloc(100 * sizeof(Record)); // Assuming a maximum of 100 records
    int count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char id[64], key_str[32];
        if (sscanf(line, "%[^,],%[^,],%s", id, key_str, line) == 3) {
            int offset = atoi(line);
            int key = atoi(key_str);

            records[count].id = strdup(id);
            records[count].offset = offset;
            records[count].key = key;
            records[count].average = (double)(offset + key) / 2;

            count++;
        }
    }

    fclose(file);
    return realloc(records, count * sizeof(Record));
}

int main() {
    Record *records = read_and_process_file("data.txt");
    if (!records) {
        fprintf(stderr, "Failed to read and process file.\n");
        return 1;
    }

    // Process the records as needed

    for (int i = 0; i < count; i++) {
        printf("ID: %s, Offset: %d, Key: %d, Average: %.2f\n", records[i].id, records[i].offset, records[i].key, records[i].average);
        free(records[i].id); // Free allocated memory for each record
    }

    free(records); // Free the array of records

    return 0;
}
