# Rate Limiting Function
def rate_limited(max_calls=100, period=60):
    def decorator(func):
        from collections import defaultdict
        from time import time

        counts = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = str(args) + str(kwargs)
            if counts[key] >= max_calls:
                raise Exception("Rate limit exceeded")
            counts[key] += 1
            return func(*args, **kwargs)
        return wrapper
    return decorator

# JWT Refresh Function
def refresh_jwt(refresh_token, user_id, role):
    # Simulate retrieving a private key from KMS based on role
    private_key = get_private_key_from_kms(role)

    try:
        payload = jwt.decode(refresh_token, private_key, algorithms=['RS256'])
