```cpp
#include <forward_list>
#include <string>

void insertString(std::forward_list<std::string>& lst, const std::string& searchString, const std::string& insertionString, size_t maxInsertions) {
    if (lst.empty()) {
        throw std::runtime_error("The input list is empty.");
    }

    auto it = lst.begin();
    size_t insertCount = 0;

    while (it != lst.end() && insertCount < maxInsertions) {
        if (*it == searchString) {
            *it += insertionString;
            break; // Insert after the first occurrence and exit
        }
        ++it;
        ++insertCount;
    }

    if (insertCount == maxInsertions && it != lst.end()) {
        *it += insertionString;
    } else if (it == lst.end()) {
        lst.push_front(insertionString);
    }

    // Truncate strings to 100 characters
    for (auto& str : lst) {
        if (str.length() > 100) {
            str = str.substr(0, 100);
        }
    }
}

// Example usage:
int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    try {
        insertString(myList, "banana", "_inserted_", 2);
        for (const auto& str : myList) {
            std::cout << str << " ";
        }
    } catch (const std::runtime_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
