            Object loadedObject = ois.readObject();
            if (loadedObject instanceof MoSTState) {
                return (MoSTState) loadedObject;
            }
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Failed to load state from file: " + filePath);
            e.printStackTrace();
        }
        return null;
    }

