from flask_caching import Cache
import requests
import os

app = Flask(__name__)

# Load environment variables from .env file
app.config.from_dotenv('.env')

# Initialize extensions
db = SQLAlchemy(app)
login_manager = LoginManager(app)
cache = Cache(app, config={'CACHE_TYPE': 'simple'})

# Setup logging
logging.basicConfig(level=logging.INFO)

# Define user model
class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(120), nullable=False)

# Load dependencies from requirements.txt
os.system('pip install -r requirements.txt')

# Rate limiting middleware
class RateLimiter:
    def __init__(self, max_requests, time_window):
        self.max_requests = max_requests
        self.time_window = time_window

    def __call__(self, f):
        cache_key = 'rate_limit_%s' % request.remote_addr
        if cache.get(cache_key) is None:
            cache.set(cache_key, 1)
        else:
            current_count = cache.get(cache_key)
            if current_count >= self.max_requests:
                return jsonify({'error': 'Rate limit exceeded'}), 429
            else:
                cache.set(cache_key, current_count + 1)

@app.before_request
@RateLimiter(max_requests=50, time_window=60)  # Example rate limiting: 50 requests per minute
def before_request():
    pass

# Error handling
@app.errorhandler(Exception)
def handle_exception(e):
    app.logger.exception('An error occurred')
    return jsonify({'error': str(e)}), 500

# User authentication and authorization
@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']
    user = User.query.filter_by(username=username).first()
    if user and user.check_password(password):
        login_user(user)
        return jsonify({'message': 'Logged in successfully'}), 200
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/protected', methods=['GET'])
@login_required
def protected():
    if current_user.role == 'admin':
        return jsonify({'message': 'Admin access granted'})
    elif current_user.role == 'user':
        return jsonify({'message': 'User access granted'})
    else:
        return jsonify({'error': 'Unauthorized'}), 403

# Third-party API integration
def call_api(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        app.logger.error(f'API request failed: {e}')
        return jsonify({'error': 'API error'}), 503

@app.route('/api', methods=['GET'])
