#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_STREAMS 100
#define MAX_RULES 50
#define BUFFER_SIZE 4096

typedef struct {
    int socket;
    char buffer[BUFFER_SIZE];
} NetworkStream;

typedef struct {
    int id;
    char *rule;
} ParsingRule;

NetworkStream streams[MAX_STREAMS];
ParsingRule rules[MAX_RULES];

int stream_count = 0;
int rule_count = 0;

void *process_stream(void *arg) {
    NetworkStream *stream = (NetworkStream *) arg;
    while (1) {
        int bytes_read = recv(stream->socket, stream->buffer, BUFFER_SIZE - 1, 0);
        if (bytes_read <= 0) break; // Connection closed or error
        stream->buffer[bytes_read] = '\0';
        for (int i = 0; i < rule_count; i++) {
            ParsingRule *rule = &rules[i];
            // Apply parsing rule to the data in stream->buffer
            printf("Applying rule %d: %s\n", rule->id, rule->rule);
        }
    }
    close(stream->socket);
    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[MAX_STREAMS];

    // Example of setting up network streams and rules (replace with actual implementation)
    for (int i = 0; i < MAX_STREAMS; i++) {
        NetworkStream *stream = (NetworkStream *) malloc(sizeof(NetworkStream));
        stream->socket = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
        server_addr.sin_port = htons(8080 + i);
        connect(stream->socket, (struct sockaddr *) &server_addr, sizeof(server_addr));
        streams[i] = *stream;
        pthread_create(&threads[i], NULL, process_stream, (void *) stream);
    }

    for (int i = 0; i < MAX_RULES; i++) {
        ParsingRule *rule = &rules[i];
        rule->id = i + 1;
        snprintf(rule->rule, BUFFER_SIZE, "Rule %d", i + 1);
        rule_count++;
    }

    // Example of waiting for all threads to finish (replace with actual implementation)
    for (int i = 0; i < stream_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
