// Function to append a slash if length is within the limit
char* appendSlashIfSmall(char* str, size_t maxSize) {
    if (str == NULL || strlen(str) >= maxSize) {
        return NULL;
    }
    char* newStr = realloc(str, strlen(str) + 2); // Allocate space for one more character and a null terminator
    if (newStr == NULL) {
        return NULL; // Handle memory allocation failure
    }
    strncat(newStr, "/", 1); // Append the slash
    return newStr;
}

// Function to log error messages with variable arguments
