#include <stdexcept>
#include <log4cpp/Category.hh>
#include <log4cpp/Appender.hh>
#include <log4cpp/FileAppender.hh>
#include <log4cpp/OstreamAppender.hh>

// Custom min-max algorithm
void findMinMax(std::ifstream& file, float& minVal, float& maxVal) {
    if (!file.is_open()) {
        throw std::runtime_error("File not open");
    }

    minVal = std::numeric_limits<float>::max();
    maxVal = std::numeric_limits<float>::lowest();

    for (float value; file >> value;) {
        if (value < minVal) {
            minVal = value;
        }
        if (value > maxVal) {
            maxVal = value;
        }
    }

    if (!file.eof() && !file.good()) {
        throw std::runtime_error("Error reading from file");
    }
}

int main() {
    log4cpp::Category& root = log4cpp::Category::getRoot();
    root.addAppender(new log4cpp::OstreamAppender("console", &std::cout));
    root.setPriority(log4cpp::Priority::DEBUG);

    try {
        std::ifstream inputFile("input.txt");
        if (!inputFile.is_open()) {
            throw std::runtime_error("Unable to open input file");
        }

        std::ofstream outputFile("output.txt");
        if (!outputFile.is_open()) {
            throw std::runtime_error("Unable to open output file");
        }

        float minVal, maxVal;
        findMinMax(inputFile, minVal, maxVal);

        outputFile << "Min Value: " << minVal << std::endl;
        outputFile << "Max Value: " << maxVal << std::endl;

    } catch (const std::exception& e) {
        root.error("Error: %s", e.what());
        return 1;
    }

    log4cpp::Category::shutdown();

    return 0;
}
