```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.*;

public class GitCommandExecutor {
    public static void main(String[] args) {
        if (args.length != 5) {
            System.out.println("Usage: java GitCommandExecutor <repository_path> <branch_name> <output_file_path> <command> <timeout>");
            return;
        }

        String repositoryPath = args[0];
        String branchName = args[1];
        String outputFilePath = args[2];
        String command = args[3];
        int timeout = Integer.parseInt(args[4]);

        Path outputFile = Paths.get(outputFilePath);
        try {
            // Delete existing output file
            if (Files.exists(outputFile)) {
                Files.delete(outputFile);
            }

            // Prepare Git command with branch and output redirection
            String[] gitCommand = { "git", "-C", repositoryPath, command + " " + branchName };
            ProcessBuilder processBuilder = new ProcessBuilder(gitCommand);
            processBuilder.redirectErrorStream(true);
            processBuilder.directory(repositoryPath.toFile());

            // Execute the Git command with a timeout
            Process process = processBuilder.start();
            Future<Integer> future = Executors.newSingleThreadExecutor().submit(() -> {
                try {
                    return process.waitFor();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Process interrupted", e);
                }
            });

            // Check for timeout
            if (!future.isDone()) {
                future.cancel(true);
                System.out.println("Git command timed out after " + timeout + " seconds.");
                return;
            }

            int exitCode = future.get();
            if (exitCode != 0) {
                System.err.println("Git command failed with exit code: " + exitCode);
                return;
            }

            // Capture and write output to file
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                 BufferedWriter writer = Files.newBufferedWriter(outputFile)) {
                String line;
                while ((line = reader.readLine()) != null) {
                    writer.write(line);
                    writer.newLine();
                }
            }

            System.out.println("Git command completed successfully. Output saved to " + outputFilePath);

        } catch (IOException | InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }
    }
}
