Here's an example code block that demonstrates how you can write a Node.js program that dynamically loads and executes multiple JavaScript modules in a specified order:

```javascript
const fs = require('fs');
const path = require('path');

function loadModules(modules) {
  return new Promise((resolve, reject) => {
    const results = [];
    let completed = 0;

    modules.forEach((modulePath, index) => {
      fs.readFile(modulePath, 'utf8', (err, data) => {
        if (err) {
          return reject(err);
        }

        try {
          const moduleFunction = new Function('require', data);
          const moduleResult = moduleFunction(require);
          results[index] = moduleResult;
        } catch (error) {
          return reject(error);
        }

        completed++;
        if (completed === modules.length) {
          resolve(results);
        }
      });
    });
  });
}

function executeModules(modules) {
  return new Promise((resolve, reject) => {
    let currentIndex = 0;

    function executeNextModule() {
      if (currentIndex >= modules.length) {
        return resolve();
      }

      const modulePath = modules[currentIndex];
      fs.readFile(modulePath, 'utf8', (err, data) => {
        if (err) {
          return reject(err);
        }

        try {
          const moduleFunction = new Function('require', data);
          const moduleResult = moduleFunction(require);
          currentIndex++;
          executeNextModule();
        } catch (error) {
          return reject(error);
        }
      });
    }

    executeNextModule();
  });
}

const modules = [
  path.join(__dirname, 'module1.js'),
  path.join(__dirname, 'module2.js'),
  path.join(__dirname, 'module3.js')
];

loadModules(modules)
  .then(results => {
    console.log('All modules loaded successfully:', results);
    return executeModules(modules);
  })
  .then(() => {
    console.log('All modules executed successfully');
  })
  .catch(error => {
    console.error('Error loading or executing modules:', error);
  });
```

This code defines two functions, `loadModules` and `executeModules`, that take an array of module paths as input. The `loadModules` function uses the `fs.readFile` method to read the contents of each module file asynchronously, parses the JavaScript code using the `new Function` constructor, and stores the results in an array. If any errors occur during reading or parsing, they are caught and rejected with a Promise.

The `executeModules` function also takes an array of module paths as input. It uses a recursive approach to execute each module asynchronously by calling `fs.readFile` to read the contents of the current module file, parsing the JavaScript code using the `new Function` constructor, and then moving on to the next module. If any errors occur during reading or parsing, they are caught and rejected with a Promise.

Finally, the code demonstrates how to use these functions by passing an array of module paths to both functions in sequence. If all modules load and execute successfully, it logs success messages to the console; otherwise, it logs error messages to the console.

