#include <iostream>
#include <vector>
#include <algorithm>
#include <chrono>
#include <boost/asio.hpp>

// Function to find the largest integer in a vector
int findLargest(const std::vector<int>& numbers) {
    return *std::max_element(numbers.begin(), numbers.end());
}

// Function to send asynchronous GET requests using Boost.ASIO and handle responses
void sendRequests(boost::asio::io_context& io, const std::vector<std::string>& urls, int timeoutSeconds) {
    // Create a Sandesh client using Boost library
    boost::asio::ip::tcp::resolver resolver(io);
    boost::asio::ip::tcp::socket socket(io);

    for (const auto& url : urls) {
        try {
            // Resolve the URL to an IP address
            auto endpoints = resolver.resolve(url, "http");

            // Connect to the server asynchronously
            boost::asio::async_connect(socket, endpoints,
                [&](const boost::system::error_code& error, const boost::asio::ip::tcp::endpoint&) {
                    if (!error) {
                        // Send a GET request asynchronously
                        socket.async_send(boost::asio::buffer("GET / HTTP/1.1\r\nHost: " + url + "\r\nConnection: close\r\n\r\n"),
                            [&](const boost::system::error_code& error, std::size_t bytes_sent) {
                                if (!error) {
                                    // Wait for the response asynchronously
                                    socket.async_read_some(boost::asio::buffer(response_buffer),
                                        [&](const boost::system::error_code& error, std::size_t bytes_received) {
                                            if (!error && response_buffer.find("200 OK") != std::string::npos) {
                                                ++successful_responses;
                                            } else {
                                                ++failed_responses;
                                            }
                                        });
                                } else {
                                    ++failed_responses;
                                }
                            });
                    } else {
                        ++failed_responses;
                    }
                });

            // Wait for the response asynchronously
            boost::asio::deadline_timer timer(io, boost::posix_time::seconds(timeoutSeconds));
            socket.async_read_some(boost::asio::buffer(response_buffer),
                [&](const boost::system::error_code& error, std::size_t bytes_received) {
                    if (!error && response_buffer.find("200 OK") != std::string::npos) {
                        ++successful_responses;
                    } else {
                        ++failed_responses;
                    }
                    timer.cancel();
                });
        } catch (const boost::system::error_code& error) {
            ++failed_responses;
        }

        // Wait for the request to complete
        io.run_one();
    }
}

