```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class SecureEncryptionManager
{
    public byte[] Decrypt(byte[] ciphertext, byte[] iv = null, byte[] key = null, CipherMode mode = CipherMode.CBC, PaddingMode padding = PaddingMode.PKCS7)
    {
        if (iv == null) iv = GenerateRandomBytes(16);
        if (key == null) key = GenerateRandomBytes(32);

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.KeySize = 256;
            aesAlg.Mode = mode;
            aesAlg.Padding = padding;

            ICryptoTransform decryptor;
            switch (mode)
            {
                case CipherMode.CBC:
                    aesAlg.IV = iv;
                    decryptor = aesAlg.CreateDecryptor(key, iv);
                    break;
                case CipherMode.GCM:
                    aesAlg.GcmTagLength = 128; // Set GCM tag length
                    aesAlg.IV = iv;
                    aesAlg.Key = key;
                    decryptor = aesAlg.CreateDecryptor();
                    break;
                default:
                    throw new ArgumentException("Unsupported cipher mode.");
            }

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[ciphertext.Length];
                    int decryptedCount = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
    }

    private static byte[] GenerateRandomBytes(int length)
    {
        using (RNGCryptoServiceProvider rngCsp = new RNGCryptoServiceProvider())
        {
            byte[] randomBytes = new byte[length];
            rngCsp.GetBytes(randomBytes);
            return randomBytes;
        }
    }
}
```
