using UnityEngine;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

public class DynamicValueGenerator : MonoBehaviour
{
    private DistributionType _currentDistribution = DistributionType.Uniform;
    private object[] _distributionParameters;
    private ConcurrentDictionary<string, float> _cache = new ConcurrentDictionary<string, float>();
    private int _cacheSize = 1000;

    public enum DistributionType
    {
        Uniform,
        Gaussian,
        Exponential,
        Custom
    }

    public void SetDistribution(DistributionType type, params object[] parameters)
    {
        if (type == DistributionType.Custom && !(parameters.Length >= 2 && parameters[0] is float && parameters[1] is float))
        {
            Debug.LogError("Custom distribution requires two floats: mean and standard deviation.");
            return;
        }

        _currentDistribution = type;
        _distributionParameters = parameters;
    }

    public float GenerateRandomFloat()
    {
        string cacheKey = $"Float_{_currentDistribution}_{string.Join(",", _distributionParameters)}";

        if (_cache.TryGetValue(cacheKey, out float cachedValue))
        {
            return cachedValue;
        }

        float value;
        switch (_currentDistribution)
        {
            case DistributionType.Uniform:
                value = UnityEngine.Random.Range(0f, 1f);
                break;
            case DistributionType.Gaussian:
                value = (float)UnityEngine.Random.Normal(0f, 1f); // Simplified for demonstration
                break;
            case DistributionType.Exponential:
                value = (float)(-Mathf.Log(UnityEngine.Random.value));
                break;
            default:
                value = UnityEngine.Random.Range(0f, 1f);
                Debug.LogWarning("Unsupported distribution type. Using uniform distribution as fallback.");
                break;
        }

        _cache.TryAdd(cacheKey, value);

        if (_cache.Count > _cacheSize)
        {
            string oldestKey;
            _cache.TryRemove(_cache.Keys.First(), out _);
        }

        return value;
    }

    public int GenerateRandomInt(int min, int max)
    {
        string cacheKey = $"Int_{_currentDistribution}_{min}_{max}";

        if (_cache.TryGetValue(cacheKey, out float cachedValue))
        {
            return Mathf.RoundToInt(cachedValue);
        }

        float normalizedFloat = UnityEngine.Random.Range(0f, 1f);
        int value;

        switch (_currentDistribution)
        {
            case DistributionType.Uniform:
                value = (int)(normalizedFloat * (max - min + 1)) + min;
                break;
            case DistributionType.Gaussian:
                float gaussianValue = UnityEngine.Random.Range(0f, 1f);
                // Apply inverse transform sampling for Gaussian distribution
                // This is a simplified example and may not be the most efficient method.
                value = Mathf.RoundToInt((min + max) / 2 + (max - min) * gaussianValue);
                break;
            case DistributionType.Exponential:
                float exponentialValue = UnityEngine.Random.Range(0f, 1f);
                value = Mathf.RoundToInt(min + (max - min) * Mathf.Log(1f - exponentialValue));
                break;
            default:
                value = UnityEngine.Random.Range(min, max + 1);
                Debug.LogWarning("Unsupported distribution type. Using uniform distribution as fallback.");
                break;
        }

        _cache.TryAdd(cacheKey, value);

        if (_cache.Count > _cacheSize)
        {
            string oldestKey;
            _cache.TryRemove(_cache.Keys.First(), out _);
        }

        return value;
    }

    public override string ToString()
    {
        string parametersStr = string.Join(", ", _distributionParameters.Select(param => param.ToString()));
        return $"Range: 0 to 1, Distribution: {_currentDistribution}, Parameters: {parametersStr}";
    }
}
