```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionService
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private static readonly ILog Logger = LogManager.GetLogger(typeof(DecryptionService));

    public DecryptionService(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 24) throw new ArgumentException("Key must be exactly 24 bytes for Triple DES.");
        if (iv == null || iv.Length != 8) throw new ArgumentException("IV must be exactly 8 bytes.");

        _key = key;
        _iv = iv;
    }

    public async Task<string> DecryptAsync(string base64EncodedMessage, string expectedHmac)
    {
        try
        {
            var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            using (var tripleDES = new TripleDESCryptoServiceProvider())
            {
                tripleDES.Mode = CipherMode.CBC;
                tripleDES.Padding = PaddingMode.PKCS7;
                tripleDES.Key = _key;
                tripleDES.IV = _iv;

                using (var memoryStream = new MemoryStream(encryptedBytes))
                using (var cryptoStream = new CryptoStream(memoryStream, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    var decryptedBytes = new byte[encryptedBytes.Length];
                    await cryptoStream.ReadAsync(decryptedBytes, 0, decryptedBytes.Length);
                    string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

                    if (!VerifyHmac(expectedHmac, decryptedBytes, _key))
                    {
                        throw new InvalidOperationException("Integrity check failed.");
                    }

                    Logger.Info($"Decryption successful: {decryptedMessage}");
                    return decryptedMessage;
                }
            }
        }
        catch (Exception ex)
        {
            Logger.Error(ex, "Decryption failed.");
            throw new InvalidOperationException("Failed to decrypt message.", ex);
        }
    }

    private static bool VerifyHmac(string expectedHmac, byte[] data, byte[] key)
    {
        using (var hmacSHA256 = new HMACSHA256(key))
        {
            var computedHmac = Convert.ToBase64String(hmacSHA256.ComputeHash(data));
            return computedHmac == expectedHmac;
        }
    }

    public void Dispose()
    {
        // Implement IDisposable if necessary
    }
}
```

