import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class CloudStorageUploader {

    public static void uploadFileToCloudStorage(String filePath, String bucketName, String directoryPath) {
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                System.out.println("File does not exist.");
                return;
            }

            String hash = calculateFileSHA256(file);
            boolean isPresent = checkIfFileIsPresent(bucketName, directoryPath, hash);

            if (isPresent) {
                System.out.println("File already exists in the specified location.");
                return;
            }

            // Upload file to cloud storage
            uploadFileToCloud(file, bucketName, directoryPath, hash);
        } catch (IOException | NoSuchAlgorithmException e) {
            handleException(e);
        }
    }

    private static String calculateFileSHA256(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new FileInputStream(file)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private static boolean checkIfFileIsPresent(String bucketName, String directoryPath, String hash) throws IOException {
        // Simulate API call to check if file is present
        // Replace with actual API integration logic
        URL url = new URL("https://api.cloudstorage.com/check?bucket=" + bucketName + "&directory=" + directoryPath + "&hash=" + hash);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        int responseCode = conn.getResponseCode();
        return responseCode == 200;
    }

    private static void uploadFileToCloud(File file, String bucketName, String directoryPath, String hash) throws IOException {
        // Simulate API call to upload file
        // Replace with actual API integration logic
        URL url = new URL("https://api.cloudstorage.com/upload?bucket=" + bucketName + "&directory=" + directoryPath);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);

        try (OutputStream os = conn.getOutputStream()) {
            try (InputStream is = new FileInputStream(file)) {
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    os.write(buffer, 0, bytesRead);
                }
            }
        }

        if (conn.getResponseCode() == 200) {
            System.out.println("File uploaded successfully.");
        } else {
            handleException(new IOException("Failed to upload file. Status code: " + conn.getResponseCode()));
        }
    }

    private static void handleException(Exception e) {
        System.err.println("An error occurred: " + e.getMessage());
        // Log the exception and provide appropriate feedback to the user
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // Unit tests
        try {
            File testFile = new File("test.txt");
            uploadFileToCloudStorage(testFile.getAbsolutePath(), "myBucket", "myDirectory");
        } catch (IOException | NoSuchAlgorithmException e) {
            handleException(e);
        }
    }
}
