#include <iostream>
#include <thread>
#include <chrono>
#include <future>
#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>

// Mock function to simulate metadata service query
std::string FindVmUuidFromMetadataIp(const std::string& ip) {
    return "mock-uuid";
}

class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& ioc, const std::string& server_ip, int max_retries)
        : resolver_(ioc), stream_(ioc), server_ip_(server_ip), max_retries_(max_retries) {}

    void send_requests() {
        while (true) {
            try {
                auto uuid = FindVmUuidFromMetadataIp("192.168.1.1");
                if (!uuid.empty()) {
                    send_request("GET", "/status", uuid);
                    send_request("POST", "/data", uuid);
                }
            } catch (...) {
                std::cerr << "Failed to query metadata service, using mock UUID" << std::endl;
            }

            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

private:
    void send_request(const std::string& method, const std::string& path, const std::string& uuid) {
        auto self(shared_from_this());
        boost::asio::ip::tcp::resolver::results_type endpoints = resolver_.resolve(server_ip_, "80");

        boost::beast::http::request<boost::beast::http::string_body> req{boost::beast::http::verb::get, path + "?uuid=" + uuid, 11};
        req.set(boost::beast::http::field::host, server_ip_);
        req.set(boost::beast::http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        req.method(method == "POST" ? boost::beast::http::verb::post : boost::beast::http::verb::get);

        stream_.async_connect(endpoints,
            [self](const boost::system::error_code& ec, const boost::asio::ip::tcp::endpoint&) {
                if (!ec) self->do_request(std::move(req));
            });
    }

    void do_request(boost::beast::http::request<boost::beast::http::string_body> req) {
        auto self(shared_from_this());
        http::async_write(stream_, req,
            [self](const boost::system::error_code& ec, std::size_t bytes_transferred) {
                if (!ec) self->do_read();
            });
    }

    void do_read() {
        auto self(shared_from_this());
        stream_.async_read_some(boost::asio::buffer(buffer_),
            [self](const boost::system::error_code& ec, std::size_t bytes_transferred) {
                if (!ec) {
                    std::cout << "Received: " << boost::beast::make_printable({buffer_.data(), bytes_transferred}) << std::endl;
                }
            });
    }

private:
    boost::asio::ip::tcp::resolver resolver_;
    boost::beast::ssl_stream<boost::beast::tcp_stream> stream_;
    std::string server_ip_;
    int max_retries_;
    char buffer_[8192];
};

int main() {
    try {
        boost::asio::io_context ioc;
        SandeshClient client(ioc, "example.com", 3);
        client.send_requests();
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
