#include <variant>
#include <unordered_map>
#include <json.hpp>

using json = nlohmann::json;

// Function to parse JSON configuration
std::unordered_map<std::string, std::variant<int, double, std::string, bool>> parseConfig(const std::string& configPath) {
    // Read and parse the JSON file
    std::ifstream configFile(configPath);
    json config = json::parse(configFile);

    // Convert JSON to unordered_map
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> configMap;
    for (auto& [key, value] : config.items()) {
        if (value.is_number_integer()) {
            configMap[key] = value.get<int>();
        } else if (value.is_number_unsigned()) {
            configMap[key] = static_cast<double>(value.get<uint64_t>());
        } else if (value.is_number_float()) {
            configMap[key] = value.get<double>();
        } else if (value.is_string()) {
            configMap[key] = value.get<std::string>();
        } else if (value.is_boolean()) {
            configMap[key] = value.get<bool>();
        }
    }

    return configMap;
}

// Class for handling logging with different levels
class Logger {
public:
    enum LogLevel { DEBUG, INFO, WARN, ERROR, CRITICAL };

    void setLevel(LogLevel level) {
        logLevel.store(level);
    }

    template<typename T>
    void log(LogLevel level, const std::string& message) {
        if (level >= logLevel.load()) {
            // Log the message with timestamp and appropriate prefix
            std::cout << "[" << getLogPrefix(level) << "] " << message << std::endl;
        }
    }

private:
    std::atomic<LogLevel> logLevel{INFO};

    std::string getLogPrefix(LogLevel level) {
        switch (level) {
            case DEBUG: return "DEBUG";
            case INFO: return "INFO";
            case WARN: return "WARN";
            case ERROR: return "ERROR";
            case CRITICAL: return "CRITICAL";
        }
        return "";
    }
};

// Main utility class
class SecureMessagingUtility {
public:
    SecureMessagingUtility(const std::string& configPath) : logger(), config(parseConfig(configPath)) {}

    void run() {
        // Initialize cryptographic resources
        if (!initializeCrypto()) {
            logger.log(Logger::ERROR, "Failed to initialize cryptographic resources.");
            return;
        }

        // Process messages in a multi-threaded environment
        std::vector<std::thread> threads;
        for (int i = 0; i < config["num_threads"].get<int>(); ++i) {
            threads.emplace_back(&SecureMessagingUtility::processMessages, this);
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
