<?php

class PasswordManager {
    private $database;
    private $logger;

    public function __construct($database, $logger) {
        $this->database = $database;
        $this->logger = $logger;
    }

    public function generatePasswordHash($password, $algorithm = PASSWORD_DEFAULT, $options = []) {
        if (!in_array($algorithm, [PASSWORD_DEFAULT, PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
            throw new InvalidArgumentException("Unsupported password algorithm");
        }

        // Generate a unique salt
        $salt = $this->generateSalt();

        // Hash the password with the specified algorithm and options
        $hash = password_hash("$password$salt", $algorithm, $options);

        if (false === $hash) {
            throw new Exception("Password hashing failed");
        }

        // Store the salt and hash in the database
        $this->database->storeHash($salt, $hash);

        return $hash;
    }

    public function validatePasswordHash($password, $storedHash) {
        if (false === password_verify($password, $storedHash)) {
            throw new Exception("Invalid password");
        }

        return true;
    }

    private function generateSalt() {
        // Generate a unique salt using a secure random string
        return bin2hex(random_bytes(16));
    }
}

