public class AsynchronousFileReportGenerator {

    private ExecutorService executorService;
    private HashMap<String, String> fileCache;
    private HashMap<String, String> metadataCache;

    public AsynchronousFileReportGenerator() {
        this.executorService = Executors.newFixedThreadPool(10);
        this.fileCache = new HashMap<>();
        this.metadataCache = new HashMap<>();
    }

    public void processFiles(String directoryPath) {
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isFile() && isTextFile(file)) {
                    executorService.submit(() -> processFile(file));
                }
            }
        }
    }

    private boolean isTextFile(File file) {
        // Implement logic to check if the file is a text file
        return file.getName().endsWith(".txt");
    }

    private void processFile(File file) {
        try {
            String filePath = file.getAbsolutePath();
            Path path = Paths.get(filePath);
            byte[] bytes = Files.readAllBytes(path);

            // Validate file metadata and calculate SHA-256 hash
            if (validateMetadata(file, bytes)) {
                String hash = calculateSHA256(bytes);

                // Cache the file and its hash for future use
                cacheFile(hash, filePath);

                // Process the file content to identify specific keywords using regular expressions
                List<String> lines = Files.readAllLines(path);
                List<String> keywordLines = lines.stream()
                    .filter(line -> Pattern.compile("error|warning", Pattern.CASE_INSENSITIVE).matcher(line).find())
                    .collect(Collectors.toList());

                // Generate a customizable summary report
                String report = generateReport(keywordLines);

                // Upload the summary report to multiple external cloud storage services
                uploadToCloud(hash, report);
            }
        } catch (IOException e) {
            handleException(e);
        }
    }

    private boolean validateMetadata(File file, byte[] bytes) {
        try {
            // Implement logic to validate file metadata and content type
            return true;
        } catch (IOException e) {
            handleException(e);
            return false;
        }
    }

    private String calculateSHA256(byte[] bytes) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(bytes);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            handleException(e);
            return null;
        }
    }

    private void cacheFile(String hash, String filePath) {
        fileCache.put(hash, filePath);
        metadataCache.put(hash, getMetadata(filePath));
    }

    private String getMetadata(String filePath) {
        // Implement logic to retrieve and return file metadata
        return "File size: " + new File(filePath).length() + ", Content type: text/plain";
    }

    private String generateReport(List<String> lines) {
        // Implement logic to generate a customizable summary report
        StringBuilder sb = new StringBuilder();
        for (String line : lines) {
            sb.append(line).append("\n");
        }
        return sb.toString();
    }

    private void uploadToCloud(String hash, String report) {
