            // Handle potential errors from API integration gracefully
        } catch (Exception e) {
            handleException(e);
        }
    }

    private void handleException(Exception e) {
        // Implement logic to handle potential errors gracefully
        System.err.println("An error occurred: " + e.getMessage());
    }

    public void shutdown() {
        executorService.shutdown();
    }
