    {
        public async Task CompressAsync(ReadOnlyMemory<byte> input, Stream output)
        {
            using (var gzipStream = new System.IO.Compression.GZipStream(output, System.IO.Compression.CompressionMode.Compress))
                await gzipStream.WriteAsync(input.ToArray(), 0, input.Length);
        }
    }

    public class DeflateCompressionAlgorithm : ICompressionAlgorithm
    {
        public async Task CompressAsync(ReadOnlyMemory<byte> input, Stream output)
        {
            using (var deflateStream = new System.IO.Compression.DeflateStream(output, System.IO.Compression.CompressionMode.Compress))
                await deflateStream.WriteAsync(input.ToArray(), 0, input.Length);
        }
    }

    public class LZ4CompressionAlgorithm : ICompressionAlgorithm
    {
        public async Task CompressAsync(ReadOnlyMemory<byte> input, Stream output)
        {
