#include <iostream>
#include <string>
#include <map>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <random>

// Simulated payment gateway interface
class PaymentGateway {
public:
    virtual bool processTransaction(const std::string& method, const std::string& details) = 0;
    virtual void extendSession() = 0;
};

// Mock payment gateway implementation
class MockPaymentGateway : public PaymentGateway {
private:
    std::mutex mtx;
    bool sessionActive;

public:
    MockPaymentGateway() : sessionActive(false) {}

    bool processTransaction(const std::string& method, const std::string& details) override {
        // Simulate transaction processing
        return true;
    }

    void extendSession() override {
        std::unique_lock<std::mutex> lock(mtx);
        if (!sessionActive) {
            sessionActive = true;
            std::thread([this]() {
                std::this_thread::sleep_for(std::chrono::minutes(30));
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    sessionActive = false;
                }
            }).detach();
        }
    }
};

// Transaction cache
class TransactionCache {
private:
    std::map<std::string, std::future<bool>> cache;
    std::chrono::seconds ttl;

public:
    TransactionCache(std::chrono::seconds ttl) : ttl(ttl) {}

    bool getOrSet(const std::string& transactionId, std::function<std::future<bool>()> func) {
        auto now = std::chrono::system_clock::now();
        if (cache.find(transactionId) != cache.end() && 
            (now - cache[transactionId].get().wait_for(std::chrono::seconds(0)) < ttl)) {
            return cache[transactionId].get();
        }
        cache[transactionId] = func();
        return cache[transactionId].get();
    }
};

// Payment processing function
std::future<bool> processPayment(const std::string& method, const std::string& details) {
    static MockPaymentGateway gateway;
    static TransactionCache cache(std::chrono::seconds(30));
    static std::mutex logMutex;

    // Extend session if necessary
    if (!gateway.sessionActive) {
        gateway.extendSession();
    }

    // Process transaction with caching and exponential backoff
    auto process = [&]() -> bool {
        int retries = 5;
        while (retries > 0) {
            try {
                return gateway.processTransaction(method, details);
            } catch (...) {
                --retries;
                if (retries == 0) {
                    throw;
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(1 << (5 - retries)));
            }
        }
        return false;
    };

    // Log transaction activity
    auto log = [&](const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) 
                  << "] " << message << std::endl;
    };

    try {
        return cache.getOrSet(details, process);
    } catch (...) {
        log("Transaction failed: " + std::string(std::current_exception()));
        throw;
    }
}

// Example usage
int main() {
    try {
        auto result = processPayment("credit_card", "details");
        if (result) {
            std::cout << "Transaction processed successfully." << std::endl;
        } else {
            std::cout << "Transaction failed." << std::endl;
        }
    } catch (...) {
        std::cerr << "Exception occurred during transaction processing." << std::endl;
    }
    return 0;
}
