import gzip
import json
import csv
import sqlite3
import requests
import threading
import time

class DataTransformer:
    def __init__(self, rules):
        self.rules = rules

    def transform(self, data):
        for rule in self.rules:
            if rule['type'] == 'uppercase':
                data[rule['column']] = data[rule['column']].upper()
            # Add more transformation types as needed
        return data

class CSVReader:
    def __init__(self, filename):
        self.filename = filename

    def read(self):
        with gzip.open(self.filename, 'rt') as f:
            reader = csv.DictReader(f)
            for row in reader:
                yield row

class SQLWriter:
    def __init__(self, db_name, table_name):
        self.db_name = db_name
        self.table_name = table_name
        self.connection = sqlite3.connect(self.db_name, isolation_level=None, detect_types=sqlite3.PARSE_DECLTYPES)

    def write(self, data):
        cursor = self.connection.cursor()
        placeholders = ', '.join('?' * len(data))
        columns = ', '.join(data.keys())
        query = f'INSERT INTO {self.table_name} ({columns}) VALUES ({placeholders})'
        cursor.execute(query, list(data.values()))

    def close(self):
        self.connection.close()

class ProgressMonitor:
    def __init__(self):
        self.processed_rows = 0
        self.lock = threading.Lock()

    def update_progress(self, rows):
        with self.lock:
            self.processed_rows += rows

    def get_progress(self):
        return self.processed_rows

def main():
    rules = json.load(open('rules.json'))
    transformer = DataTransformer(rules)
    reader = CSVReader('data.csv.gz')
    writer = SQLWriter('database.db', 'transformed_data')
    monitor = ProgressMonitor()

    for row in reader.read():
        transformed_row = transformer.transform(row)
        writer.write(transformed_row)
        monitor.update_progress(1)

    print(f'Processed {monitor.get_progress()} rows.')
    writer.close()

if __name__ == '__main__':
    main()
```

