class Token:
    def __init__(self, user_id: int, access_token: str, refresh_token: str):
        self.user_id = user_id
        self.access_token = access_token
        self.refresh_token = refresh_token

def generate_access_token(user_id: int, is_sensitive=False) -> str:
    if is_sensitive:
        token_length = 128
    else:
        token_length = 64
    return os.urandom(token_length).hex()

def create_tokens(user_id: int) -> Token:
    access_token = generate_access_token(user_id)
    refresh_token = generate_access_token(user_id, is_sensitive=True)
    encoded_jwt = jwt.encode({"sub": user_id, "exp": datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)}, SECRET_KEY, algorithm=ALGORITHM)
    return Token(user_id, encoded_jwt, refresh_token)

def get_user_by_token(token: str) -> Optional[int]:
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        return payload.get("sub")
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

def revoke_token(token_type: str, token: str):
    # Implement token revocation logic here
    pass

def refresh_access_token(refresh_token: str) -> str:
    user_id = get_user_by_token(refresh_token)
    if user_id is not None:
        new_access_token = generate_access_token(user_id)
        return new_access_token
    else:
        raise Exception("Invalid or expired refresh token")

# Example usage
if __name__ == "__main__":
    new_tokens = create_tokens(123)
    print("Access Token:", new_tokens.access_token)
    print("Refresh Token:", new_tokens.refresh_token)
