```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/time.h>

#define MAX_CONCURRENT_REQUESTS 100
#define CACHE_SIZE 1024

typedef struct {
    char hostname[NI_MAXHOST];
    u_char ip[NI_MAXHOST];
} DNSCacheEntry;

DNSCacheEntry cache[CACHE_SIZE];
int cacheIndex = 0;
int concurrentRequests = 0;
pthread_mutex_t lock;
pthread_cond_t cond;

u_char* resolveHostname(const char* hostname) {
    pthread_mutex_lock(&lock);
    while (concurrentRequests >= MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&cond, &lock);
    }
    concurrentRequests++;
    pthread_mutex_unlock(&lock);

    struct addrinfo hints, *res, *p;
    int status;
    u_char* ipAddress = malloc(INET6_ADDRSTRLEN);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        concurrentRequests--;
        pthread_mutex_lock(&lock);
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        strcpy((char*)ipAddress, ipstr);
        break; // Use the first available address
    }

    freeaddrinfo(res);

    pthread_mutex_lock(&lock);
    concurrentRequests--;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    return ipAddress;
}
