int read_and_parse_tiff(const char *filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        return -1;
    }

    uint32_t bitsPerSample, samplesPerPixel;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) &&
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
        printf("Bits per sample: %u\n", bitsPerSample);
        printf("Samples per pixel: %u\n", samplesPerPixel);
    } else {
        fprintf(stderr, "Failed to read TIFF tags.\n");
        TIFFClose(tif);
        return -1;
    }

    TIFFClose(tif);
    return 0;
}
