use std::env;
use std::fs::{self, DirBuilder};
use std::io::{Error, ErrorKind};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use serde::{Deserialize, Serialize};
use toml;

#[derive(Serialize, Deserialize)]
struct Config {
    max_retries: u32,
    backoff_intervals: Vec<u64>,
}

fn load_config() -> Result<Config, Error> {
    let config_path = "config.toml";
    let config_content = std::fs::read_to_string(config_path)?;
    toml::from_str(&config_content)
}

fn create_directory_and_set_env_var(dir_name: &str) -> Result<(), Error> {
    const MAX_NAME_LEN: usize = 255;
    const ILLEGAL_CHARS: &[char] = &['/', '\\', ':', '*', '?', '"', '<', '>', '|'];

    if dir_name.len() > MAX_NAME_LEN {
        return Err(Error::new(ErrorKind::InvalidInput, "Directory name is too long"));
    }

    for c in dir_name.chars().filter(|c| ILLEGAL_CHARS.contains(c)) {
        return Err(Error::new(ErrorKind::InvalidInput, format!("Illegal character in directory name: {}", c)));
    }

    let config = load_config()?;
    let max_retries = config.max_retries;
    let backoff_intervals = config.backoff_intervals;

    if env::var(dir_name).is_ok() {
        log::info!("Environment variable {} already set, using existing value", dir_name);
        return Ok(());
    }

    let lock = Arc::new(Mutex::new(()));
    let mut handle = lock.lock().unwrap();

    for i in 0..max_retries {
        if fs::create_dir(dir_name).is_err() && i < max_retries - 1 {
            log::warn!("Failed to create directory {}, retrying...", dir_name);
            std::thread::sleep(Duration::from_secs(backoff_intervals[i as usize]));
        } else {
            break;
        }
    }

    if fs::create_dir(dir_name).is_err() {
        log::error!("Failed to create directory {}", dir_name);
        return Err(Error::new(ErrorKind::Other, "Failed to create directory"));
    }

    env::set_var(dir_name, &dir_name);
    log::info!("Created directory {} and set environment variable", dir_name);

    Ok(())
}
