import hashlib
import os

class FileHasher:
    def calculate_md5_hash_from_file(self, file_path):
        hasher = hashlib.md5()
        chunk_size = 4096  # Adjust based on performance needs
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()

