        _httpClient.BaseAddress = new Uri("https://database-server/api");
    }

    public async Task<DbDataReader> ExecuteQueryAndReturnResult(byte[] data)
    {
        var content = new ByteArrayContent(data);
        content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");

        try
        {
            HttpResponseMessage response = await _httpClient.PostAsync("/query", content);
            response.EnsureSuccessStatusCode();

            using (var stream = await response.Content.ReadAsStreamAsync())
            {
                var reader = DbDataReader.Create(stream, null, true, true);
                return reader;
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions and retry logic here
            throw new Exception("Failed to execute query", ex);
        }
    }

    public void Dispose()
