#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, FILE *logFile) {
    if (maxStructures > MAX_STRUCTURES || logFile == NULL) {
        fprintf(logFile, "Error: Invalid input parameters\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *tempList = malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (tempList == NULL) {
        fprintf(logFile, "Error: Memory allocation failed\n");
        return -1;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < maxStructures; ++i) {
        tempList[i].RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
        tempList[i].RNTI = rand() % 65536;
        tempList[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0);
    }

    pthread_mutex_unlock(&mutex);

    *crcList = tempList;
    *listSize = maxStructures;

    return 0;
}
