use clap::{App, Arg};
use lexer::Lexer;
use parser::Parser;
use semantic_analyzer::SemanticAnalyzer;
use optimizer::Optimizer;
use code_generator::CodeGenerator;

mod lexer;
mod parser;
mod semantic_analyzer;
mod optimizer;
mod code_generator;

fn main() -> io::Result<()> {
    let matches = App::new("Rust Compiler")
        .version("1.0")
        .author("Your Name <your.email@example.com>")
        .about("A compiler written in Rust that generates optimized LLVM IR code.")
        .arg(
            Arg::with_name("input")
                .short('i')
                .long("input")
                .value_name("FILE")
                .help("Sets the input file path")
                .takes_value(true)
                .required(true),
        )
        .arg(
            Arg::with_name("output")
                .short('o')
                .long("output")
                .value_name("FILE")
                .help("Sets the output LLVM IR file path")
                .takes_value(true)
                .default_value("output.ll"),
        )
        .arg(
            Arg::with_name("format")
                .short('f')
                .long("format")
                .value_name("FORMAT")
                .help("Sets the output format (verbose or compact)")
                .takes_value(true)
                .possible_values(&["verbose", "compact"])
                .default_value("verbose"),
        )
        .arg(
            Arg::with_name("passes")
                .short('p')
                .long("passes")
                .value_name("PASSES")
                .help("Sets custom LLVM passes to apply during optimization")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("debug")
                .short('d')
                .long("debug")
                .help("Enables debug mode for detailed logging"),
        )
        .get_matches();

    let input_file = matches.value_of("input").unwrap();
    let output_file = matches.value_of("output").unwrap();
    let format = matches.value_of("format").unwrap();
    let passes = matches.value_of("passes").unwrap_or("");
    let debug_mode = matches.is_present("debug");

    // Read the input file
    let content = fs::read_to_string(input_file)?;

    // Create lexer, parser, semantic analyzer, optimizer, and code generator
    let mut lexer = Lexer::new(&content);
    let mut parser = Parser::new(&mut lexer);
    let ast = parser.parse();
    let semantic_analyzer = SemanticAnalyzer::new(ast.clone());
    let optimized_ast = Optimizer::optimize(semantic_analyzer.analyze(), passes, debug_mode);
    let code_generator = CodeGenerator::new(optimized_ast, format);

    // Generate LLVM IR code
    let ir_code = code_generator.generate();

    // Write the generated LLVM IR to output file
    fs::write(output_file, ir_code)?;

    Ok(())
}
