```php
<?php

class ConfigManager {
    private $environment;
    private $configCache = [];

    public function __construct($environment) {
        $this->environment = $environment;
    }

    public function reloadConfiguration() {
        $url = "http://central-config-service/config/$this->environment";
        $client = new HttpClient();
        try {
            $response = $client->get($url, ['disable_ssl' => true]);
            $config = json_decode($response, true);
            file_put_contents('config.yml', yaml_emit($config));
        } catch (Exception $e) {
            error_log("Error fetching configuration: " . $e->getMessage());
        }
    }

    public function reloadConfigurationOnEvent() {
        // Logic to check for specific events or environment variables
        if ($this->shouldReloadConfig()) {
            $this->reloadConfiguration();
        }
    }

    private function shouldReloadConfig() {
        // Placeholder logic
        return getenv('RELOAD_CONFIG') === 'true';
    }

    public function applyConfigurations() {
        $configFile = 'config.yml';
        if (file_exists($configFile)) {
            $localConfigFile = 'config-local.yml';
            if (file_exists($localConfigFile)) {
                $baseConfig = include($configFile);
                $localConfig = include($localConfigFile);
                $mergedConfig = array_merge_recursive($baseConfig, $localConfig);
            } else {
                $mergedConfig = include($configFile);
            }

            // Apply configurations
            foreach ($mergedConfig as $key => $value) {
                putenv("$key=$value");
            }
        } else {
            error_log("Configuration file not found: $configFile");
        }
    }
}

class HttpClient {
    public function get($url, $options = []) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_SSL_VERIFYPEER => isset($options['disable_ssl']) ? false : true,
        ]);

        $response = curl_exec($ch);
        if ($response === false) {
            throw new Exception("cURL Error: " . curl_error($ch));
        }

        return $response;
    }
}

// Example usage
$script = new ConfigManager('development');
$script->reloadConfiguration();
$script->applyConfigurations();

?>
