// JavaScript function to fetch weather data from a third-party API and update the UI of a web application

async function fetchWeatherData(cities, updateUI) {
    const apiKey = 'your_api_key';
    let backoffDelay = 100;
    const maxRetries = 5;

    for (const city of cities) {
        for (let retryCount = 0; retryCount < maxRetries; retryCount++) {
            try {
                const response = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}`);
                if (!response.ok) {
                    throw new Error(`API error: ${response.status} - ${response.statusText}`);
                }
                const data = await response.json();
                updateUI(city, data);
                backoffDelay = 100; // Reset backoff delay on successful request
                break;
            } catch (error) {
                if (retryCount === maxRetries - 1) {
                    console.error(`Failed to fetch weather data for ${city}:`, error);
                }
                await new Promise(resolve => setTimeout(resolve, Math.min(backoffDelay * (2 ** retryCount), 60000)));
            }
        }
    }
}

// Example usage
const cities = ['New York', 'Los Angeles', 'Chicago'];
fetchWeatherData(cities, (city, data) => {
    console.log(`Weather for ${city}:`, data);
});
