const axios = require('axios');
const { createHash } = require('crypto');
const fs = require('fs');
const { Queue, Worker } = require('bull');
const winston = require('winston');

// Configure Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'upload.log' })
  ]
});

// Create a Bull queue for managing uploads
const uploadQueue = new Queue('uploads', {
  concurrency: 5,
  limiter: { max: 10, duration: 60 * 1000 }
});

// Function to detect file type from URL
async function getFileType(url) {
  const response = await axios.head(url);
  return response.headers['content-type'].split(';')[0];
}

// Function to split large files into chunks
function chunkFile(file, size) {
  const chunks = [];
  let start = 0;
  while (start < file.length) {
    chunks.push(file.slice(start, start + size));
    start += size;
  }
  return chunks;
}

// Worker function for processing uploads
async function uploadWorker(job) {
  const { url, serviceConfig } = job.data;

  try {
    // Validate URL
    new URL(url);

    // Get file type
    const fileType = await getFileType(url);

    // Check file size and handle chunking if necessary
    let fileBuffer;
    if (fileSize > 100 * 1024 * 1024) {
      const response = await axios.get(url, { responseType: 'arraybuffer' });
      const chunks = chunkFile(Buffer.from(response.data), 10 * 1024 * 1024);
      // Logic to handle chunking and reassembly
    } else {
      const response = await axios.get(url, { responseType: 'arraybuffer' });
      fileBuffer = Buffer.from(response.data);
    }

    // Dynamic import based on service type
    const storageService = await import(serviceConfig.serviceType);
    const uploadFunction = storageService.uploadFile;
    await uploadFunction(fileBuffer, fileType, serviceConfig);

    logger.info(`File uploaded successfully: ${url}`);
  } catch (error) {
    logger.error(`Failed to upload file: ${url}`, error);
    job.retry({ delay: Math.pow(2, job.attemptsMade) * 1000 });
  }
}

// Add worker to queue
uploadQueue.process(uploadWorker);

// Function to enqueue a new upload task
function enqueueUpload(url, serviceConfig) {
  const jobId = uploadQueue.add({ url, serviceConfig }, { attempts: 5 });
  logger.info(`Enqueued upload for ${url}, Job ID: ${jobId}`);
}

module.exports = {
  enqueueUpload,
};
