```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MIN_EVENT_ID 100
#define MAX_EVENT_ID 999

typedef struct {
    time_t timestamp;
    int event_id;
    char *message;
} record;

record *records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex;

void initialize_record(record **rec, time_t ts, int id, const char *msg) {
    *rec = (record *)malloc(sizeof(record));
    if (*rec == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    (*rec)->timestamp = ts;
    (*rec)->event_id = id;
    (*rec)->message = strdup(msg); // Using strdup for safe string copy
}

void *initialize_records_thread(void *arg) {
    int thread_index = *(int *)arg;
    time_t ts = time(NULL);
    int start_id = MIN_EVENT_ID + (thread_index * 10);
    for (int i = 0; i < MAX_RECORDS / pthread_os_info().num_threads; ++i) {
        int id = start_id + i;
        initialize_record(&records[record_count++], ts, id, "Event Message");
        if (record_count >= MAX_RECORDS) break;
    }
    free(arg);
    return NULL;
}

void initialize_records() {
    pthread_t threads[pthread_os_info().num_threads];
    int *indices = (int *)malloc(sizeof(int) * pthread_os_info().num_threads);

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < pthread_os_info().num_threads; ++i) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, initialize_records_thread, &indices[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < pthread_os_info().num_threads; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Thread join failed\n");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_destroy(&mutex);

    printf("Records initialized: %d\n", record_count);
}

int main() {
    srand(time(NULL));
    initialize_records();
    return 0;
}
```

This code snippet demonstrates how to create a C function for managing and initializing a collection of `record` structures in a multi-threaded environment. It includes error handling, thread safety, dynamic memory allocation for strings, and efficient memory usage strategies. The function uses mutexes to ensure that concurrent access does not corrupt the records array and provides a mechanism for dynamically specifying message content.

