#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>

// Define a simple DataPoint structure to hold sensor data
struct DataPoint {
    int timestamp;
    double value;
};

// DataProcessor class to handle real-time data processing
class DataProcessor {
public:
    void addData(DataPoint data) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(data);
        cond_.notify_one();
    }

    void run() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cond_.wait(lock, [this] { return !queue_.empty() || !running_; });

            if (!running_ && queue_.empty()) break;

            DataPoint data = queue_.front();
            queue_.pop();

            // Process the data here (e.g., aggregate or store)
            std::cout << "Processing data: " << data.value << std::endl;
        }
    }

    void stop() {
        running_ = false;
        cond_.notify_all();
    }

private:
    std::queue<DataPoint> queue_;
    std::mutex mutex_;
    std::condition_variable cond_;
    std::atomic<bool> running_{true};
};

int main() {
    DataProcessor processor;
    std::thread processorThread(&DataProcessor::run, &processor);

    // Simulate adding data to the system
    for (int i = 0; i < 10000; ++i) {
        DataPoint point{i, static_cast<double>(i)};
        processor.addData(point);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stop();
    processorThread.join();

    return 0;
}
```

