#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for storing encryption parameters
typedef struct {
    EVP_CIPHER *cipher;
    const char *key;
    const char *iv;
} EncryptionParams;

// Function to initialize the OpenSSL library
void openssl_init() {
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();
}

// Function to clean up the OpenSSL library
void openssl_cleanup() {
    EVP_cleanup();
    ERR_free_strings();
}

// Function to encrypt data using AES-256-CBC
int aes_encrypt(const unsigned char *plaintext, int plaintext_len,
                const unsigned char *key, const unsigned char *iv,
                unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto cleanup;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto cleanup;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto cleanup;
    ciphertext_len += len;

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len > 0 ? ciphertext_len : -1;
}

// Function to decrypt data using AES-256-CBC
int aes_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                const unsigned char *key, const unsigned char *iv,
                unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto cleanup;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        goto cleanup;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        goto cleanup;
    plaintext_len += len;

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len > 0 ? plaintext_len : -1;
}

// Function to hash data using SHA-256
void sha256_hash(const unsigned char *data, size_t len, unsigned char *hash) {
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(ctx, data, len);
    EVP_DigestFinal_ex(ctx, hash, NULL);
    EVP_MD_CTX_free(ctx);
}

// Function to generate a random initialization vector
void generate_iv(unsigned char *iv) {
    if (RAND_bytes(iv, EVP_CIPHER_block_size(EVP_aes_256_cbc())) != 1) {
        fprintf(stderr, "Error generating IV\n");
        exit(EXIT_FAILURE);
    }
}

// Main function to demonstrate usage of the secure messaging service
int main() {
    openssl_init();

    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];
    unsigned char hash[SHA256_DIGEST_LENGTH];

    // Generate a random key and IV
    if (RAND_bytes(key, sizeof(key)) != 1) {
        fprintf(stderr, "Error generating key\n");
        exit(EXIT_FAILURE);
    }
    generate_iv(iv);

    // Encrypt the plaintext
    int ciphertext_len = aes_encrypt(plaintext, strlen((char *)plaintext), key, iv, ciphertext);
    if (ciphertext_len < 0) {
        fprintf(stderr, "Encryption failed\n");
        exit(EXIT_FAILURE);
    }

    // Decrypt the ciphertext
    int decryptedtext_len = aes_decrypt(ciphertext, ciphertext_len, key, iv, decryptedtext);
    if (decryptedtext_len < 0) {
        fprintf(stderr, "Decryption failed\n");
        exit(EXIT_FAILURE);
    }
    decryptedtext[decryptedtext_len] = '\0';

    // Hash the plaintext
    sha256_hash(plaintext, strlen((char *)plaintext), hash);

    printf("Plaintext: %s\n", plaintext);
    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++)
        printf("%02x", ciphertext[i]);
    printf("\n");
    printf("Decryptedtext: %s\n", decryptedtext);
    printf("SHA-256 Hash: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++)
        printf("%02x", hash[i]);
    printf("\n");

    openssl_cleanup();

    return 0;
}
