```javascript
function copyBufferChunks(chunks, byteCount) {
    const newBuffer = Buffer.alloc(byteCount);
    let copiedBytes = 0;

    for (const chunk of chunks) {
        if (copiedBytes >= byteCount) break;
        const toCopy = Math.min(chunk.length, byteCount - copiedBytes);
        try {
            chunk.copy(newBuffer, copiedBytes, 0, toCopy);
            copiedBytes += toCopy;
        } catch (error) {
            console.error(`Encoding error at position ${copiedBytes}:`, error.message);
        }
    }

    return newBuffer.slice(0, copiedBytes);
}
