#include <openssl/sha.h>
#include <curl/curl.h>

// Function to calculate SHA-256 hash of a file
std::string calculateSHA256(const std::string& filePath) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) return "File not found";

    const int bufferSize = 4096;
    char buffer[bufferSize];
    while (file.good() && !file.eof()) {
        file.read(buffer, bufferSize);
        SHA256_Update(&sha256, buffer, file.gcount());
    }
    file.close();

    SHA256_Final(hash, &sha256);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }
    return ss.str();
}

// Function to upload and monitor file
std::string uploadAndMonitorFile(const std::string& filePath, const std::string& bucketName,
                                 const std::map<std::string, std::string>& metadata = {}) {
    // Check if file exists and is accessible
    if (!std::ifstream(filePath).good()) return "File not found or inaccessible";

    // Calculate SHA-256 hash of the file
    std::string hash = calculateSHA256(filePath);
    if (hash == "File not found") return hash;

    // Simulate uploading and monitoring progress (replace with actual API calls)
    std::cout << "Uploading file: " << filePath << " to bucket: " << bucketName << "\n";
    for (int i = 0; i <= 100; ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        std::cout << "Upload progress: " << i << "%\r";
    }
    std::cout << "Upload complete\n";

    // Log successful upload
    std::cout << "Uploaded file with hash: " << hash << "\n";

    return hash;
}

// Example usage
int main() {
    std::string filePath = "path/to/your/file.txt";
    std::string bucketName = "your-bucket-name";
    std::map<std::string, std::string> metadata = {{"key1", "value1"}, {"key2", "value2"}};

    std::string result = uploadAndMonitorFile(filePath, bucketName, metadata);
    if (result != "File not found or inaccessible" && result != "File not found") {
        std::cout << "Upload and hash calculation successful. Hash: " << result << "\n";
    } else {
        std::cerr << "Error: " << result << "\n";
    }

    return 0;
}
