// EvolutionsManager.java
package com.pokemon.evolutions;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestTemplate;

@Configuration
public class EvolutionsManagerConfig {

    @Value("${api.timeout}")
    private int apiTimeout;

    @Bean
    public ExecutorService executorService() {
        return Executors.newCachedThreadPool();
    }

    @Bean
    public RestTemplate restTemplate(ExecutorService executorService) {
        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
        factory.setConnectTimeout(apiTimeout);
        factory.setReadTimeout(apiTimeout);
        factory.setBufferRequestBody(false);

        ListableBeanFactory beanFactory = ((ListableBeanFactory)applicationContext).getParentBeanFactory();
        ClientHttpRequestFactory requestFactory = beanFactory.getBean(ClientHttpRequestFactory.class, ClientHttpRequestFactory.class.getName());
        if (requestFactory != null) {
            factory.copyProperties(requestFactory);
        }

        return new RestTemplate(factory);
    }
}

