        return CompletableFuture.supplyAsync(() -> fetchPokemonDetails(pokemonName));
    }

    private PokemonDetails fetchPokemonDetails(String pokemonName) {
        String url = "https://api.example.com/pokemon/" + pokemonName;
        ResponseEntity<PokemonResponse> response = restTemplate.getForEntity(url, PokemonResponse.class);
        // Handle API exceptions and retries
        if (response.getStatusCode().is2xxSuccessful()) {
            return mapToPokemonDetails(response.getBody());
        }
        throw new RuntimeException("Failed to fetch Pokemon details");
    }

    private PokemonDetails mapToPokemonDetails(PokemonResponse pokemonResponse) {
        PokemonDetails details = new PokemonDetails();
        details.setName(pokemonResponse.getName());
        details.setType(pokemonResponse.getType());
        // Map weaknesses and evolutions
        return details;
    }
}

