import requests
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timedelta

class StockMarketService:
    def __init__(self):
        self.api_urls = {
            'alpha_vantage': 'https://www.alphavantage.co/query',
            'iex_cloud': 'https://api.iextrading.com/1.0'
        }
        self.api_keys = {
            'alpha_vantage': 'YOUR_ALPHA_VANTAGE_API_KEY',
            'iex_cloud': 'YOUR_IEX_CLOUD_API_KEY'
        }

    def get_data(self, symbol):
        results = {}
        with ThreadPoolExecutor() as executor:
            futures = {
                'alpha_vantage': executor.submit(self.fetch_from_alpha_vantage, symbol),
                'iex_cloud': executor.submit(self.fetch_from_iex_cloud, symbol)
            }
            for api, future in futures.items():
                try:
                    data = future.result()
                    results[api] = data
                except Exception as e:
                    print(f"Failed to fetch data from {api}: {e}")
        return results

    def fetch_from_alpha_vantage(self, symbol):
        params = {
            'function': 'GLOBAL_QUOTE',
            'symbol': symbol,
            'apikey': self.api_keys['alpha_vantage']
        }
        response = requests.get(self.api_urls['alpha_vantage'], params=params)
        response.raise_for_status()
        data = response.json()
        return {
            'symbol': data['Global Quote']['01. symbol'],
            'last_price': float(data['Global Quote']['05. price']),
            'volume': int(data['Global Quote']['06. volume']),
            'high': float(data['Global Quote']['03. high']),
            'low': float(data['Global Quote']['04. low']),
            'timestamp': datetime.now()
        }

    def fetch_from_iex_cloud(self, symbol):
        params = {
            'symbols': symbol,
            'types': 'quote'
        }
        headers = {
            'Authorization': f'Bearer {self.api_keys["iex_cloud"]}'
        }
        response = requests.get(f"{self.api_urls['iex_cloud']}/stock/market/batch", params=params, headers=headers)
        response.raise_for_status()
        data = response.json()[symbol]['quote']
        return {
            'symbol': data['symbol'],
            'last_price': float(data['latestPrice']),
            'volume': int(data['latestVolume']),
            'high': float(data['dayHigh']),
            'low': float(data['dayLow']),
            'timestamp': datetime.now()
        }

# Example usage
service = StockMarketService()
data = service.get_data('AAPL')
print(data)
