```php
<?php

class PasswordManager {
    private $saltGenerator;
    private $cryptoLibrary;
    private $rateLimiter;
    private $storageClient;
    private $config;

    public function __construct(SaltGenerator $saltGenerator, CryptoLibrary $cryptoLibrary, RateLimiter $rateLimiter, StorageClient $storageClient, Config $config) {
        $this->saltGenerator = $saltGenerator;
        $this->cryptoLibrary = $cryptoLibrary;
        $this->rateLimiter = $rateLimiter;
        $this->storageClient = $storageClient;
        $this->config = $config;
    }

    public function hashPassword($password, $algorithm = PASSWORD_DEFAULT, array $options = []) {
        $tenantId = $this->getTenantId();
        if (!$this->rateLimiter->allowRequest($tenantId)) {
            throw new Exception('Rate limit exceeded', 429);
        }

        $salt = $this->generateSalt($algorithm, $options);
        $hash = $this->cryptoLibrary->hashPassword($password, $algorithm, $salt, $options);

        $key = "pwd:{$tenantId}:{$hash}";
        $this->storageClient->set($key, $salt);

        return [
            'algorithm' => $algorithm,
            'salt' => base64_encode($salt),
            'hash' => $hash
        ];
    }

    public function verifyPassword($password, $hashedPassword) {
        $tenantId = $this->getTenantId();
        if (!$this->rateLimiter->allowRequest($tenantId)) {
            throw new Exception('Rate limit exceeded', 429);
        }

        $key = "pwd:{$tenantId}:{$hashedPassword}";
        if ($this->storageClient->exists($key)) {
            $salt = $this->storageClient->get($key);
            return $this->cryptoLibrary->verifyPassword($password, $hashedPassword, $salt);
        } else {
            throw new Exception('Invalid password', 401);
        }
    }

    private function generateSalt($algorithm, array $options) {
        // Customize salt generation logic based on algorithm and options
        return $this->saltGenerator->generate($algorithm, $options);
    }

    private function getTenantId() {
        // Implement logic to retrieve the current tenant ID
        return $_SERVER['TENANT_ID'] ?? 'default';
    }
}

interface SaltGenerator {
    public function generate($algorithm, array $options): string;
}

class DefaultSaltGenerator implements SaltGenerator {
    public function generate($algorithm, array $options): string {
        // Implement logic to generate a salt based on algorithm and options
        return openssl_random_pseudo_bytes(16);
    }
}

interface CryptoLibrary {
    public function hashPassword($password, $algorithm, $salt, array $options): string;
    public function verifyPassword($password, $hashedPassword, $salt): bool;
}

class BcryptCryptoLibrary implements CryptoLibrary {
    public function hashPassword($password, $algorithm, $salt, array $options): string {
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);
    }

    public function verifyPassword($password, $hashedPassword, $salt): bool {
        return password_verify($password, $hashedPassword);
    }
}

interface RateLimiter {
    public function allowRequest(string $tenantId): bool;
}

class InMemoryRateLimiter implements RateLimiter {
    private $requestCounts = [];

    public function allowRequest(string $tenantId): bool {
        if (!isset($this->requestCounts[$tenantId])) {
            $this->requestCounts[$tenantId] = 0;
        }

        if ($this->requestCounts[$tenantId] >= 50) {
            return false;
        }

        $this->requestCounts[$tenantId]++;
        return true;
    }
}

interface StorageClient {
    public function set($key, $value): bool;
    public function get($key);
    public function exists($key): bool;
}

class RedisStorageClient implements StorageClient {
    private $redis;

    public function __construct(Redis $redis) {
        $this->redis = $redis;
    }

    public function set($key, $value): bool {
        return $this->redis->setex($key, 3600, $value); // Set with expiration
    }

    public function get($key) {
        return $this->redis->get($key);
    }

    public function exists($key): bool {
        return $this->redis->exists($key);
    }
}

class Config {
    private $config;

    public function __construct(array $config) {
        $this->config = $config;
    }

    public function get($key, $default = null) {
        return $this->config[$key] ?? $default;
    }
}
