using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using MySql.Data.MySqlClient;
using Npgsql;
using MongoDB.Driver;
using Amazon.S3;
using Amazon.S3.Model;

public class SecurelyDecryptAndUpload
{
    private readonly ICryptoTransform _decryptor;
    private readonly ICloudStorageProvider _cloudStorageProvider;

    public SecurelyDecryptAndUpload(string key, string iv)
    {
        ValidateKeyLength(key);
        ValidateIVLength(iv);

        var aes = Aes.Create();
        aes.Key = Encoding.UTF8.GetBytes(key);
        aes.IV = Encoding.UTF8.GetBytes(iv);
        aes.Mode = CipherMode.GCM;
        aes.Padding = PaddingMode.PKCS7;

        _decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        _cloudStorageProvider = new CloudStorageProvider();
    }

    public async Task<string> DecryptAndUploadAsync(string file_path, string bucket_name, string metadata_tags = null)
    {
        if (!File.Exists(file_path))
            throw new FileNotFoundException("The specified file does not exist.");

        var decryptedFilePath = Path.GetTempFileName();

        using (var inputStream = File.OpenRead(file_path))
        using (var outputStream = File.Create(decryptedFilePath))
        using (var cryptoStream = new CryptoStream(inputStream, _decryptor, CryptoStreamMode.Read))
        {
            await cryptoStream.CopyToAsync(outputStream);
        }

        var file_hex_digest = CalculateSHA256HexDigest(decryptedFilePath);

        try
        {
            await _cloudStorageProvider.UploadFileAsync(decryptedFilePath, bucket_name, metadata_tags);
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }

        return file_hex_digest;
    }

    private void ValidateKeyLength(string key)
    {
        // Validate AES-GCM key length (128, 192, or 256 bits)
        if (key.Length * 8 < 128 || key.Length * 8 > 256)
            throw new ArgumentException("Invalid key length for AES-GCM.");
    }

    private void ValidateIVLength(string iv)
    {
        // Validate AES-GCM IV length (96 bits or more)
        if (iv.Length * 8 < 96)
            throw new ArgumentException("Invalid IV length for AES-GCM.");
    }

    private string CalculateSHA256HexDigest(string file_path)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashBytes = sha256.ComputeHash(File.ReadAllBytes(file_path));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    private void LogError(Exception ex)
    {
        // Implement error logging
        Console.Error.WriteLine($"An error occurred: {ex.Message}");
    }
}

public interface ICloudStorageProvider
{
    Task UploadFileAsync(string file_path, string bucket_name, string metadata_tags);
}

public class CloudStorageProvider : ICloudStorageProvider
{
    private readonly IAmazonS3 _s3Client;

    public CloudStorageProvider()
    {
        // Initialize S3 client with appropriate configuration
        var config = new AmazonS3Config { RegionEndpoint = Amazon.RegionEndpoint.USEast1 };
        _s3Client = new AmazonS3Client(config);
    }

    public async Task UploadFileAsync(string file_path, string bucket_name, string metadata_tags)
    {
        var request = new PutObjectRequest
        {
            BucketName = bucket_name,
            FilePath = file_path,
            Key = Path.GetFileName(file_path),
            CannedACL = S3CannedACL.PublicRead
        };

        if (!string.IsNullOrEmpty(metadata_tags))
        {
            request.Metadata.Add("custom_metadata", metadata_tags);
        }

        await _s3Client.PutObjectAsync(request);
    }
}

