public class SensorDataProcessor
{
    private readonly IMongoClient _client;
    private readonly IMongoDatabase _database;

    public SensorDataProcessor(string connectionString)
    {
        _client = new MongoClient(connectionString);
        _database = _client.GetDatabase("SensorData");
    }

    public string ValidateAndProcessFilePath(string filePath, int maxBufferSize, out string errorMessage)
    {
        if (string.IsNullOrEmpty(filePath) || filePath.Length > maxBufferSize)
        {
            errorMessage = "Invalid file path or exceeds maximum buffer size.";
            return null;
        }

        if (!Path.IsPathFullyQualified(filePath))
        {
            filePath = Path.Combine(Directory.GetCurrentDirectory(), filePath);
        }

        errorMessage = string.Empty;
        return filePath;
    }

    public void ProcessSensorData(string filePath)
    {
        try
        {
            using (var reader = XmlReader.Create(filePath))
            {
                var doc = new XPathDocument(reader);
                var navigator = doc.CreateNavigator();

                while (navigator.MoveToFollowing("sensor", ""))
                {
                    string deviceId = navigator.SelectSingleNode("id").Value;
                    string reading = navigator.SelectSingleNode("reading").Value;

                    InsertSensorData(deviceId, reading);
                }
            }
        }
        catch (Exception ex)
        {
            HandleError(ex);
        }
    }

    private void InsertSensorData(string deviceId, string reading)
    {
        var collection = _database.GetCollection<BsonDocument>("SensorReadings");
        var document = new BsonDocument
        {
            { "deviceId", deviceId },
            { "reading", reading },
            { "timestamp", DateTime.UtcNow }
        };

        collection.InsertOne(document);
    }

    private void HandleError(Exception ex)
    {
        // Implement error handling logic here, e.g., logging the exception
    }
}
