using System;
using System.Collections.Generic;
using System.Linq;

public class CustomRandomGenerator : ICloneable
{
    private Random _random;
    private int _seed;
    private (int Min, int Max) _rangeInt;
    private (float Min, float Max) _rangeFloat;

    public CustomRandomGenerator(int seed = 0)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public void SetSeed(int seed)
    {
        if (seed < 0) throw new ArgumentException("Seed must be non-negative.");
        _seed = seed;
        _random = new Random(seed);
    }

    public int GetSeed() => _seed;

    public void SetRangeInt(int min, int max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max for integer range.");
        _rangeInt = (min, max);
    }

    public void SetRangeFloat(float min, float max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max for float range.");
        _rangeFloat = (min, max);
    }

    public int GetRandomInt()
    {
        return _random.Next(_rangeInt.Min, _rangeInt.Max + 1); // Inclusive
    }

    public float GetRandomFloat()
    {
        return (float)_random.NextDouble() * (_rangeFloat.Max - _rangeFloat.Min) + _rangeFloat.Min; // Inclusive
    }

    public IEnumerable<int> GenerateSequenceOfInts(int count)
    {
        if (count <= 0) throw new ArgumentException("Count must be positive.");
        for (int i = 0; i < count; i++)
        {
            Log($"Generated int: {GetRandomInt()}");
        }
        return Enumerable.Range(_rangeInt.Min, _rangeInt.Max - _rangeInt.Min + 1).OrderBy(x => _random.Next());
    }

    public IEnumerable<float> GenerateSequenceOfFloats(int count)
    {
        if (count <= 0) throw new ArgumentException("Count must be positive.");
        for (int i = 0; i < count; i++)
        {
            Log($"Generated float: {GetRandomFloat()}");
        }
        return Enumerable.Range(0, (int)((_rangeFloat.Max - _rangeFloat.Min) * count)).Select(x => (float)x / count).OrderBy(x => _random.NextDouble());
    }

    public void Reset()
    {
        _random = new Random(_seed);
    }

    private void Log(string message)
    {
        Console.WriteLine(message);
    }

    public override string ToString()
    {
        return $"CustomRandomGenerator with seed: {_seed}, Int Range: ({_rangeInt.Min}, {_rangeInt.Max}), Float Range: ({_rangeFloat.Min}, {_rangeFloat.Max})";
    }

    public object Clone()
    {
        return MemberwiseClone();
    }
}
```

