enum LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
};

enum LogFormat {
    JSON,
    CSV,
    PLAIN_TEXT
};

struct LoggerConfig {
    std::string format;
    std::string level;
    std::string filePath;
};

class LogOutputHandler {
public:
    virtual ~LogOutputHandler() {}
    virtual void log(const std::string& message) = 0;
    virtual void initialize(const std::string& config) = 0;
};

class Logger {
private:
    std::vector<std::shared_ptr<LogOutputHandler>> handlers;

public:
    static Logger* getInstance() {
        static Logger instance;
        return &instance;
    }

    void initialize(const LoggerConfig& config) {
        std::string formatName = config.format;
        std::string levelName = config.level;

        LogLevel level = getLogLevel(levelName);
        LogFormat format = getLogFormat(formatName);

        if (level == LogLevel::UNKNOWN || format == LogFormat::UNKNOWN) {
            logError("Invalid configuration");
            return;
        }

        loadHandlers(format, level, config.filePath);
    }

    void log(const std::string& message, LogLevel level) {
        for (auto& handler : handlers) {
            if (handler->canLog(level)) {
                handler->log(message);
            }
        }
    }

private:
    Logger() {}

    LogLevel getLogLevel(const std::string& levelName) {
        if (levelName == "DEBUG") return DEBUG;
        if (levelName == "INFO") return INFO;
        if (levelName == "WARNING") return WARNING;
        if (levelName == "ERROR") return ERROR;
        if (levelName == "CRITICAL") return CRITICAL;
        return LogLevel::UNKNOWN;
    }

    LogFormat getLogFormat(const std::string& formatName) {
        if (formatName == "JSON") return JSON;
        if (formatName == "CSV") return CSV;
        if (formatName == "PLAIN_TEXT") return PLAIN_TEXT;
