<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIP, $lastModifiedTimestamp) {
    // Validate input parameters
    if (!is_numeric($clinicId)) {
        error_log('Invalid clinic ID provided.');
        return false;
    }

    if (!filter_var($lastModifiedIP, FILTER_VALIDATE_IP)) {
        error_log('Invalid IP address provided.');
        return false;
    }

    if ($lastModifiedTimestamp === null || !strtotime($lastModifiedTimestamp)) {
        error_log('Invalid timestamp provided.');
        return false;
    }

    $maxRetries = 3;
    for ($retryCount = 0; $retryCount < $maxRetries; $retryCount++) {
        try {
            // Establish database connection
            $dbHost = 'localhost';
            $dbName = 'clinic_db';
            $dbUser = 'user';
            $dbPass = 'password';

            $pdo = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUser, $dbPass);
            $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

            // Fetch current status and IP
            $stmtFetch = $pdo->prepare('SELECT `status`, `last_modified_ip` FROM clinics WHERE `id` = :clinicId FOR UPDATE');
            $stmtFetch->execute([' clinicId' => $clinicId]);
            $result = $stmtFetch->fetch(PDO::FETCH_ASSOC);

            if (!$result) {
                error_log("Clinic ID $clinicId does not exist.");
                return false;
            }

            // Check for stale data
            $currentStatus = $result['status'];
            $currentIP = $result['last_modified_ip'];

            if ($newStatus === $currentStatus && $lastModifiedIP === $currentIP) {
                error_log("No changes needed for clinic ID $clinicId.");
                return true;
            }

            // Update clinic status
            $stmtUpdate = $pdo->prepare('UPDATE clinics SET `status` = :newStatus, `last_modified_ip` = :lastModifiedIP, `last_modified_timestamp` = NOW() WHERE `id` = :clinicId');
            $stmtUpdate->execute(['newStatus' => $newStatus, 'lastModifiedIP' => $lastModifiedIP, 'clinicId' => $clinicId]);

            // Check if update was successful
            if ($stmtUpdate->rowCount() > 0) {
                return true;
            } else {
                error_log("Failed to update clinic ID $clinicId.");
                return false;
            }
        } catch (PDOException $e) {
            // Handle exceptions and retry logic
            error_log("Database error: " . $e->getMessage());
            if ($retryCount < $maxRetries - 1) {
                sleep(1); // Wait before retrying
            } else {
                return false;
            }
        }
    }

    return false; // Maximum retries reached without success
}

// Example usage:
$clinicId = 123;
$newStatus = 'open';
$lastModifiedIP = '192.168.1.1';
$lastModifiedTimestamp = date('Y-m-d H:i:s');

if (updateClinicStatus($clinicId, $newStatus, $lastModifiedIP, $lastModifiedTimestamp)) {
    echo "Clinic status updated successfully.";
} else {
    echo "Failed to update clinic status.";
}

