import asyncio
import aiohttp
from collections import defaultdict

async def fetch_data(url, session):
    try:
        async with session.get(url) as response:
            return await response.text()
    except (aiohttp.ClientError, asyncio.TimeoutError) as e:
        print(f"Failed to fetch data from {url}: {e}")
        return None

async def process_data(data, processor):
    if not data_processor:
        return data
    try:
        return processor(data)
    except Exception as e:
        print(f"Data processing failed: {e}")
        return None

async def fetchAndProcessData(api_urls, data_processor=None, timeout=10, max_concurrent_requests=5):
    async with aiohttp.ClientSession() as session:
        tasks = []
        results = defaultdict(list)

        for url in api_urls:
            task = asyncio.create_task(fetch_data(url, session))
            tasks.append(task)

        while tasks:
            done, pending = await asyncio.wait(tasks, timeout=timeout, return_when=asyncio.FIRST_COMPLETED)
            for future in done:
                raw_data = await future
                if raw_data is not None:
                    processed_data = await process_data(raw_data, data_processor)
                    if processed_data is not None:
                        results[url].append(processed_data)

            tasks = list(pending)
            if len(tasks) > max_concurrent_requests:
                await asyncio.sleep(1)

        return dict(results)

# Example usage
async def custom_data_processor(data):
    # Implement your data processing logic here
    return data

api_urls = ['http://example.com/api1', 'http://example.com/api2']
result = await fetchAndProcessData(api_urls, custom_data_processor, timeout=5, max_concurrent_requests=3)
print(result)
