using System;
using System.Net.Http;
using System.Xml.XPath;

public class XmlParser
{
    private readonly HttpClient _httpClient;
    private readonly MemoryCache _cache;

    public XmlParser(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = new MemoryCache(new MemoryCacheOptions());
    }

    /// <summary>
    /// Parses an XML document using XPath and retrieves the first element matching a given name.
    /// </summary>
    /// <param name="url">The URL of the XML document to fetch.</param>
    /// <param name="elementName">The name of the element to retrieve.</param>
    /// <returns>The first element matching the specified name.</returns>
    /// <exception cref="InvalidOperationException">Thrown if no element is found or multiple elements are found with the given name.</exception>
    public XPathNavigator GetFirstElement(string url, string elementName)
    {
        if (string.IsNullOrEmpty(url) || string.IsNullOrEmpty(elementName))
            throw new ArgumentException("URL and elementName must not be null or empty.");

        try
        {
            var xml = _cache.GetOrAdd(url, key =>
            {
                using (var response = _httpClient.GetAsync(key).Result)
                {
                    response.EnsureSuccessStatusCode();
                    return response.Content.ReadAsStringAsync().Result;
                }
            });

            using (var nav = new XPathDocument(xml.CreateNavigator()).CreateNavigator())
            {
                var selectSingleNode = nav.SelectSingleNode($"//{elementName}");
                if (selectSingleNode == null)
                    throw new InvalidOperationException("No element found with the specified name.");

                var selectNodes = nav.Select($"(//{elementName})[position() > 1]");
                if (selectNodes.MoveNext())
                    throw new InvalidOperationException("Multiple elements found with the specified name.");

                return selectSingleNode;
            }
        }
        catch (HttpRequestException ex)
        {
            throw new Exception("Error fetching XML document from the API.", ex);
        }
    }
}
