from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

class SensorDataHandler:
    def __init__(self, db_config):
        self.db_pool = psycopg2.pool.SimpleConnectionPool(1, 20, **db_config)
        self.session = self.create_session()

    @staticmethod
    def create_session():
        session = requests.Session()
        retries = Retry(total=5,
                       backoff_factor=1,
                       status_forcelist=[ 500, 502, 503, 504 ])
        session.mount('https://', HTTPAdapter(max_retries=retries))
        return session

    def fetch_data(self, url):
        try:
            response = self.session.get(url)
            response.raise_for_status()
            return response.json() if response.headers['Content-Type'] == 'application/json' else response.content
        except requests.RequestException as e:
            print(f"Failed to fetch data from {url}: {e}")
            return None

    def validate_data(self, schema, data):
        # Placeholder for actual validation logic using a library like jsonschema
        if isinstance(data, dict):
            try:
                jsonschema.validate(instance=data, schema=schema)
                return True
            except jsonschema.exceptions.ValidationError as err:
                print(f"Data validation failed: {err}")
                return False

    def insert_data(self, data):
        conn = self.db_pool.getconn()
        try:
            with conn.cursor() as cursor:
                # Placeholder for actual SQL insertion logic
                cursor.execute("INSERT INTO sensor_data (data) VALUES (%s)", (json.dumps(data),))
                conn.commit()
        except psycopg2.DatabaseError as e:
            print(f"Failed to insert data into database: {e}")
        finally:
            self.db_pool.putconn(conn)

    def serialize_data(self, data, format='json'):
        if format == 'json':
            return json.dumps(data)
        elif format == 'binary':
            return json.dumps(data).encode('utf-8')
        else:
            raise ValueError("Unsupported format")

