```java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.function.BiFunction;
import java.util.logging.Logger;

public class StateReducer {

    private static final Logger logger = Logger.getLogger(StateReducer.class.getName());

    public static <T> CompletableFuture<List<T>> loadMoSTStateAsync(String[] filePaths, T initialState, BiFunction<T, String, T> processor) {
        List<CompletableFuture<T>> futures = new ArrayList<>();
        for (String path : filePaths) {
            CompletableFuture<T> future = CompletableFuture.supplyAsync(() -> processFile(path, initialState, processor));
            future.exceptionally(ex -> {
                logger.severe("Error processing file " + path + ": " + ex.getMessage());
                return null;
            });
            futures.add(future);
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                              .thenApply(v -> futures.stream()
                                                     .map(CompletableFuture::join)
                                                     .filter(result -> result != null)
                                                     .reduce(initialState, processor));
    }

    private static <T> T processFile(String path, T initialState, BiFunction<T, String, T> processor) {
        try {
            String content = new String(Files.readAllBytes(Paths.get(path)));
            return processor.apply(initialState, content);
        } catch (IOException e) {
            logger.severe("Error reading file " + path + ": " + e.getMessage());
            return initialState;
        }
    }

    public static void main(String[] args) {
        // Sample usage
        String[] filePaths = {"file1.txt", "file2.txt", "file3.txt"};
        Integer initialState = 0;
        BiFunction<Integer, String, Integer> processor = (acc, content) -> acc + content.length();

        CompletableFuture<List<Integer>> resultFuture = loadMoSTStateAsync(filePaths, initialState, processor);

        resultFuture.thenAccept(result -> {
            logger.info("Reduced result: " + result);
        }).exceptionally(ex -> {
            logger.severe("Error in reduction process: " + ex.getMessage());
            return null;
        });
    }
}
