// Main Java class for the Pokemon Evolution Service
public class PokemonEvolutionService {

    private final PokemonApiClient apiClient;
    private final Cache<String, PokemonDetails> pokemonCache;

    public PokemonEvolutionService(PokemonApiClient apiClient, Cache<String, PokemonDetails> pokemonCache) {
        this.apiClient = apiClient;
        this.pokemonCache = pokemonCache;
    }

    public PokemonDetails getPokemonDetails(int pokemonId) throws Exception {
        String cacheKey = "pokemon:" + pokemonId;
        // Check if data is already cached
        PokemonDetails cachedDetails = pokemonCache.getIfPresent(cacheKey);
        if (cachedDetails != null) {
            return cachedDetails;
        }

        // Fetch data from the external API
        PokemonDetails details = apiClient.fetchPokemonDetails(pokemonId);

        // Cache the fetched data
        pokemonCache.put(cacheKey, details);

        return details;
    }
}

// Interface for interacting with the external REST API
interface PokemonApiClient {
    PokemonDetails fetchPokemonDetails(int pokemonId) throws Exception;
}

// Class to represent detailed information about a Pokemon
class PokemonDetails {
    private String name;
    private List<String> types;
    private List<PokemonEvolutionStage> evolutionStages;
    private List<String> weaknesses;

    // Getters and setters for the fields
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public List<String> getTypes() { return types; }
    public void setTypes(List<String> types) { this.types = types; }

    public List<PokemonEvolutionStage> getEvolutionStages() { return evolutionStages; }
    public void setEvolutionStages(List<PokemonEvolutionStage> evolutionStages) { this.evolutionStages = evolutionStages; }

    public List<String> getWeaknesses() { return weaknesses; }
    public void setWeaknesses(List<String> weaknesses) { this.weaknesses = weaknesses; }
}

// Class to represent a stage in the Pokemon's evolutionary chain
class PokemonEvolutionStage {
    private String name;
    private int level;
    private List<String> types;

    // Getters and setters for the fields
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public int getLevel() { return level; }
    public void setLevel(int level) { this.level = level; }

    public List<String> getTypes() { return types; }
    public void setTypes(List<String> types) { this.types = types; }
}
