package microservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.client.RestTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.concurrent.ConcurrentHashMap;
import javax.sql.DataSource;
import io.r2dbc.spi.ConnectionFactory;
import org.springframework.data.mongodb.core.ReactiveMongoOperations;
import org.springframework.data.mongodb.core.SimpleReactiveMongoDatabaseFactory;
import org.springframework.data.relational.core.dialect.DatabaseDialect;
import org.springframework.data.relational.core.dialect.MySqlDialect;
import org.springframework.data.relational.core.dialect.PostgresDialect;
import io.r2dbc.mysql.MySqlConnectionConfiguration;
import io.r2dbc.postgresql.PostgresqlConnectionConfiguration;
import org.springframework.data.r2dbc.connectionfactory.R2dbcConnectionFactory;

@SpringBootApplication
public class DynamicDeserializationService {

    private final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        SpringApplication.run(DynamicDeserializationService.class, args);
    }

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }

    @Bean
    public ObjectMapper objectMapper() {
        return new ObjectMapper();
    }

    @Bean
    public DataSource dataSource(Environment env) {
        String url = env.getProperty("DATABASE_URL");
        // Add more database support as needed
        throw new UnsupportedOperationException("Unsupported database type");
    }

    @Bean
    public ConnectionFactory connectionFactory(DataSource dataSource, Environment env) {
        String dbType = env.getProperty("DATABASE_TYPE").toLowerCase();
        switch (dbType) {
            case "mysql":
                return R2dbcConnectionFactory.from(ConnectionConfiguration.builder()
                    .url(dataSource.getUrl())
                    .username(dataSource.getUsername())
                    .password(dataSource.getPassword())
                    .build());
            case "postgresql":
                return R2dbcConnectionFactory.from(PostgresqlConnectionConfiguration.builder()
                    .host(dataSource.getURL().replace("jdbc:postgresql://", ""))
                    .port(5432)
                    .database(dataSource.getCatalog())
                    .username(dataSource.getUsername())
                    .password(dataSource.getPassword())
                    .build());
            case "mongodb":
                return ConnectionFactory.create(MongoClientSettings.builder()
                    .applyToClusterSettings(builder -> builder.hosts(
                        Arrays.asList(new ServerAddress(dataSource.getHost(), dataSource.getPort()))))
                    .build());
            default:
                throw new UnsupportedOperationException("Unsupported database type");
        }
    }

    @Bean
    public ReactiveMongoOperations mongoTemplate(ConnectionFactory connectionFactory) {
        return new SimpleReactiveMongoDatabaseFactory(connectionFactory);
    }

    // Add more beans for additional database support and caching strategies

    @PreDestroy
    public void cleanup() {
        // Clean up resources
    }
}
