```javascript
// Node.js Real-Time Chat Application

const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const jwt = require('jsonwebtoken');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

app.use(bodyParser.json());

// Dummy database for storing users and messages
let users = [];
let messages = [];

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (token == null) return res.sendStatus(401);

  jwt.verify(token, 'secret_key', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Endpoint for user login
app.post('/login', authenticateToken, (req, res) => {
  const { username, password } = req.body;

  // Validate credentials and issue JWT token if successful
  // For simplicity, we assume valid credentials here

  const token = jwt.sign({ username }, 'secret_key');
  res.json({ status: 'success', message: 'Login successful', token });
});

// Endpoint for sending messages
app.post('/send-message', authenticateToken, (req, res) => {
  const { message, recipient } = req.body;

  // Validate message content

  const newMessage = {
    id: Date.now(),
    sender: req.user.username,
    recipient,
    message,
    timestamp: new Date()
  };

  messages.push(newMessage);

  // Broadcast message to the recipient
  io.to(recipient).emit('new-message', newMessage);

  res.json({ status: 'success', message: 'Message sent' });
});

// Socket.IO connection handling
io.on('connection', (socket) => {
  console.log('A user connected');

  socket.on('disconnect', () => {
    console.log('User disconnected');
  });

  // Handle receiving messages
  socket.on('receive-message', (message) => {
    socket.broadcast.emit('new-message', message);
  });
});

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

This code provides a basic structure for a real-time chat application in Node.js. It includes user authentication using JWT tokens, handling of messages through Socket.IO, and separation of concerns into distinct modules. You can further expand this code by adding message content filtering, push notification systems, and other features as per your requirements.

