// Java code for managing inventory system

public class InventorySystem {
    private Warehouse[] warehouses;

    public InventorySystem(int numWarehouses) {
        this.warehouses = new Warehouse[numWarehouses];
        for (int i = 0; i < numWarehouses; i++) {
            warehouses[i] = new Warehouse();
        }
    }

    public void updateStock(String productId, int quantity) {
        synchronized (warehouses) {
            for (Warehouse warehouse : warehouses) {
                if (warehouse.hasProduct(productId)) {
                    warehouse.updateStock(productId, quantity);
                    break;
                }
            }
        }
    }
}

class Warehouse {
    private Map<String, Integer> productStock;

    public Warehouse() {
        this.productStock = new ConcurrentHashMap<>();
    }

    public boolean hasProduct(String productId) {
        return productStock.containsKey(productId);
    }

    public void updateStock(String productId, int quantity) {
        productStock.put(productId, productStock.getOrDefault(productId, 0) + quantity);
    }
}

// PHP code for updating user password with DAO class

class UserDAO {
    private PDO $pdo;

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    public function updatePassword(int $userId, string $newPassword): bool {
        if ($this->isStrongPassword($newPassword)) {
            try {
                $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id");
                $stmt->execute(['password' => password_hash($newPassword, PASSWORD_DEFAULT), 'id' => $userId]);
                return true;
            } catch (PDOException $e) {
                error_log("Error updating user password: " . $e->getMessage());
                return false;
            }
        }
        return false;
    }

    private function isStrongPassword(string $password): bool {
        // Implement strong password criteria
        return strlen($password) >= 8 && preg_match('/[A-Za-z]/', $password) && preg_match('/\d/', $password);
    }
}

// C code for AES-256-GCM initialization with PBKDF2

#include <openssl/evp.h>
#include <openssl/rand.h>

int init_aes_256_gcm(unsigned char *key, unsigned char *salt, const char *password) {
    EVP_KDF_CTX *ctx = EVP_KDF_CTX_new_id(EVP_KDF_ID_PBKDF2);
    if (!ctx) return 0;

    if (!EVP_KDF_set_ctx_params(ctx, 
        EVP_KDF_PARAM_SALT, salt, sizeof(salt),
        EVP_KDF_PARAM_ITER, 10000,
        EVP_KDF_PARAM_PASSLEN, strlen(password),
        EVP_KDF_PARAM_ALGID, EVP_sha256(),
        NULL)) {
        EVP_KDF_CTX_free(ctx);
        return 0;
    }

    if (!EVP_KDF_derive(ctx, key, sizeof(key), (unsigned char *)password)) {
        EVP_KDF_CTX_free(ctx);
        return 0;
    }

    EVP_KDF_CTX_free(ctx);

    // Initialize AES-256-GCM cipher
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return 0;

    if (1 != EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return 0;
    }

    // Additional initialization steps for AES-256-GCM

    return 1;
}
