import java.util.*;
import java.util.concurrent.*;

public class DistributedCache {
    private final Map<String, CacheEntry> cache;
    private final ExecutorService executor;
    private final ExternalDataSource dataSource;

    public DistributedCache(int capacity) {
        this.cache = new ConcurrentHashMap<>(capacity);
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.dataSource = new ExternalDataSource();
    }

    public void put(String key, Object value) {
        cache.put(key, new CacheEntry(value, System.currentTimeMillis()));
        executor.submit(() -> dataSource.updateMetadata(key));
    }

    public Object get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && entry.isValid()) {
            return entry.getValue();
        }
        return null;
    }

    public void remove(String key) {
        cache.remove(key);
        executor.submit(() -> dataSource.deleteMetadata(key));
    }

    private class CacheEntry {
        private final Object value;
        private final long timestamp;
        private static final long TTL = 60000; // Time-To-Live in milliseconds

        public CacheEntry(Object value, long timestamp) {
            this.value = value;
            this.timestamp = timestamp;
        }

        public Object getValue() {
            return value;
        }

        public boolean isValid() {
            return System.currentTimeMillis() - timestamp < TTL;
        }
    }

    private class ExternalDataSource {
        public void updateMetadata(String key) {
            // Code to fetch metadata and update it in the data source
        }

        public void deleteMetadata(String key) {
            // Code to delete metadata from the data source
        }
    }
}
