      'https://provider3.com/api'
    ];

    for (const api of providerAPIs) {
      try {
        const response = await fetch(api, { method: 'GET' });
        if (!response.ok) throw new Error('Network response was not ok');
        return await response.json();
      } catch (error) {
        // Handle error and retry with exponential backoff
      }
    }

    throw new Error('Failed to fetch payment details from all providers');
  }

  async run() {
    const startTime = Date.now();
    await Promise.all(this.workerPool);
    const endTime = Date.now();
    console.log(`Processing completed in ${endTime - startTime}ms`);
  }
}

// Usage
const paymentIDs = Array.from({ length: 10000 }, (_, i) => `paymentID${i}`);
const processor = new PaymentProcessor(paymentIDs, 50);
processor.run().catch(console.error);
