    setup_rate_limiting();

    // Create background thread for dynamic function behavior updates
    pthread_t bg_thread;
    pthread_create(&bg_thread, NULL, bg_thread_function, NULL);

    // Monitor health and scale worker threads dynamically
    start_health_monitoring();
    start_worker_scaling();

    // Start processing TIFF images
    const char* image_dir = "/path/to/images";
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir(image_dir)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strstr(ent->d_name, ".tiff")) {
                char filepath[256];
                snprintf(filepath, sizeof(filepath), "%s/%s", image_dir, ent->d_name);
                parse_tiff_image(filepath);
            }
        }
        closedir(dir);
    }

    // Clean up resources
    cleanup();

    return 0;
}
