              prec_distr(prec_min, prec_max), wind_distr(wind_min, wind_max) {}

        ~WeatherRandomGenerator() noexcept {}

        double generate_temperature() {
            std::lock_guard<std::mutex> lock(mutex_);
            return temp_distr(gen);
        }

        double generate_precipitation() {
            std::lock_guard<std::mutex> lock(mutex_);
            return prec_distr(gen);
        }

        double generate_wind_speed() {
            std::lock_guard<std::mutex> lock(mutex_);
            return wind_distr(gen);
        }

    private:
        std::mt19937 gen;
        std::uniform_real_distribution<> temp_distr;
        std::uniform_real_distribution<> prec_distr;
        std::uniform_real_distribution<> wind_distr;
        std::mutex mutex_;
    };
