using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public class MonitoringDashboardHandler
{
    private readonly DashboardService _dashboardService;
    private readonly AlertingService _alertingService;
    private static readonly Dictionary<string, List<string>> LogFilePatterns = new Dictionary<string, List<string>>
    {
        { "Device1", new List<string> { @"\bSensorA:\d+\.\d+\s\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}", @"\bSensorB:\d+\.\d+\s\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}" } },
        { "Device2", new List<string> { @"\bSensorC:\d+\.\d+\s\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}", @"\bSensorD:\d+\.\d+\s\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}" } }
    };

    public MonitoringDashboardHandler(DashboardService dashboardService, AlertingService alertingService)
    {
        _dashboardService = dashboardService;
        _alertingService = alertingService;
    }

    public async Task<HttpResponseMessage> HandlePostRequestAsync(string deviceIdentifier, string sensorName, double sensorData, DateTime timestamp)
    {
        if (string.IsNullOrEmpty(deviceIdentifier) || string.IsNullOrEmpty(sensorName))
        {
            return new HttpResponseMessage(HttpStatusCode.BadRequest)
            {
                Content = new StringContent("Device identifier and sensor name cannot be empty.")
            };
        }

        if (!LogFilePatterns.ContainsKey(deviceIdentifier))
        {
            return new HttpResponseMessage(HttpStatusCode.NotFound)
            {
                Content = new StringContent("Invalid device identifier.")
            };
        }

        var patterns = LogFilePatterns[deviceIdentifier];
        var logFiles = Directory.GetFiles($"logs/{deviceIdentifier}", "*.log");

        using (var readerPool = ReaderPool.Get(logFiles))
        {
            var relevantData = await Task.WhenAll(logFiles.Select(async file =>
            {
                using (var reader = await readerPool.GetReaderAsync(file))
                {
                    return await FilterAndAggregateDataAsync(reader, patterns, sensorName, timestamp);
                }
            }));

            var aggregatedData = relevantData.Where(d => d != null).SelectMany(d => d).ToList();
            if (!aggregatedData.Any())
            {
                return new HttpResponseMessage(HttpStatusCode.NoContent)
                {
                    Content = new StringContent("No data found for the given criteria.")
                };
            }

            await _dashboardService.UpdateDashboardAsync(deviceIdentifier, sensorName, aggregatedData);
        }

        bool shouldRefreshDashboard;
        try
        {
            shouldRefreshDashboard = await _alertingService.CheckForAlertsAsync(deviceIdentifier, sensorName, aggregatedData);
        }
        catch (Exception ex)
        {
            return new HttpResponseMessage(HttpStatusCode.InternalServerError)
            {
                Content = new StringContent($"Error checking for alerts: {ex.Message}")
            };
        }

        var responseMessage = new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("Data added successfully.")
        };

        if (shouldRefreshDashboard)
        {
            responseMessage.Headers.Add("X-Refresh-Dashboard", "true");
        }

        return responseMessage;
    }

    private static async Task<List<(string SensorName, double Data)>> FilterAndAggregateDataAsync(TextReader reader, List<string> patterns, string sensorName, DateTime timestamp)
    {
        var filteredData = new List<(string SensorName, double Data)>();

        while (!reader.EndOfStream)
        {
            string line;
            try
            {
                line = await reader.ReadLineAsync();
            }
            catch (IOException ex)
            {
                Console.WriteLine($"Error reading log file: {ex.Message}");
                continue;
            }

            if (patterns.Any(pattern => Regex.IsMatch(line, pattern)))
            {
                var match = patterns.First(m => m.Contains(sensorName)).Match(line);
                if (match.Success && DateTime.ParseExact(match.Groups[2].Value, "yyyy-MM-dd HH:mm:ss", null) <= timestamp)
                {
                    double data;
                    if (double.TryParse(match.Groups[1].Value, out data))
                    {
                        filteredData.Add((sensorName, data));
                    }
                }
            }
        }

        return filteredData;
    }
}

public class ReaderPool
{
    private readonly List<StreamReader> _readers = new List<StreamReader>();
    private int _currentReaderIndex;

    public static async Task<ReaderPool> Get(string[] files)
    {
        var readerPool = new ReaderPool();

        foreach (var file in files)
        {
            using (var stream = File.OpenRead(file))
            {
                readerPool._readers.Add(new StreamReader(stream));
            }
        }

        return readerPool;
    }

    public async Task<StreamReader> GetReaderAsync(string file)
    {
        if (_currentReaderIndex >= _readers.Count)
        {
            _currentReaderIndex = 0;
        }

        var stream = await File.OpenRead(file);
        return new StreamReader(stream);
    }
}
