import hashlib

def calculate_file_md5(file_path, chunk_size=8192, progress_callback=None, storage_backend=None):
    try:
        with open(file_path, 'rb') as file:
            hasher = hashlib.md5()
            total_bytes_read = 0
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
                total_bytes_read += len(data)

                if progress_callback:
                    progress_callback(total_bytes_read, file_path)

            md5_hash = hasher.hexdigest()

            if storage_backend:
                storage_backend.store_hash(md5_hash, file_path)

            return md5_hash
    except FileNotFoundError:
        print(f"Error: File '{file_path}' not found.")
    except PermissionError:
        print(f"Error: Permission denied for accessing the file '{file_path}'.")
    except Exception as e:
        print(f"An error occurred while reading the file: {e}")

# Example usage of calculate_file_md5
class MockStorageBackend:
    def store_hash(self, md5_hash, file_path):
        print(f"Storing hash {md5_hash} for file {file_path}")

storage_backend = MockStorageBackend()
progress_callback = lambda bytes_read, file_path: print(f"Read {bytes_read}/{os.path.getsize(file_path)} bytes")
calculate_file_md5('example.txt', storage_backend=storage_backend, progress_callback=progress_callback)
