```java
import java.io.*;
import java.util.function.Predicate;
import java.util.stream.Stream;

interface StorageBackend {
    void saveData(String data) throws IOException;
}

class FileStorageBackend implements StorageBackend {
    private final String output_path;

    public FileStorageBackend(String output_path) {
        this.output_path = output_path;
    }

    @Override
    public void saveData(String data) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(output_path, true))) {
            writer.write(data);
        }
    }
}

class Main {
    public static void filterCsvFile(String file_path, Predicate<String[]> filter_condition, String output_path,
                                      StorageBackend storage_backend) {
        try (BufferedReader reader = new BufferedReader(new FileReader(file_path));
             Stream<String> lines = reader.lines()) {

            lines.filter(line -> {
                String[] parts = line.split(",");
                return filter_condition.test(parts);
            }).map(line -> line + "\n").forEach(storage_backend::saveData);

        } catch (IOException e) {
            System.err.println("Error processing file: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Example usage
        String input_path = "input.csv";
        Predicate<String[]> condition = parts -> Integer.parseInt(parts[1]) > 50; // Filter rows where second column > 50
        String output_path = "filtered_output.csv";

        StorageBackend storage_backend = new FileStorageBackend(output_path);

        filterCsvFile(input_path, condition, output_path, storage_backend);
    }
}
