import io.opentracing.Tracer;
import io.opentracing.util.GlobalTracer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class TracingConfig {

    @Value("${tracing.backend}")
    private String backend;

    @Value("${tracing.samplingRate}")
    private double samplingRate;

    @Value("${tracing.serviceName}")
    private String serviceName;

    @Value("${tracing.fallbackLog}")
    private String fallbackLog;

    @Bean
    public Tracer tracer() {
        try {
            // Load the appropriate tracing backend driver dynamically based on configuration
            Class<?> backendClass = Class.forName("com.example.tracing." + backend + "Tracer");
            return (Tracer) backendClass.getDeclaredConstructor(String.class, double.class)
                    .newInstance(serviceName, samplingRate);
        } catch (Exception e) {
            // Log the error and continue with a no-op tracer
            e.printStackTrace();
            return new NoOpTracer(fallbackLog);
        }
    }

    public static class NoOpTracer implements Tracer {
        private final String fallbackLog;

        public NoOpTracer(String fallbackLog) {
            this.fallbackLog = fallbackLog;
        }

        @Override
        public Span activeSpan() {
            return NoOpSpan.INSTANCE;
        }

        @Override
        public Scope activateSpan(Span span) {
            return NoOpScope.INSTANCE;
        }

        // Implement other Tracer methods to no-op

        private static class NoOpSpan implements Span {
            public static final NoOpSpan INSTANCE = new NoOpSpan();

            @Override
            public Span setOperationName(String operationName) {
                return this;
            }

            @Override
            public Span addTag(String key, String value) {
                return this;
            }

            // Implement other Span methods to no-op

            @Override
