public class JwtService {

    private static final String SECRET_KEY_ALIAS = "your-secret-key-alias";
    private static final AWSKMS kmsClient = AWSKMSClientBuilder.defaultClient();

    public String generateJwtToken(String username) {
        byte[] secretKeyBytes = kmsClient.getSecretValue(SECRET_KEY_ALIAS).getPlaintext();
        return Jwts.builder()
                .setSubject(username)
                .signWith(SignatureAlgorithm.HS256, secretKeyBytes)
                .compact();
    }

    public Claims validateJwtToken(String token) {
        byte[] secretKeyBytes = kmsClient.getSecretValue(SECRET_KEY_ALIAS).getPlaintext();
        return Jwts.parser()
                .setSigningKey(secretKeyBytes)
                .parseClaimsJws(token)
                .getBody();
    }
}
