import java.io.IOException;
import java.lang.reflect.Constructor;
import java.net.URI;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DynamicNestedDeserializer {
    private final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService cacheCleanupService = Executors.newScheduledThreadPool(1);

    public DynamicNestedDeserializer() {
        // Schedule cache cleanup every hour
        cacheCleanupService.scheduleAtFixedRate(this::cleanupCache, 0, 1, TimeUnit.HOURS);
    }

    public <T> T deserialize(byte[] byteArray) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray))) {
            return deserializeObject(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            throw new DeserializationException("Error during deserialization", e);
        }
    }

    private <T> T deserializeObject(Object obj) throws IOException, ClassNotFoundException {
        if (obj instanceof byte[]) {
            try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream((byte[]) obj))) {
                return deserializeObject(ois.readObject());
            } catch (IOException | ClassNotFoundException e) {
                throw new DeserializationException("Error during nested deserialization", e);
            }
        } else {
            Class<?> clazz = loadClass(obj.getClass().getName());
            try {
                Constructor<?> constructor = clazz.getDeclaredConstructor();
                constructor.setAccessible(true);
                return (T) constructor.newInstance();
            } catch (Exception e) {
                throw new DeserializationException("Error during object creation", e);
            }
        }
    }

    private Class<?> loadClass(String className) throws ClassNotFoundException {
        if (!classCache.containsKey(className)) {
            try {
                URI uri = new URI("https://api.example.com/classes/" + className);
                String response = HttpClient.newHttpClient().send(HttpRequest.newBuilder()
                        .uri(uri)
                        .GET()
                        .build(), HttpResponse.BodyHandlers.ofString()).body();
                Class<?> clazz = Class.forName(response);
                classCache.put(className, clazz);
            } catch (Exception e) {
                throw new DeserializationException("Error during class loading from API", e);
            }
        }
        return classCache.get(className);
    }

    private void cleanupCache() {
        // Implement LRU cache cleanup logic here
    }

    public static class DeserializationException extends RuntimeException {
        public DeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
