// Constants for error messages
const ERROR_DB_CONNECTION = 'Failed to connect to the database.';
const ERROR_UPDATE_FAILED = 'Update failed.';
const ERROR_RATE_LIMITED = 'Rate limit exceeded.';
const ERROR_INVALID_INPUT = 'Invalid input provided.';

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip, $is_delete) {
    // Database connection details
    $db_host = 'your_db_host';
    $db_user = 'your_db_user';
    $db_password = 'your_db_password';
    $db_name = 'your_db_name';

    // Rate limiting parameters
    $redis_host = 'your_redis_host';
    $redis_port = 6379;
    $rate_limit_key = "update_rate_limit_{$last_modified_ip}";
    $rate_limit_interval = 60; // seconds

    // Connect to the database
    try {
        $pdo = new PDO("mysql:host=$db_host;dbname=$db_name", $db_user, $db_password);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Connect to Redis for rate limiting
        $redis = new Redis();
        $redis->connect($redis_host, $redis_port);

        // Check rate limit
        if ($redis->get($rate_limit_key)) {
            $last_update_time = $redis->get($rate_limit_key);
            if (time() - $last_update_time < $rate_limit_interval) {
                return ERROR_RATE_LIMITED;
            }
        }

        // Prepare and execute the update statement
        $sql = "START TRANSACTION";
        $pdo->exec($sql);

        $stmt = $pdo->prepare("UPDATE clinics SET status = :new_status, last_modified_date = NOW(), last_modified_ip = :last_modified_ip");
        if ($is_delete) {
            $stmt->bindParam(':new_status', $deleted_at, PDO::PARAM_STR);
            $deleted_at = date('Y-m-d H:i:s');
        } else {
            $stmt->bindParam(':new_status', $new_status, PDO::PARAM_STR);
        }
        $stmt->bindParam(':last_modified_ip', $last_modified_ip, PDO::PARAM_STR);

        if (!$stmt->execute()) {
            throw new Exception(ERROR_UPDATE_FAILED);
        }

        // Commit the transaction
        $pdo->exec("COMMIT");

        // Log successful update to ELK Stack (pseudo-code)
        logToELKStack($clinic_id, $new_status, $last_modified_ip, $is_delete);

        return 'Update successful.';
    } catch (PDOException $e) {
        // Log database connection or execution errors to ELK Stack
        logToELKStack(null, null, null, null, ERROR_DB_CONNECTION . ': ' . $e->getMessage());
        return ERROR_UPDATE_FAILED;
    } catch (Exception $e) {
        // Log other exceptions to ELK Stack
        logToELKStack($clinic_id, null, null, null, $e->getMessage());
        return ERROR_UPDATE_FAILED;
    } finally {
        if (isset($pdo)) {
            $pdo = null; // Close database connection
        }
        $redis->close(); // Close Redis connection
    }
}

