import asyncio
import aiohttp
from typing import Any, Type

class FileMetadataExtractor:
    def __init__(self, storage_service_url: str):
        self.storage_service_url = storage_service_url
        self.cache = {}

    async def fetch_file_metadata(self, file_path: str, target_class: Type) -> Any:
        try:
            if file_path in self.cache:
                return self.cache[file_path]

            async with aiohttp.ClientSession() as session:
                async with session.get(f"{self.storage_service_url}/file/schema/{file_path}") as response:
                    schema = await response.json()
                    if schema['format'] != target_class.FILE_FORMAT:
                        raise ValueError(f"Invalid file format for {file_path}")

                async with session.get(f"{self.storage_service_url}/file/metadata/{file_path}") as response:
                    metadata_raw = await response.read()
                    metadata = target_class.from_bytes(metadata_raw)

            self.cache[file_path] = metadata
            return metadata

        except Exception as e:
            print(f"Error fetching file metadata for {file_path}: {e}")
            raise

