const express = require('express');
const axios = require('axios');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

// Database configuration for caching
const pool = new Pool({
  user: 'your_db_user',
  host: 'your_db_host',
  database: 'your_db_name',
  password: 'your_db_password',
  port: your_db_port,
});

const primaryWeatherApiUrl = 'https://api.weatherapi.com/v1';
const fallbackWeatherApiUrl = 'https://api.fallbackweatherapi.com/v1';

async function fetchWeatherData(lat, lon) {
  try {
    const response = await axios.get(`${primaryWeatherApiUrl}/current.json?key=your_api_key&q=${lat},${lon}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching data from primary API:', error);
    try {
      const fallbackResponse = await axios.get(`${fallbackWeatherApiUrl}/current.json?key=your_fallback_api_key&q=${lat},${lon}`);
      return fallbackResponse.data;
    } catch (fallbackError) {
      console.error('Error fetching data from fallback API:', fallbackError);
      throw new Error('Failed to fetch weather data');
    }
  }
}

app.get('/weather', async (req, res) => {
  const { lat, lon } = req.query;

  if (!lat || !lon) {
    return res.status(400).json({ error: 'Latitude and longitude are required' });
  }

  try {
    const weatherData = await fetchWeatherData(lat, lon);
    res.json(weatherData);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
