#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, const char *logFilePath) {
    if (maxStructures > MAX_STRUCTURES || listSize == NULL || crcList == NULL || logFilePath == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    time_t start_time = time(NULL);
    *crcList = malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crcList == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    int uniqueTags[1000] = {0};
    int uniqueRNTIs[1000] = {0};
    size_t count = 0;

    srand(time(NULL));
    while (count < maxStructures) {
        int tag = rand() % 1000;
        int rnti = rand() % 1000;

        if (!uniqueTags[tag] && !uniqueRNTIs[rnti]) {
            uniqueTags[tag] = 1;
            uniqueRNTIs[rnti] = 1;

            (*crcList)[count].RX_UE_INFORMATION_TAG = tag;
            (*crcList)[count].RNTI = rnti;
            (*crcList)[count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

            count++;
        }
    }

    *listSize = count;
    time_t end_time = time(NULL);
    fprintf(stderr, "Memory allocation took %ld seconds\n", (end_time - start_time));

    return 0;
}
