using System;
using System.Data;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;
using log4net;

public class DataSender
{
    private static readonly ILog log = LogManager.GetLogger(typeof(DataSender));

    public async Task<DataTableReader> SendDataAsync(byte[] data, string connectionString)
    {
        var compressedData = CompressData(data);
        var memoryMappedFile = CreateMemoryMappedFile(compressedData);
        var transmissionTime = await TransmitDataAsync(memoryMappedFile, connectionString);

        // Simulate query execution
        var queryExecutionTime = TimeSpan.FromSeconds(2);
        log.Info($"Query Execution Time: {queryExecutionTime}");

        // Return a mock DataTableReader for demonstration purposes
        return new MockDataTableReader();
    }

    private byte[] CompressData(byte[] data)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress))
            {
                gzipStream.Write(data, 0, data.Length);
            }
            return memoryStream.ToArray();
        }
    }

    private MemoryMappedFile CreateMemoryMappedFile(byte[] compressedData)
    {
        var tempFileName = Path.GetTempFileName();
        File.WriteAllBytes(tempFileName, compressedData);

        return MemoryMappedFile.CreateFromFile(
            tempFileName,
            FileMode.Open,
            null,
            compressedData.Length,
            MemoryMappedFileAccess.ReadWrite);
    }

    private async Task<TimeSpan> TransmitDataAsync(MemoryMappedFile memoryMappedFile, string connectionString)
    {
        var timer = Stopwatch.StartNew();

        using (var socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp))
        {
            await socket.ConnectAsync(new IPEndPoint(IPAddress.Parse("127.0.0.1"), 12345));

            using (var memoryMappedViewAccessor = memoryMappedFile.CreateViewAccessor())
            {
                var buffer = new byte[memoryMappedViewAccessor.Capacity];
                memoryMappedViewAccessor.ReadArray(0, buffer, 0, buffer.Length);

                await socket.SendAsync(new ArraySegment<byte>(buffer), SocketFlags.None);
            }

            await socket.ShutdownAsync(SocketShutdown.Both);
        }

        timer.Stop();
        log.Info($"Transmission Time: {timer.Elapsed}");

        return timer.Elapsed;
    }
}

