#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    char uuid[37]; // UUID format: 8-4-4-4-12 characters
    int key;
    double timestamp;
    char* tags; // Pointer to dynamically allocated string for tags
} UserProfile;

UserProfile* create_user_profile(const char* uuid, int key, double timestamp, const char* tags) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    strcpy(profile->uuid, uuid);
    profile->key = key;
    profile->timestamp = timestamp;
    profile->tags = strdup(tags);
    return profile;
}

void free_user_profile(UserProfile* profile) {
    free(profile->tags);
    free(profile);
}

void update_user_profile_in_db(UserProfile* profile, const char* server_address, int server_port) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "http://%s:%d/api/update", server_address, server_port);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        cJSON* root = cJSON_CreateObject();
        cJSON_AddStringToObject(root, "uuid", profile->uuid);
        cJSON_AddNumberToObject(root, "key", profile->key);
        cJSON_AddNumberToObject(root, "timestamp", profile->timestamp);
        cJSON_AddStringToObject(root, "tags", profile->tags);

        char* json_data = cJSON_Print(root);
        cJSON_Delete(root);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        free(json_data);

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

void* update_user_profile_task(void* arg) {
    UserProfile* profile = (UserProfile*)arg;
    const char* server_address = getenv("DB_SERVER_ADDRESS");
    int server_port = atoi(getenv("DB_SERVER_PORT"));

    if(server_address && server_port > 0)
        update_user_profile_in_db(profile, server_address, server_port);

    free_user_profile(profile);
    pthread_exit(NULL);
}

int main() {
    UserProfile* profile = create_user_profile("12345678-1234-1234-1234-1234567890ab", 123, 1633024800.0, "tag1,tag2");

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, update_user_profile_task, profile);
    pthread_join(thread_id, NULL);

    return 0;
}
