<?php

class PasswordManager {
    private $redis;
    private $rateLimiter;

    public function __construct($redisHost, $redisPort) {
        $this->redis = new Redis();
        $this->redis->connect($redisHost, $redisPort);
        $this->rateLimiter = new RateLimiter($this->redis);
    }

    public function hashPassword($password, $algorithm = PASSWORD_DEFAULT, $options = []) {
        if (!$this->rateLimiter->allowRequest()) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        $salt = $this->generateSalt();
        $hash = password_hash($password . $salt, $algorithm, $options);

        if ($hash === false) {
            throw new Exception("Failed to hash password.");
        }

        $this->storeHash($hash, $salt);
        return $hash;
    }

    public function verifyPassword($password, $storedHash) {
        if (!$this->rateLimiter->allowRequest()) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        return password_verify($password, $storedHash);
    }

    private function generateSalt() {
        // Implement salt generation logic here
    }

    private function storeHash($hash, $salt) {
        $this->redis->set($hash, $salt);
    }
}

class RateLimiter {
    private $redis;
    private $tenantId;
    private $maxRequests;
    private $timeWindow;

    public function __construct(Redis $redis, $tenantId = null, $maxRequests = 50, $timeWindow = 60) {
        $this->redis = $redis;
        $this->tenantId = $tenantId ?: $_SERVER['REMOTE_ADDR'];
        $this->maxRequests = $maxRequests;
        $this->timeWindow = $timeWindow;
    }

    public function allowRequest() {
        $currentRequests = (int)$this->redis->get("rate_limit:{$this->tenantId}:requests");
        if ($currentRequests >= $this->maxRequests) {
            return false;
        }
        $this->redis->incr("rate_limit:{$this->tenantId}:requests");
        $this->redis->expire("rate_limit:{$this->tenantId}:requests", $this->timeWindow);
        return true;
    }

    public function resetRequestCount() {
        $this->redis->del("rate_limit:{$this->tenantId}:requests");
    }
}

// Usage example
$passwordManager = new PasswordManager('localhost', 6379);
$hashedPassword = $passwordManager->hashPassword('user_password');
$isValid = $passwordManager->verifyPassword('user_password', $hashedPassword);
?>
