#include <limits>
#include <memory> // For std::unique_ptr

// Function signature
void insertStringWithLimit(std::forward_list<std::string>& list, const std::string& searchString, const std::string& insertionString, size_t maxInsertions, size_t maxLength);

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    std::string searchStr = "banana";
    std::string insertStr = "orange";
    size_t maxIns = 1;
    size_t strLenLimit = 5;

    insertStringWithLimit(myList, searchStr, insertStr, maxIns, strLenLimit);

    for (const auto& item : myList) {
        std::cout << item << " ";
    }

    return 0;
}

// Function definition
void insertStringWithLimit(std::forward_list<std::string>& list, const std::string& searchString, const std::string& insertionString, size_t maxInsertions, size_t maxLength) {
    auto it = list.before_begin();
    auto currentIt = list.begin();

    while (maxInsertions > 0 && currentIt != list.end()) {
        if (*currentIt == searchString) {
            *it = insertionString;
            maxInsertions--;
        }
        ++it;
        ++currentIt;
    }

    // If search string not found within the allowed insertions, append at the end
    if (maxInsertions > 0) {
        list.push_front(insertionString);
    }

    // Truncate strings to the maximum length limit
    for (auto& item : list) {
        if (item.length() > maxLength) {
            item.resize(maxLength);
        }
    }
}
