```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_REQUESTS 50000
#define MAX_THREADS 100

typedef struct {
    int id;
    char *data_source;
} Request;

Request request_queue[MAX_REQUESTS];
int front = 0, rear = -1;
sem_t empty, full;
pthread_mutex_t queue_lock;

void* worker(void *arg) {
    while (1) {
        sem_wait(&full);
        pthread_mutex_lock(&queue_lock);

        int id = request_queue[front].id;
        char *data_source = request_queue[front].data_source;
        front = (front + 1) % MAX_REQUESTS;

        pthread_mutex_unlock(&queue_lock);
        sem_post(&empty);

        // Process the request
        printf("Thread %d processing data from %s\n", id, data_source);
    }
}

void enqueue_request(int id, char *data_source) {
    sem_wait(&empty);
    pthread_mutex_lock(&queue_lock);

    rear = (rear + 1) % MAX_REQUESTS;
    request_queue[rear].id = id;
    strcpy(request_queue[rear].data_source, data_source);

    pthread_mutex_unlock(&queue_lock);
    sem_post(&full);
}

int main() {
    pthread_t threads[MAX_THREADS];
    int i;

    // Initialize semaphore and mutex
    sem_init(&empty, 0, MAX_REQUESTS);
    sem_init(&full, 0, 0);
    pthread_mutex_init(&queue_lock, NULL);

    // Create worker threads
    for (i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }

    // Enqueue requests
    enqueue_request(1, "MySQL");
    enqueue_request(2, "PostgreSQL");
    enqueue_request(3, "MongoDB");
    enqueue_request(4, "Redis");
    enqueue_request(5, "Elasticsearch");

    // Wait for all threads to finish
    for (i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    sem_destroy(&empty);
    sem_destroy(&full);
    pthread_mutex_destroy(&queue_lock);

    return 0;
}
```

This code snippet provides a basic structure for creating a thread pool to handle multiple requests concurrently. It uses semaphore synchronization and mutex locking to manage the request queue, ensuring that only one thread can access the queue at a time. Each worker thread waits for tasks from the queue and processes them. The `enqueue_request` function is used to add new tasks to the queue.

