// Define a template class for data processing algorithms
template <typename T>
class DataProcessor {
public:
    virtual ~DataProcessor() {}
    virtual void process(const T& data) = 0;
};

// Example processor: JSONFilter
class JSONFilter : public DataProcessor<JSONData> {
public:
    void process(const JSONData& data) override {
        // Implement JSON-specific filtering logic here
        std::cout << "Processing JSON data" << std::endl;
    }
};

// Example processor: Aggregator
class Aggregator : public DataProcessor<CSVData> {
public:
    void process(const CSVData& data) override {
        // Implement aggregation logic here
        std::cout << "Aggregating CSV data" << std::endl;
    }
};

// Define a class for the streaming data library
class StreamingDataLibrary {
private:
    std::vector<std::shared_ptr<DataProcessor<JSONData>>> jsonProcessors;
    std::vector<std::shared_ptr<DataProcessor<XMLData>>> xmlProcessors;
    std::vector<std::shared_ptr<DataProcessor<CSVData>>> csvProcessors;

public:
    void addJSONProcessor(std::shared_ptr<DataProcessor<JSONData>> processor) {
        jsonProcessors.push_back(processor);
    }

    void addXMLProcessor(std::shared_ptr<DataProcessor<XMLData>> processor) {
        xmlProcessors.push_back(processor);
    }

    void addCSVProcessor(std::shared_ptr<DataProcessor<CSVData>> processor) {
        csvProcessors.push_back(processor);
    }

    template <typename T>
    void processBatch(const std::vector<T>& batch) {
        for (const auto& item : batch) {
            processItem(item);
        }
    }

private:
    template <typename T>
    void processItem(const T& data) {
        if constexpr (std::is_same_v<T, JSONData>) {
            for (auto& processor : jsonProcessors) {
                processor->process(data);
            }
        } else if constexpr (std::is_same_v<T, XMLData>) {
            for (auto& processor : xmlProcessors) {
                processor->process(data);
            }
        } else if constexpr (std::is_same_v<T, CSVData>) {
            for (auto& processor : csvProcessors) {
                processor->process(data);
            }
        }
    }
};

int main() {
    StreamingDataLibrary library;

    // Add processors
    library.addJSONProcessor(std::make_shared<JSONFilter>());
    library.addCSVProcessor(std::make_shared<Aggregator>());

    // Simulate data streaming
    std::vector<JSONData> jsonDataBatch = { /* Populate with JSON data */ };
    std::vector<CSVData> csvDataBatch = { /* Populate with CSV data */ };

    library.processBatch(jsonDataBatch);
    library.processBatch(csvDataBatch);

    return 0;
}
```

