using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/[controller]")]
public class UserProfileController : ControllerBase
{
    private readonly UserProfileContext _context;
    private readonly ICacheService _cacheService;
    private readonly ISocialMediaClient _socialMediaClient;

    public UserProfileController(UserProfileContext context, ICacheService cacheService, ISocialMediaClient socialMediaClient)
    {
        _context = context;
        _cacheService = cacheService;
        _socialMediaClient = socialMediaClient;
    }

    [HttpPatch("{userId}")]
    public async Task<IActionResult> UpdateUserProfile(int userId, [FromBody] UserProfileUpdateDto updateData)
    {
        try
        {
            // Retrieve user profile from cache or database
            var userProfile = await GetCachedOrDatabaseProfile(userId);

            if (userProfile == null)
                return NotFound($"User with ID {userId} not found.");

            // Apply updates to the user profile
            UserProfileExtensions.ApplyUpdate(userProfile, updateData);

            // Save changes to the database
            _context.UserProfiles.Update(userProfile);
            await _context.SaveChangesAsync();

            // Invalidate cache for this user
            await _cacheService.InvalidateCache($"user:{userId}");

            // Synchronize with external social media platform
            var syncResult = await _socialMediaClient.SyncUserProfile(userId, userProfile);

            return Ok(new { message = "Profile updated successfully", syncResult });
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    [HttpPost("{userId}/sync")]
    public async Task<IActionResult> SyncUserProfileToSocialMedia(int userId)
    {
        try
        {
            // Retrieve user profile from cache or database
            var userProfile = await GetCachedOrDatabaseProfile(userId);

            if (userProfile == null)
                return NotFound($"User with ID {userId} not found.");

            // Synchronize with external social media platform
            var syncResult = await _socialMediaClient.SyncUserProfile(userId, userProfile);

            return Ok(new { message = "Social media profile synchronized successfully", syncResult });
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    private async Task<UserProfile> GetCachedOrDatabaseProfile(int userId)
    {
        // Try to retrieve from cache
        var userProfile = await _cacheService.GetFromCacheAsync<UserProfile>($"user:{userId}");

        if (userProfile == null)
        {
            // If not in cache, fetch from database and store in cache
            userProfile = await _context.UserProfiles.FindAsync(userId);
            await _cacheService.SetToCacheAsync($"user:{userId}", userProfile, TimeSpan.FromMinutes(10));
        }

        return userProfile;
    }
}

public class UserProfileExtensions
{
    public static void ApplyUpdate(UserProfile profile, UserProfileUpdateDto updateData)
    {
        if (updateData.Name != null) profile.Name = updateData.Name;
        if (updateData.Email != null) profile.Email = updateData.Email;
        if (updateData.Address != null) profile.Address = updateData.Address;
        if (updateData.PhoneNumbers != null)
        {
            profile.PhoneNumbers.Clear();
            foreach (var phoneNumber in updateData.PhoneNumbers)
                profile.PhoneNumbers.Add(phoneNumber);
        }
    }
}

public class UserProfileUpdateDto
{
    public string Name { get; set; }
    public string Email { get; set; }
    public AddressDto Address { get; set; }
    public List<string> PhoneNumbers { get; set; }
}

public class AddressDto
{
    public string Street { get; set; }
    public string City { get; set; }
    public string State { get; set; }
    public string ZipCode { get; set; }
}
