    Task InvalidateCache(string key);
}

public class MemoryCacheService : ICacheService
{
    private readonly ConcurrentDictionary<string, (object Value, DateTimeOffset Expiration)> _cache = new ConcurrentDictionary<string, (object, DateTimeOffset)>();

    public async Task<T> GetFromCacheAsync<T>(string key)
    {
        if (_cache.TryGetValue(key, out var cacheItem))
        {
            if (cacheItem.Expiration > DateTimeOffset.UtcNow)
                return (T)cacheItem.Value;
        }

        return default;
    }

    public async Task SetToCacheAsync<T>(string key, T value, TimeSpan expiration)
    {
        _cache.TryAdd(key, (value, DateTimeOffset.UtcNow + expiration));
    }

    public async Task InvalidateCache(string key)
    {
        _cache.TryRemove(key, out _);
    }
}

