    public LargeFileProcessor(int numThreads, int cacheSize) {
        this.executor = Executors.newFixedThreadPool(numThreads);
        this.cache = new LinkedHashMap<String, String>(cacheSize, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry eldest) {
                return size() > cacheSize;
            }
        };
        this.reportingAPI = new ExternalReportingAPI();
    }

    public void processDirectory(String directoryPath) throws IOException {
        Path startDir = Paths.get(directoryPath);
        Files.walkFileTree(startDir, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                executor.submit(() -> processFile(file));
                return FileVisitResult.CONTINUE;
            }
        });
    }

    private void processFile(Path file) {
        String content = readFileContent(file);
        if (content != null) {
            String summary = generateSummary(content);
            cache.put(file.toString(), summary);
            uploadReport(summary, file.getFileName().toString());
        }
    }

    private String readFileContent(Path file) {
        try {
            return new String(Files.readAllBytes(file), detectEncoding(file));
        } catch (IOException e) {
            logError("Failed to read file " + file, e);
            return null;
        }
    }

