        Pattern pattern = Pattern.compile("(error|warning)", Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(content);
        while (matcher.find()) {
            summary.append(matcher.group()).append("\n");
        }
        return summary.toString();
    }

    private void uploadReport(String report, String fileName) {
        for (int retryCount = 0; retryCount < maxRetries; retryCount++) {
            try {
                reportingAPI.upload(report, fileName);
                break;
            } catch (Exception e) {
                logError("Failed to upload report for " + fileName, e);
                if (!shouldRetry(e)) break;
                sleepForBackoff(retryCount);
            }
        }
    }

