using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using MySql.Data.MySqlClient;
using Npgsql;
using MongoDB.Driver;

public class DecryptAndUpload
{
    public async Task DecryptFile(string encryptedFilePath, string key, string iv, string outputFilePath)
    {
        ValidateKeyAndIV(key, iv);
        using (var decryptedFileStream = new FileStream(outputFilePath, FileMode.Create))
        {
            using (var aesCryptoServiceProvider = Aes.Create())
            {
                aesCryptoServiceProvider.Key = Convert.FromBase64String(key);
                aesCryptoServiceProvider.IV = Convert.FromBase64String(iv);
                aesCryptoServiceProvider.Mode = CipherMode.CBC;
                aesCryptoServiceProvider.Padding = PaddingMode.PKCS7;

                using (var cryptoStream = new CryptoStream(decryptedFileStream, aesCryptoServiceProvider.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    await CopyFileAsync(encryptedFilePath, cryptoStream);
                }
            }
        }

        LogAction($"File decrypted and saved to {outputFilePath}");
    }

    private static void ValidateKeyAndIV(string key, string iv)
    {
        if (key.Length != 32 && key.Length != 48 && key.Length != 64)
            throw new ArgumentException("Invalid key length. It must be 256, 384, or 512 bits.");

        if (iv.Length != 16)
            throw new ArgumentException("Invalid IV length. It must be 128 bits.");
    }

    private static async Task CopyFileAsync(string sourceFilePath, Stream targetStream)
    {
        using (var fileStream = File.OpenRead(sourceFilePath))
        {
            var buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = await fileStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                await targetStream.WriteAsync(buffer, 0, bytesRead);
                LogAction($"Bytes read and written: {bytesRead}");
            }
        }
    }

    private static void LogAction(string message)
    {
        Console.WriteLine(message);
    }
}
