#include <chrono>
#include <cmath>
#include <openssl/sha.h>
#include <curl/curl.h>

class BloomFilter {
private:
    std::vector<bool> bits;
    size_t num_bits;
    size_t num_hashes;

public:
    BloomFilter(size_t num_bits, size_t num_hashes) : num_bits(num_bits), num_hashes(num_hashes), bits(num_bits, false) {}

    void add(const std::string& key) {
        for (size_t i = 0; i < num_hashes; ++i) {
            size_t index = hash(key, i) % num_bits;
            bits[index] = true;
        }
    }

    bool mightContain(const std::string& key) const {
        for (size_t i = 0; i < num_hashes; ++i) {
            size_t index = hash(key, i) % num_bits;
            if (!bits[index]) return false;
        }
        return true;
    }

private:
    size_t hash(const std::string& key, size_t seed) const {
        size_t hash = 5381;
        for (char c : key) {
            hash = ((hash << 5) + hash) + static_cast<size_t>(c) + seed;
        }
        return hash;
    }
};

class TransactionAnalyzer {
private:
    BloomFilter bloomFilter;
    std::mutex lock;
    std::condition_variable cv;
    bool done;
    double totalSuspiciousActivityTime;

public:
    TransactionAnalyzer(size_t num_bits, size_t num_hashes) : bloomFilter(num_bits, num_hashes), totalSuspiciousActivityTime(0.0), done(false) {}

    void initialize() {
        // Initialize the Bloom Filter
    }

    void addTransaction(const std::string& transactionId) {
        std::lock_guard<std::mutex> guard(lock);
        auto start = std::chrono::high_resolution_clock::now();
        if (bloomFilter.mightContain(transactionId)) {
            std::cout << "Suspicious activity detected: Duplicate transaction ID - " << transactionId << std::endl;
            auto end = std::chrono::high_resolution_clock::now();
            totalSuspiciousActivityTime += std::chrono::duration<double, std::milli>(end - start).count();
        }
    }

    void processTransactions(const std::string& filePath) {
        // Process transactions from the file
        std::ifstream file(filePath);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filePath << std::endl;
            return;
        }

        std::string transactionId;
        while (std::getline(file, transactionId)) {
            addTransaction(transactionId);
        }
    }

    void verifyTransactionsWithGateway(const std::vector<std::string>& transactions) {
        // Verify transactions with the external payment gateway API
        CURL *curl;
        CURLcode res;

        for (const auto& transaction : transactions) {
            curl = curl_easy_init();
            if(curl) {
                // Set up the request and handle errors
                std::lock_guard<std::mutex> guard(lock);
                auto start = std::chrono::high_resolution_clock::now();

                res = curl_easy_setopt(curl, CURLOPT_URL, "https://api.paymentgateway.com/verify");
                if(res != CURLE_OK) {
                    std::cerr << "curl_easy_setopt() failed: " << curl_easy_strerror(res) << std::endl;
                }

                // Add code to handle API response and retries

                auto end = std::chrono::high_resolution_clock::now();
                totalSuspiciousActivityTime += std::chrono::duration<double, std::milli>(end - start).count();

                curl_easy_cleanup(curl);
            }
        }
    }

    void run() {
        // Main loop to process transactions
        while (!done) {
            cv.wait(lock);
        }
        double averageTime = totalSuspiciousActivityTime / (cv.notify_count());
        std::cout << "Average suspicious activity check time: " << averageTime << " ms" << std::endl;
    }

    void stop() {
        done = true;
        cv.notify_all();
    }
};

int main(int argc, char* argv[]) {
    // Command-line interface for testing the utility
    TransactionAnalyzer analyzer(/* num_bits */, /* num_hashes */);
    analyzer.initialize();

    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <dataset_file_path> <payment_gateway_api_endpoint>" << std::endl;
        return 1;
    }

    std::string datasetFilePath = argv[1];
    std::string paymentGatewayApiEndpoint = argv[2];

    // Set up the payment gateway API endpoint
    // ...

    analyzer.processTransactions(datasetFilePath);

    // Start processing transactions in a separate thread
    std::thread processThread(&TransactionAnalyzer::run, &analyzer);
    // Simulate transaction verification with the payment gateway API
    std::vector<std::string> transactions = {"transaction1", "transaction2"};
    analyzer.verifyTransactionsWithGateway(transactions);

    // Stop the processing thread
    analyzer.stop();
    processThread.join();

    return 0;
}
