<?php

function generateRandomString($length, $charset) {
    if ($length <= 0 || empty($charset)) {
        throw new InvalidArgumentException("Invalid input");
    }

    $uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    $lowercase = 'abcdefghijklmnopqrstuvwxyz';
    $digits = '0123456789';
    $specialChars = '!@#$%^&*()_+-=[]{}|;:,.<>?';

    if (!preg_match('/[A-Z]/', $charset) ||
        !preg_match('/[a-z]/', $charset) ||
        !preg_match('/\d/', $charset) ||
        !preg_match('/[\W]/', $charset)) {
        throw new InvalidArgumentException("Character set must include at least one uppercase letter, one lowercase letter, one digit, and one special character.");
    }

    return substr(str_shuffle($uppercase . $lowercase . $digits . $specialChars), 0, $length);
}

function hashPassword($password, $algorithm = 'bcrypt', $rounds = 12) {
    if (!in_array($algorithm, ['bcrypt', 'sha256'])) {
        throw new InvalidArgumentException("Unsupported hash algorithm");
    }

    switch ($algorithm) {
        case 'bcrypt':
            return password_hash($password, PASSWORD_BCRYPT, ['cost' => $rounds]);
        case 'sha256':
            return hash('sha256', $password);
    }
}

