#include <iostream>
#include <thread>
#include <vector>
#include <fstream>
#include <string>
#include <openssl/sha.h>
#include <curl/curl.h>

// Function to calculate SHA-256 hash of a file
std::string calculateSHA256(const std::string& filename) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filename, std::ios::binary | std::ios::ate);
    if (file.is_open()) {
        size_t length = file.tellg();
        file.seekg(0, std::ios::beg);

        char buffer[1024 * 1024]; // 1MB chunk
        while (file.read(buffer, sizeof(buffer))) {
            SHA256_Update(&sha256, buffer, file.gcount());
        }
        size_t remaining = length % sizeof(buffer);
        if (remaining > 0) {
            SHA256_Update(&sha256, buffer, remaining);
        }

        file.close();
    } else {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return "";
    }

    SHA256_Final(hash, &sha256);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }
    return ss.str();
}

// Function to download a file from a remote URL
size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t realsize = size * nmemb;
    std::string& output = *(std::string*)userp;
    output.append((char*)contents, realsize);
    return realsize;
}

bool downloadFile(const std::string& url, const std::string& filename) {
    CURL* curl;
    CURLcode res;
    std::string readBuffer;

    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
            curl_easy_cleanup(curl);
            return false;
        }

        std::ofstream file(filename, std::ios::binary);
        if (file.is_open()) {
            file.write(readBuffer.c_str(), readBuffer.size());
            file.close();
        } else {
            std::cerr << "Failed to open file for writing: " << filename << std::endl;
            return false;
        }

        curl_easy_cleanup(curl);
    }
    return true;
}

