        std::cout << "Download successful." << std::endl;
        std::string sha256 = calculateSHA256(filename);
        std::cout << "SHA-256: " << sha256 << std::endl;
    } else {
        std::cerr << "Failed to download file." << std::endl;
    }

    return 0;
}
