const axios = require('axios');
const { Pool } = require('pg');
const EventEmitter = require('events');

class PaymentProcessor extends EventEmitter {
  constructor(paymentIds, providerConfig) {
    super();
    this.paymentIds = paymentIds;
    this.providerConfig = providerConfig;
    this.databasePool = new Pool({ connectionString: providerConfig.databaseUrl });
  }

  async processPayments() {
    const batchSize = Math.ceil(this.paymentIds.length / providerConfig.workerCount);
    for (let i = 0; i < this.paymentIds.length; i += batchSize) {
      const batch = this.paymentIds.slice(i, i + batchSize);
      await Promise.all(batch.map(paymentId => this.processPayment(paymentId)));
    }
  }

  async processPayment(paymentId) {
    try {
      const paymentDetails = await this.fetchPaymentDetails(paymentId);
      // Process payment details
      console.log(`Processed payment ${paymentId}`);
    } catch (error) {
      console.error(`Failed to process payment ${paymentId}:`, error);
    }
  }

  async fetchPaymentDetails(paymentId) {
    const provider = this.providerConfig.providers.find(p => p.paymentId === paymentId);
    if (!provider) throw new Error('Provider not found');

    const { url, headers } = provider.config;
    try {
      const response = await axios.get(url, { headers });
      // Validate and process response
      return response.data;
    } catch (error) {
      console.error(`Failed to fetch payment details for ${paymentId}:`, error);
      throw error;
    }
  }

  async close() {
    await this.databasePool.end();
  }
}

// Example usage
