  ],
  databaseUrl: 'postgresql://user:password@localhost/db'
});

paymentProcessor.on('error', error => {
  console.error('Error processing payments:', error);
});

paymentProcessor.processPayments().then(() => {
  paymentProcessor.close();
}).catch(error => {
  paymentProcessor.emit('error', error);
});
