```cpp
#include <forward_list>
#include <functional>
#include <thread>
#include <mutex>

class ThreadPool {
public:
    ThreadPool(size_t threads);
    ~ThreadPool();

    template<class F, class... Args>
    void enqueue(F&& f, Args&&... args);

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;

    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

ThreadPool::ThreadPool(size_t threads) : stop(false) {
    for(size_t i = 0; i < threads; ++i)
        workers.emplace_back([this] {
            for(;;) {
                std::function<void()> task;

                {
                    std::unique_lock<std::mutex> lock(this->queue_mutex);
                    this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                    if(this->stop && this->tasks.empty())
                        return;
                    task = std::move(this->tasks.front());
                    this->tasks.pop();
                }

                task();
            }
        });
}

ThreadPool::~ThreadPool() {
    {
        std::unique_lock<std::mutex> lock(queue_mutex);
        stop = true;
    }
    condition.notify_all();
    for(std::thread &worker: workers)
        worker.join();
}

template<class F, class... Args>
void ThreadPool::enqueue(F&& f, Args&&... args) {
    {
        std::unique_lock<std::mutex> lock(queue_mutex);

        // don't allow enqueueing after stopping the pool
        if(stop)
            throw std::runtime_error("enqueue on stopped ThreadPool");

        tasks.emplace([f, args...] { f(args...); });
    }
    condition.notify_one();
}

void insertAfterForwardList(std::forward_list<int>& list, int searchValue, int insertValue, bool async = false, ThreadPool* pool = nullptr) {
    auto it = std::find(list.begin(), list.end(), searchValue);
    if (it != list.end()) {
        list.insert_after(it, insertValue);
    } else {
        list.push_back(insertValue);
    }

    if (async && pool) {
        pool->enqueue([&list, insertValue]() {
            // Perform any additional processing here if needed
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Example task
        });
    }
}
```

