#include <forward_list>
#include <string>
#include <mutex>
#include <condition_variable>
#include <stdexcept>

// Function to safely insert a string into a forward list after the first occurrence of another string
void safeInsert(std::forward_list<std::string>& lst, const std::string& search, const std::string& insertion, int maxInsertions) {
    static std::mutex mtx;
    static std::condition_variable cv;

    // Lock the mutex to ensure thread-safe access to the list
    std::unique_lock<std::mutex> lock(mtx);

    // Search for the first occurrence of the search string and insert after it
    auto pos = lst.before_begin();
    int inserted = 0;
    while (pos != lst.end() && inserted < maxInsertions) {
        if (*pos == search) {
            ++pos; // Move to the next position to insert after the search string
            lst.insert_after(pos, insertion);
            ++inserted;
            break;
        }
        ++pos;
    }

    // If the search string was not found, insert at the end of the list
    if (pos == lst.end()) {
        lst.push_back(insertion);
    }

    // Notify any waiting threads that the list has been modified
    cv.notify_all();
}

// Function to truncate a string to a maximum length
std::string truncateString(const std::string& str) {
    return str.substr(0, 100);
}
```

