using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureMessageProcessor : IDisposable
{
    private readonly ConcurrentDictionary<string, byte[]> _decryptionCache = new ConcurrentDictionary<string, byte[]>();
    private readonly Dictionary<string, (byte[], byte[])> _keyIvPairs = new Dictionary<string, (byte[], byte[])>();
    private readonly ConcurrentDictionary<string, DateTime> _rateLimiters = new ConcurrentDictionary<string, DateTime>();
    private readonly ILogger _logger;
    private Timer _cacheCleanupTimer;

    public SecureMessageProcessor(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cacheCleanupTimer = new Timer(CleanupCache, null, TimeSpan.Zero, TimeSpan.FromMinutes(10)); // Every 10 minutes
    }

    public byte[] DecryptMessage(string base64EncryptedMessage, string keyBase64, string ivBase64)
    {
        var key = Convert.FromBase64String(keyBase64);
        var iv = Convert.FromBase64String(ivBase64);
        var cacheKey = $"{keyBase64}_{ivBase64}";

        if (!_rateLimiters.TryGetValue(base64EncryptedMessage, out var lastRequestTime) || DateTime.Now - lastRequestTime > TimeSpan.FromSeconds(1))
        {
            _rateLimiters[base64EncryptedMessage] = DateTime.Now;

            if (!_decryptionCache.ContainsKey(cacheKey))
            {
                try
                {
                    using (var ms = new MemoryStream(Convert.FromBase64String(base64EncryptedMessage)))
                    using (var cryptoProvider = new TripleDESCryptoServiceProvider { Key = key, IV = iv })
                    using (var decryptor = cryptoProvider.CreateDecryptor(key, iv))
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        var decryptedBytes = new byte[ms.Length];
                        int bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                        _decryptionCache.TryAdd(cacheKey, decryptedBytes);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Decryption failed.");
                    throw;
                }
            }

            return _decryptionCache[cacheKey];
        }

        _logger.LogWarning("Rate limit exceeded.");
        throw new InvalidOperationException("Too many requests per minute.");
    }

    public byte[] EncryptMessage(string message, string keyBase64, string ivBase64)
    {
        var key = Convert.FromBase64String(keyBase64);
        var iv = Convert.FromBase64String(ivBase64);

        using (var ms = new MemoryStream())
        using (var cryptoProvider = new TripleDESCryptoServiceProvider { Key = key, IV = iv })
        using (var encryptor = cryptoProvider.CreateEncryptor(key, iv))
        using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
        {
            var bytes = Encoding.UTF8.GetBytes(message);
            cs.Write(bytes, 0, bytes.Length);
        }

        return ms.ToArray();
    }

    public void Dispose()
    {
        _cacheCleanupTimer?.Change(Timeout.Infinite, Timeout.Infinite);
        _cacheCleanupTimer?.Dispose();
    }

    private void CleanupCache(object state)
    {
        var now = DateTime.Now;
        _decryptionCache.TryRemoveAll(kvp => now - kvp.Value.Value > TimeSpan.FromMinutes(5));
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
    void LogWarning(string message);
}
```

This code snippet provides a basic implementation of the `SecureMessageProcessor` class with thread-safe decryption, caching, logging, and rate-limiting. It uses Triple DES encryption by default but can be extended to support other algorithms as needed. The class also includes methods for encrypting messages for testing purposes and a mechanism for managing encryption and decryption sessions.

