using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly HttpClient _httpClient;
    private readonly JsonValidator _jsonValidator;
    private readonly Cache<string, bool> _configFileCache;
    private readonly RateLimiter _rateLimiter;
    private readonly QuotaManager _quotaManager;

    public WebsiteManager(HttpClient httpClient, JsonValidator jsonValidator)
    {
        _httpClient = httpClient;
        _jsonValidator = jsonValidator;
        _configFileCache = new Cache<string, bool>();
        _rateLimiter = new RateLimiter();
        _quotaManager = new QuotaManager();
    }

    public async Task ManageWebsiteLifecycle(string configFilePath, List<string> siteNames, HashSet<string> operations)
    {
        // Validate inputs
        if (!File.Exists(configFilePath))
        {
            Console.WriteLine("Error: Configuration file not found.");
            return;
        }

        foreach (var siteName in siteNames)
        {
            if (string.IsNullOrEmpty(siteName) || siteNames.Contains(siteName, StringComparer.OrdinalIgnoreCase))
            {
                Console.WriteLine($"Error: Invalid or duplicate site name '{siteName}'.");
                return;
            }
        }

        // Prioritize critical operations
        var criticalOperations = new HashSet<string> { "start", "stop" };
        foreach (var operation in operations)
        {
            if (criticalOperations.Contains(operation))
            {
                await PerformOperation(siteNames, operation);
            }
        }

        foreach (var operation in operations)
        {
            if (!criticalOperations.Contains(operation))
            {
                await PerformOperation(siteNames, operation);
            }
        }

        // Log actions
        Console.WriteLine("Website lifecycle management completed.");
    }

    private async Task PerformOperation(List<string> siteNames, string operation)
    {
        if (_rateLimiter.IsRateLimited())
        {
            Console.WriteLine("Rate limit exceeded. Please try again later.");
            return;
        }

        _quotaManager.CheckQuota();

        foreach (var siteName in siteNames)
        {
            var sitePath = Path.Combine(configFilePath, siteName);
            if (!_configFileCache.Get(sitePath, out bool configFileExists))
            {
                configFileExists = File.Exists(Path.Combine(sitePath, "web.config"));
                _configFileCache.Add(sitePath, configFileExists);
            }

            if (!configFileExists)
            {
                Console.WriteLine($"Error: Missing web.config file for site '{siteName}'.");
                continue;
            }

            // Perform operation using external API
            var url = $"https://api.example.com/{operation}/{siteName}";
            var response = await _httpClient.GetAsync(url);
            if (!response.IsSuccessStatusCode)
            {
                Console.WriteLine($"Error: Failed to {operation} site '{siteName}'.");
            }
        }
    }

    public static void Main(string[] args)
    {
        // Command-line interface (CLI) usage
        if (args.Length == 0)
        {
            ShowHelpMenu();
            return;
        }

        var configFilePath = args[0];
        var siteNames = new List<string>();
        var operations = new HashSet<string>();

        for (int i = 1; i < args.Length; i++)
        {
            if (args[i].StartsWith("-"))
            {
                switch (args[i])
                {
                    case "-add":
                        operations.Add("add");
                        break;
                    case "-remove":
                        operations.Add("remove");
                        break;
                    case "-start":
                        operations.Add("start");
                        break;
                    case "-stop":
                        operations.Add("stop");
                        break;
                    case "-restart":
                        operations.Add("restart");
                        break;
                    default:
                        ShowHelpMenu();
                        return;
                }
            }
            else
            {
                siteNames.Add(args[i]);
            }
        }

        var httpClient = new HttpClient();
        var jsonValidator = new JsonValidator();
        var websiteManager = new WebsiteManager(httpClient, jsonValidator);
        websiteManager.ManageWebsiteLifecycle(configFilePath, siteNames, operations).Wait();
    }

    private static void ShowHelpMenu()
    {
        Console.WriteLine("Usage: ManageWebsiteLifecycle <config_file_path> [-add|-remove|-start|-stop|-restart] [site_name...]");
        Console.WriteLine("Example: ManageWebsiteLifecycle config.json -start -stop site1 site2");
        Environment.Exit(0);
    }
}

public class Cache<TKey, TValue>
{
    private Dictionary<TKey, TValue> _cache;
    private int _capacity;

    public Cache(int capacity = 100)
    {
        _cache = new Dictionary<TKey, TValue>();
        _capacity = capacity;
    }

    public bool Get(TKey key, out TValue value)
    {
        return _cache.TryGetValue(key, out value);
    }

    public void Add(TKey key, TValue value)
    {
        if (_cache.Count >= _capacity)
        {
            var firstKey = _cache.Keys.GetEnumerator().Current;
            _cache.Remove(firstKey);
        }
        _cache.Add(key, value);
    }
}

public class RateLimiter
{
    private int _maxRequestsPerMinute;
    private DateTime _lastRequestTime;

    public RateLimiter(int maxRequestsPerMinute = 60)
    {
        _maxRequestsPerMinute = maxRequestsPerMinute;
        _lastRequestTime = DateTime.Now;
    }

    public bool IsRateLimited()
    {
        if ((DateTime.Now - _lastRequestTime).TotalMinutes >= 1)
        {
            _lastRequestTime = DateTime.Now;
            return false;
        }
        return true;
    }
}

public class QuotaManager
{
    private int _quota;
    private int _currentUsage;

    public QuotaManager(int quota = 1000)
    {
        _quota = quota;
        _currentUsage = 0;
    }

    public void CheckQuota()
    {
        if (_currentUsage >= _quota)
        {
            throw new InvalidOperationException("Quota exceeded. Please try again later.");
        }
        _currentUsage++;
    }
}

