    {
        using (var s3Client = new AmazonS3Client(Amazon.RegionEndpoint.USEast1)) // Change region as needed
        {
            var fileTransferUtility = new TransferUtility(s3Client);

            try
            {
                if (!File.Exists(filePath))
                {
                    throw new FileNotFoundException("The specified file does not exist.");
                }

                TransferUtilityUploadRequest uploadRequest =
                    new TransferUtilityUploadRequest()
                    {
                        BucketName = bucketName,
                        FilePath = filePath,
                        Key = Path.GetFileName(filePath),
                        Metadata = metadata
                    };

                // Start the asynchronous upload.
                var uploadTask = fileTransferUtility.UploadAsync(uploadRequest);
                uploadTask.Wait();

                Console.WriteLine("Upload completed.");
            }
            catch (Exception ex)
            {
                // Handle errors from external API or other exceptions here
                Console.Error.WriteLine($"Error uploading file: {ex.Message}");
            }
        }
    }

    public string CalculateSHA256Hash(string filePath)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            using (FileStream fs = File.OpenRead(filePath))
            {
                byte[] hashBytes = sha256.ComputeHash(fs);
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
            }
        }
    }

