int main(int argc, char* argv[]) {
    if (argc != 5) {
        std::cerr << "Usage: " << argv[0] << " <bucket-name> <access-key> <secret-key> <output-file>" << std::endl;
        return 1;
    }

    // Initialize AWS SDK
    Aws::SDKOptions options;
    Aws::InitAPI(options);

    std::string bucketName = argv[1];
    std::string accessKey = argv[2];
    std::string secretKey = argv[3];
    std::string outputFile = argv[4];

    Aws::Client::ClientConfiguration clientConfig;
    clientConfig.region = "us-west-2"; // Change to your desired region
    clientConfig.scheme = Aws::Http::Scheme::HTTPS;

    Aws::S3::S3Client s3Client(clientConfig, Aws::Auth::AWSCredentials(accessKey, secretKey));

    Aws::S3::Model::GetObjectRequest getObjectRequest;
    getObjectRequest.WithBucket(bucketName).WithKey("your-file.txt");

    Aws::S3::Model::GetObjectOutcome getObjectOutcome = s3Client.GetObject(getObjectRequest);
    if (!getObjectOutcome.IsSuccess()) {
        std::cerr << "Failed to download file from S3: " << getObjectOutcome.GetError().GetMessage() << std::endl;
        return 1;
    }

    Aws::OFStream localFile(outputFile, std::ios::out | std::ios::binary);
    if (!localFile) {
        std::cerr << "Failed to open output file: " << outputFile << std::endl;
        return 1;
    }

    localFile << getObjectOutcome.GetResult().GetBody().rdbuf();
    localFile.close();

    // Read the file and store lines in a vector
    std::ifstream file(outputFile);
    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }
    file.close();

    size_t numThreads = std::thread::hardware_concurrency();
    if (numThreads == 0) {
        numThreads = 4; // Default to 4 threads if hardware concurrency is not available
    }

    std::vector<std::thread> threads;
    size_t chunkSize = lines.size() / numThreads;
    for (size_t i = 0; i < numThreads; ++i) {
        size_t start = i * chunkSize;
        size_t end = (i == numThreads - 1) ? lines.size() : (start + chunkSize);
        threads.emplace_back(threadFunction, std::ref(lines), start, end);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    // Clean up AWS SDK
    Aws::ShutdownAPI(options);

    return 0;
}
