import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.util.Properties;

public class HybridAutomationTool {

    public static void main(String[] args) {
        Properties config = loadConfig("config.properties");

        String logFilePath = config.getProperty("logFilePath");
        String errorLogFilePath = config.getProperty("errorLogFilePath");
        String[] commands = {"command1", "command2"};

        try {
            deleteFileIfExists(logFilePath);
            deleteFileIfExists(errorLogFilePath);

            for (String command : commands) {
                Process process = Runtime.getRuntime().exec(command);
                readAndLogStream(process.getInputStream(), logFilePath, LocalDateTime.now());
                readAndLogStream(process.getErrorStream(), errorLogFilePath, LocalDateTime.now());

                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    logError(config.getProperty("errorLogFilePath"), "Command execution failed: " + command);
                    // Handle and log command execution errors here
                }
            }

        } catch (IOException | InterruptedException e) {
            logError(errorLogFilePath, "Exception occurred: " + e.getMessage());
            // Log exception and handle error gracefully
        }
    }

    private static Properties loadConfig(String filePath) {
        Properties config = new Properties();
        try (InputStream input = new FileInputStream(filePath)) {
            config.load(input);
        } catch (IOException ex) {
            System.out.println("Failed to load configuration file.");
            ex.printStackTrace();
        }
        return config;
    }

    private static void deleteFileIfExists(String filePath) {
        Path path = Path.of(filePath);
        if (Files.exists(path)) {
            try {
                Files.delete(path);
            } catch (IOException e) {
                System.out.println("Failed to delete file: " + filePath);
                e.printStackTrace();
            }
        }
    }

    private static void readAndLogStream(InputStream inputStream, String logFilePath, LocalDateTime timestamp) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        String line;
        while ((line = reader.readLine()) != null) {
            String formattedMessage = String.format("%s - %s", timestamp, line);
            Files.write(Path.of(logFilePath), formattedMessage.getBytes(), StandardOpenOption.APPEND);
        }
    }

    private static void logError(String errorLogFilePath, String message) {
        try (FileWriter writer = new FileWriter(errorLogFilePath, true)) {
            writer.append(message).append("\n");
        } catch (IOException e) {
            System.out.println("Failed to log error.");
            e.printStackTrace();
        }
    }
}
