const WebSocket = require('ws');
const crypto = require('crypto');

class FinancialApiService {
  async fetchTransactionAmount(id) {
    // Simulated financial API endpoint
    const response = await fetch(`https://api.example.com/transaction/${id}`);
    if (!response.ok) {
      throw new Error('Failed to fetch transaction amount');
    }
    return await response.json();
  }
}

class WebSocketStreamReducer {
  constructor(workerCount, apiService) {
    this.workerCount = workerCount;
    this.apiService = apiService;
    this.reductionPromise = null;
  }

  async reduceWebSocketData(webSocketUrl, contentTypeFilter, encryptionConfig) {
    if (this.reductionPromise) {
      throw new Error('Reduction already in progress');
    }

    const ws = new WebSocket(webSocketUrl);
    const workers = Array.from({ length: this.workerCount }, () => this.processWorker());
    let reductionValue = 0;
    let transactionIds = [];

    ws.on('message', async (data) => {
      if (contentTypeFilter.includes(data.contentType)) {
        try {
          const transactionId = data.transactionId;
          const transactionAmount = await this.apiService.fetchTransactionAmount(transactionId);
          transactionIds.push(transactionId);
          reductionValue += transactionAmount.amount;
        } catch (error) {
          console.error(`Failed to process message: ${error.message}`);
        }
      }
    });

    ws.on('close', () => {
      workers.forEach(worker => worker.resolve());
      this.reductionPromise = Promise.all(workers.map(w => w.promise)).then(() => reductionValue);
      this.closeConnection(ws, encryptionConfig, transactionIds);
    });

    return this.reductionPromise;
  }

  async processWorker() {
    const results = [];
    const promise = new Promise((resolve) => (this.resolve = resolve));
    while (true) {
      const result = await crypto.randomInt(10); // Simulate processing
      if (result === 0) break; // Exit condition for demonstration
      results.push(result);
    }
    return { promise, results };
  }

  async closeConnection(ws, encryptionConfig, transactionIds) {
    ws.close();
    try {
      const encryptedData = await this.encryptData(transactionIds, encryptionConfig);
      console.log('Encrypted Data:', encryptedData);
    } catch (error) {
      console.error(`Failed to encrypt data: ${error.message}`);
    }
  }

  async encryptData(data, config) {
    const { key, salt, iv } = config;
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), Buffer.from(iv));
    let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return encrypted;
  }
}

// Usage example
(async () => {
  const apiService = new FinancialApiService();
  const reducer = new WebSocketStreamReducer(5, apiService);
  const contentTypeFilter = ['financial_transaction'];
  const encryptionConfig = { key: 'secretkey', salt: 'saltvalue', iv: 'ivvalue' };

  try {
    const reductionValue = await reducer.reduceWebSocketData('wss://example.com/socket', contentTypeFilter, encryptionConfig);
    console.log('Total Reduction Value:', reductionValue);
  } catch (error) {
    console.error(`Error during reduction: ${error.message}`);
  }
})();
