public class CommandExecutor {

    private static final String CONFIG_FILE_PATH = "/path/to/config/file";
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        // Simulate loading commands from external configuration
        List<String> commands = loadCommandsFromConfig();

        for (String command : commands) {
            executeCommand(command, MAX_RETRIES);
        }
    }

    private static List<String> loadCommandsFromConfig() {
        // Placeholder for actual implementation
        return Arrays.asList("command1", "command2");
    }

    private static void executeCommand(String command, int retries) {
        boolean success = false;
        int retryCount = 0;

        while (!success && retryCount < retries) {
            try {
                Process process = Runtime.getRuntime().exec(command);
                readStreams(process.getInputStream(), process.getErrorStream());
                process.waitFor();
                if (process.exitValue() == 0) {
                    success = true;
                }
            } catch (IOException | InterruptedException e) {
                logError("Command execution failed", e);
                retryCount++;
            }

            if (!success && retryCount < retries) {
                long backoff = calculateBackoff(retryCount);
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    logError("Thread sleep interrupted", ie);
                }
            }
        }

        if (!success) {
            logError("Command execution failed after " + retries + " attempts", null);
        } else {
            logInfo("Command executed successfully: " + command);
        }
    }

    private static void readStreams(InputStream in, InputStream err) throws IOException {
        // Placeholder for reading and logging streams
    }

    private static long calculateBackoff(int retryCount) {
        return (long) Math.pow(2, retryCount) * 100; // Exponential backoff
    }

    private static void logInfo(String message) {
        System.out.println("INFO: " + message);
    }

    private static void logError(String message, Exception e) {
        if (e != null) {
            System.err.println("ERROR: " + message + " - " + e.getMessage());
        } else {
            System.err.println("ERROR: " + message);
        }
    }
}
