public class AvatarService {
    private final ConcurrentHashMap<String, CachedAvatar> avatarCache = new ConcurrentHashMap<>();
    private static final int MAX_DOWNLOAD_SIZE = 5 * 1024 * 1024; // 5 MB
    private static final int LOW_RESOLUTION = 32;
    private static final int MEDIUM_RESOLUTION = 64;
    private static final int HIGH_RESOLUTION = 128;

    public void updateAvatar(String userId, String avatarUrl) {
        try {
            CachedAvatar cachedAvatar = avatarCache.get(userId);
            if (cachedAvatar == null || !cachedAvatar.isUpToDate(avatarUrl)) {
                InputStream avatarStream = downloadAvatar(avatarUrl);
                if (avatarStream != null) {
                    byte[] avatarData = readAvatarBytes(avatarStream, MAX_DOWNLOAD_SIZE);
                    cachedAvatar = new CachedAvatar(userId, avatarUrl, avatarData, LOW_RESOLUTION);
                    avatarCache.put(userId, cachedAvatar);
                    updateProfile(userId, cachedAvatar.avatarData);
                }
            }
        } catch (Exception e) {
            handleException(e);
        }
    }

    private InputStream downloadAvatar(String avatarUrl) throws Exception {
        URL url = new URL(avatarUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        if (connection.getResponseCode() == HttpURLConnection.HTTP_OK) {
            return connection.getInputStream();
        } else {
            throw new Exception("Failed to download avatar: " + connection.getResponseMessage());
        }
    }

    private byte[] readAvatarBytes(InputStream inputStream, int maxSize) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        int nRead;
        byte[] data = new byte[16 * 1024];
        while ((nRead = inputStream.read(data, 0, data.length)) != -1 && buffer.size() < maxSize) {
            buffer.write(data, 0, nRead);
        }
        inputStream.close();
        return buffer.toByteArray();
    }

