    notEmpty.notify_all();

    // Join all worker threads
    for (auto& thread : workerThreads) {
        thread.join();
    }

    return 0;
}

void workerThread() {
    while (true) {
        std::string filePath;
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            notEmpty.wait(lock, []{ return !workQueue.empty() || stopProcessing; });
            if (stopProcessing && workQueue.empty()) {
                break;
            }
            filePath = workQueue.front();
            workQueue.pop();
        }

        try {
            processFile(filePath);
        } catch (const std::exception& e) {
