std::vector<char> decompressFile(const std::string& filePath) {
    std::ifstream inFile(filePath, std::ios::binary);
    if (!inFile) {
        throw std::runtime_error("Failed to open input file");
    }

    // Simulate decompression
    std::vector<char> inputData((std::istreambuf_iterator<char>(inFile)), std::istreambuf_iterator<char>());
    std::vector<char> decompressedData(inputData.size() * 2); // Overestimate size for decompression

    z_stream stream = {0};
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    inflateInit(&stream);
    stream.avail_in = inputData.size();
    stream.next_in = reinterpret_cast<Bytef*>(inputData.data());
    stream.avail_out = decompressedData.size();
    stream.next_out = reinterpret_cast<Bytef*>(decompressedData.data());

    if (inflate(&stream, Z_FINISH) != Z_STREAM_END) {
        throw std::runtime_error("Decompression failed");
    }

    decompressedData.resize(stream.total_out);
    inflateEnd(&stream);

    return decompressedData;
}

