#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    sem_t *sem;
    int initial_value;
    int timeout_ms;
} Semaphore;

Semaphore* create_semaphore(int initial_value, int timeout_ms) {
    Semaphore *s = malloc(sizeof(Semaphore));
    if (!s) {
        fprintf(stderr, "Error: Failed to allocate memory for semaphore.\n");
        return NULL;
    }

    s->sem = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, initial_value);
    if (s->sem == SEM_FAILED) {
        perror("Error: Failed to create semaphore.");
        free(s);
        return NULL;
    }

    s->initial_value = initial_value;
    s->timeout_ms = timeout_ms;
    return s;
}

void delete_semaphore(Semaphore *s) {
    if (s) {
        sem_close(s->sem);
        sem_unlink("/my_semaphore");
        free(s);
    }
}

int semaphore_acquire(Semaphore *s) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int ret = sem_timedwait(s->sem, &ts);
    if (ret == -1) {
        perror("Error: Failed to acquire semaphore.");
        return -1;
    }
    return 0;
}

int semaphore_release(Semaphore *s) {
    int ret = sem_post(s->sem);
    if (ret == -1) {
        perror("Error: Failed to release semaphore.");
        return -1;
    }
    return 0;
}
