```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Global variables
Record *records;
int record_count = 0;
int max_records = 1000;
pthread_mutex_t records_lock;

// Function to manage memory allocation and initialization for storing records of long-term offset values and associated integer keys
void initialize_records(int min_key, int max_key) {
    pthread_mutex_init(&records_lock, NULL);
    records = (Record *)malloc(max_records * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records with unique identifiers within the specified range
    for (int i = 0; i < max_records; i++) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].offset = rand();
    }
}

// Function to add a new record
void add_record(int key, long offset) {
    pthread_mutex_lock(&records_lock);
    if (record_count < max_records) {
        records[record_count].key = key;
        records[record_count].offset = offset;
        record_count++;
    } else {
        fprintf(stderr, "Record storage is full\n");
    }
    pthread_mutex_unlock(&records_lock);
}

// Function to retrieve a record
long get_offset(int key) {
    long offset = -1;
    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            offset = records[i].offset;
            break;
        }
    }
    pthread_mutex_unlock(&records_lock);
    return offset;
}

// Function to clean up and free allocated resources
void cleanup() {
    pthread_mutex_destroy(&records_lock);
    free(records);
}
```

This code block provides a basic implementation of a record management system with thread-safe operations for concurrent data updates and retrievals. It includes memory allocation, initialization, addition of new records, retrieval of offsets based on keys, and cleanup functionality. The system uses a mutex to ensure safe access and modification of the shared records array.

