```c
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <limits.h>

char* constructFilePath(const char* path, int maxBufferSize, bool isAbsolute, char* errorMessage) {
    // Check if the path exceeds the maximum buffer size
    if (strlen(path) >= maxBufferSize) {
        strcpy(errorMessage, "Path exceeds maximum buffer size");
        return NULL;
    }

    // Allocate memory for the resolved path
    char* resolvedPath = malloc(maxBufferSize);
    if (!resolvedPath) {
        strcpy(errorMessage, "Memory allocation failed");
        return NULL;
    }

    // Replace environment variables
    if (path[0] == '~') {
        const char* homeDir = getenv("HOME");
        if (!homeDir) {
            strcpy(errorMessage, "Failed to resolve home directory");
            free(resolvedPath);
            return NULL;
        }
        snprintf(resolvedPath, maxBufferSize, "%s%s", homeDir, path + 1);
    } else {
        strcpy(resolvedPath, path);
    }

    // Append the current working directory if not already absolute
    if (!isAbsolute) {
        char cwd[PATH_MAX];
        if (getcwd(cwd, sizeof(cwd)) == NULL) {
            strcpy(errorMessage, "Failed to get current working directory");
            free(resolvedPath);
            return NULL;
        }
        snprintf(resolvedPath + strlen(resolvedPath), maxBufferSize - strlen(resolvedPath), "/%s", resolvedPath);
    }

    // Log the path construction process (for debugging purposes)
    printf("Resolved Path: %s\n", resolvedPath);

    return resolvedPath;
}
