from flask import Flask, request, jsonify
import requests
import logging
from kombu import Connection, Queue, Exchange

app = Flask(__name__)

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Message queue setup
connection = Connection('amqp://guest:guest@localhost//')
exchange = Exchange('events', type='direct')
queue = Queue('notifications', exchange=exchange, routing_key='notify')

@app.route('/webhook/<tool>', methods=['POST'])
def handle_webhook(tool):
    data = request.json
    logger.info(f"Received {tool} webhook event: {data}")

    # Process the event and send notification
    if tool == 'jenkins':
        notify_jenkins_event(data)
    elif tool == 'github':
        notify_github_event(data)

    return jsonify({"status": "success"}), 200

def notify_jenkins_event(data):
    status = data.get('build_status')
    if status == 'SUCCESS':
        message = f"Build {data['build_number']} succeeded: {data['url']}"
    else:
        message = f"Build {data['build_number']} failed: {data['url']}"

    send_notification(message, event_type='jenkins')

def notify_github_event(data):
    action = data.get('action')
    if action == 'pushed':
        message = f"Code pushed to {data['repository']['name']}: {data['ref']}"
    elif action == 'opened':
        message = f"Issue opened: {data['issue']['title']} - {data['issue']['html_url']}"

    send_notification(message, event_type='github')

def send_notification(message, event_type):
    try:
        queue.publish({'message': message, 'event_type': event_type}, routing_key='notify')
        logger.info(f"Notification sent: {message}")
    except Exception as e:
        logger.error(f"Failed to send notification: {e}")

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

