[ApiController]
[Route("api/[controller]")]
public class ResourcesController : ControllerBase
{
    private readonly IResourceRepository _resourceRepository;
    private readonly IDistributedCache _cache;
    private readonly INotificationService _notificationService;

    public ResourcesController(IResourceRepository resourceRepository, IDistributedCache cache, INotificationService notificationService)
    {
        _resourceRepository = resourceRepository;
        _cache = cache;
        _notificationService = notificationService;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateAsync(int id, [FromBody] ResourceUpdateModel updateModel)
    {
        if (updateModel == null || !ModelState.IsValid)
            return BadRequest(ModelState);

        var resource = await _resourceRepository.GetByIdAsync(id);
        if (resource == null)
            return NotFound();

        // Merge update model with existing resource
        resource.Update(updateModel);
        await _resourceRepository.SaveChangesAsync();
        await _cache.RemoveAsync(id.ToString());

        return Ok(resource);
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteAsync(int id)
    {
        var resource = await _resourceRepository.GetByIdAsync(id);
        if (resource == null)
            return NotFound();

        try
        {
            // Cascade deletion logic
            await _resourceRepository.CascadeDeleteAsync(resource);
            await _cache.RemoveAsync(id.ToString());
            await _notificationService.SendDeletionAlertAsync(resource);

            return Ok(new Resource { Id = id, DefaultValues() });
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"An error occurred during cascading deletion: {ex.Message}");
        }
    }
}

public class ResourceUpdateModel
{
    public string Name { get; set; }
    public int Quantity { get; set; }
    // Add other fields as needed
}

public interface IResourceRepository
{
    Task<Resource> GetByIdAsync(int id);
    void SaveChangesAsync();
    Task CascadeDeleteAsync(Resource resource);
}

public class Resource
{
    public int Id { get; set; }
    public string Name { get; private set; }
    public int Quantity { get; private set; }

    public void Update(ResourceUpdateModel model)
    {
        if (model.Name != null) Name = model.Name;
        if (model.Quantity >= 0) Quantity = model.Quantity;
    }

    public Dictionary<string, object> DefaultValues()
    {
        return new Dictionary<string, object>
        {
            { "Id", Id },
            { "Name", "" },
            { "Quantity", 0 }
            // Add default values for other fields
        };
    }
}

public interface IDistributedCache
{
    Task RemoveAsync(string key);
}

public class NotificationService : INotificationService
{
    public async Task SendDeletionAlertAsync(Resource resource)
    {
        // Logic to send alert for deleted resources
    }
}
