// Define the cipher types
typedef enum {
    AES_128,
    AES_256,
    CHACHA20,
    GCM_MODE
} CipherType;

// Define a structure for encryption/decryption context
typedef struct {
    CipherType type;
    void* key;
    void* iv; // Initialization Vector
    pthread_mutex_t mutex;
} CryptoContext;

// Function to initialize the crypto context based on cipher type
CryptoContext* initCryptoContext(CipherType type, const void* key, const void* iv) {
    CryptoContext* ctx = malloc(sizeof(CryptoContext));
    if (ctx == NULL) {
        perror("Failed to allocate memory for CryptoContext");
        return NULL;
    }
    ctx->type = type;
    memcpy(ctx->key, key, get_key_size(type));
    memcpy(ctx->iv, iv, get_iv_size(type));
    pthread_mutex_init(&ctx->mutex, NULL);
    return ctx;
}

// Function to encrypt data using the crypto context
int encryptData(CryptoContext* ctx, const void* plaintext, size_t plaintext_len, void* ciphertext) {
    pthread_mutex_lock(&ctx->mutex);
    int result = perform_encryption(ctx, plaintext, plaintext_len, ciphertext);
    pthread_mutex_unlock(&ctx->mutex);
    return result;
}

// Function to decrypt data using the crypto context
int decryptData(CryptoContext* ctx, const void* ciphertext, size_t ciphertext_len, void* plaintext) {
    pthread_mutex_lock(&ctx->mutex);
    int result = perform_decryption(ctx, ciphertext, ciphertext_len, plaintext);
    pthread_mutex_unlock(&ctx->mutex);
    return result;
}

// Function to get the key size for a given cipher type
size_t get_key_size(CipherType type) {
    switch (type) {
        case AES_128:
            return 16;
        case AES_256:
            return 32;
        case CHACHA20:
            return 32; // ChaCha20 key size
        default:
            return 0;
    }
}

