// Command-line interface function for testing and validation
int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <cipher> <key> <iv> <plaintext>\n", argv[0]);
        return 1;
    }

    CipherType type = get_cipher_type(argv[1]);
    if (type == -1) {
        fprintf(stderr, "Unsupported cipher type\n");
        return 1;
    }

    // Convert key and IV from string to binary data
    unsigned char key[32], iv[16];
    hex_string_to_binary(argv[2], key);
    hex_string_to_binary(argv[3], iv);

    CryptoContext* ctx = initCryptoContext(type, key, iv);
    if (ctx == NULL) {
        return 1;
    }

    // Convert plaintext from string to binary data
    unsigned char *plaintext = malloc(strlen(argv[4]) / 2);
    hex_string_to_binary(argv[4], plaintext);

    // Encrypt and decrypt the data
    unsigned char ciphertext[strlen(argv[4]) / 2];
    unsigned char decryptedtext[strlen(argv[4]) / 2];

    if (encryptData(ctx, plaintext, strlen(plaintext), ciphertext) != 0) {
        fprintf(stderr, "Encryption failed\n");
        free(plaintext);
        return 1;
    }

    if (decryptData(ctx, ciphertext, strlen(ciphertext), decryptedtext) != 0) {
        fprintf(stderr, "Decryption failed\n");
        free(plaintext);
        return 1;
    }

    // Print the results
    binary_to_hex_string(ciphertext, strlen(ciphertext), stdout);
    printf("\n");

    free(plaintext);
    free(ctx);

    return 0;
}

// Helper function to convert hex string to binary data
void hex_string_to_binary(const char* hex_str, unsigned char* binary_data) {
    size_t hex_len = strlen(hex_str);
    size_t binary_len = hex_len / 2;
    for (size_t i = 0; i < binary_len; i++) {
        binary_data[i] = (hex_str[2 * i] - '0') << 4 | (hex_str[2 * i + 1] - '0');
    }
}

// Helper function to convert binary data to hex string
void binary_to_hex_string(const unsigned char* binary_data, size_t binary_len, FILE* output) {
    for (size_t i = 0; i < binary_len; i++) {
        fprintf(output, "%02x", binary_data[i]);
    }
}

// Helper function to get the cipher type from a string
CipherType get_cipher_type(const char* name) {
    if (strcmp(name, "AES-128") == 0)
        return AES_128;
    else if (strcmp(name, "AES-256") == 0)
        return AES_256;
    else if (strcmp(name, "CHACHA20") == 0)
        return CHACHA20;
    else
        return -1; // Unsupported cipher type
}
