#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/hkdf.h>
#include <openssl/pbkdf2.h>
#include <iostream>

EVP_CIPHER_CTX* createCipherContext(const std::string& mode, const std::string& padding) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        std::cerr << "Error creating EVP_CIPHER_CTX" << std::endl;
        return nullptr;
    }

    const EVP_CIPHER* cipher;
    int pad_mode = EVP_PKEY_NO_ENGINE;

    if (mode == "ECB") {
        cipher = EVP_aes_256_ecb();
    } else if (mode == "CBC") {
        cipher = EVP_aes_256_cbc();
        pad_mode = EVP_PKCS1_PADDING;
    } else if (mode == "GCM") {
        cipher = EVP_aes_256_gcm();
        pad_mode = EVP_PKEY_NO_ENGINE; // GCM uses additional data
    } else {
        std::cerr << "Unsupported AES mode: " << mode << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    if (!EVP_EncryptInit_ex2(ctx, cipher, nullptr, nullptr, nullptr)) {
        std::cerr << "Error initializing EVP_CIPHER_CTX" << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    if (padding == "PKCS7") {
        if (!EVP_CIPHER_CTX_set_padding(ctx, pad_mode)) {
            std::cerr << "Error setting padding mode" << std::endl;
            EVP_CIPHER_CTX_free(ctx);
            return nullptr;
        }
    } else if (padding != "NoPadding") { // Assuming NoPadding is used for GCM
        std::cerr << "Unsupported padding scheme: " << padding << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    return ctx;
}

unsigned char* deriveKey(const std::string& password, const unsigned char* salt, size_t salt_len, int key_length, const std::string& kdf) {
    unsigned char* derived_key = new unsigned char[key_length];
    if (!derived_key) {
        std::cerr << "Error allocating memory for derived key" << std::endl;
        return nullptr;
    }

    if (kdf == "PBKDF2") {
        int iterations = 100000; // Example number of iterations
        if (!PKCS5_PBKDF2_HMAC(password.c_str(), password.size(), salt, salt_len, iterations, EVP_sha256(), key_length, derived_key)) {
            std::cerr << "Error deriving key using PBKDF2" << std::endl;
            delete[] derived_key;
            return nullptr;
        }
    } else if (kdf == "HKDF") {
        // Example HKDF usage
        unsigned char info[] = "HKDF example";
        size_t info_len = sizeof(info) - 1;

        if (!HKDF(derived_key, key_length, EVP_sha256(), reinterpret_cast<const uint8_t*>(password.c_str()), password.size(), salt, salt_len, info, info_len)) {
            std::cerr << "Error deriving key using HKDF" << std::endl;
            delete[] derived_key;
            return nullptr;
        }
    } else {
        std::cerr << "Unsupported KDF: " << kdf << std::endl;
        delete[] derived_key;
        return nullptr;
    }

    return derived_key;
}

// Usage example
int main() {
    const char* password = "securepassword123";
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        std::cerr << "Error generating random salt" << std::endl;
        return 1;
    }

    int key_length = 32; // 256-bit key for AES-256
    const std::string mode = "GCM";
    const std::string padding = "NoPadding";
    const std::string kdf = "PBKDF2";

    unsigned char* derived_key = deriveKey(password, salt, sizeof(salt), key_length, kdf);
    if (!derived_key) {
        return 1;
    }

    EVP_CIPHER_CTX* ctx = createCipherContext(mode, padding);
    if (!ctx) {
        delete[] derived_key;
        return 1;
    }

    // Set the derived key and salt for encryption/decryption
    if (mode == "GCM") {
        if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, nullptr)) { // Example IV length
            std::cerr << "Error setting GCM IV length" << std::endl;
            EVP_CIPHER_CTX_free(ctx);
            delete[] derived_key;
            return 1;
        }
    }

    if (!EVP_EncryptInit_ex2(ctx, nullptr, nullptr, derived_key, salt)) {
        std::cerr << "Error initializing encryption with key and salt" << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        delete[] derived_key;
        return 1;
    }

    // Continue with encryption/decryption operations using ctx

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    delete[] derived_key;

    return 0;
}
