#include <pthread.h>

// Function prototypes
void* chunkProcessor(void*);
int fetchMetadata(const char*, char*);

int convertJpegToPdfAsync(const char* inputFileName, const char* outputDir, const char* metadataFile) {
    // Create output directory if it does not exist
    DIR *dir = opendir(outputDir);
    if (!dir) {
        mkdir(outputDir, 0755);
    }

    // Open the input file
    FILE *inputFile = fopen(inputFileName, "rb");
    if (!inputFile) {
        perror("Error opening input file");
        return 1;
    }

    // Determine the number of chunks (e.g., 10 chunks for simplicity)
    int numChunks = 10;
    pthread_t threads[numChunks];

    // Process each chunk asynchronously
    for (int i = 0; i < numChunks; ++i) {
        if (pthread_create(&threads[i], NULL, chunkProcessor, (void*)inputFile) != 0) {
            perror("Error creating thread");
            fclose(inputFile);
            return 1;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < numChunks; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Fetch metadata if a file name is provided
    if (metadataFile) {
        fetchMetadata(inputFileName, metadataFile);
    }

    // Close the input file
    fclose(inputFile);

    return 0;
}

void* chunkProcessor(void* arg) {
    FILE *inputFile = (FILE*)arg;

    // Simulate processing a chunk
    sleep(1); // Simulating time taken for processing

    printf("Chunk processed\n");

    return NULL;
}

int fetchMetadata(const char* inputFileName, char* metadataFile) {
    // Simulate fetching metadata from an external service
    FILE *metadata = fopen(metadataFile, "w");
    if (!metadata) {
        perror("Error opening metadata file");
        return 1;
    }

    fprintf(metadata, "{\"filename\": \"%s\", \"dimensions\": \"800x600\", \"filesize\": \"1MB\"}", inputFileName);
    fclose(metadata);

    printf("Metadata saved to %s\n", metadataFile);

    return 0;
}

int main() {
    const char* inputFileName = "input.jpg";
    const char* outputDir = "output/";
    const char* metadataFile = "metadata.json";

    if (convertJpegToPdfAsync(inputFileName, outputDir, metadataFile) != 0) {
        printf("Conversion failed\n");
        return 1;
    }

    printf("Conversion successful\n");

    return 0;
}
