    }

    private Class<?> getClassFromCacheOrProvider(String className, ClassProvider classProvider) throws ClassNotFoundException {
        if (classCache.size() >= DEFAULT_CACHE_SIZE && !classCache.containsKey(className)) {
            evictLeastRecentlyUsedClass();
        }
        return classCache.computeIfAbsent(className, name -> classProvider.getClassByName(name));
    }

    private void evictLeastRecentlyUsedClass() {
        // Implement LRU eviction strategy here
    }
}

interface ClassProvider {
    Class<?> getClassByName(String className) throws ClassNotFoundException;
}

class DeserializationException extends RuntimeException {
