using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class UserProfileUpdater
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _memoryCache;
    private readonly ILogger<UserProfileUpdater> _logger;

    public UserProfileUpdater(HttpClient httpClient, IMemoryCache memoryCache, ILogger<UserProfileUpdater> logger)
    {
        _httpClient = httpClient;
        _memoryCache = memoryCache;
        _logger = logger;
    }

    public async Task<byte[]> DecryptAndUpdateUserProfile(byte[] ciphertext, byte[] key, byte[] iv)
    {
        // Perform AES-CBC decryption
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    return await csDecrypt.ReadAllBytesAsync();
                }
            }
        }
    }

    public async Task UpdateUserProfiles(List<UserProfile> userProfiles)
    {
        var tasks = userProfiles.Select(async userProfile =>
        {
            try
            {
                // Validate directory paths and user IDs
                if (string.IsNullOrEmpty(userProfile.DirectoryPath) || string.IsNullOrEmpty(userProfile.UserId))
                {
                    _logger.LogError("Invalid user profile data.");
                    return;
                }

                // Update user profile concurrently for multiple users
                var response = await _httpClient.PutAsJsonAsync($"api/user/{userProfile.UserId}", userProfile);
                if (!response.IsSuccessStatusCode)
                {
                    _logger.LogError($"Failed to update user profile for {userProfile.UserId}.");
                    return;
                }

                // Cache the updated user profile
                _memoryCache.Set(userProfile.UserId, userProfile, new MemoryCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
                });

                // Send notifications via email or SMS
                await SendNotification(userProfile);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"An error occurred while updating user profile for {userProfile.UserId}.");
            }
        }).ToList();

        await Task.WhenAll(tasks);
    }

    private async Task SendNotification(UserProfile userProfile)
    {
        // Determine notification type based on configured settings
        var notificationType = GetNotificationType(userProfile);

        switch (notificationType)
        {
            case NotificationType.Email:
                await SendEmailNotification(userProfile);
                break;
            case NotificationType.SMS:
                await SendSmsNotification(userProfile);
                break;
        }
    }

    private async Task SendEmailNotification(UserProfile userProfile)
    {
        // Encrypt sensitive data in transit using TLS 1.2
        var client = new HttpClient();
        client.DefaultRequestHeaders.Add("Accept", "application/json");
        client.DefaultRequestHeaders.Add("Content-Type", "application/json");

        // Encrypt email addresses and phone numbers at rest using AES-256
        var encryptedEmail = EncryptData(userProfile.Email);
        var encryptedPhone = EncryptData(userProfile.Phone);

        var notification = new Notification { UserId = userProfile.UserId, Field = "email/phone", NewValue = $"{encryptedEmail}/{encryptedPhone}" };

        // Send notification via email
        var response = await client.PostAsJsonAsync("api/notification/email", notification);
        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError($"Failed to send email notification for {userProfile.UserId}.");
        }
    }

    private async Task SendSmsNotification(UserProfile userProfile)
    {
        // Encrypt sensitive data in transit using TLS 1.2
        var client = new HttpClient();
        client.DefaultRequestHeaders.Add("Accept", "application/json");
        client.DefaultRequestHeaders.Add("Content-Type", "application/json");

        // Encrypt phone numbers at rest using AES-256
        var encryptedPhone = EncryptData(userProfile.Phone);

        var notification = new Notification { UserId = userProfile.UserId, Field = "phone", NewValue = encryptedPhone };

        // Send notification via SMS
        var response = await client.PostAsJsonAsync("api/notification/sms", notification);
        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError($"Failed to send SMS notification for {userProfile.UserId}.");
        }
    }

    private string GetNotificationType(UserProfile userProfile)
    {
        // Determine notification type based on configured settings
        return Configuration.GetSection("NotificationSettings").GetValue<string>("Type");
    }

    private byte[] EncryptData(string data)
    {
        // Implement AES-256 encryption for sensitive data
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = Encoding.UTF8.GetBytes(Configuration.GetSection("EncryptionSettings").GetValue<string>("Key"));
            aesAlg.IV = Encoding.UTF8.GetBytes(Configuration.GetSection("EncryptionSettings").GetValue<string>("IV"));
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    csEncrypt.Write(Encoding.UTF8.GetBytes(data), 0, data.Length);
                }
                return msEncrypt.ToArray();
            }
        }
    }

    private class UserProfile
    {
        public string UserId { get; set; }
        public string DirectoryPath { get; set; }
        public string Email { get; set; }
        public string Phone { get; set; }
        // Other user profile fields...
    }

    private class Notification
    {
        public string UserId { get; set; }
        public string Field { get; set; }
        public string NewValue { get; set; }
    }

    private enum NotificationType
    {
        Email,
        SMS
    }
}
