<?php

class OAuthSessionHandler {
    private $provider;
    private $params;
    private static $tokenStorage;
    private static $cache;

    public function __construct($provider, $params) {
        $this->provider = $provider;
        $this->params = $params;
    }

    public function authenticate() {
        if (!self::$tokenStorage) {
            self::$tokenStorage = new ExternalTokenStorage();
        }

        if (!self::$cache) {
            self::$cache = new ThreadSafeCache(100); // Fixed cache size
        }

        $accessToken = self::$cache->get($this->provider);
        if ($accessToken) {
            return $accessToken;
        }

        try {
            switch ($this->provider) {
                case 'Google':
                    $accessToken = self::authenticateWithGoogle();
                    break;
                case 'Facebook':
                    $accessToken = self::authenticateWithFacebook();
                    break;
                case 'GitHub':
                    $accessToken = self::authenticateWithGitHub();
                    break;
                default:
                    throw new Exception('Unsupported provider');
            }

            self::$cache->set($this->provider, $accessToken);
        } catch (Exception $e) {
            echo 'Error authenticating with ' . $this->provider . ': ' . $e->getMessage();
            return null;
        }

        return $accessToken;
    }

    private static function authenticateWithGoogle() {
        // Implement Google authentication logic
        return 'google_access_token';
    }

    private static function authenticateWithFacebook() {
        // Implement Facebook authentication logic
        return 'facebook_access_token';
    }

    private static function authenticateWithGitHub() {
        // Implement GitHub authentication logic
        return 'github_access_token';
    }

    public function __toString() {
        return "Provider: " . $this->provider . "\nParameters: " . json_encode($this->params);
    }
}

class ExternalTokenStorage {
    // Implement token storage logic
}

class ThreadSafeCache {
    private $maxSize;
    private $cache;

    public function __construct($maxSize) {
        $this->maxSize = $maxSize;
        $this->cache = [];
    }

    public function get($key) {
        if (isset($this->cache[$key])) {
            return $this->cache[$key];
        }
        return null;
    }

    public function set($key, $value) {
        if (count($this->cache) >= $this->maxSize) {
            // Evict LRU entry
            array_shift($this->cache);
        }
        $this->cache[$key] = $value;
    }
}

