using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using NodaTime;
using MongoDB.Driver;

public class SensorDataProcessor
{
    private readonly IConfiguration _configuration;
    private readonly IMongoClient _mongoClient;
    private readonly IMongoDatabase _database;
    private readonly XPathDocument _vendorAutoloader;

    public SensorDataProcessor(IConfiguration configuration, IMongoClient mongoClient)
    {
        _configuration = configuration;
        _mongoClient = mongoClient;
        _database = mongoClient.GetDatabase(_configuration["MongoDb:DatabaseName"]);
        _vendorAutoloader = new XPathDocument(_configuration["VendorAutoloaderPath"]);
    }

    public async Task ProcessSensorDataAsync(string xmlFilePath)
    {
        var xmlDoc = new XPathDocument(xmlFilePath);
        var sensorReadings = ExtractSensorReadings(xmlDoc);

        foreach (var reading in sensorReadings)
        {
            await StoreReadingInDatabase(reading);
        }
    }

    private List<SensorReading> ExtractSensorReadings(XPathDocument xmlDoc)
    {
        var readings = new List<SensorReading>();

        // Use XPath to extract the most recent sensor reading for each device
        var nodes = xmlDoc.DocumentElement.SelectNodes("//Device/Sensor/Reading[@type='Latest']");

        foreach (var node in nodes)
        {
            var deviceId = node.SelectSingleNode("../@id").Value;
            var timestamp = DateTime.Parse(node.SelectSingleNode("@timestamp").Value);
            var value = double.Parse(node.InnerText);

            readings.Add(new SensorReading { DeviceId = deviceId, Timestamp = timestamp, Value = value });
        }

        return readings;
    }

    private async Task StoreReadingInDatabase(SensorReading reading)
    {
        var collection = _database.GetCollection<SensorReading>("SensorReadings");

        // Implement optimistic concurrency control to manage concurrent access
        var filter = Builders<SensorReading>.Filter.Eq("_id", reading.DeviceId);
        var update = Builders<SensorReading>.Update.Set("Timestamp", reading.Timestamp).Set("Value", reading.Value);

        await collection.FindOneAndUpdateAsync(filter, update, new FindOneAndUpdateOptions { ReturnDocument = ReturnDocument.After });

        // Implement rate limiting and traffic shaping mechanisms
        // ...
    }

    public class SensorReading
    {
        public string DeviceId { get; set; }
        public DateTime Timestamp { get; set; }
        public double Value { get; set; }
    }
}

public static class Program
{
    public static async Task Main(string[] args)
    {
        var configuration = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
            .Build();

        var mongoClient = new MongoClient(configuration["MongoDb:ConnectionString"]);
        var sensorDataProcessor = new SensorDataProcessor(configuration, mongoClient);

        // Process sensor data from XML files
        string[] xmlFiles = { "path/to/file1.xml", "path/to/file2.xml" };
        foreach (var file in xmlFiles)
        {
            await sensorDataProcessor.ProcessSensorDataAsync(file);
        }
    }
}
