#include <iostream>
#include <fstream>
#include <unordered_map>
#include <variant>
#include <nlohmann/json.hpp>
#include <typeindex>
#include <mutex>
#include <log4cpp/Category.hh>

namespace log4cpp {
    class Category;
}

class ConfigParser {
public:
    using ConfigMap = std::unordered_map<std::string, std::variant<int, double, std::string, bool>>;
    using Schema = std::unordered_map<std::string, std::type_index>;

private:
    static std::mutex configMutex;
    ConfigMap configMap;

    void parseJson(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            log4cpp::Category::getRoot().error("Failed to open JSON file: " + filePath);
            return;
        }

        nlohmann::json jsonConfig = nlohmann::json::parse(file);
        for (auto& [key, value] : jsonConfig.items()) {
            configMap[key] = value.get<std::variant<int, double, std::string, bool>>();
        }
    }

public:
    ConfigParser(const std::string& filePath, const Schema& schema) {
        parseJson(filePath);

        std::lock_guard<std::mutex> lock(configMutex);
        for (auto& [key, expectedType] : schema) {
            if (!configMap.contains(key)) {
                log4cpp::Category::getRoot().error("Missing configuration setting: " + key);
                continue;
            }

            auto configValue = std::get_if<std::variant<int, double, std::string, bool>>(&configMap[key]);
            if (!configValue) {
                log4cpp::Category::getRoot().error("Invalid type for setting: " + key);
                continue;
            }

            if (typeid(**configValue) != expectedType) {
                log4cpp::Category::getRoot().error("Type mismatch for setting: " + key);
            }
        }
    }

    ConfigMap getConfig() const {
        std::lock_guard<std::mutex> lock(configMutex);
        return configMap;
    }
};

std::mutex ConfigParser::configMutex;

int main() {
    ConfigParser parser("config.json", {{"port", typeid(int)}, {"timeout", typeid(double)}, {"enabled", typeid(bool)}});
    auto config = parser.getConfig();

    for (auto& [key, value] : config) {
        std::cout << key << ": " << value.index() << std::endl;
    }

    return 0;
}
