```python
import asyncio
import aiohttp
import json
import yaml
import xml.etree.ElementTree as ET
from aiohttp.client_exceptions import ClientTimeoutError, TooManyRequests

async def fetch_config(session, url):
    async with session.get(url) as response:
        return await response.text()

async def parse_config(config_data, config_format):
    if config_format == 'json':
        return json.loads(config_data)
    elif config_format == 'yaml':
        return yaml.safe_load(config_data)
    elif config_format == 'xml':
        return ET.fromstring(config_data)
    else:
        raise ValueError("Unsupported configuration format")

async def load_config(url, cache=None):
    if cache and cache.get('url') == url and not cache['expired']:
        return cache['data']

    try:
        async with aiohttp.ClientSession() as session:
            config_data = await fetch_config(session, url)
            config_format = url.split('.')[-1]
            data = await parse_config(config_data, config_format)

            if cache:
                cache['url'] = url
                cache['data'] = data
                cache['expired'] = False

            return data

    except (ClientTimeoutError, TooManyRequests) as e:
        print(f"Network error: {e}")
        raise
    except Exception as e:
        print(f"Failed to load config: {e}")
        raise

async def main():
    url = "http://example.com/config.json"
    config_cache = {'url': '', 'data': None, 'expired': True}

    try:
        config = await load_config(url, config_cache)
        print(config)
    except Exception as e:
        print(f"Error loading config: {e}")

if __name__ == "__main__":
    asyncio.run(main())
```

