        {
            LogError("Directory does not exist: " + directoryPath);
            return "DirectoryDoesNotExist";
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            LogError("web.config file is missing in the specified directory.");
            return "WebConfigMissing";
        }

        string packageHash = await CalculateMd5Hash(packagePath);
        if (packageHash != checksum)
        {
            LogError("MD5 hash mismatch. Deployment aborted.");
            return "HashMismatch";
        }

        try
        {
            await DeployPackageAsync(directoryPath, siteName, packagePath);
            LogInfo("Deployment successful.");
            return "Success";
        }
        catch (Exception ex)
        {
            LogError("An error occurred during deployment: " + ex.Message);
            return "DeploymentFailed";
        }
    }

    private async Task<string> CalculateMd5Hash(string filePath)
    {
        using var md5 = MD5.Create();
        using var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, _chunkSize, true);

        byte[] hashBytes;
        await using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            hashBytes = md5.ComputeHash(memoryStream.ToArray());
        }

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private async Task DeployPackageAsync(string directoryPath, string siteName, string packagePath)
