#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[12]; // 96 bits IV for GCM
    int key_len;
} AES_GCM_Context;

int aes_gcm_init(AES_GCM_Context *ctx, const char *password, size_t password_len,
                  const unsigned char *salt, size_t salt_len, int iterations) {
    ctx->key_len = 32; // AES-256
    if (!PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iterations,
                            EVP_sha256(), ctx->key_len, ctx->key)) {
        return -1;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return -1;
    }

    return 0;
}

void aes_gcm_cleanup(AES_GCM_Context *ctx) {
    if (ctx->ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
    }
    memset(ctx, 0, sizeof(*ctx));
}

int aes_gcm_encrypt(AES_GCM_Context *ctx, const unsigned char *plaintext,
                    size_t plaintext_len, unsigned char *ciphertext,
                    unsigned char *tag) {
    if (EVP_EncryptUpdate(ctx->ctx, ciphertext, NULL, plaintext, plaintext_len) != 1) {
        return -1;
    }

    int len = 0;
    if (EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len) != 1) {
        return -1;
    }

    return EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, GCM_TAG_LEN, tag);
}

int aes_gcm_decrypt(AES_GCM_Context *ctx, const unsigned char *ciphertext,
                    size_t ciphertext_len, unsigned char *plaintext,
                    unsigned char *tag) {
    if (EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv) != 1) {
        return -1;
    }

    if (EVP_DecryptUpdate(ctx->ctx, plaintext, NULL, ciphertext, ciphertext_len) != 1) {
        return -1;
    }

    int len = 0;
    if (EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, GCM_TAG_LEN, tag) != 1) {
        return -1;
    }

    return EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len);
}
