```php
<?php

class ConfigManager {
    private $config;
    private $localConfig;
    private $apiUrl;
    private $cacheTtl;

    public function __construct($environment) {
        $this->apiUrl = 'https://config-service/api/config/' . $environment;
        $this->cacheTtl = 3600; // Cache TTL in seconds
        $this->loadLocalConfig();
        $this->loadRemoteConfig();
    }

    private function loadLocalConfig() {
        if (file_exists(__DIR__ . '/config-local.yml')) {
            $this->localConfig = yaml_parse_file(__DIR__ . '/config-local.yml');
        } else {
            $this->localConfig = [];
        }
    }

    private function loadRemoteConfig() {
        $options = [
            'http' => [
                'method'  => 'GET',
                'header'  => 'User-Agent: PHP'
            ]
        ];
        $context  = stream_context_create($options);
        $configData = file_get_contents($this->apiUrl, false, $context);

        if ($configData === FALSE) {
            error_log('Failed to fetch remote config');
            return;
        }

        try {
            $this->config = yaml_parse($configData);
        } catch (Exception $e) {
            error_log('Error parsing remote config: ' . $e->getMessage());
            $this->config = [];
        }
    }

    private function getConfiguration($key, $default = null) {
        return $this->localConfig[$key] ?? $this->config[$key] ?? $default;
    }

    public function reloadConfiguration() {
        if (time() - filemtime(__DIR__ . '/cache/config_cache.yml') > $this->cacheTtl) {
            $this->loadRemoteConfig();
            file_put_contents(__DIR__ . '/cache/config_cache.yml', serialize($this->config));
        } else {
            $this->config = unserialize(file_get_contents(__DIR__ . '/cache/config_cache.yml'));
        }
    }

    public function reloadConfigurationOnEvent() {
        if (getenv('RELOAD_CONFIG') === 'true') {
            $this->reloadConfiguration();
        }
    }

    public function applyConfigurations() {
        // Example: Apply a configuration setting to a service
        $dbHost = $this->getConfiguration('database.host');
        echo "Database Host: $dbHost\n";
    }
}

// Example 1: Fetching and applying configuration in development mode
$script = new ConfigManager('development');
$script->reloadConfiguration();
$script->applyConfigurations();

// Example 2: Handling configuration changes in production
$script = new ConfigManager('production');
$script->reloadConfigurationOnEvent();
$script->applyConfigurations();
