// Password Manager Class
class PasswordManager {
    private $tenantId;
    private $config;

    public function __construct($tenantId) {
        $this->tenantId = $tenantId;
        $this->loadConfig();
    }

    private function loadConfig() {
        // Load tenant-specific configurations from database or cache
        $this->config = [
            'password_algorithm' => PASSWORD_DEFAULT,
            'min_length' => 8,
            'allowed_chars' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()'
        ];
    }

    public function hashPassword($password) {
        $algorithm = $this->config['password_algorithm'];
        return password_hash($password, $algorithm);
    }

    public function verifyPassword($input, $storedHash) {
        return password_verify($input, $storedHash);
    }

    public function enforcePolicy($password) {
        $minLength = $this->config['min_length'];
        $allowedChars = $this->config['allowed_chars'];

        if (strlen($password) < $minLength) {
            throw new Exception("Password must be at least {$minLength} characters long.");
        }

        if (!preg_match("/[{$allowedChars}]/", $password)) {
            throw new Exception("Password must contain only allowed characters.");
        }
    }

    public function changeAlgorithm($algorithm, $options = []) {
        // Update tenant-specific configuration for password algorithm
        $this->config['password_algorithm'] = $algorithm;
        // Save the updated configuration to database or cache
    }

    public function getPolicy() {
        return [
            'min_length' => $this->config['min_length'],
            'allowed_chars' => $this->config['allowed_chars']
        ];
    }
}

// Example Usage
$tenantId = 1;
$passwordManager = new PasswordManager($tenantId);

try {
    $password = "examplePassword123!";
    $hashedPassword = $passwordManager->hashPassword($password);
    echo "Hashed Password: " . $hashedPassword . "\n";

    if ($passwordManager->verifyPassword("examplePassword123!", $hashedPassword)) {
        echo "Password verification successful.\n";
    } else {
        echo "Invalid password.\n";
    }

    $passwordManager->enforcePolicy($password);
    echo "Policy enforced successfully.\n";

} catch (Exception $e) {
    echo "Error: " . $e->getMessage() . "\n";
}
?>
