import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class SessionManager {
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private ExternalSessionService sessionService;
    private ScheduledExecutorService scheduler;

    public SessionManager(ExternalSessionService sessionService) {
        this.sessionService = sessionService;
        this.scheduler = Executors.newScheduledThreadPool(1);
        scheduleCleanup();
    }

    public void createSession(String userId, String sessionData) {
        try {
            cache.put(userId, sessionData);
            sessionService.createSession(sessionData);
        } catch (Exception e) {
            handleException("Failed to create session for user: " + userId, e);
        }
    }

    public String getSessionData(String userId) {
        String sessionData = cache.get(userId);
        if (sessionData == null) {
            try {
                sessionData = sessionService.getSessionData(userId);
                cache.put(userId, sessionData);
            } catch (Exception e) {
                handleException("Failed to retrieve session data for user: " + userId, e);
                return null;
            }
        }
        return sessionData;
    }

    public void updateSession(String userId, String newSessionData) {
        try {
            cache.put(userId, newSessionData);
            sessionService.updateSession(newSessionData);
        } catch (Exception e) {
            handleException("Failed to update session for user: " + userId, e);
        }
    }

    public void deleteSession(String userId) {
        try {
            cache.remove(userId);
            sessionService.deleteSession(userId);
        } catch (Exception e) {
            handleException("Failed to delete session for user: " + userId, e);
        }
    }

    private void scheduleCleanup() {
        scheduler.scheduleAtFixedRate(() -> {
            // Implement logic to clean up expired sessions
        }, 0, 1, TimeUnit.HOURS);
    }

    private void handleException(String message, Exception e) {
        // Implement robust error handling and logging
    }

