using System;
using System.IO;
using System.Security.Cryptography;
using Amazon.S3;
using Amazon.S3.Model;
using Azure.Storage.Blobs;
using Google.Apis.Auth.OAuth2;
using Google.Cloud.Storage.V1;
using Microsoft.Extensions.Logging;

public class SecurelyDecryptAndUpload
{
    private readonly ILogger _logger;
    private readonly ICloudStorageClientFactory _cloudStorageClientFactory;

    public SecurelyDecryptAndUpload(ILogger logger, ICloudStorageClientFactory cloudStorageClientFactory)
    {
        _logger = logger;
        _cloudStorageClientFactory = cloudStorageClientFactory;
    }

    public async Task<string> ExecuteAsync(string filePath, string bucketName, string key, byte[] iv, Dictionary<string, string> metadataTags = null)
    {
        // Validate input
        if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(bucketName))
        {
            throw new ArgumentException("File path and bucket name must not be empty.");
        }

        try
        {
            // Check file existence and accessibility
            if (!File.Exists(filePath))
            {
                _logger.LogError($"File {filePath} does not exist or is inaccessible.");
                return "File not found.";
            }

            // Decrypt the file
            var decryptedFilePath = Path.GetTempFileName();
            using (var aesGcm = Aes.Create())
            {
                aesGcm.KeySize = 256;
                aesGcm.Mode = CipherMode.GCM;
                aesGcm.Padding = PaddingMode.PKCS7;
                aesGcm.GenerateIV();
                aesGcm.GenerateKey();

                if (!aesGcm.Key.SequenceEqual(key) || !aesGcm.IV.SequenceEqual(iv))
                {
                    _logger.LogError("Invalid key or IV.");
                    return "Invalid decryption parameters.";
                }

                using (var fsInput = File.OpenRead(filePath))
                using (var fsOutput = File.Create(decryptedFilePath))
                using (var decryptor = aesGcm.CreateDecryptor(aesGcm.Key, aesGcm.IV))
                {
                    await decryptor.CopyToAsync(fsOutput);
                }
            }

            // Upload the decrypted file to cloud storage
            var uploadResult = await UploadToCloudStorageAsync(decryptedFilePath, bucketName, metadataTags);

            return uploadResult;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred during decryption or upload.");
            return $"Error: {ex.Message}";
        }
    }

    private async Task<string> UploadToCloudStorageAsync(string filePath, string bucketName, Dictionary<string, string> metadataTags)
    {
        try
        {
            var client = await _cloudStorageClientFactory.CreateAsync();
            using (var fileStream = File.OpenRead(filePath))
            {
                var uploadObject = new PutObjectRequest
                {
                    BucketName = bucketName,
                    Key = Path.GetFileName(filePath),
                    InputStream = fileStream,
                    Metadata = metadataTags ?? new Dictionary<string, string>(),
                    AutoCloseInputStream = true
                };

                await client.PutObjectAsync(uploadObject);
                return "Upload successful.";
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred during cloud storage upload.");
            throw;
        }
    }
}

