public class TracingSystem {

    private Map<String, String> configMap = new HashMap<>();
    private String fallbackLogFilePath = "fallback.log";

    public void loadConfiguration(String configFilePath) {
        try (FileReader reader = new FileReader(configFilePath)) {
            JSONObject jsonConfig = new JSONObject(reader);
            for (String key : jsonConfig.keySet()) {
                configMap.put(key, jsonConfig.getString(key));
            }
        } catch (Exception e) {
            logError("Failed to load configuration file: " + e.getMessage());
        }
    }

    public void initializeTracing() {
        String backendServiceUrl = configMap.get("backend_service_url");
        String serviceName = configMap.get("service_name");
        double samplingRate = Double.parseDouble(configMap.get("sampling_rate"));

        // Initialize tracing with selected backend and parameters
        Tracer tracer = new Tracer(backendServiceUrl, serviceName, samplingRate);

        try {
            tracer.initialize();
        } catch (Exception e) {
            logError("Failed to initialize tracing: " + e.getMessage());
            fallbackToReducedTracing(tracer);
        }
    }

    private void logError(String errorMessage) {
        try (FileWriter writer = new FileWriter(fallbackLogFilePath, true)) {
            writer.write(errorMessage + "\n");
        } catch (Exception e) {
            System.err.println("Failed to write to fallback log: " + e.getMessage());
