#include <iostream>
#include <fstream>
#include <string>

const size_t MAX_FILE_PATH_LENGTH = 4096;

class FileHandler {
public:
    explicit FileHandler(const std::string& filePath) : filePath_(filePath), fileStream_(filePath, std::ios_base::app) {
        if (!fileStream_.is_open()) {
            std::cerr << "Failed to open file: " << filePath_ << std::endl;
            throw std::runtime_error("File opening failed");
        }
    }

    ~FileHandler() {
        if (fileStream_.is_open()) {
            fileStream_.close();
        }
    }

    size_t append(const char* buffer, std::streamsize bytes) {
        if (!fileStream_.good()) {
            std::cerr << "Error in file stream" << std::endl;
            return -1;
        }

        fileStream_.write(buffer, bytes);
        if (fileStream_.fail()) {
            std::cerr << "Failed to append data to file: " << filePath_ << std::endl;
            return -1;
        }

        return bytes;
    }

private:
    std::string filePath_;
    std::ofstream fileStream_;
};

int safeFileAppend(const char* filePath, const void* buffer, size_t bufferSize) {
    if (!filePath || strlen(filePath) >= MAX_FILE_PATH_LENGTH) {
        std::cerr << "Invalid file path" << std::endl;
        return -1;
    }

    FileHandler handler(filePath);
    return static_cast<int>(handler.append(static_cast<const char*>(buffer), bufferSize));
}

// Example usage
int main() {
    const char* filePath = "/path/to/your/file.txt";
    const char* data = "Hello, world!\n";
    size_t dataSize = strlen(data);

    int result = safeFileAppend(filePath, data, dataSize);
    if (result == -1) {
        std::cerr << "Failed to append to file" << std::endl;
    } else {
        std::cout << "Successfully appended " << result << " bytes to file" << std::endl;
    }

    return 0;
}
