class AuthService {
    private $apiUrl;
    private $hashingAlgorithm;

    public function __construct($apiUrl, $hashingAlgorithm = PASSWORD_BCRYPT) {
        $this->apiUrl = $apiUrl;
        $this->hashingAlgorithm = $hashingAlgorithm;
    }

    public function generateSalt($length = 20) {
        return bin2hex(random_bytes($length));
    }

    public function hashPassword($password, $salt) {
        return password_hash($password . $salt, $this->hashingAlgorithm);
    }

    public function registerUser($username, $password) {
        $salt = $this->generateSalt();
        $hashedPassword = $this->hashPassword($password, $salt);

        // Simulate API call to external user management system
        $response = file_get_contents($this->apiUrl . "/register?username=" . urlencode($username) . "&password=" . urlencode($hashedPassword));

        if ($response === "success") {
            return ["success" => true, "salt" => $salt];
        } else {
            throw new Exception("Registration failed: " . $response);
        }
    }

    public function loginUser($username, $password) {
        // Simulate API call to external user management system
        $response = file_get_contents($this->apiUrl . "/login?username=" . urlencode($username));

        if (isset($response["salt"]) && isset($response["hashedPassword"])) {
            $hashedPassword = $response["hashedPassword"];
            $salt = $response["salt"];

            $userProvidedHash = $this->hashPassword($password, $salt);

            if ($userProvidedHash === $hashedPassword) {
                return ["success" => true];
            } else {
                throw new Exception("Login failed: Incorrect password");
            }
        } else {
            throw new Exception("Login failed: User not found");
        }
    }

    public function regenerateSalt($username) {
        // Simulate API call to external user management system
        $salt = $this->generateSalt();
        $hashedPassword = $response["hashedPassword"];

        $response = file_get_contents($this->apiUrl . "/update-salt?username=" . urlencode($username) . "&newSalt=" . urlencode($salt));

        if ($response === "success") {
            return ["success" => true];
        } else {
            throw new Exception("Salt regeneration failed: " . $response);
        }
    }
}
