#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the transaction structure
typedef struct {
    int id;
    char type[256];
    // Other fields...
} Transaction;

// Define the factory function signature
typedef void (*FactoryFunction)(Transaction *transaction);

// Define the configuration structure
typedef struct {
    int id;
    FactoryFunction factoryFunction;
    // Other fields...
} Configuration;

// Define the registry of factory functions
Configuration* configRegistry[100];
int configCount = 0;

// Mutex for thread-safe access to the registry
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a configuration to the registry
void addConfiguration(int id, FactoryFunction factoryFunction) {
    pthread_mutex_lock(&configMutex);
    if (id >= 0 && id < 100) {
        configRegistry[id] = malloc(sizeof(Configuration));
        configRegistry[id]->id = id;
        configRegistry[id]->factoryFunction = factoryFunction;
        configCount++;
    }
    pthread_mutex_unlock(&configMutex);
}

// Function to remove a configuration from the registry
void removeConfiguration(int id) {
    pthread_mutex_lock(&configMutex);
    if (id >= 0 && id < 100 && configRegistry[id] != NULL) {
        free(configRegistry[id]);
        configRegistry[id] = NULL;
        configCount--;
    }
    pthread_mutex_unlock(&configMutex);
}

// Function to fetch a configuration from the registry
FactoryFunction getConfiguration(int id) {
    FactoryFunction factoryFunction = NULL;
    pthread_mutex_lock(&configMutex);
    if (id >= 0 && id < 100 && configRegistry[id] != NULL) {
        factoryFunction = configRegistry[id]->factoryFunction;
    }
    pthread_mutex_unlock(&configMutex);
    return factoryFunction;
}

// Function to filter transactions based on configuration
void filterTransactions(Transaction *transaction) {
