public class ThemeCacheManager {
    private final Map<String, Bitmap> bitmapCache;
    private final Map<String, ThemeMetadata> metadataCache;
    private final LruCache<String, Bitmap> lruBitmapCache;
    private final ExecutorService networkExecutor;
    private final Handler uiHandler;

    public ThemeCacheManager(int maxMemory) {
        int cacheSize = maxMemory / 8; // Assuming bitmap memory is around 8 times the actual size
        bitmapCache = Collections.synchronizedMap(new HashMap<>());
        metadataCache = Collections.synchronizedMap(new HashMap<>());
        lruBitmapCache = new LruCache<>(cacheSize) {
            @Override
            protected int sizeOf(String key, Bitmap value) {
                return value.getByteCount();
            }
        };
        networkExecutor = Executors.newFixedThreadPool(5);
        uiHandler = new Handler(Looper.getMainLooper());
    }

    public void applyTheme(final String themeId) {
        if (metadataCache.containsKey(themeId)) {
            ThemeMetadata metadata = metadataCache.get(themeId);
            Bitmap bitmap = lruBitmapCache.get(themeId);
            if (bitmap == null) {
                networkExecutor.execute(() -> downloadBitmap(themeId));
            } else {
                uiHandler.post(() -> applyThemeToUI(metadata, bitmap));
            }
        } else {
            networkExecutor.execute(() -> fetchThemeData(themeId));
        }
    }

    private void fetchThemeData(final String themeId) {
        // Simulate network request to download theme data
        new Thread(() -> {
            try {
                ThemeMetadata metadata = downloadMetadata(themeId);
                Bitmap bitmap = downloadBitmap(themeId);
                uiHandler.post(() -> {
                    metadataCache.put(themeId, metadata);
                    lruBitmapCache.put(themeId, bitmap);
                    applyThemeToUI(metadata, bitmap);
                });
            } catch (IOException e) {
                handleNetworkError(e);
            }
        }).start();
    }

    private void downloadMetadata(String themeId) throws IOException {
        // Simulate network request to download metadata
        return new ThemeMetadata("Theme 1", "Description for theme 1", System.currentTimeMillis());
    }

    private Bitmap downloadBitmap(String themeId) throws IOException {
