#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

// Function to convert JPEG to PDF and embed metadata
int convertJpegToPdf(const char *inputFile, const char *outputDir, const char *author, const char *title, const char *creationDate) {
    // Check if input file exists
    struct stat buffer; 
    if (stat(inputFile, &buffer) != 0) {
        fprintf(stderr, "Error: Input file does not exist.\n");
        return 1;
    }

    // Check if output directory exists, create if not
    DIR *dir = opendir(outputDir);
    if (!dir) {
        if (mkdir(outputDir, 0755) != 0) {
            fprintf(stderr, "Error: Could not create output directory.\n");
            return 1;
        }
    } else {
        closedir(dir);
    }

    // Construct the output file path
    char outputFilePath[256];
    snprintf(outputFilePath, sizeof(outputFilePath), "%s/%s.pdf", outputDir, inputFile);

    // Command to convert JPEG to PDF and embed metadata (Assuming use of ImageMagick with Ghostscript)
    char command[1024];
    snprintf(command, sizeof(command), "convert -quality 90 %s -pdf %s -metadata author='%s' -metadata title='%s' -metadata creationdate='%s'", inputFile, outputFilePath, author, title, creationDate);

    // Execute the command
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error: Conversion failed.\n");
        return 1;
    }

    printf("Conversion successful. PDF saved at %s\n", outputFilePath);
    return 0;
}

// Example usage
int main() {
    const char *inputFile = "example.jpg";
    const char *outputDir = "output";
    const char *author = "John Doe";
    const char *title = "Sample Document";
    const char *creationDate = "2023-10-05";

    if (convertJpegToPdf(inputFile, outputDir, author, title, creationDate) != 0) {
        fprintf(stderr, "Conversion failed.\n");
        return 1;
    }

    return 0;
}
