using System;
using System.Xml.XPath;
using System.Drawing;

public class XmlParser {
    public static string GetFirstElement(string xml, string name) {
        XPathDocument doc = new XPathDocument(xml);
        XPathNavigator nav = doc.CreateNavigator();

        XPathNodeIterator nodes = nav.Select($"//{name}");

        if (nodes.Count == 0) throw new InvalidOperationException("No element found");
        if (nodes.Count > 1) throw new InvalidOperationException("Multiple elements found");

        return nodes.Current.Value;
    }
}

public class StringModifier {
    public static string AppendSlashIfNotExceeded(string str, int sizeLimit) {
        if (str.Length <= sizeLimit) {
            return str + "/";
        }
        return null;
    }
}
