import os

def parse_tiff_file(file_path):
    with open(file_path, 'rb') as file:
        tif = Image.open(file)

        bits_per_sample = tif.tag_v2.get(258, [])[0]
        sample_per_pixel = tif.tag_v2.get(277, 1)

        if bits_per_sample not in [1, 2, 4, 8, 16]:
            raise ValueError(f"Unsupported bits per sample: {bits_per_sample}")

        return {
            'bits_per_sample': bits_per_sample,
            'sample_per_pixel': sample_per_pixel
        }

def read_and_sort_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        sorted_lines = sorted(lines)

        last_line = sorted_lines[-1]
        sequence_number = int(last_line.split()[0])  # Assuming the first word is a number

        return sequence_number
    except Exception as e:
        print(f"Error reading and sorting file: {e}")
        return None

def parse_env_variables():
    env_vars = {}

    for env_file in ['.env', '.env.local']:
        try:
            with open(env_file, 'r') as file:
                for line in file:
                    key, value = line.strip().split('=')
                    env_vars[key] = value
        except FileNotFoundError:
            continue

    return env_vars
