import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class FileMonitoringSystem {
    private static final String[] CRITICAL_KEYWORDS = {"error", "critical", "warning"};
    private static final String DB_URL = "jdbc:mysql://localhost:3306/logdb";
    private static final String DB_USER = "user";
    private static final String DB_PASSWORD = "password";
    private static final int EMAIL_RETRIES = 3;

    public static void main(String[] args) {
        Set<String> monitoredDirs = Arrays.asList("/path/to/logs/dir1", "/path/to/logs/dir2");
        ExecutorService executor = Executors.newFixedThreadPool(10);
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

        for (String dir : monitoredDirs) {
            Path path = Paths.get(dir);
            try (WatchService watcher = FileSystems.getDefault().newWatchService()) {
                path.register(watcher, StandardWatchEventKinds.ENTRY_CREATE, StandardWatchEventKinds.ENTRY_MODIFY);
                scheduler.scheduleAtFixedRate(() -> processEvents(watcher), 0, 10, TimeUnit.SECONDS);
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        }

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException ie) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }));
    }

    private static void processEvents(WatchService watcher) throws InterruptedException {
        for (;;) {
            WatchKey key;
            try {
                key = watcher.take();
            } catch (InterruptedException x) {
                return;
            }

            List<WatchEvent<?>> events = new ArrayList<>(key.pollEvents());
            boolean valid = false;

            for (WatchEvent<?> event : events) {
                WatchEvent.Kind<?> kind = event.kind();

                if (kind == StandardWatchEventKinds.OVERFLOW) {
                    continue;
                }

                Path filename = (Path) event.context();
                Path filePath = Paths.get(((WatchEvent<Path>) event).context().toString());

                if (!Files.isDirectory(filePath)) {
                    executor.execute(() -> processFile(filePath));
                    valid = true;
                }
            }

            if (valid && !key.reset()) {
                break;
            }
        }
    }

    private static void processFile(Path filePath) {
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            List<String> lines = reader.lines().filter(FileMonitoringSystem::containsCriticalKeyword).collect(Collectors.toList());
            saveToDatabase(lines);
            publishAlerts(lines, filePath.getFileName().toString());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static boolean containsCriticalKeyword(String line) {
        for (String keyword : CRITICAL_KEYWORDS) {
            if (line.toLowerCase().contains(keyword)) {
                return true;
            }
        }
        return false;
    }

    private static void saveToDatabase(List<String> lines) {
        // Implement database save logic here
    }

    private static void publishAlerts(List<String> lines, String filename) {
        // Publish alerts to web dashboard and logging service API here
        sendEmailNotification(filename);
        sendSMSNotification(filename);
        postToCustomAPI(lines, filename);
    }

    private static void sendEmailNotification(String filename) {
        int retries = 0;
        while (retries < EMAIL_RETRIES) {
            try {
                // Send email logic here
                break;
            } catch (Exception e) {
                retries++;
                if (retries == EMAIL_RETRIES) {
                    System.err.println("Failed to send email notification after " + retries + " attempts.");
                }
            }
        }
    }

    private static void sendSMSNotification(String filename) {
        // Send SMS logic here
    }

    private static void postToCustomAPI(List<String> lines, String filename) {
        // Post data to custom API endpoint here
    }
}
