import abc
import json
from typing import Any, Dict, Optional

class ConfigStorageBackend(abc.ABC):
    @abc.abstractmethod
    def get_config(self, key: str) -> bytes:
        pass

    @abc.abstractmethod
    def set_config(self, key: str, value: bytes) -> None:
        pass

class DFSConfigManager:
    def __init__(self, storage_backend: ConfigStorageBackend):
        self.storage_backend = storage_backend
        self.cache = {}

    def get_config(self, key: str) -> Optional[Dict[str, Any]]:
        if key in self.cache:
            return json.loads(self.cache[key])

        try:
            config_bytes = self.storage_backend.get_config(key)
            config = json.loads(config_bytes.decode('utf-8'))
            self.cache[key] = config_bytes
            return config
        except Exception as e:
            print(f"Error retrieving config: {e}")
            return None

    def set_config(self, key: str, value: Dict[str, Any]) -> None:
        try:
            config_bytes = json.dumps(value).encode('utf-8')
            self.storage_backend.set_config(key, config_bytes)
            self.cache[key] = config_bytes
        except Exception as e:
            print(f"Error setting config: {e}")

class NFSStorageBackend(ConfigStorageBackend):
    def get_config(self, key: str) -> bytes:
        # Logic to retrieve configuration from NFS
        pass

    def set_config(self, key: str, value: bytes) -> None:
        # Logic to set configuration in NFS
        pass

class HDFSConfigManager(DFSConfigManager):
    def __init__(self):
        super().__init__(HDFSStorageBackend())

# Example usage
config_manager = DFSConfigManager(NFSStorageBackend())
