use reqwest::header::{HeaderMap, HeaderValue};
use reqwest::Client;
use std::sync::Arc;
use tokio::sync::Mutex;
use redis::{Client as RedisClient, Commands};
use log::{error, info};

struct WeatherClientConfig {
    client_id: String,
    client_secret: String,
    scope: String,
    token_refresh_url: String,
}

struct QueryParams {
    location: String,
    units: String,
    start_date: Option<String>,
    end_date: Option<String>,
}

#[derive(Debug)]
enum WeatherClientError {
    Reqwest(reqwest::Error),
    Redis(redis::RedisError),
    TokenRefreshFailed,
    Other(String),
}

struct TokenCache {
    redis_client: Arc<RedisClient>,
    lock: Mutex<()>,
}

impl TokenCache {
    async fn new(redis_url: &str) -> Result<Self, redis::RedisError> {
        let redis_client = RedisClient::connect(redis_url)?;
        Ok(TokenCache {
            redis_client: Arc::new(redis_client),
            lock: Mutex::new(()),
        })
    }

    async fn get_or_refresh_token(&self, config: &WeatherClientConfig) -> Result<String, WeatherClientError> {
        let mut redis_client = self.redis_client.get_multiplexed_async_connection().await?;
        let token = redis_client.get("weather_token").await.map_err(|e| WeatherClientError::Redis(e))?;

        if let Some(token) = token {
            return Ok(token);
        }

        // Simulate token refresh
        info!("Refreshing token...");
        let client = reqwest::Client::new();
        let response = client.post(&config.token_refresh_url)
            .form(&[
                ("client_id", &config.client_id),
                ("client_secret", &config.client_secret),
                ("scope", &config.scope),
            ])
            .send()
            .await
            .map_err(|e| WeatherClientError::Reqwest(e))?;
        let token = response.json::<serde_json::Value>().await?
            .get("access_token")
            .and_then(|v| v.as_str())
            .ok_or(WeatherClientError::TokenRefreshFailed)?;

        redis_client.set_ex("weather_token", token, 3600).await.map_err(|e| WeatherClientError::Redis(e))?;
        Ok(token.to_string())
    }
}

struct WeatherRequestBuilder {
    client: Client,
    config: WeatherClientConfig,
    cache: TokenCache,
    params: QueryParams,
}

impl WeatherRequestBuilder {
    async fn new(config: WeatherClientConfig, params: QueryParams) -> Result<Self, WeatherClientError> {
        let token_cache = TokenCache::new("redis://127.0.0.1/").await?;
        Ok(WeatherRequestBuilder {
            client: Client::new(),
            config,
            cache: token_cache,
            params,
        })
    }

    async fn build(&self) -> Result<reqwest::RequestBuilder, WeatherClientError> {
        let token = self.cache.get_or_refresh_token(&self.config).await?;
        let mut headers = HeaderMap::new();
        headers.insert("Authorization", HeaderValue::from_str(&format!("Bearer {}", token))?.into());
        Ok(self.client
            .get(format!("https://api.weather.com/forecast?location={}&units={}", self.params.location, self.params.units))
            .headers(headers)
            .query(&[
                ("start_date", self.params.start_date.as_deref().unwrap_or("")),
                ("end_date", self.params.end_date.as_deref().unwrap_or("")),
            ]))
    }

    async fn execute<F>(&self, callback: F) -> Result<(), WeatherClientError>
    where
        F: FnOnce(reqwest::Response) -> (),
    {
        let request = self.build().await?;
        let response = self.client.execute(request).await.map_err(|e| WeatherClientError::Reqwest(e))?;
        if response.status().is_success() {
            callback(response);
        } else {
            error!("Failed to fetch weather data: {:?}", response.status());
            // Handle different types of failures here
        }
        Ok(())
    }
}
