```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_KEY_LENGTH 32

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB
} CipherMode;

void log_activity(const char* message) {
    // Securely log the activity to a file or system logs
    printf("Activity: %s\n", message);
}

int read_config(const char* filename, int* cipher_mode, unsigned char** key) {
    FILE* fp = fopen(filename, "r");
    if (!fp) return -1;

    fscanf(fp, "%d %s", cipher_mode, (char*)key);
    fclose(fp);
    return 0;
}

int write_config(const char* filename, CipherMode mode, const unsigned char* key) {
    FILE* fp = fopen(filename, "w");
    if (!fp) return -1;

    fprintf(fp, "%d %s\n", mode, (const char*)key);
    fclose(fp);
    return 0;
}

int generate_key(unsigned char* key) {
    if (!RAND_bytes(key, MAX_KEY_LENGTH)) return -1;
    return 0;
}

int encrypt_data(CipherMode mode, const unsigned char* key, const unsigned char* plaintext, size_t plaintext_len, unsigned char** ciphertext, size_t* ciphertext_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    *ciphertext_len = 0;

    switch (mode) {
        case ECB:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL)) goto error;
            break;
        case EDE:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_192_cbc(), NULL, key, NULL)) goto error;
            break;
        case EDE3:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, NULL)) goto error;
            break;
        case CFB:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb(), NULL, key, NULL)) goto error;
            break;
    }

    if (!EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) goto error;
    *ciphertext_len += len;

    if (!EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) goto error;
    *ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;

error:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int decrypt_data(CipherMode mode, const unsigned char* key, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char** plaintext, size_t* plaintext_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    *plaintext_len = 0;

    switch (mode) {
        case ECB:
            if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL)) goto error;
            break;
        case EDE:
            if (!EVP_DecryptInit_ex(ctx, EVP_aes_192_cbc(), NULL, key, NULL)) goto error;
            break;
        case EDE3:
            if (!EVP_DecryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, NULL)) goto error;
            break;
        case CFB:
            if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cfb(), NULL, key, NULL)) goto error;
            break;
    }

    if (!EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) goto error;
    *plaintext_len += len;

    if (!EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) goto error;
    *plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;

error:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <mode> <keyfile> <inputfile> <outputfile>\n", argv[0]);
        return 1;
    }

    CipherMode mode = atoi(argv[1]);
    int config_mode;
    unsigned char* key = (unsigned char*)malloc(MAX_KEY_LENGTH);
    if (!key) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 1;
    }

    if (read_config("config.txt", &config_mode, (unsigned char**)&key)) {
        fprintf(stderr, "Failed to read config file\n");
        free(key);
        return 1;
    }

    if (mode != config_mode) {
        fprintf(stderr, "Cipher mode mismatch\n");
        free(key);
        return 1;
    }

    FILE* input = fopen(argv[3], "rb");
    if (!input) {
        fprintf(stderr, "Failed to open input file\n");
        free(key);
        return 1;
    }

    fseek(input, 0, SEEK_END);
    size_t input_size = ftell(input);
    fseek(input, 0, SEEK_SET);

    unsigned char* plaintext = (unsigned char*)malloc(input_size);
    if (!plaintext) {
        fprintf(stderr, "Failed to allocate memory\n");
        fclose(input);
        free(key);
        return 1;
    }

    if (fread(plaintext, 1, input_size, input) != input_size) {
        fprintf(stderr, "Failed to read input file\n");
        free(plaintext);
        fclose(input);
        free(key);
        return 1;
    }

    fclose(input);

    unsigned char* ciphertext = (unsigned char*)malloc(input_size + EVP_CIPHER_block_size(EVP_aes_256_ecb()));
    if (!ciphertext) {
        fprintf(stderr, "Failed to allocate memory\n");
        free(plaintext);
        free(key);
        return 1;
    }

    size_t ciphertext_len;

    if (encrypt_data(mode, key, plaintext, input_size, &ciphertext, &ciphertext_len)) {
        fprintf(stderr, "Encryption failed\n");
        free(ciphertext);
        free(plaintext);
        free(key);
        return 1;
    }

    FILE* output = fopen(argv[4], "wb");
    if (!output) {
        fprintf(stderr, "Failed to open output file\n");
        free(ciphertext);
        free(plaintext);
        free(key);
        return 1;
    }

    if (fwrite(ciphertext, 1, ciphertext_len, output) != ciphertext_len) {
        fprintf(stderr, "Failed to write output file\n");
        fclose(output);
        free(ciphertext);
        free(plaintext);
        free(key);
        return 1;
    }

    fclose(output);

    free(ciphertext);
    free(plaintext);
    free(key);

    return 0;
}
```

This code provides a basic implementation of an AES encryption and decryption tool. It reads the cipher mode, key from a configuration file, and input data from a file, then encrypts or decrypts the data accordingly. The output is written to another file. Note that this example does not include error handling for all possible issues, such as file I/O errors or incorrect key sizes, which should be added in a production environment.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <stdexcept>

class ThreadPool {
public:
    using Task = std::function<void()>;

    ThreadPool(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                for (;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void enqueue(Task task) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.push(std::move(task));
        }
        condition.notify_one();
    }

    size_t activeTasks() const {
        return tasks.size();
    }

private:
    std::vector<std::thread> workers;
    std::queue<Task> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

int main() {
    ThreadPool pool(4);
    for (size_t i = 0; i < 10; ++i) {
        pool.enqueue([i] {
            std::cout << "Task " << i << " is running on thread " << std::this_thread::get_id() << std::endl;
        });
    }
    std::cout << "Active tasks: " << pool.activeTasks() << std::endl;
    return 0;
}
```

This code defines a basic ThreadPool class in C++ that manages a set of worker threads and a shared task queue. The class provides methods for initializing the thread pool, enqueuing tasks, and shutting down the pool safely. It includes basic synchronization mechanisms to ensure thread safety when accessing the task queue.

