struct Cache<T: ApiRequest> {
    requests: HashMap<String, T>,
    cache: HashMap<String, Vec<String>>,
}

impl<T: ApiRequest> Cache<T> {
    fn new() -> Self {
        Cache {
            requests: Default::default(),
            cache: Default::default(),
        }
    }

    async fn get_data(&mut self, endpoint: &str) -> Result<Vec<String>, String> {
        if let Some(data) = self.cache.get(endpoint) {
            return Ok(data.clone());
        }

        if let Some(request) = self.requests.get(endpoint) {
            match request.fetch_data().await {
                Ok(data) => {
                    self.cache.insert(endpoint.to_string(), data.clone());
                    Ok(data)
                }
                Err(e) => Err(e),
            }
        } else {
            Err("Endpoint not found".to_string())
        }
    }
}

