// Load configuration file
const config = JSON.parse(fs.readFileSync(path.join(__dirname, 'config.json'), 'utf8'));

// Middleware for rate limiting
const rateLimit = require('express-rate-limit');
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));

// Middleware for error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Endpoint to fetch weather data
app.get('/weather', async (req, res) => {
  try {
    const { city } = req.query;

    // Fetch weather data from OpenWeatherMap API
    const weatherResponse = await axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${config.openweathermap.apiKey}`);

    // Fetch forecasted weather for the next 7 days
    const forecastResponse = await axios.get(`https://api.openweathermap.org/data/2.5/forecast?q=${city}&cnt=8&appid=${config.openweathermap.apiKey}`);

    res.json({
      currentWeather: weatherResponse.data,
      forecast: forecastResponse.data.list.slice(1)
    });
  } catch (error) {
    console.error(error);
    res.status(500).send('Error fetching weather data');
  }
});

// Endpoint to fetch climate data
app.get('/climate', async (req, res) => {
  try {
    const { location } = req.query;

    // Fetch average temperature statistics for each month over the past year
    const monthlyTempResponse = await axios.get(`https://api.climateapi.com/v1/monthly?location=${location}&year=2023&appid=${config.climate.apiKey}`);

    // Fetch a list of historical climate events
    const eventResponse = await axios.get(`https://api.climateapi.com/v1/events?location=${location}&year=2023&appid=${config.climate.apiKey}`);

    res.json({
      monthlyTemperatures: monthlyTempResponse.data,
      historicalEvents: eventResponse.data
    });
  } catch (error) {
    console.error(error);
    res.status(500).send('Error fetching climate data');
  }
});

// Endpoint to check health of the application and C++ library
app.get('/health', (req, res) => {
  try {
    // Check connection to OpenWeatherMap API
    axios.get(`https://api.openweathermap.org/data/2.5/weather?q=London&appid=${config.openweathermap.apiKey}`).then(() => {
      console.log('OpenWeatherMap API is healthy');
    }).catch(() => {
      console.error('OpenWeatherMap API is not healthy');
    });

    // Check connection to Climate API
    axios.get(`https://api.climateapi.com/v1/monthly?location=London&year=2023&appid=${config.climate.apiKey}`).then(() => {
      console.log('Climate API is healthy');
    }).catch(() => {
      console.error('Climate API is not healthy');
    });

    res.json({ status: 'healthy' });
  } catch (error) {
    console.error(error);
    res.status(500).send('Error checking health of the application and C++ library');
  }
});

// Start server
app.listen(config.port, () => {
  console.log(`Server is running on port ${config.port}`);
});
```

This code sets up a basic Node.js microservice that integrates with OpenWeatherMap and Climate API to fetch weather and climate data for a given location. It includes endpoints to fetch current weather, forecasted weather, average temperature statistics, and historical climate events. The service also has basic error handling and logging mechanisms, as well as a health check endpoint to monitor the status of both the Node.js application and the underlying C++ library.

