```java
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4J;
import io.github.bucket4j.Refill;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.CacheManager;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import java.net.URI;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.List;
import java.util.stream.Collectors;

@Service
public class ClinicStatusUpdater {

    private final RestTemplate restTemplate;
    private final CacheManager cacheManager;
    private final Bucket rateLimiter;

    @Autowired
    public ClinicStatusUpdater(RestTemplate restTemplate, CacheManager cacheManager, Environment environment) {
        this.restTemplate = restTemplate;
        this.cacheManager = cacheManager;
        this.rateLimiter = createRateLimiter(environment.getRateLimit());
    }

    private Bucket createRateLimiter(int limitPerHour) {
        return Bucket4J.builder()
                .addLimit(Refill.intervally(limitPerHour, Duration.ofHours(1)))
                .build();
    }

    @Retryable(value = {Exception.class}, maxAttempts = 3, backoff = @Backoff(delay = 500))
    public void updateClinicStatus(String clinicId, String newStatus, String lastModifiedIp, List<String> externalDataSources, EnvironmentVariables environmentVariables) {
        rateLimiter.tryConsume(1); // Check if the request is allowed

        List<CompletableFuture<Void>> futures = externalDataSources.stream()
                .map(dataSource -> CompletableFuture.runAsync(() -> updateFromDataSource(clinicId, newStatus, lastModifiedIp, dataSource), cacheManager.getNativeCache("async").getExecutor()))
                .collect(Collectors.toList());

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join(); // Wait for all data sources to update
    }

    @Retryable(value = {Exception.class}, maxAttempts = 3, backoff = @Backoff(delay = 500))
    private void updateFromDataSource(String clinicId, String newStatus, String lastModifiedIp, String dataSource) {
        URI uri = constructUri(dataSource);
        HttpHeaders headers = constructHeaders(lastModifiedIp);
        HttpEntity<String> entity = new HttpEntity<>(constructPayload(clinicId, newStatus), headers);

        try {
            restTemplate.postForEntity(uri, entity, String.class);
            cacheManager.getCache("clinicStatuses").put(clinicId, newStatus); // Cache the updated status
        } catch (Exception e) {
            logFailure(dataSource, e);
        }
    }

    private URI constructUri(String dataSource) {
        // Construct the URI based on the data source
        return URI.create("https://api." + dataSource + "/update");
    }

    private HttpHeaders constructHeaders(String lastModifiedIp) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.set("X-Forwarded-For", lastModifiedIp);
        return headers;
    }

    private String constructPayload(String clinicId, String newStatus) {
        // Construct the payload based on the data source's schema
        return "{\"clinic_id\":\"" + clinicId + "\",\"status\":\"" + newStatus + "\"}";
    }

    private void logFailure(String dataSource, Exception e) {
        // Log the failure with detailed information
        System.err.println("Failed to update " + dataSource + ": " + e.getMessage());
    }
}
