#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include "libimageconversion.h"

#define MAX_IMAGES_PER_PDF 100
#define NUM_WORKER_THREADS 4

typedef struct {
    char *input_path;
    char *output_path;
    int max_images_per_pdf;
    int num_worker_threads;
} ConversionTask;

void* convert_image(void *arg) {
    ConversionTask *task = (ConversionTask*) arg;
    // Implement image conversion logic here using libimageconversion
    printf("Converting images in %s\n", task->input_path);
    // Log each image conversion process
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input_directory> <output_directory> <max_images_per_pdf> <num_worker_threads>\n", argv[0]);
        return 1;
    }

    ConversionTask task;
    strcpy(task.input_path, argv[1]);
    strcpy(task.output_path, argv[2]);
    task.max_images_per_pdf = atoi(argv[3]);
    task.num_worker_threads = atoi(argv[4]);

    DIR *dir;
    struct dirent *entry;
    pthread_t threads[NUM_WORKER_THREADS];
    int thread_index = 0;

    if ((dir = opendir(task.input_path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            // Check for image files
            if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg") || 
                strstr(entry->d_name, ".png") || strstr(entry->d_name, ".gif")) {
                if (thread_index == task.num_worker_threads) {
                    for (int i = 0; i < task.num_worker_threads; i++) {
                        pthread_join(threads[i], NULL);
                    }
                    thread_index = 0;
                }
                pthread_create(&threads[thread_index++], NULL, convert_image, &task);
            }
        }
        closedir(dir);
    } else {
        perror("Error opening directory");
        return 1;
    }

    // Wait for all threads to complete
    while (thread_index > 0) {
        pthread_join(threads[--thread_index], NULL);
    }

    printf("Conversion completed successfully\n");
    return 0;
}
```

