#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <limits>
#include <cmath>
#include <ctime>
#include <clog>

// Custom min-max algorithm implementation
void customMinMax(const std::vector<float>& data, float& minVal, float& maxVal) {
    if (data.empty()) {
        throw std::runtime_error("Data vector is empty.");
    }
    minVal = data[0];
    maxVal = data[0];
    for (const auto& val : data) {
        if (val < minVal) minVal = val;
        if (val > maxVal) maxVal = val;
    }
}

// Error handling and logging
void handleError(const std::string& message, const std::string& logFile) {
    std::ofstream logStream(logFile, std::ios::app);
    if (!logStream.is_open()) {
        throw std::runtime_error("Failed to open log file.");
    }
    logStream << std::ctime(&std::time(nullptr)) << "ERROR: " << message << std::endl;
}

// Main function
int main() {
    try {
        const std::string inputFilePath = "sensor_data.txt";
        const std::string outputFilePath = "statistics.txt";
        const std::string logFile = "program_log.txt";

        std::ifstream inputFile(inputFilePath);
        if (!inputFile.is_open()) {
            handleError("Failed to open input file.", logFile);
            return 1;
        }

        std::vector<float> sensorData;
        float value;
        while (inputFile >> value) {
            sensorData.push_back(value);
        }
        inputFile.close();

        if (sensorData.empty()) {
            handleError("No valid data found in the input file.", logFile);
            return 1;
        }

        float minVal, maxVal;
        customMinMax(sensorData, minVal, maxVal);

        std::ofstream outputFile(outputFilePath);
        if (!outputFile.is_open()) {
            handleError("Failed to open output file.", logFile);
            return 1;
        }
        outputFile << "Minimum value: " << minVal << "\n";
        outputFile << "Maximum value: " << maxVal << "\n";
        outputFile.close();

    } catch (const std::exception& e) {
        handleError(e.what(), logFile);
        return 1;
    }

    return 0;
}
```

This code provides a basic structure for the program. It reads sensor data from a file, processes it using a custom min-max algorithm, and writes statistics to another file. Error handling is implemented to manage file operations and data validation. Logging is integrated for error tracking.

