```python
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)

# Mock data for demonstration purposes
departments = {}
employees = {}
projects = {}

def check_dependency(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        # Check if the required resources are available
        return f(*args, **kwargs)
    return wrapper

@app.route('/department/<int:dept_id>', methods=['PUT', 'DELETE'])
@check_dependency
def manage_department(dept_id):
    if request.method == 'PUT':
        data = request.get_json()
        departments[dept_id] = data
        return jsonify({"message": "Department updated"}), 200
    elif request.method == 'DELETE':
        # Implement cascading delete functionality
        for project_id in list(projects.keys()):
            if projects[project_id]['department_id'] == dept_id:
                del projects[project_id]
        del departments[dept_id]
        return jsonify({"message": "Department deleted"}), 200

@app.route('/employee/<int:emp_id>', methods=['PUT'])
@check_dependency
def manage_employee(emp_id):
    data = request.get_json()
    employees[emp_id] = {**employees.get(emp_id, {}), **data}
    return jsonify({"message": "Employee updated"}), 200

@app.route('/project/<int:proj_id>', methods=['PUT', 'DELETE'])
@check_dependency
def manage_project(proj_id):
    if request.method == 'PUT':
        data = request.get_json()
        projects[proj_id] = data
        return jsonify({"message": "Project updated"}), 200
    elif request.method == 'DELETE':
        del projects[proj_id]
        return jsonify({"message": "Project deleted"}), 200

if __name__ == '__main__':
    app.run(debug=True)
