```python
import requests
from cachetools import TTLCache, cached
from datetime import datetime, timedelta

# Define a list of stock market APIs to use
apis = [
    "https://api.example.com/stock/{symbol}",
    "https://api.anotherexample.com/data?ticker={symbol}"
]

# Define a TTL cache with a max size and expiration time
cache = TTLCache(maxsize=100, ttl=3600)

@cached(cache)
def fetch_stock_data(symbol):
    """ Fetch stock data for a given symbol from available APIs """
    for api in apis:
        try:
            response = requests.get(api.format(symbol=symbol))
            response.raise_for_status()
            return response.json()
        except (requests.RequestException, ValueError):
            continue
    raise Exception(f"Failed to fetch stock data for {symbol}")

def get_local_time(stock_data, user_timezone):
    """ Convert stock data timestamp to user's local time """
    utc_timestamp = datetime.strptime(stock_data['timestamp'], "%Y-%m-%dT%H:%M:%S")
    user_offset = timedelta(hours=user_timezone)
    return (utc_timestamp + user_offset).strftime("%Y-%m-%d %H:%M:%S")

def main():
    symbols = ["AAPL", "GOOGL"]
    user_timezone = -5  # Eastern Time
    api_requests = 0
    cache_hits = 0
    cache_misses = 0

    for symbol in symbols:
        try:
            stock_data = fetch_stock_data(symbol)
            api_requests += 1
            if stock_data is not None:
                local_time = get_local_time(stock_data, user_timezone)
                print(f"Symbol: {symbol}, Last Updated: {local_time}")
            else:
                cache_misses += 1
        except Exception as e:
            print(e)

    print(f"API Requests: {api_requests}, Cache Hits: {cache_hits}, Cache Misses: {cache_misses}")

if __name__ == "__main__":
    main()
