import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class NetworkDataFetcher {

    private static final String DEFAULT_CACHE_DIR = "cache";
    private static final long DEFAULT_CACHE_AGE_THRESHOLD = 60000; // 1 minute

    private Map<String, CacheEntry> cache = new HashMap<>();
    private long cacheAgeThreshold;
    private File cacheDir;

    public NetworkDataFetcher(String cacheDir, long cacheAgeThreshold) {
        this.cacheDir = new File(cacheDir);
        this.cacheAgeThreshold = cacheAgeThreshold;
        if (!this.cacheDir.exists()) {
            this.cacheDir.mkdirs();
        }
    }

    public List<FinancialData> fetchAndProcessData(String jsonUrl, List<String> filterCriteria) throws IOException {
        String cachedContent = getCachedContent(jsonUrl);
        if (cachedContent == null || isCacheExpired(cachedContent)) {
            cachedContent = downloadJsonFromServer(jsonUrl);
            cache.put(jsonUrl, new CacheEntry(cachedContent, System.currentTimeMillis()));
        }

        return FilterAndProcessFinancialData(cachedContent, filterCriteria);
    }

    private String getCachedContent(String jsonUrl) {
        File cacheFile = getCacheFile(jsonUrl);
        if (cacheFile.exists()) {
            try (BufferedReader reader = new BufferedReader(new FileReader(cacheFile))) {
                StringBuilder sb = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    sb.append(line);
                }
                return sb.toString();
            } catch (IOException e) {
                // Log error and handle accordingly
            }
        }
        return null;
    }

    private boolean isCacheExpired(String cachedContent) {
        CacheEntry cacheEntry = getCacheEntry(cachedContent);
        if (cacheEntry != null) {
            long timeSinceLastModified = System.currentTimeMillis() - cacheEntry.lastModified;
            return timeSinceLastModified > cacheAgeThreshold;
        }
        return true;
    }

    private String downloadJsonFromServer(String jsonUrl) throws IOException {
        URL url = new URL(jsonUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
            return sb.toString();
        } finally {
            connection.disconnect();
        }
    }

    private CacheEntry getCacheEntry(String cachedContent) {
        if (cachedContent == null || !cachedContent.startsWith("{")) {
            return null;
        }
        try {
            ObjectMapper mapper = new ObjectMapper();
            JsonNode node = mapper.readTree(cachedContent);
            String lastModifiedStr = node.get("last_modified").asText();
            long lastModified = Long.parseLong(lastModifiedStr);
            return new CacheEntry(cachedContent, lastModified);
        } catch (IOException e) {
            // Log error and handle accordingly
        }
        return null;
    }

    private File getCacheFile(String jsonUrl) {
        String fileName = jsonUrl.substring(jsonUrl.lastIndexOf("/") + 1).replace(".json", "") + ".cache";
        return new File(cacheDir, fileName);
    }

    public static List<FinancialData> FilterAndProcessFinancialData(String jsonString, List<String> filterCriteria) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        JsonNode rootNode = mapper.readTree(jsonString);

        List<FinancialData> filteredData = new ArrayList<>();
        for (JsonNode dataNode : rootNode.get("data")) {
            FinancialData data = new FinancialData();
            data.setSymbol(dataNode.path("symbol").asText());
            data.setPrice(dataNode.path("price").asDouble());
            // Process other fields as needed

            if (isFiltered(data, filterCriteria)) {
                filteredData.add(data);
            }
        }

        return filteredData;
    }

    private static boolean isFiltered(FinancialData data, List<String> filterCriteria) {
        for (String criterion : filterCriteria) {
            // Apply filtering logic based on the criterion
            if (!criterion.matches(data.getSymbol())) {
                return false;
            }
        }
        return true;
    }
}

class CacheEntry {
    String content;
    long lastModified;

    public CacheEntry(String content, long lastModified) {
        this.content = content;
        this.lastModified = lastModified;
    }

    // Getters and setters
}

class FinancialData {
    private String symbol;
    private double price;
    // Add other fields as needed

    // Getters and setters
}
