// Import necessary libraries
import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.Pattern;

public class FileProcessor {
    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService executorService;
    private ConcurrentHashMap<String, Integer> keywordCache;
    private ExternalReportingAPI reportingAPI;

    public FileProcessor(ExternalReportingAPI reportingAPI) {
        this.reportingAPI = reportingAPI;
        this.executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        this.keywordCache = new ConcurrentHashMap<>();
    }

    public void processFiles(String directoryPath, Set<String> keywords, String reportFormat) throws IOException {
        // Load keyword patterns into cache
        for (String keyword : keywords) {
            keywordCache.put(keyword, Pattern.compile(Pattern.quote(keyword), Pattern.CASE_INSENSITIVE));
        }

        // Get list of files in the directory
        List<Path> filePaths = Files.walk(Paths.get(directoryPath))
                .filter(Files::isRegularFile)
                .sorted((p1, p2) -> Long.compare(p2.toFile().lastModified(), p1.toFile().lastModified()))
                .toList();

        // Process files asynchronously
        for (Path filePath : filePaths) {
            executorService.submit(() -> {
                try {
                    processFile(filePath, keywords);
                } catch (IOException e) {
                    System.err.println("Error processing file " + filePath + ": " + e.getMessage());
                }
            });
        }

        // Shutdown executor service and wait for completion
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(1, TimeUnit.HOURS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private void processFile(Path filePath, Set<String> keywords) throws IOException {
        BufferedReader reader = null;
        try {
            reader = Files.newBufferedReader(filePath);
            String line;
            StringBuilder report = new StringBuilder();

            while ((line = reader.readLine()) != null) {
                for (String keyword : keywords) {
                    if (keywordCache.get(keyword).matcher(line).find()) {
                        report.append(line).append("\n");
                        break; // Match only the first keyword found per line
                    }
                }
            }

            generateReport(filePath.toString(), report.toString(), keywords, reportFormat);
        } finally {
            if (reader != null) {
                reader.close();
            }
        }
    }

    private void generateReport(String filePath, String content, Set<String> keywords, String format) throws IOException {
        // Implement report generation logic based on the specified format
        // For example, you can create a CSV, JSON, or HTML file and upload it using reportingAPI
        System.out.println("Generating " + format + " report for " + filePath);
    }

    public void close() {
        executorService.shutdown();
    }
}
