from tenacity import retry, stop_after_attempt, wait_exponential

class DataIngestionPipeline:
    def __init__(self):
        self.metadata_service_url = 'http://metadata-service/api'
        self.cache = TTLCache(maxsize=100, ttl=300)
        self.clients = {
            'rest_api': ClientSession(),
            'mqtt_broker': MQTTClient('mqtt-broker'),
            'kafka_topic': AIOKafkaConsumer('topic-name', bootstrap_servers='localhost:9092')
        }

    @retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=1, min=2, max=30))
    async def fetch_data(self, source):
        try:
            if source == 'rest_api':
                async with self.clients['rest_api'].get('http://api.example.com/data') as response:
                    return await response.json()
            elif source == 'mqtt_broker':
                message = await self.clients['mqtt_broker'].receive()
                return json.loads(message.payload)
            elif source == 'kafka_topic':
                async for message in self.clients['kafka_topic']:
                    return json.loads(message.value)
        except Exception as e:
            print(f"Error fetching data from {source}: {e}")
            raise

    async def validate_data(self, data):
        # Implement validation logic against metadata service
        pass

    async def process_data(self, data):
        # Implement data processing logic
        pass

    async def start_pipeline(self):
        await asyncio.gather(
            self.process_source('rest_api'),
            self.process_source('mqtt_broker'),
            self.process_source('kafka_topic')
        )

    async def process_source(self, source):
        while True:
            data = await self.fetch_data(source)
            if await self.validate_data(data):
                await self.process_data(data)

# Usage
pipeline = DataIngestionPipeline()
asyncio.run(pipeline.start_pipeline())
