#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>

#define MAX_THREADS 10

// Function prototypes
int convertJpegToPdf(const char *inputFile, const char *outputFile);
void *threadFunction(void *arg);

typedef struct {
    size_t threadId;
    const char *inputDir;
    const char *outputDir;
    size_t maxPagesPerPdf;
    int numThreads;
} ThreadData;

int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf, int numThreads) {
    DIR *dir = opendir(inputDir);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    pthread_t threads[MAX_THREADS];
    ThreadData threadData[MAX_THREADS];
    size_t threadCount = 0;

    while (threadCount < numThreads && (struct dirent *)dirent *entry = readdir(dir)) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char filePath[256];
        snprintf(filePath, sizeof(filePath), "%s/%s", inputDir, entry->d_name);

        struct stat fileStat;
        if (stat(filePath, &fileStat) != 0) {
            perror("stat");
            closedir(dir);
            return -1;
        }

        if (S_ISDIR(fileStat.st_mode)) {
            continue; // Skip directories
        }

        if (!endsWith(entry->d_name, ".jpg") && !endsWith(entry->d_name, ".jpeg") && !endsWith(entry->d_name, ".png")) {
            continue; // Skip non-image files
        }

        if (threadCount >= numThreads) {
            int ret = pthread_join(threads[threadData[0].threadId], NULL);
            if (ret != 0) {
                perror("pthread_join");
                closedir(dir);
                return -1;
            }
            threadCount--;
        }

        threadData[threadCount].threadId = threadCount;
        threadData[threadCount].inputDir = inputDir;
        threadData[threadCount].outputDir = outputDir;
        threadData[threadCount].maxPagesPerPdf = maxPagesPerPdf;
        threadData[threadCount].numThreads = numThreads;

        if (pthread_create(&threads[threadCount], NULL, threadFunction, &threadData[threadCount]) != 0) {
            perror("pthread_create");
            closedir(dir);
            return -1;
        }

        threadCount++;
    }

    for (size_t i = 0; i < threadCount; i++) {
        int ret = pthread_join(threads[i], NULL);
        if (ret != 0) {
            perror("pthread_join");
            closedir(dir);
            return -1;
        }
    }

    closedir(dir);
    return 0;
}

void *threadFunction(void *arg) {
    ThreadData *data = (ThreadData *)arg;

    DIR *dir = opendir(data->inputDir);
    if (!dir) {
        perror("opendir");
        pthread_exit((void *)-1);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char filePath[256];
        snprintf(filePath, sizeof(filePath), "%s/%s", data->inputDir, entry->d_name);

        struct stat fileStat;
        if (stat(filePath, &fileStat) != 0) {
            perror("stat");
            closedir(dir);
            pthread_exit((void *)-1);
        }

        if (S_ISDIR(fileStat.st_mode)) {
            continue; // Skip directories
        }

        if (!endsWith(entry->d_name, ".jpg") && !endsWith(entry->d_name, ".jpeg") && !endsWith(entry->d_name, ".png")) {
            continue; // Skip non-image files
        }

        char outputFile[256];
        snprintf(outputFile, sizeof(outputFile), "%s/%zu.pdf", data->outputDir, entry->d_name[0]);

        int ret = convertJpegToPdf(filePath, outputFile);
        if (ret != 0) {
            printf("Error converting %s to PDF\n", filePath);
            closedir(dir);
            pthread_exit((void *)-1);
        }
    }

    closedir(dir);
    pthread_exit(NULL);
}

int convertJpegToPdf(const char *inputFile, const char *outputFile) {
    // Call the third-party tool here
    // Example: char command[256];
    // snprintf(command, sizeof(command), "third_party_tool %s -o %s", inputFile, outputFile);
    // return system(command);
    return 0; // Placeholder for conversion logic
}

int endsWith(const char *str, const char *suffix) {
    size_t strLen = strlen(str);
    size_t suffixLen = strlen(suffix);

    if (strLen < suffixLen) {
        return 0;
    }

    return strncmp(str + strLen - suffixLen, suffix, suffixLen) == 0;
}
