    public void uploadAndProcessImage(List<File> imageFiles, boolean isAsync, int timeout) {
        // Validate images and check format/quality standards
        for (File file : imageFiles) {
            if (!isValidImageFormat(file)) {
                logError("Invalid image format: " + file.getName());
                continue;
            }
