            if (isAsync) {
                CompletableFuture<Void> future = CompletableFuture.runAsync(() -> processImage(file, service, timeout));
                handleFuture(future);
            } else {
                processImage(file, service, timeout);
            }
        }

        // Update product details and inventory records
        updateProductDetails(imageFiles);
