import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

class DistributedFileStorage:
    def __init__(self, region_name, access_key_id, secret_access_key):
        self.s3_client = boto3.client('s3', region_name=region_name,
                                       aws_access_key_id=access_key_id,
                                       aws_secret_access_key=secret_access_key)
        self.dynamodb_client = boto3.resource('dynamodb', region_name=region_name,
                                              aws_access_key_id=access_key_id,
                                              aws_secret_access_key=secret_access_key)

    def upload_file(self, file_name, bucket_name):
        try:
            self.s3_client.upload_file(file_name, bucket_name, file_name)
            return True
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return False

    def download_file(self, file_name, bucket_name):
        try:
            self.s3_client.download_file(bucket_name, file_name, file_name)
            return True
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return False

    def delete_file(self, file_name, bucket_name):
        try:
            self.s3_client.delete_object(Bucket=bucket_name, Key=file_name)
            return True
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return False

    def get_file_metadata(self, file_name, bucket_name):
        try:
            response = self.s3_client.head_object(Bucket=bucket_name, Key=file_name)
            return response
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return None

    def list_files(self, bucket_name):
        try:
            files = []
            for file in self.s3_client.list_objects(Bucket=bucket_name)['Contents']:
                files.append(file['Key'])
            return files
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return None

    def create_bucket(self, bucket_name):
        try:
            self.s3_client.create_bucket(Bucket=bucket_name)
            return True
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return False

    def delete_bucket(self, bucket_name):
        try:
            self.s3_client.delete_bucket(Bucket=bucket_name)
            return True
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")
            return False
