// Define DroneManager class
class DroneManager {
private:
    std::vector<Drone*> drones;
    std::queue<SurveyRequest> requests;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addDrone(Drone* drone) { drones.push_back(drone); }
    void submitRequest(const SurveyRequest& request) {
        std::lock_guard<std::mutex> lock(mtx);
        requests.push(request);
        cv.notify_one();
    }

    void processRequests() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !requests.empty(); });
            SurveyRequest request = requests.front();
            requests.pop();

            // Assign drone to the request
            for (Drone* drone : drones) {
                drone->flyTo(request.location);
                for (const std::string& sensor : request.sensors) {
                    drone->captureImage(); // Simplified for example
                }
                drone->streamVideo();
                drone->sendData("Survey data");
                break; // Assign one drone per request for simplicity
            }
        }
    }

    void startProcessing() {
        std::thread t(&DroneManager::processRequests, this);
        t.detach();
    }
};

// Main function
int main() {
    DroneManager manager;
    manager.addDrone(new Drone());
    manager.addDrone(new Drone());

    SurveyRequest request1;
    request1.location = "Location1";
    request1.sensors.push_back("SensorA");
    request1.payloadType = 1;

    SurveyRequest request2;
    request2.location = "Location2";
    request2.sensors.push_back("SensorB");
    request2.payloadType = 2;

    manager.submitRequest(request1);
    manager.submitRequest(request2);

    manager.startProcessing();

    return 0;
}
