#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int id;
    off_t offset;
    int key;
    double avg_offset_key;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* read_file(void* arg) {
    FILE *file = fopen("data.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Record record;
        sscanf(line, "%d %ld %d", &record.id, &record.offset, &record.key);
        record.avg_offset_key = (double)(record.offset + record.key) / 2.0;

        pthread_mutex_lock(&mutex);
        records[record_count++] = record;
        pthread_mutex_unlock(&mutex);
    }

    fclose(file);
    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, read_file, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);

    for (int i = 0; i < record_count; i++) {
        printf("ID: %d, Offset: %ld, Key: %d, Avg: %.2f\n",
               records[i].id, records[i].offset, records[i].key, records[i].avg_offset_key);
    }

    return 0;
}
