#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/bio.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to encrypt data using DES algorithm in ECB mode
int des_ecb_encrypt(const unsigned char *plaintext, int plaintext_len,
                    unsigned char *key, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using DES algorithm in ECB mode
int des_ecb_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                    unsigned char *key, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_des_ecb(), NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Function to combine private key and certificate into a single PEM file
int combine_key_certificate(const char *private_key_path, const char *certificate_path,
                             const char *output_pem_path) {
    FILE *key_file = fopen(private_key_path, "r");
    if (!key_file) return -1;

    FILE *cert_file = fopen(certificate_path, "r");
    if (!cert_file) {
        fclose(key_file);
        return -1;
    }

    FILE *output_file = fopen(output_pem_path, "w");
    if (!output_file) {
        fclose(key_file);
        fclose(cert_file);
        return -1;
    }

    BIO *key_bio = BIO_new(BIO_s_mem());
    BIO *cert_bio = BIO_new(BIO_s_mem());

    PEM_read_PrivateKey(key_file, NULL, NULL, NULL);
    PEM_write_PrivateKey(output_file, key_bio);

    PEM_read_X509(cert_file, NULL, NULL, NULL);
    PEM_write_X509(output_file, cert_bio);

    BIO_free_all(key_bio);
    BIO_free_all(cert_bio);

    fclose(key_file);
    fclose(cert_file);
    fclose(output_file);

    return 0;
}

// Function to dynamically select cipher mode based on input parameters
int select_cipher_mode(const char *mode) {
    if (strcmp(mode, "ECB") == 0) return des_ecb_encrypt;
    else if (strcmp(mode, "CBC") == 0) // Additional modes can be added here
        return -1; // Mode not supported
    else
        return NULL; // Null encryption
}

// Function to handle key retrieval and data transmission with error checking
int handle_key_and_data(const char *key_path, const unsigned char *data, int data_len,
                        void (*encrypt_func)(const unsigned char *, int,
                                             unsigned char *, unsigned char *)) {
    FILE *key_file = fopen(key_path, "r");
    if (!key_file) return -1;

    unsigned char key[8];
    if (fread(key, 1, sizeof(key), key_file) != sizeof(key)) {
        fclose(key_file);
        return -1;
    }

    fclose(key_file);

    unsigned char ciphertext[data_len];
    encrypt_func(data, data_len, key, ciphertext);

    // Data transmission code goes here

    return 0;
}

// User-friendly API function
int des_encrypt(const unsigned char *plaintext, int plaintext_len,
                const char *key_path, const char *mode) {
    void (*encrypt_func)(const unsigned char *, int,
                         unsigned char *, unsigned char *) = select_cipher_mode(mode);
    if (!encrypt_func) return -1; // Null encryption or unsupported mode

    return handle_key_and_data(key_path, plaintext, plaintext_len, encrypt_func);
}

// Test suite code goes here
