// C++ Code Example: OpenSSL Initialization with Error Handling

#include <openssl/evp.h>
#include <openssl/sha.h>
#include <iostream>
#include <fstream>

void initializeCrypto(const std::string& config, const std::string& logFile) {
    try {
        // Initialize OpenSSL library
        if (!EVP_add_cipher(EVP_aes_256_cbc()) || !EVP_add_cipher(EVP_chacha20_poly1305())) {
            throw std::runtime_error("Failed to initialize AES-256 or ChaCha20 cipher");
        }
        if (!SHA256_Init(&sha256_ctx) || !SHA384_Init(&sha384_ctx) || !SHA512_Init(&sha512_ctx)) {
            throw std::runtime_error("Failed to initialize SHA-256, SHA-384, or SHA-512 contexts");
        }

        // Open log file for writing
        log_stream.open(logFile, std::ios::app);
        if (!log_stream.is_open()) {
            throw std::runtime_error("Failed to open log file");
        }
    } catch (const std::exception& e) {
        logError(e.what());
        throw;
    }
}

void logError(const std::string& error) {
    // Write error to log file
    if (log_stream.is_open()) {
        log_stream << "ERROR: " << error << "\n";
        log_stream.flush();
    } else {
        std::cerr << "ERROR: " << error << "\n";
    }
}

// Destructor for cleanup
initializeCrypto::~initializeCrypto() {
    // Clean up OpenSSL resources
    EVP_cleanup();
    if (log_stream.is_open()) {
        log_stream.close();
    }
}
