```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileComparator
{
    private readonly HashSet<string> excludedFileTypes = new HashSet<string> { ".tmp", ".log" };

    public Dictionary<string, Tuple<SHA256HashAlgorithm, SHA256HashAlgorithm>> CompareDirectories(string dir1, string dir2)
    {
        var differences = new Dictionary<string, Tuple<SHA256HashAlgorithm, SHA256HashAlgorithm>>();

        Parallel.ForEach(GetFiles(dir1), file1 =>
        {
            var relativePath = Path.GetRelativePath(dir1, file1);
            var file2 = Path.Combine(dir2, relativePath);

            if (!File.Exists(file2) || excludedFileTypes.Contains(Path.GetExtension(file1)))
                return;

            using (var sha256 = SHA256.Create())
            {
                var checksum1 = CalculateChecksum(sha256, file1);
                var checksum2 = File.Exists(file2) ? CalculateChecksum(sha256, file2) : null;

                if (!checksum1.SequenceEqual(checksum2))
                    differences[relativePath] = Tuple.Create(checksum1, checksum2);
            }
        });

        return differences;
    }

    public byte[] CalculateFileChecksum(SHA256 sha256, string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        {
            return sha256.ComputeHash(stream);
        }
    }

    private IEnumerable<string> GetFiles(string directory)
    {
        try
        {
            return Directory.GetFiles(directory).Concat(Directory.GetDirectories(directory)
                .SelectMany(GetFiles)).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error accessing directory {directory}: {ex.Message}");
            return Enumerable.Empty<string>();
        }
    }

    public void ExcludeFileType(string fileType)
    {
        excludedFileTypes.Add(fileType);
    }
}
