import os
import hashlib
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor
from threading import Lock
import time

# Mocked functions for demonstration purposes
def upload_to_cloud_service(file_name, file_hash, metadata):
    print(f"Uploading {file_name} with hash {file_hash}")

def authenticate_with_cloud_service():
    print("Authenticating with cloud service")

def get_api_rate_limit():
    return 10

class ImageBackupSystem:
    def __init__(self, cloud_storage_url, api_key, max_workers=5):
        self.cloud_storage_url = cloud_storage_url
        self.api_key = api_key
        self.max_workers = max_workers
        self.lock = Lock()
        self.cached_hashes = {}
        self.processed_files = set()

    def process_directory(self, directory_path):
        authenticate_with_cloud_service()
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            for root, _, files in os.walk(directory_path):
                for file_name in files:
                    if file_name not in self.processed_files:
                        file_path = os.path.join(root, file_name)
                        future = executor.submit(self.process_file, file_path)
                        result = future.result()
                        if result:
                            with self.lock:
                                self.cached_hashes[file_name] = result

    def process_file(self, file_path):
        try:
            with open(file_path, 'rb') as file:
                file_hash = hashlib.sha256(file.read()).hexdigest()
                metadata = {
                    "file_name": os.path.basename(file_path),
                    "file_size": os.path.getsize(file_path),
                    "last_modified": datetime.fromtimestamp(os.path.getmtime(file_path)).strftime('%Y-%m-%d %H:%M:%S')
                }
                if self.check_rate_limit():
                    upload_to_cloud_service(metadata["file_name"], file_hash, metadata)
                    self.processed_files.add(metadata["file_name"])
                    return (metadata["file_name"], file_hash)
        except Exception as e:
            print(f"Error processing {file_path}: {e}")
        return None

    def check_rate_limit(self):
        rate_limit = get_api_rate_limit()
        current_time = time.time()
        with self.lock:
            if current_time - self.last_request < 1/rate_limit:
                time.sleep(1/rate_limit)
        self.last_request = current_time
        return True

# Example usage
backup_system = ImageBackupSystem(cloud_storage_url="https://example.com/api", api_key="your_api_key")
backup_system.process_directory("/path/to/images")
