    private int chunkSize;

    public CloudStorageServiceManager(int chunkSize) {
        this.chunkSize = chunkSize;
    }

    public void cloudStorageServiceManager(String filePath, String bucketName, String directoryPath, String service)
            throws IOException, NoSuchAlgorithmException {
        File file = new File(filePath);
        validateFileMetadata(file);

        if (isFilePresentInBucket(bucketName, directoryPath, service)) {
            System.out.println("File already exists in the specified location.");
            return;
        }

        switch (service) {
            case "S3":
                // Implement S3 specific logic here
                break;
            case "Azure Blob Storage":
                // Implement Azure Blob Storage specific logic here
                break;
            case "Google Cloud Storage":
                // Implement Google Cloud Storage specific logic here
                break;
            default:
                throw new IllegalArgumentException("Invalid cloud storage service provided.");
        }

        System.out.println("File uploaded successfully to " + bucketName + "/" + directoryPath);
    }

    private void validateFileMetadata(File file) throws IOException, NoSuchAlgorithmException {
        if (file.length() > 1073741824) { // Check file size
            throw new IllegalArgumentException("File size exceeds the allowed limit.");
        }
        String contentType = org.apache.tika.Tika.detect(file);
        if (!contentType.startsWith("image") && !contentType.equals("application/pdf")) {
            throw new IllegalArgumentException("Unsupported content type.");
        }

        String sha256Hash = calculateSHA256Hash(file);
        if (metadataCache.containsKey(sha256Hash)) {
            System.out.println("File with the same hash already exists in the cache.");
        }
    }

    private boolean isFilePresentInBucket(String bucketName, String directoryPath, String service) throws IOException {
        // Implement logic to check if file is present in the bucket
        return false;
    }

    private String calculateSHA256Hash(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] buffer = new byte[8192];
        int bytesRead;

        try (java.io.FileInputStream fis = new java.io.FileInputStream(file)) {
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }

        return bytesToHex(digest.digest());
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
