public class JWTGenerator {
    public String generateJWT(HttpServletRequest request) throws Exception {
        // Retrieve user credentials from request
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        // Validate user credentials (e.g., against database)
        if (!isValidUser(username, password)) {
            throw new SecurityException("Invalid credentials");
        }

        // Retrieve private key from KMS
        String privateKey = getPrivateKeyFromKMS();

        // Define JWT algorithm and claims
        Algorithm algorithm = Algorithm.RSA256(privateKey);
        return JWT.create()
                .withSubject(username)
                .withClaim("role", getUserRole(username))
                .sign(algorithm);
    }

    private boolean isValidUser(String username, String password) {
        // Implement user validation logic (e.g., database query)
        return true;
    }

    private String getPrivateKeyFromKMS() throws Exception {
        // Retrieve private key from KMS
        Jedis jedis = new Jedis("localhost");
        String privateKey = jedis.get("private_key:" + username);
        jedis.close();
        return privateKey;
    }

    private String getUserRole(String username) {
        // Retrieve user role based on username (e.g., database query)
        return "admin";
    }
}
