import requests
from threading import Lock

class RealTimeStockMiddleware:
    def __init__(self):
        self.stock_data = {}
        self.news_data = {}
        self.cache_lock = Lock()
        self.source = "Alpha Vantage"

    def fetch_stock_quotes(self, symbol):
        with self.cache_lock:
            if symbol in self.stock_data and not expired():
                return self.stock_data[symbol]
            else:
                response = requests.get(f"https://api.example.com/stock/{symbol}")
                data = response.json()
                self.stock_data[symbol] = data
                return data

    def fetch_news(self):
        with self.cache_lock:
            if not expired(self.news_data):
                return self.news_data
            else:
                response = requests.get(f"https://api.example.com/news")
                data = response.json()
                self.news_data = data
                return data

    def update_stock_conditions(self, symbol, new_price):
        with self.cache_lock:
            self.stock_data[symbol]['price'] = new_price

    def __str__(self):
        with self.cache_lock:
            return f"Current Stock Conditions: {self.stock_data}\nSource: {self.source}"

# Example usage
middleware = RealTimeStockMiddleware()
stock_quote = middleware.fetch_stock_quotes("AAPL")
news = middleware.fetch_news()
print(middleware)
