```java
import java.io.BufferedReader;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DataSyncApplication {
    private static final String API_URL = "https://api.example.com/data";
    private static final int CACHE_EXPIRATION_TIME = 60; // in seconds
    private static ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static Cache<String, String> dataCache = new ExpiringCache<>(CACHE_EXPIRATION_TIME);

    public static void main(String[] args) {
        scheduler.scheduleAtFixedRate(DataSyncApplication::syncData, 0, CACHE_EXPIRATION_TIME, TimeUnit.SECONDS);
    }

    private static void syncData() {
        try {
            URL url = new URL(API_URL);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String responseLine;
            StringBuilder response = new StringBuilder();

            while ((responseLine = reader.readLine()) != null) {
                response.append(responseLine);
            }
            reader.close();

            dataCache.put(API_URL, response.toString());
        } catch (IOException e) {
            System.err.println("Error syncing data: " + e.getMessage());
        }
    }

    public static String getData() {
        return dataCache.get(API_URL);
    }

    // Custom caching mechanism with expiration
    private static class ExpiringCache<K, V> extends HashMap<K, V> {
        private final int expirationTime;

        public ExpiringCache(int expirationTime) {
            this.expirationTime = expirationTime;
        }

        @Override
        public V get(Object key) {
            if (containsKey(key)) {
                long currentTime = System.currentTimeMillis();
                long entryTime = ((Entry<K, V>) entrySet().iterator().next()).getValue().timestamp;

                if ((currentTime - entryTime) / 1000 <= expirationTime) {
                    return super.get(key);
                } else {
                    remove(key);
                }
            }
            return null;
        }

        public void put(K key, V value) {
            super.put(key, new CacheEntry<>(value));
        }

        private static class CacheEntry<V> {
            final V value;
            final long timestamp;

            public CacheEntry(V value) {
                this.value = value;
                this.timestamp = System.currentTimeMillis();
            }
        }
    }
}
```

