using System;
using System.Collections.Generic;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class CMSMiddleware
{
    private readonly HttpClient _httpClient;
    private Dictionary<string, ICMSProvider> _cmsProviders;
    private readonly CompressionOptions _compressionOptions;
    private readonly RateLimiter _rateLimiter;

    public CMSMiddleware(CompressionOptions compressionOptions)
    {
        _httpClient = new HttpClient();
        InitializeCMSProviders();
        _compressionOptions = compressionOptions;
        _rateLimiter = new RateLimiter();
    }

    private void InitializeCMSProviders()
    {
        _cmsProviders = new Dictionary<string, ICMSProvider>
        {
            { "WordPress", new WordPressProvider() },
            { "Drupal", new DrupalProvider() },
            { "CustomBuiltCMS", new CustomBuiltCMSProvider() },
            { "Joomla", new JoomlaProvider() },
            { "Magento", new MagentoProvider() }
        };
    }

    public async Task UpdateContentAsync(string cmsType, string endpoint, object content)
    {
        if (!_cmsProviders.ContainsKey(cmsType))
        {
            throw new ArgumentException("Invalid CMS type");
        }

        var provider = _cmsProviders[cmsType];
        var authHeader = await provider.GetAuthenticationHeaderAsync();
        var apiRateLimit = await provider.GetAPIRateLimitAsync();

        try
        {
            if (_rateLimiter.IsRequestAllowed(apiRateLimit))
            {
                var serializedContent = SerializeContent(content);
                var compressedData = CompressData(serializedContent, _compressionOptions.SelectedAlgorithm);

                using (var memoryStream = new MemoryStream(compressedData))
                {
                    var response = await _httpClient.PostAsync(endpoint, new StreamContent(memoryStream));
                    response.EnsureSuccessStatusCode();
                    var transmissionTime = response.Headers.Date.Value - DateTime.UtcNow;
                    LogStatistics(compressionOptions.SelectedAlgorithm, compressedData.Length, transmissionTime);
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            throw;
        }
    }

    private string SerializeContent(object content)
    {
        // Implement serialization logic based on content type (JSON, XML, plain text)
        return JsonConvert.SerializeObject(content);
    }

    private byte[] CompressData(byte[] data, CompressionAlgorithm algorithm)
    {
        switch (algorithm)
        {
            case CompressionAlgorithm.Gzip:
                using (var memoryStream = new MemoryStream())
                using (var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress))
                {
                    gzipStream.Write(data, 0, data.Length);
                    gzipStream.Flush();
                    return memoryStream.ToArray();
                }
            case CompressionAlgorithm.Deflate:
                using (var memoryStream = new MemoryStream())
                using (var deflateStream = new DeflateStream(memoryStream, CompressionMode.Compress))
                {
                    deflateStream.Write(data, 0, data.Length);
                    deflateStream.Flush();
                    return memoryStream.ToArray();
                }
            case CompressionAlgorithm.Lz4:
                return Lz4Codec.Encode(data);
            default:
                throw new ArgumentException("Invalid compression algorithm");
        }
    }

    private void LogStatistics(CompressionAlgorithm algorithm, int compressedSize, TimeSpan transmissionTime)
    {
        Console.WriteLine($"Compression Algorithm: {algorithm}, Compressed Size: {compressedSize} bytes, Transmission Time: {transmissionTime}");
    }

    private void LogError(string message)
    {
        // Implement error logging logic
        Console.Error.WriteLine(message);
    }
}

public interface ICMSProvider
{
    Task<string> GetAuthenticationHeaderAsync();
    Task<int> GetAPIRateLimitAsync();
    // Add other CMS-specific methods
}

// Implement concrete CMS providers (WordPressProvider, DrupalProvider, etc.)

public enum CompressionAlgorithm
{
    Gzip,
    Deflate,
    Lz4
}

public class RateLimiter
{
    private readonly object _lock = new object();
    private Dictionary<string, DateTime> _requestTimes;

    public RateLimiter()
    {
        _requestTimes = new Dictionary<string, DateTime>();
    }

    public bool IsRequestAllowed(int rateLimit)
    {
        lock (_lock)
        {
            var now = DateTime.UtcNow;
            foreach (var requestTime in _requestTimes.Values.ToList())
            {
                if (now - requestTime >= TimeSpan.FromSeconds(1 / rateLimit))
                    _requestTimes.Remove(requestTime);
            }

            if (_requestTimes.Count < rateLimit)
            {
                _requestTimes[now] = now;
                return true;
            }
            else
            {
                return false;
            }
        }
    }
}
