use rustc_driver::{run_compiler, Compilation};
use std::time::{Instant, UNIX_EPOCH};
use sysinfo::{ProcessExt, System, SystemExt};

struct CompilationReport {
    compilation_time: u128,
    resident_set_size_before: usize,
    resident_set_size_after: usize,
    warnings_and_errors: Vec<String>,
    ice_hook_statuses: Vec<bool>,
}

fn compile_rust_files(paths: Vec<&str>) -> Vec<CompilationReport> {
    let mut reports = vec![];
    for path in paths {
        reports.push(compile_single_file(path));
    }
    reports
}

fn compile_single_file(path: &str) -> CompilationReport {
    let start_time = Instant::now();
    let system = System::new();

    // Get resident set size before compilation
    let resident_set_size_before = system.process(std::process::id()).unwrap().memory();

    // Run the compiler
    run_compiler(&path, |_, _, mut sess| {
        sess.target_features.borrow_mut().insert("no-softfloat".to_string());
        Compilation::Continue
    });

    let end_time = Instant::now();
    let compilation_time = end_time.duration_since(start_time).as_millis();

    // Get resident set size after compilation
    let system = System::new();
    let resident_set_size_after = system.process(std::process::id()).unwrap().memory();

    // Handle warnings and errors
    let mut warnings_and_errors = vec![];
    // TODO: Add code to handle warnings and errors

    // Install ice hooks
    let mut ice_hook_statuses = vec![];
    for _ in 0..5 {
        ice_hook_statuses.push(install_ice_hook());
    }

    CompilationReport {
        compilation_time,
        resident_set_size_before,
        resident_set_size_after,
        warnings_and_errors,
        ice_hook_statuses,
    }
}

