// spatial_hash_grid.h

#ifndef SPATIAL_HASH_GRID_H
#define SPATIAL_HASH_GRID_H

#include <vector>
#include <mutex>
#include <thread>
#include <unordered_map>

class SpatialHashGrid {
public:
    struct Point {
        double x, y, z;
        // Other point properties as needed
    };

    struct Bucket {
        std::vector<Point> points;
        std::mutex mutex;

        bool insert(const Point& point) {
            if (points.size() >= max_entries_per_bucket) return false;
            points.push_back(point);
            return true;
        }
    };

    SpatialHashGrid(double cell_size, size_t max_entries_per_bucket)
        : cell_size(cell_size), max_entries_per_bucket(max_entries_per_bucket),
          buckets(100) {} // Initial bucket count

    void insert(const Point& point) {
        size_t hash = get_hash(point);
        std::lock_guard<std::mutex> lock(buckets[hash].mutex);
        if (!buckets[hash].insert(point)) {
            // Handle insertion failure, e.g., expand the grid or rehash
        }
    }

    bool query(double x, double y, double z, double radius) const {
        size_t hash = get_hash(Point{x, y, z});
        std::lock_guard<std::mutex> lock(buckets[hash].mutex);
        for (const auto& point : buckets[hash].points) {
            if ((point.x - x) * (point.x - x) + (point.y - y) * (point.y - y) + (point.z - z) * (point.z - z) <= radius * radius) {
                return true;
            }
        }
        return false;
    }

private:
    double cell_size;
    size_t max_entries_per_bucket;
    std::vector<Bucket> buckets;

    size_t get_hash(const Point& point) const {
        return static_cast<size_t>((point.x / cell_size + 0.5) * 100 +
                                   (point.y / cell_size + 0.5) * 100 +
                                   (point.z / cell_size + 0.5) * 100);
    }
};

#endif // SPATIAL_HASH_GRID_H
```

