    char* baseName = strtok((char*)filename, ".");
    if (baseName == NULL) {
        return "Error: Filename must have an extension";
    }

    char* originalExtension = strtok(NULL, "");
    int digitCount = 0;
    for (int i = 0; filename[i] != '\0'; i++) {
        if (filename[i] >= '0' && filename[i] <= '9') {
            digitCount++;
        }
    }

    const char* newExtension;
    switch (digitCount) {
        case 3:
            newExtension = "jpg";
            break;
        case 4:
            newExtension = "png";
            break;
        default:
            if (digitCount > 0) {
                filename = strndup(filename, 5);
            }
            newExtension = "bmp";
            break;
    }

    char* newFilename = malloc(MAX_FILENAME_LENGTH * sizeof(char));
    if (newFilename == NULL) {
        return "Error: Memory allocation failed";
    }

    sprintf(newFilename, "%s.%s", filename, newExtension);

    // Free dynamically allocated memory
    free((char*)filename);
    free(baseName);

    return newFilename;
}
