```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define NUM_FILES 5
#define MAX_RECORDS 1000

typedef struct {
    int id;
    off_t offset;
    char *key;
    // Additional metadata fields
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
sem_t mutex;
sem_t full;

void* read_file(void* arg) {
    FILE *file = fopen((char*)arg, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Record new_record;
        // Parse line and populate record fields
        sem_wait(&mutex);
        records[record_count++] = new_record;
        if (record_count == MAX_RECORDS) {
            sem_post(&full);
        }
        sem_post(&mutex);
    }

    fclose(file);
    return NULL;
}

int main() {
    pthread_t threads[NUM_FILES];
    sem_init(&mutex, 0, 1);
    sem_init(&full, 0, 0);

    char *file_names[NUM_FILES] = {"file1.txt", "file2.txt", "file3.txt", "file4.txt", "file5.txt"};
    for (int i = 0; i < NUM_FILES; i++) {
        pthread_create(&threads[i], NULL, read_file, file_names[i]);
    }

    for (int i = 0; i < NUM_FILES; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&mutex);
    sem_destroy(&full);

    return 0;
}
