        try (FileReader reader = new FileReader(filePath)) {
            JSONObject jsonObject = (JSONObject) parser.parse(reader);
            return jsonObject;
        } catch (IOException | ParseException e) {
            System.err.println("Error parsing the configuration file: " + e.getMessage());
            return null;
        }
    }
