async fn handle_request(req: Request<Body>, data: Arc<AsyncMutex<Data>>) -> Result<Response<Body>, hyper::Error> {
    let start_time = Instant::now();
    let req_body = hyper::body::to_bytes(req.into_body()).await?;

    let mut data = data.lock().await;
    let image_data = match data.process_image(&req_body) {
        Ok(image_data) => image_data,
        Err(e) => return Ok(Response::builder()
            .status(500)
            .body(Body::from(format!("Error processing image: {}", e)))
            .unwrap()),
    };

    let end_time = start_time.elapsed();
    data.log_execution_details(end_time);

    Ok(Response::builder()
        .status(200)
        .body(Body::from(json!({
            "compressed_data": image_data,
            "execution_time": format!("{:?}", end_time),
        }).to_string()))
        .unwrap())
}

