import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from queue import Queue

def process_images(image_urls, initial_status, callback):
    if not isinstance(image_urls, list):
        raise ValueError("image_urls must be a list")

    results = {}

    def worker(url):
        try:
            response = requests.get(url)
            response.raise_for_status()
            processed_result = callback(response.content)
            return {url: processed_result}
        except Exception as e:
            return {url: f"Error processing image: {str(e)}"}

    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = [executor.submit(worker, url) for url in image_urls]
        for future in as_completed(futures):
            results.update(future.result())

    return results

