```python
import asyncio
from websockets import WebSocketServerProtocol, serve

class ChatService:
    def __init__(self):
        self.rooms = {}

    async def send_message(self, room_id, message):
        if room_id in self.rooms:
            await self.broadcast(room_id, message)

    async def broadcast(self, room_id, message):
        for user_id, websocket in self.rooms[room_id].items():
            try:
                await websocket.send(message)
            except Exception as e:
                print(f"Error sending message to {user_id}: {e}")

class ChatHandler(WebSocketServerProtocol):
    def __init__(self, chat_service):
        super().__init__()
        self.chat_service = chat_service
        self.room_id = None

    async def handle_request(self, user_id, room_id, message):
        if not await self.validate_ids(user_id, room_id):
            return "Permission denied"

        await self.chat_service.send_message(room_id, f"User {user_id}: {message}")
        return "Message sent"

    async def validate_ids(self, user_id, room_id):
        # Placeholder for validation logic
        if user_id not in self.users or room_id not in self.rooms[user_id]:
            return False
        return True

    async def send_confirmation(self, user_id, message):
        try:
            await self.send(f"Message received: {message}")
        except Exception as e:
            print(f"Error sending confirmation to {user_id}: {e}")

    async def send_error(self, error_message):
        try:
            await self.send(error_message)
        except Exception as e:
            print(f"Error sending error message: {e}")

async def handler(websocket, path):
    chat_service = ChatService()
    handler_instance = ChatHandler(chat_service)

    async for message in websocket:
        user_id, room_id, payload = message.split(',')
        response = await handler_instance.handle_request(user_id, room_id, payload)

        if response == "Permission denied":
            await handler_instance.send_error(response)
        else:
            await handler_instance.send_confirmation(user_id, response)

start_server = serve(handler, "localhost", 8765)

asyncio.get_event_loop().run_until_complete(start_server)
asyncio.get_event_loop().run_forever()
```

This code provides a basic structure for handling WebSocket connections in a real-time chat application. It includes error handling, message broadcasting, and a placeholder for room and user validation. The `ChatService` class is responsible for managing the rooms and broadcasting messages, while the `ChatHandler` class handles individual WebSocket connections and communication.

