function updateClinicStatus($clinicId, $ipAddress, $timestamp) {
    // Validate clinic ID
    if (!is_numeric($clinicId)) {
        return "Invalid clinic ID";
    }

    // Validate IP address
    if (filter_var($ipAddress, FILTER_VALIDATE_IP) === false) {
        return "Invalid IP address";
    }

    // Validate timestamp
    if (!is_numeric($timestamp)) {
        return "Invalid timestamp";
    }

    // Update clinic status in the database
    $conn = new mysqli("localhost", "username", "password", "database");
    if ($conn->connect_error) {
        return "Database connection failed: " . $conn->connect_error;
    }

    $sql = "UPDATE clinics SET last_updated_at = ? WHERE id = ?";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("is", $timestamp, $clinicId);

    if ($stmt->execute()) {
        return "Clinic status updated successfully";
    } else {
        return "Error updating clinic status: " . $stmt->error;
    }

    $stmt->close();
    $conn->close();
}
