                return Unauthorized();
            }

            // Update clinic status in the database
            using (SqlConnection conn = new SqlConnection("Server=localhost;Database=database;User Id=username;Password=password")) {
                await conn.OpenAsync();

                string sql = "UPDATE clinics SET last_updated_at = @Timestamp WHERE id = @ClinicId";
                using (SqlCommand cmd = new SqlCommand(sql, conn)) {
                    cmd.Parameters.AddWithValue("@Timestamp", request.Timestamp);
                    cmd.Parameters.AddWithValue("@ClinicId", request.ClinicId);

                    int affectedRows = await cmd.ExecuteNonQueryAsync();
                    if (affectedRows > 0) {
                        return Ok("Clinic status updated successfully");
                    } else {
                        return NotFound("Clinic not found");
                    }
                }
            }
        } catch (Exception ex) {
            _logger.LogError(ex, "Error updating clinic status");
            return StatusCode(500, "Internal server error");
        }
    }
}

public class ClinicStatusUpdateRequest {
    public string ClinicId { get; set; }
    public string IpAddress { get; set; }
    public DateTime Timestamp { get; set; }
}
