import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class PokemonController {

    private final PokeAPIClient pokeAPIClient;
    private final HabitatAPIClient habitatAPIClient;
    private final PokemonRepository pokemonRepository;
    private final CacheManager cacheManager;

    public PokemonController(PokeAPIClient pokeAPIClient, HabitatAPIClient habitatAPIClient, PokemonRepository pokemonRepository, CacheManager cacheManager) {
        this.pokeAPIClient = pokeAPIClient;
        this.habitatAPIClient = habitatAPIClient;
        this.pokemonRepository = pokemonRepository;
        this.cacheManager = cacheManager;
    }

    @GetMapping("/pokemon")
    public PokemonDetails getPokemonDetails(@RequestParam int id) {
        String cachedData = cacheManager.get(id);
        if (cachedData != null) {
            return cacheManager.deserialize(cachedData);
        } else {
            PokemonDetails pokemonDetails = fetchAndCachePokemonDetails(id);
            cacheManager.put(id, cacheManager.serialize(pokemonDetails));
            return pokemonDetails;
        }
    }

    private PokemonDetails fetchAndCachePokemonDetails(int id) {
        PokeAPIResponse pokeAPIResponse = pokeAPIClient.fetchPokemonData(id);
        HabitatAPIResponse habitatAPIResponse = habitatAPIClient.fetchHabitatData(pokeAPIResponse.getHabitat());
        EvolutionChain evolutionChain = pokeAPIResponse.getEvolutionChain();
        List<PokemonType> types = pokeAPIResponse.getTypes();

        // Fetch weaknesses and other details from pokeAPIResponse

        PokemonDetails pokemonDetails = new PokemonDetails();
        pokemonDetails.setName(pokeAPIResponse.getName());
        pokemonDetails.setTypes(types);
        pokemonDetails.setWeaknesses(weaknesses);
        pokemonDetails.setEvolutionChain(evolutionChain);
        pokemonDetails.setHabitat(habitatAPIResponse);

        return pokemonDetails;
    }
}
