import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PokemonService {
    private ExecutorService executorService;
    private Cache cache;

    public PokemonService() {
        this.executorService = Executors.newFixedThreadPool(10);
        this.cache = new Cache();
    }

    public String getPokemonWeaknesses(int id) {
        // Check if the data is already in cache
        String weaknesses = cache.get(id);
        if (weaknesses != null) {
            return weaknesses;
        }

        // Fetch data from external API
        PokemonData pokemonData = fetchFromApi(id);
        if (pokemonData == null) {
            throw new RuntimeException("Failed to fetch data for Pokemon ID: " + id);
        }

        // Store data in cache
        cache.put(id, pokemonData.getWeaknesses());

        return pokemonDataToJson(pokemonData);
    }

    private PokemonData fetchFromApi(int id) {
        try {
            // Code to call external REST API and parse the response
            // Return null if an error occurs or the response is invalid
            return new PokemonData("Pikachu", "Electric", new String[]{"Ground"});
        } catch (Exception e) {
            System.err.println("Error fetching data from API: " + e.getMessage());
            return null;
        }
    }

    private String pokemonDataToJson(PokemonData data) {
        // Code to convert PokemonData object to JSON string
        return "{\"name\":\"" + data.getName() + "\", \"type\":\"" + data.getType() + "\", \"weaknesses\":" + arrayToJson(data.getWeaknesses()) + "}";
    }

    private String arrayToJson(String[] array) {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (int i = 0; i < array.length; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append("\"" + array[i] + "\"");
        }
        sb.append("]");
        return sb.toString();
    }

    private static class Cache {
        private final java.util.Map<Integer, String> cacheMap;

        public Cache() {
            this.cacheMap = new java.util.concurrent.ConcurrentHashMap<>();
        }

        public void put(int id, String weaknesses) {
            cacheMap.put(id, weaknesses);
        }

        public String get(int id) {
            return cacheMap.getOrDefault(id, null);
        }
    }

    private static class PokemonData {
        private final String name;
        private final String type;
        private final String[] weaknesses;

        public PokemonData(String name, String type, String[] weaknesses) {
            this.name = name;
            this.type = type;
            this.weaknesses = weaknesses;
        }

        public String getName() {
            return name;
        }

        public String getType() {
            return type;
        }

        public String[] getWeaknesses() {
            return weaknesses;
        }
    }
}
