    public async Task<XDocument> FetchAndParseAsync(string xmlUrl, string xpathExpression)
    {
        XDocument xmlDoc;

        if (ShouldFetchFromCache(xmlUrl))
        {
            xmlDoc = await LoadXmlFromCache();
        }
        else
        {
            xmlDoc = await FetchXmlFromRemote(xmlUrl);
            CacheXml(xmlDoc);
        }

        try
        {
            var nodeIterator = xmlDoc.CreateNavigator().Select(xpathExpression);
            return new XDocument(new XElement("Results", nodeIterator));
        }
        catch (XPathException ex)
        {
            throw new Exception($"Invalid XPath expression: {xpathExpression}", ex);
        }
    }

    private bool ShouldFetchFromCache(string xmlUrl)
    {
        if (!File.Exists(_cachePath))
        {
            return true;
        }

        _lastCacheUpdate = File.GetLastWriteTime(_cachePath);
        return DateTime.Now - _lastCacheUpdate > _cacheExpiry;
    }

    private async Task<XDocument> FetchXmlFromRemote(string xmlUrl)
    {
        try
        {
            var response = await _httpClient.GetAsync(xmlUrl, HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();
            using (var stream = await response.Content.ReadAsStreamAsync())
            {
                return XDocument.Load(stream);
            }
        }
        catch (HttpRequestException ex)
        {
            throw new Exception($"Failed to fetch XML from remote server: {xmlUrl}", ex);
        }
    }

    private async Task<XDocument> LoadXmlFromCache()
    {
        using (var reader = XmlReader.Create(_cachePath))
        {
            return XDocument.Load(reader);
        }
    }

    private void CacheXml(XDocument xmlDoc)
    {
        using (var writer = new StreamWriter(_cachePath, false))
        {
            xmlDoc.Save(writer);
        }
    }
}
