using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class UserPreferencesCache
{
    private readonly IDistributedCache _distributedCache;
    private readonly IRelationalDatabase _database;
    private readonly int _ttlInMinutes;

    public UserPreferencesCache(IDistributedCache distributedCache, IRelationalDatabase database, int ttlInMinutes)
    {
        _distributedCache = distributedCache ?? throw new ArgumentNullException(nameof(distributedCache));
        _database = database ?? throw new ArgumentNullException(nameof(database));
        _ttlInMinutes = ttlInMinutes;
    }

    public async Task<UserPreferences> GetUserPreferencesAsync(string userId, CancellationToken cancellationToken)
    {
        if (string.IsNullOrEmpty(userId))
            throw new ArgumentException("User ID cannot be null or empty", nameof(userId));

        var cacheKey = $"user-preferences:{userId}";
        try
        {
            var cachedData = await _distributedCache.GetStringAsync(cacheKey, cancellationToken);
            if (!string.IsNullOrEmpty(cachedData))
                return Deserialize(cachedData);

            // Fallback to database in case of cache miss or corruption
            var preferencesFromDb = await _database.GetUserPreferencesAsync(userId, cancellationToken);
            var serializedData = Serialize(preferencesFromDb);
            await _distributedCache.SetStringAsync(cacheKey, serializedData, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(_ttlInMinutes) }, cancellationToken);

            return preferencesFromDb;
        }
        catch (Exception ex)
        {
            // Log the exception and fall back to database
            var preferencesFromDb = await _database.GetUserPreferencesAsync(userId, cancellationToken);
            return preferencesFromDb;
        }
    }

    public async Task PurgeStaleCacheEntriesAsync(CancellationToken cancellationToken)
    {
        var now = DateTimeOffset.UtcNow;
        var ttlThreshold = TimeSpan.FromMinutes(_ttlInMinutes);

        var cacheKeys = await _distributedCache.GetKeysAsync(cancellationToken);
        var keysToRemove = cacheKeys.Where(key => key.StartsWith("user-preferences:") && (now - (await _distributedCache.GetLastAccessedTimeAsync(key, cancellationToken))).TotalMinutes > _ttlInMinutes).ToList();

        foreach (var key in keysToRemove)
            await _distributedCache.RemoveAsync(key, cancellationToken);
    }

    public void InsertAfterForwardList(string[] forwardList, string searchValue, string insertValue)
    {
        if (forwardList == null || !forwardList.Any())
            throw new ArgumentException("Forward list cannot be null or empty", nameof(forwardList));
        if (string.IsNullOrEmpty(searchValue))
            throw new ArgumentException("Search value cannot be null or empty", nameof(searchValue));

        var index = Array.IndexOf(forwardList, searchValue);
        if (index == -1)
            forwardList[forwardList.Length] = insertValue;
        else
            Array.Copy(forwardList, index + 1, forwardList, index + 2, forwardList.Length - index - 1);
            forwardList[index + 1] = insertValue;
    }

    private string Serialize(UserPreferences preferences)
    {
        // Implement serialization logic here
        return string.Empty;
    }

    private UserPreferences Deserialize(string data)
    {
        // Implement deserialization logic here
        return new UserPreferences();
    }
}
