using Microsoft.Extensions.Caching.Distributed;
using System.Threading.Tasks;

public class DistributedCacheAdapter : IDistributedCache
{
    private readonly IDistributedCache _distributedCache;

    public DistributedCacheAdapter(IDistributedCache distributedCache)
    {
        _distributedCache = distributedCache ?? throw new ArgumentNullException(nameof(distributedCache));
    }

    public async Task<string> GetStringAsync(string key, CancellationToken cancellationToken)
    {
        return await _distributedCache.GetStringAsync(key, cancellationToken);
    }

    public async Task SetStringAsync(string key, string value, DistributedCacheEntryOptions options, CancellationToken cancellationToken)
    {
        await _distributedCache.SetStringAsync(key, value, options, cancellationToken);
    }

    public async Task RemoveAsync(string key, CancellationToken cancellationToken)
    {
        await _distributedCache.RemoveAsync(key, cancellationToken);
    }

    public async Task<DateTimeOffset?> GetLastAccessedTimeAsync(string key, CancellationToken cancellationToken)
    {
        return await _distributedCache.GetLastAccessedTimeAsync(key, cancellationToken);
    }

    public async Task<IEnumerable<string>> GetKeysAsync(CancellationToken cancellationToken)
    {
        var keys = new List<string>();
        var cacheEntries = await _distributedCache.GetAllCacheEntriesAsync(cancellationToken);

        foreach (var entry in cacheEntries)
            keys.Add(entry.Key);

        return keys;
    }
}

