const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const redis = require('redis');
const crypto = require('crypto');

const app = express();
app.use(bodyParser.json());
app.use(express.static('public'));

// Connect to Redis for caching
const cacheClient = redis.createClient();

cacheClient.on('error', (err) => {
  console.error(`Redis error: ${err}`);
});

cacheClient.connect().then(() => {
  console.log('Connected to Redis');
}).catch((err) => {
  console.error(`Failed to connect to Redis: ${err}`);
});

// Payment gateway API endpoint
const paymentGatewayUrl = 'https://api.paymentgateway.com/transaction';

// Function to process transactions using the third-party payment gateway API
async function processTransaction(transactionData) {
  try {
    const response = await axios.post(paymentGatewayUrl, transactionData);
    return response.data;
  } catch (error) {
    console.error(`Error processing transaction: ${error.message}`);
    throw error;
  }
}

// Route to handle incoming transactions
app.post('/process-transaction', async (req, res) => {
  const { transactionData } = req.body;

  try {
    // Check if transaction data is valid
    if (!transactionData || !transactionData.amount || !transactionData.method) {
      return res.status(400).json({ error: 'Invalid transaction data' });
    }

    // Cache user preferences for faster access
    const userId = crypto.randomBytes(16).toString('hex');
    await cacheClient.set(userId, JSON.stringify(transactionData.userPreferences));

    // Process the transaction using the third-party payment gateway API
    const result = await processTransaction(transactionData);

    res.json(result);
