function checkPasswordAndConnect(passwordInfo, conn, callbackFn) {
  const { password, connection } = passwordInfo;
  if (!password || !connection.title) {
    return "Error: Password is empty or connection title not set";
  }
  if (typeof callbackFn !== 'function') {
    return "Error: Callback function is not provided";
  }

  try {
    loadAndExecuteScript("scripts/script1.js");
    loadAndExecuteScript("scripts/script2.js");
  } catch (error) {
    console.error("Failed to load or execute script:", error);
  }

  function loadAndExecuteScript(filePath) {
    const script = document.createElement('script');
    script.src = filePath;
    document.head.appendChild(script);

    return new Promise((resolve, reject) => {
      script.onload = resolve;
      script.onerror = (error) => reject(new Error(`Failed to load ${filePath}`));
    });
  }

  callbackFn();
}
