#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    sem_t *sem;
    int initial_value;
    int acquired_count;
} SemaphoreManager;

SemaphoreManager* create_semaphore(const char* name, int initial_value) {
    SemaphoreManager* manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!manager) {
        perror("Failed to allocate memory for semaphore manager");
        return NULL;
    }

    char sem_path[100];
    snprintf(sem_path, sizeof(sem_path), "/sem/%s", name);

    // Create the semaphore
    if ((manager->sem = sem_open(sem_path, O_CREAT, 0666, initial_value)) == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }

    manager->initial_value = initial_value;
    manager->acquired_count = 0;

    return manager;
}

void delete_semaphore(SemaphoreManager* manager) {
    if (manager->sem != SEM_FAILED) {
        sem_close(manager->sem);
        sem_unlink("/sem/"); // Unlink will remove the semaphore
    }
    free(manager);
}

int acquire_semaphore(SemaphoreManager* manager, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (timeout_ms == -1) {
        if (sem_wait(manager->sem) == 0) {
            manager->acquired_count++;
            return 0; // Success
        } else {
            perror("Failed to acquire semaphore");
            return -1;
        }
    } else {
        ts.tv_sec += timeout_ms / 1000;
        ts.tv_nsec += (timeout_ms % 1000) * 1000000;

        if (sem_timedwait(manager->sem, &ts) == 0) {
            manager->acquired_count++;
            return 0; // Success
        } else {
            perror("Failed to acquire semaphore within timeout");
            return -1;
        }
    }
}

int release_semaphore(SemaphoreManager* manager) {
    if (sem_post(manager->sem) == 0) {
        manager->acquired_count--;
        return 0; // Success
    } else {
        perror("Failed to release semaphore");
        return -1;
    }
}

void report_semaphore_metrics(const SemaphoreManager* manager, FILE* log_file) {
    fprintf(log_file, "Semaphore %p acquired %d times\n", (void*)manager->sem, manager->acquired_count);
}
