import java.io.*;
import java.util.*;
import org.yaml.snakeyaml.Yaml;

public class HybridAutomationTool {

    private static final String CONFIG_FILE = "config.yaml";
    private static Map<String, Object> config;
    private static Logger logger;

    public static void main(String[] args) {
        loadConfig(CONFIG_FILE);
        initializeLogger((String) config.get("log_level"));
        deployEnvironment((String) config.get("environment"));
    }

    private static void loadConfig(String filePath) {
        Yaml yaml = new Yaml();
        try (InputStream inputStream = new FileInputStream(filePath)) {
            config = yaml.load(inputStream);
        } catch (IOException e) {
            logger.error("Failed to load configuration file", e);
        }
    }

    private static void initializeLogger(String logLevel) {
        switch (logLevel.toLowerCase()) {
            case "debug":
                logger = new DebugLogger();
                break;
            case "info":
                logger = new InfoLogger();
                break;
            default:
                logger = new ErrorLogger();
        }
    }

    private static void deployEnvironment(String environment) {
        if ("development".equals(environment)) {
            cleanFiles("dev");
        } else if ("staging".equals(environment)) {
            cleanFiles("stage");
        } else if ("production".equals(environment)) {
            cleanFiles("prod");
        } else {
            logger.error("Invalid environment specified: " + environment);
            return;
        }
        executeCommands(environment);
    }

    private static void cleanFiles(String env) {
        String[] files = (String[]) config.get(env + "_files_to_delete");
        for (String file : files) {
            File f = new File(file);
            if (f.exists()) {
                if (!f.delete()) {
                    logger.error("Failed to delete file: " + file);
                } else {
                    logger.info("Deleted file: " + file);
                }
            } else {
                logger.warn("File does not exist: " + file);
            }
        }
    }

    private static void executeCommands(String environment) {
        List<String> commands = (List<String>) config.get(environment + "_commands");
        for (String command : commands) {
            try {
                Process process = Runtime.getRuntime().exec(command);
                process.waitFor();
                logger.info("Command executed successfully: " + command);
            } catch (IOException | InterruptedException e) {
                logger.error("Failed to execute command: " + command, e);
            }
        }
    }

    interface Logger {
        void info(String message);
        void error(String message, Exception e);
        void warn(String message);
    }

    static class DebugLogger implements Logger {
        @Override
        public void info(String message) {
            System.out.println("DEBUG: " + message);
        }

        @Override
        public void error(String message, Exception e) {
            System.err.println("ERROR: " + message);
            e.printStackTrace();
        }

        @Override
        public void warn(String message) {
            System.err.println("WARN: " + message);
        }
    }

    static class InfoLogger implements Logger {
        @Override
        public void info(String message) {
            System.out.println("INFO: " + message);
        }

        @Override
        public void error(String message, Exception e) {
            System.err.println("ERROR: " + message);
            e.printStackTrace();
        }

        @Override
        public void warn(String message) {
            System.err.println("WARN: " + message);
        }
    }

    static class ErrorLogger implements Logger {
        @Override
        public void info(String message) {
            // No-op for error level
        }

        @Override
        public void error(String message, Exception e) {
            System.err.println("ERROR: " + message);
            e.printStackTrace();
        }

        @Override
        public void warn(String message) {
            // No-op for error level
        }
    }
}
