#include <forward_list>
#include <string>
#include <mutex>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            it = list.insert_after(it, value);
            return;
        }
        ++it;
    }

    list.push_back(value);
}
