import java.util.HashMap;
import java.util.Map;
import java.io.Serializable;

public class MicroserviceCache<K extends Serializable, V extends Serializable> {
    private Map<K, V> cache = new HashMap<>();
    private long timeout; // Timeout in milliseconds

    public MicroserviceCache(long timeout) {
        this.timeout = timeout;
    }

    public void put(K key, V value) {
        cache.put(key, value);
        // Start a thread to remove the entry after timeout
        new Thread(() -> {
            try {
                Thread.sleep(timeout);
                cache.remove(key);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }).start();
    }

    public V get(K key) {
        return cache.get(key);
    }

    public void update(K key, V value) {
        if (cache.containsKey(key)) {
            put(key, value); // Re-insert with new timeout
        } else {
            System.out.println("Key not found");
        }
    }

    public void remove(K key) {
        cache.remove(key);
    }

    public void saveToDisk() {
        // Code to serialize the cache to disk
    }

    public void loadFromDisk() {
        // Code to deserialize the cache from disk
    }
}
