```csharp
using System;
using System.Collections.Concurrent;
using UnityEngine;

public class DynamicValueGenerator : IDisposable
{
    private Random random = new Random();
    private ConcurrentDictionary<string, Func<float>> distributionCache = new ConcurrentDictionary<string, Func<float>>();
    private string currentDistributionKey;

    public float MinRange { get; set; }
    public float MaxRange { get; set; }

    public DynamicValueGenerator(float minRange, float maxRange)
    {
        MinRange = minRange;
        MaxRange = maxRange;
        ResetDistribution("Uniform");
    }

    public void ResetDistribution(string distributionType, params object[] parameters)
    {
        string key = $"{distributionType}{string.Join(",", parameters)}";
        Func<float> distribution;

        if (distributionCache.TryGetValue(key, out distribution))
        {
            currentDistributionKey = key;
        }
        else
        {
            distribution = CreateDistribution(distributionType, parameters);
            distributionCache.TryAdd(key, distribution);
            currentDistributionKey = key;
        }
    }

    private Func<float> CreateDistribution(string type, params object[] parameters)
    {
        switch (type.ToLower())
        {
            case "uniform":
                return () => UnityEngine.Random.Range((float)parameters[0], (float)parameters[1]);
            case "gaussian":
                float mean = (float)parameters[0];
                float stdDev = (float)parameters[1];
                return () => UnityEngine.Random.Gaussian(mean, stdDev);
            // Add other distribution types here
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    public float GetRandomFloat()
    {
        if (currentDistributionKey == null)
        {
            ResetDistribution("Uniform");
        }

        Func<float> distribution = distributionCache[currentDistributionKey];
        return MinRange + (distribution() * (MaxRange - MinRange));
    }

    public int GetRandomInt()
    {
        float randomFloat = GetRandomFloat();
        return (int)Math.Round(randomFloat);
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: Range ({MinRange}, {MaxRange}), Current Distribution: {currentDistributionKey}";
    }

    public void Dispose()
    {
        distributionCache.Clear();
    }
}
