// WebSocket Stream Module
const WebSocket = require('ws');
const crypto = require('crypto');

function startWebSocketServer(config) {
  const wss = new WebSocket.Server({ port: config.port });

  wss.on('connection', function connection(ws, req) {
    ws.on('message', function incoming(message) {
      // Real-time data collection
      console.log('Received message:', message);

      // Data filtering based on configuration object
      if (config.filterFunction && !config.filterFunction(message)) return;

      // AES encryption using the Node.js crypto module
      const encryptedMessage = encryptData(message, config.encryptionKey);
      ws.send(encryptedMessage);
    });
  });

  function encryptData(data, key) {
    const iv = crypto.randomBytes(16); // Initialization vector
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
    let encrypted = cipher.update(data);
    encrypted = Buffer.concat([encrypted, cipher.final()]);
    return { iv: iv.toString('hex'), encryptedData: encrypted.toString('hex') };
  }

  return wss;
}

