        this.cache = new ConcurrentHashMap<>();
        this.mapper = new ObjectMapper();
    }

    public void processLogs(List<String> serverUrls, String keywordRegex, String reportTemplate) {
        for (String url : serverUrls) {
            executor.submit(() -> {
                try {
                    downloadLogFiles(url);
                    analyzeLogs(keywordRegex, reportTemplate);
                } catch (IOException e) {
                    LOG.error("Error processing logs from " + url, e);
                }
            });
        }
    }

