    private void analyzeLogs(String keywordRegex, String reportTemplate) throws IOException {
        Pattern pattern = Pattern.compile(keywordRegex, Pattern.CASE_INSENSITIVE);
        for (String fileName : Files.newDirectoryStream(Paths.get("."), "/*.log")) {
            if (!cache.containsKey(fileName)) {
                Path path = Paths.get(fileName);
                try (BufferedReader reader = Files.newBufferedReader(path)) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        Matcher matcher = pattern.matcher(line);
                        if (matcher.find()) {
                            // Process matching lines
                            cache.putIfAbsent(fileName, line);
                        }
                    }
                }
            }
        }
    }

    public void generateReport(String reportFormat) throws IOException {
        String cachedData = cache.toString();
        if (!cachedData.isEmpty()) {
            String summary = generateSummary(cachedData, reportFormat);
            sendReport(summary);
            cache.clear();
        }
    }

    private String generateSummary(String data, String format) throws IOException {
