    private void compressReport(String report) {
        try {
            ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
            switch (compressionAlgorithm) {
                case GZIP:
                    GZIPOutputStream gzipOutputStream = new GZIPOutputStream(byteArrayOutputStream);
                    gzipOutputStream.write(report.getBytes("UTF-8"));
                    gzipOutputStream.close();
                    break;
                case DEFLATE:
                    Deflater deflater = new Deflater();
                    deflater.setInput(report.getBytes("UTF-8"));
                    deflater.finish();
                    byte[] outputBuffer = new byte[1024];
                    while (!deflater.finished()) {
                        int numBytes = deflater.deflate(outputBuffer);
                        byteArrayOutputStream.write(outputBuffer, 0, numBytes);
                    }
                    deflater.end();
                    break;
                default:
                    // No compression
                    byteArrayOutputStream.write(report.getBytes("UTF-8"));
            }

            byte[] compressedData = byteArrayOutputStream.toByteArray();
            // Send compressed data to API
        } catch (IOException e) {
            logger.log(LogLevel.ERROR, "Error compressing report", e);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

enum CompressionAlgorithm {
    GZIP,
    DEFLATE,
    NONE
}

enum LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR
}

class Logger {
    private LogLevel logLevel;

    public Logger(LogLevel logLevel) {
        this.logLevel = logLevel;
    }

    public void log(LogLevel level, String message, Throwable e) {
        if (level.ordinal() >= logLevel.ordinal()) {
            System.out.println("[" + level + "] " + message);
            if (e != null) {
                e.printStackTrace();
            }
        }
    }
}
