async function loadAndRunTests(label, f) {
    try {
        const modulePath = require.resolve(label);
        const testModule = require(modulePath);
        await runTests(testModule, f);
    } catch (error) {
        console.error(`Failed to load or run tests for ${label}:`, error);
        // Fallback mechanism
        await handleFallback(label);
    }
