async function runTests(testModule, f) {
    const forwardList = [];
    for (let i = 0; i < testModule.tests.length; i++) {
        const testFunction = testModule.tests[i];
        try {
            console.log(`Running test ${i + 1}: ${testFunction.name}`);
            await testFunction(blueslip, forwardList);
            blueslip.clear();
            // Log test result to database
            await logTestResult(testFunction.name, 'pass', null);
        } catch (error) {
            console.error(`Test ${i + 1} failed:`, error);
            // Log test result to database with error details
