import asyncio
import hashlib
import aiomysql
import asyncpg
from motor.motor_asyncio import AsyncIOMotorClient

class DatabaseConnector:
    def __init__(self):
        self.cache = {}

    async def connect(self, db_config):
        if 'mysql' in db_config:
            return await aiomysql.connect(**db_config['mysql'])
        elif 'postgresql' in db_config:
            return await asyncpg.connect(**db_config['postgresql'])
        elif 'mongodb' in db_config:
            return AsyncIOMotorClient(**db_config['mongodb'])

    def validate_data(self, data):
        checksum = hashlib.sha256(str(data).encode()).hexdigest()
        # Implement data integrity check logic here
        return checksum

    async def perform_operation(self, connection, operation, data):
        if not self.validate_data(data):
            raise ValueError("Data is invalid")

        if operation in ['insert', 'update', 'delete']:
            if operation == 'insert':
                query = "INSERT INTO table_name (column1, column2) VALUES (%s, %s)"
            elif operation == 'update':
                query = "UPDATE table_name SET column1 = %s WHERE id = %s"
            elif operation == 'delete':
                query = "DELETE FROM table_name WHERE id = %s"

            async with connection.cursor() as cursor:
                await cursor.execute(query, data)
                await connection.commit()
        elif operation == 'query':
            if data['query'] in self.cache:
                return self.cache[data['query']]

            async with connection.cursor() as cursor:
                await cursor.execute(data['query'])
                result = await cursor.fetchall()
                self.cache[data['query']] = result
                return result

    def batch_operations(self, db_config, operation, data_list, batch_size):
        tasks = []
        for i in range(0, len(data_list), batch_size):
            task = asyncio.create_task(self.perform_operation(await self.connect(db_config), operation, data_list[i:i+batch_size]))
            tasks.append(task)

        results = await asyncio.gather(*tasks)
        return [result for sublist in results for result in sublist]

    def retry_operations(self, db_config, operation, data):
        attempts = 3
        for _ in range(attempts):
            try:
                return await self.perform_operation(await self.connect(db_config), operation, data)
            except Exception as e:
                print(f"Operation failed: {e}. Retrying...")
        raise Exception("Operation failed after multiple attempts")

    async def close_connections(self, connections):
        for connection in connections:
            if isinstance(connection, aiomysql.Connection):
                connection.close()
                await connection.wait_closed()
            elif isinstance(connection, asyncpg.Connection):
                await connection.close()
            elif isinstance(connection, AsyncIOMotorClient):
                connection.close()

