using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;
using log4net;

public class XmlParser
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(XmlParser));

    public async Task<XElement> GetFirstElementAsync(string url, string elementName)
    {
        try
        {
            using (var httpClient = new HttpClient())
            {
                var response = await httpClient.GetAsync(url);
                response.EnsureSuccessStatusCode();

                using (var stream = await response.Content.ReadAsStreamAsync())
                {
                    using (var reader = XmlReader.Create(stream))
                    {
                        var navigator = XPathDocument.Create(reader).CreateNavigator();
                        navigator.MoveToFollowing(elementName, string.Empty);

                        if (navigator.CurrentNode != null)
                        {
                            return XElement.Load(navigator);
                        }
                    }
                }
            }

            Log.Warn("Element not found in the XML document.");
        }
        catch (HttpRequestException ex)
        {
            Log.Error($"Network error while fetching the XML document: {ex.Message}");
        }
        catch (XmlException ex)
        {
            Log.Error($"XML parsing error: {ex.Message}");
        }
        catch (Exception ex)
        {
            Log.Error($"Unexpected error: {ex.Message}");
        }

        throw new InvalidOperationException("Element not found in the XML document.");
    }
}
