import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandLogger {

    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static long lastExecutionTime = 0;
    private static int maxRetries = 3;

    public static void main(String[] args) {
        Path logFilePath = Paths.get("log.txt");
        if (Files.exists(logFilePath)) {
            try {
                Files.delete(logFilePath);
            } catch (IOException e) {
                System.err.println("Failed to delete log file: " + e.getMessage());
            }
        }

        String command = "your_command_here";
        executeCommand(command, logFilePath);
    }

    public static void executeCommand(String command, Path logFilePath) {
        long now = System.currentTimeMillis();
        if (now - lastExecutionTime < 1000) { // Example rate limit: 1 command per second
            System.err.println("Rate limit exceeded. Command not executed.");
            return;
        }

        executor.submit(() -> {
            try {
                ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
                processBuilder.redirectErrorStream(true);
                Path tempLogFilePath = Files.createTempFile("command", ".log");
                processBuilder.directory(tempLogFilePath.getParent());
                processBuilder.environment().put("LOG_FILE", tempLogFilePath.toString());

                Process process = processBuilder.start();

                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    logLine(line, Severity.INFO);
                }

                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    retryCommand(command, logFilePath, tempLogFilePath, exitCode);
                } else {
                    Files.move(tempLogFilePath, logFilePath);
                }
            } catch (IOException | InterruptedException e) {
                logLine("Error executing command: " + e.getMessage(), Severity.ERROR);
            }
        });

        lastExecutionTime = now;
    }

    private static void retryCommand(String command, Path logFilePath, Path tempLogFilePath, int exitCode) throws IOException, InterruptedException {
        for (int i = 1; i <= maxRetries; i++) {
            System.out.println("Retrying command (" + i + "/" + maxRetries + ")");
            executeCommand(command, logFilePath);
            break; // Simplified for example purposes
        }

        Files.move(tempLogFilePath, logFilePath);
    }

    public enum Severity {
        INFO, ERROR
    }

    public static void logLine(String message, Severity severity) {
        String timestamp = java.time.LocalDateTime.now().toString();
        System.out.println(timestamp + " [" + severity.name() + "] " + message);
    }
}
