#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to derive key and IV from password and salt using PBKDF2
int derive_key_and_iv(const char *password, const unsigned char *salt, size_t salt_len, unsigned int iterations,
                      unsigned int key_length, unsigned int iv_length, unsigned char *key, unsigned char *iv) {
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, iterations, EVP_sha256(), key_length, key) != 1) {
        fprintf(stderr, "PBKDF2 failed\n");
        return 0;
    }

    memcpy(iv, key + key_length - iv_length, iv_length);
    return 1;
}

// Function to initialize AES-256-CBC cipher
EVP_CIPHER_CTX *init_aes_cipher(const char *password, const unsigned char *salt, size_t salt_len, unsigned int iterations) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create EVP_CIPHER_CTX\n");
        return NULL;
    }

    unsigned char key[32], iv[16];
    if (!derive_key_and_iv(password, salt, salt_len, iterations, 32, 16, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize AES cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to cleanup and disable the cipher
void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
