import time
from collections import defaultdict, deque
import threading
import requests

class ActivityLog:
    def __init__(self, user_id, activity_type, timestamp, device_info):
        self.user_id = user_id
        self.activity_type = activity_type
        self.timestamp = timestamp
        self.device_info = device_info

def process_user_activity_logs(log_stream, settings):
    # Initialize data structures
    user_sessions = defaultdict(list)
    device_metrics = {}
    last_log_time = time.time()

    def log_message(level, message):
        # Implement logging mechanism here
        pass

    def send_alert(device_id, average_time_spent):
        # Integrate with external API for alerts
        try:
            response = requests.post('http://api.example.com/alert', json={'device_id': device_id, 'average_time_spent': average_time_spent})
            if response.status_code != 200:
                log_message('error', f'Failed to send alert: {response.text}')
        except requests.RequestException as e:
            log_message('error', f'Request failed: {e}')

    def update_device_metrics():
        # Update device metrics
        pass

    def persist_metrics_to_database():
        # Persist device metrics to database
        pass

    for log in log_stream:
        if time.time() - log.timestamp > 30:
            continue

        if log.activity_type == 'login' or log.activity_type == 'logout':
            user_sessions[log.user_id].append(log)
            continue

        if log.user_id not in device_metrics:
            device_metrics[log.user_id] = {'total_time': 0, 'activity_count': 0}

        current_session = user_sessions[log.user_id][-1]
        activity_duration = log.timestamp - current_session.timestamp
        device_info = log.device_info

        if device_info is None or not isinstance(device_info, dict):
            log_message('warning', f'Invalid device info for user {log.user_id}')
            continue

        device_id = device_info.get('device_id')
        if device_id is None:
            log_message('warning', f'Device ID missing in device info for user {log.user_id}')
            continue

        device_metrics[log.user_id]['total_time'] += activity_duration
        device_metrics[log.user_id]['activity_count'] += 1

        if time.time() - last_log_time > 60:
            update_device_metrics()
            persist_metrics_to_database()
            last_log_time = time.time()

        if device_metrics[log.user_id]['activity_count'] > 50:
            log_message('warning', f'User {log.user_id} exceeded activity limit')

        if device_metrics[log.user_id]['total_time'] / device_metrics[log.user_id]['activity_count'] > settings['device_threshold']:
            send_alert(device_id, device_metrics[log.user_id]['total_time'] / device_metrics[log.user_id]['activity_count'])

    return device_metrics

# Example usage
settings = {
    'device_threshold': 60,
    'max_activity_logs_per_second': 50,
    'memory_limit': 1024,  # in MB
    'cpu_limit': 0.75  # as a percentage of the CPU core
}

# Simulate a stream of logs
log_stream = [
    ActivityLog('user1', 'login', time.time(), {'device_id': 'deviceA'}),
    ActivityLog('user1', 'activity', time.time() + 5, {'device_id': 'deviceA'}),
    # ... more logs ...
]

result = process_user_activity_logs(log_stream, settings)
print(result)
