class EmailService:
    def send_confirmation_email(self, user_id, new_email):
        msg = MIMEText('Please confirm your new email address.')
        msg['Subject'] = 'Confirm New Email'
        msg['From'] = 'noreply@example.com'
        msg['To'] = new_email
        try:
            with smtplib.SMTP('smtp.example.com') as server:
                server.send_message(msg)
        except Exception as e:
            print(f"Failed to send email: {e}")
            return False
        return True

class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.lock = Lock()
        self.call_times = []

    def limit(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            with self.lock:
                now = time.time()
                self.call_times = [t for t in self.call_times if now - t < self.period]
                if len(self.call_times) >= self.max_calls:
                    sleep_time = self.period - (now - self.call_times[-1])
                    print(f"Rate limit exceeded, retrying in {sleep_time:.2f} seconds.")
                    sleep(sleep_time)
                self.call_times.append(now)
            return func(*args, **kwargs)
        return wrapper

class EmailUpdateService:
    def __init__(self):
        self.dao = EmailDAO()
        self.validator = EmailValidator()
        self.service = EmailService()
        self.rate_limiter = RateLimiter(max_calls=10, period=60)

    @rate_limiter.limit
    def update_user_email(self, user_id, new_email):
        if not self.validator.validate_format(new_email):
            print("Invalid email format")
            return False
        if self.validator.check_uniqueness(new_email):
            print("Email already exists")
            return False
        if not self.validator.verify_domain(new_email):
            print("Domain does not exist")
            return False

        try:
            if self.dao.update_email(user_id, new_email):
                if self.service.send_confirmation_email(user_id, new_email):
                    print("Email updated and confirmation sent successfully")
                    return True
                else:
                    print("Failed to send confirmation email")
            else:
                print("Failed to update user email in database")
        except Exception as e:
            print(f"An error occurred: {e}")
        return False

# Usage example:
