class LogAggregator:
    def __init__(self, max_workers=30):
        self.max_workers = max_workers
        self.semaphore = asyncio.Semaphore(max_workers)

    async def fetch_logs(self, url, protocol='HTTP'):
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as response:
                    if response.status == 200:
                        content_type = response.headers['Content-Type']
                        if 'application/json' in content_type:
                            return await response.json()
                        elif 'text/csv' in content_type:
                            return await response.text(), 'csv'
                        else:
                            return await response.text(), 'plaintext'
                    else:
                        print(f"Failed to fetch logs from {url}, status code: {response.status}")
                        return None, None
        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            print(f"Network error while fetching logs from {url}: {e}")
            return None, None

    async def process_logs(self, url):
        async with self.semaphore:
            content, log_type = await self.fetch_logs(url)
            if content is not None and log_type is not None:
                if log_type == 'json':
                    processed_data = self.process_json(content)
                elif log_type == 'csv':
                    processed_data = self.process_csv(content)
                else:
                    processed_data = self.process_plaintext(content)
                return processed_data
            return None

    def process_json(self, json_content):
