using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public class AvatarService
{
    private readonly ConcurrentDictionary<string, CachedAvatar> _cache = new ConcurrentDictionary<string, CachedAvatar>();
    private readonly HttpClient _httpClient = new HttpClient();

    public async Task UpdateUserAvatarAsync(string userId, string avatarUrl, int resolution)
    {
        if (!_cache.TryGetValue(userId, out var cachedAvatar) || !cachedAvatar.IsUpToDate(resolution))
        {
            try
            {
                var imageBytes = await DownloadAvatarImageAsync(avatarUrl);
                var avatarData = new AvatarData(imageBytes, resolution);

                _cache.TryUpdate(userId, new CachedAvatar(avatarData), cachedAvatar ?? new CachedAvatar());
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to update avatar for user {userId}: {ex.Message}");
            }
        }

        // Apply user-specific customizations and update user profile
    }

    private async Task<byte[]> DownloadAvatarImageAsync(string url)
    {
        try
        {
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsByteArrayAsync();
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Failed to download avatar from {url}: {ex.Message}");
            throw;
        }
    }

    private class CachedAvatar
    {
        public AvatarData Data { get; }
        public DateTime LastUpdated { get; } = DateTime.UtcNow;

        public CachedAvatar(AvatarData data)
        {
            Data = data;
        }

        public bool IsUpToDate(int resolution)
        {
            return Data.Resolution == resolution && DateTime.UtcNow - LastUpdated < TimeSpan.FromMinutes(10);
        }
    }

    private class AvatarData
    {
        public byte[] ImageBytes { get; }
        public int Resolution { get; }

        public AvatarData(byte[] imageBytes, int resolution)
        {
            ImageBytes = imageBytes;
            Resolution = resolution;
        }
    }
}
