#include <stdio.h>
#include <stdlib.h>

// Define the Node structure for linked list
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Function to create a new node with given value
Node* create_node(int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->value = value;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new node at the end of the linked list
void insert_node(Node** head, int value) {
    Node* newNode = create_node(value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

// Function to find the maximum value in the linked list
int find_max(Node* head) {
    int max_value = INT_MIN;
    Node* temp = head;
    while (temp != NULL) {
        if (temp->value > max_value) {
            max_value = temp->value;
        }
        temp = temp->next;
    }
    return max_value;
}

// Function to free the allocated memory of the linked list
void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int limit = 1024 * 1024; // 1MB memory limit
    Node* head = NULL;

    printf("Enter integers (non-integer to stop input):\n");

    while (1) {
        char buffer[100];
        fgets(buffer, sizeof(buffer), stdin);
        int value;
        if (sscanf(buffer, "%d", &value) == 1) {
            insert_node(&head, value);
            limit -= sizeof(Node); // Assuming each node is approximately this size
        } else if (feof(stdin)) {
            break; // Ctrl+D on Unix/Linux or Ctrl+Z followed by Enter on Windows
        } else {
            fprintf(stderr, "Invalid input\n");
        }
        if (limit <= 0) {
            fprintf(stderr, "Memory limit exceeded\n");
            free_list(head);
            return 1;
        }
    }

    int max_value = find_max(head);
    printf("Maximum value: %d\n", max_value);

    free_list(head);
    return 0;
}
