// JavaScript module loading and testing function
function loadAndTestModule(modulePath) {
    try {
        const module = import(modulePath);
        module.then((module) => {
            console.log(`Loaded module: ${module.name}`);
            Object.keys(module).forEach(key => {
                if (typeof module[key] === 'function') {
                    const testName = `test_${key}`;
                    console.log(`Running test: ${testName}`);
                    try {
                        module[key]();
                        console.log(`${testName} passed.`);
                    } catch (error) {
                        console.error(`${testName} failed with error: ${error.message}`);
                    }
                }
            });
        }).catch((error) => {
            console.error(`Failed to load module: ${modulePath}. Error: ${error.message}`);
        });
    } catch (e) {
        console.error(`Error in loading and testing the module: ${e.message}`);
    }
}
