int dynamicStringCopy(char *dest, size_t destSize, const char *src) {
    if (dest == NULL || src == NULL || destSize <= 0) {
        logMessage("Invalid input parameters");
        return -1;
    }

    // Calculate the length of the source string
    size_t srcLength = strlen(src);

    // Determine the number of characters to copy
    size_t numCharsToCopy = (srcLength < destSize - 1) ? srcLength : destSize - 1;

    // Copy the characters and ensure null-termination
    strncpy(dest, src, numCharsToCopy);
    dest[numCharsToCopy] = '\0';

    // Check for truncation
    if (numCharsToCopy == destSize - 1 && srcLength >= destSize - 1) {
        logMessage("String was truncated");
        logMessage("Original length: ");
        logMessage(srcLength);
        logMessage("Truncated length: ");
        logMessage(destSize - 1);
    }

    // Return the number of characters copied including the null terminator
    return numCharsToCopy + 1;
}

// Example usage
int main() {
    char buffer[50];
    const char *source = "This is a very long string that may cause truncation if not handled properly.";

    int result = dynamicStringCopy(buffer, sizeof(buffer), source);
    printf("Copied %d characters: '%s'\n", result, buffer);

    return 0;
}
