#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_KEY_LENGTH 32

typedef enum {
    AES_ECB,
    AES_CBC,
    AES_CTR,
    CHACHA20
} CipherMode;

void init_crypto_library() {
    // Initialize OpenSSL library for cryptographic operations
}

EVP_CIPHER* get_cipher(CipherMode mode) {
    switch (mode) {
        case AES_ECB: return EVP_aes_256_ecb();
        case AES_CBC: return EVP_aes_256_cbc();
        case AES_CTR: return EVP_aes_256_ctr();
        case CHACHA20: return EVP_chacha20_poly1305();
        default: return NULL;
    }
}

int encrypt_file(const char* input, const char* output, CipherMode mode, unsigned char* key) {
    FILE *in = fopen(input, "rb");
    if (!in) return -1;

    FILE *out = fopen(output, "wb");
    if (!out) {
        fclose(in);
        return -2;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fclose(in);
        fclose(out);
        return -3;
    }

    if (1 != EVP_EncryptInit_ex(ctx, get_cipher(mode), NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(in);
        fclose(out);
        return -4;
    }

    unsigned char buffer[4096];
    int len, written;
    while (1) {
        if (!fread(buffer, 1, sizeof(buffer), in)) break;
        if (1 != EVP_EncryptUpdate(ctx, buffer, &len, buffer, sizeof(buffer))) {
            EVP_CIPHER_CTX_free(ctx);
            fclose(in);
            fclose(out);
            return -5;
        }
        if (fwrite(buffer, 1, len, out) != len) {
            EVP_CIPHER_CTX_free(ctx);
            fclose(in);
            fclose(out);
            return -6;
        }
    }

    if (!EVP_EncryptFinal_ex(ctx, buffer, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(in);
        fclose(out);
        return -7;
    }

    fwrite(buffer, 1, len, out);

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);

    return 0;
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <mode> <key>\n", argv[0]);
        return -1;
    }

    CipherMode mode = AES_ECB; // Default to AES-ECB
    char* input_file = argv[1];
    char* output_file = argv[2];

    if (strcmp(argv[3], "AES_CBC") == 0) mode = AES_CBC;
    else if (strcmp(argv[3], "AES_CTR") == 0) mode = AES_CTR;
    else if (strcmp(argv[3], "CHACHA20") == 0) mode = CHACHA20;

    unsigned char key[MAX_KEY_LENGTH];
    if (strlen(argv[4]) > MAX_KEY_LENGTH * 2) {
        fprintf(stderr, "Key length exceeds maximum allowed\n");
        return -1;
    }
    int ret = sscanf(argv[4], "%hhx%hhx%hhx%hhx", &key[0], &key[1], &key[2], &key[3]);
    if (ret != 4) {
        fprintf(stderr, "Invalid key format\n");
        return -1;
    }

    init_crypto_library();
    int result = encrypt_file(input_file, output_file, mode, key);
    if (result != 0) {
        fprintf(stderr, "Encryption failed with error code: %d\n", result);
        return -1;
    }

    return 0;
}
```

This C code provides a basic framework for a cryptographic library supporting AES-ECB, AES-CBC, AES-CTR, and ChaCha20. It includes error handling and a simple command-line interface for specifying the input file, output file, cipher mode, and key. The `encrypt_file` function demonstrates how to use OpenSSL's EVP API for encryption operations.

