public class XmlParser
{
    public XPathNavigator GetSingleElement(string xml, string xpath)
    {
        var doc = new XPathDocument(xml);
        var nav = doc.CreateNavigator();
        var nodes = nav.Select(xpath);

        if (nodes.Count != 1)
            throw new InvalidOperationException($"Expected single element but found {nodes.Count}");

        return nodes.Current;
    }
}

public class StringModifier
{
    public string AppendSlashIfUnderLimit(string input, int sizeLimit)
    {
        if (input.Length >= sizeLimit)
            return null;

        return input + "/";
    }
}
