async function robustReduce(arr, reducer, initialValue) {
  const chunkSize = Math.ceil(arr.length / 4); // Process in chunks of 4 for performance optimization
  let accumulator = initialValue;

  for (let i = 0; i < arr.length; i += chunkSize) {
    try {
      const chunk = arr.slice(i, i + chunkSize);
      const currentNumber = await externalService.fetchCurrentNumber();
      accumulator = chunk.reduce(reducer, accumulator * currentNumber); // Real-time data fetching
    } catch (error) {
      console.error(`Failed to fetch data or process chunk: ${error}`);
      // Retry mechanism can be implemented here if needed
    }
  }

  return accumulator;
}
