public class DisjointPairFinder {

    private static final int MAX_NODES = 1_000_000;
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java DisjointPairFinder <input-file>");
            return;
        }

        try {
            int[] array = readArrayFromFile(args[0]);
            findDisjointPairs(array);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static int[] readArrayFromFile(String filePath) throws Exception {
        // Implement file reading logic here
        return new int[]{};
    }

    public static void findDisjointPairs(int[] array) {
        if (array == null || array.length == 0) {
            throw new IllegalArgumentException("Input array cannot be null or empty.");
        }
        if (array.length > MAX_NODES) {
            throw new IllegalArgumentException("Array size exceeds maximum allowed nodes.");
        }

        UnionFind uf = new UnionFind(array.length);

        long startTime, endTime;

        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                startTime = System.currentTimeMillis();
                if (!uf.isDisjoint(array[i], array[j])) {
                    uf.union(array[i], array[j]);
                }
                endTime = System.currentTimeMillis();

                long elapsedTime = endTime - startTime;
                System.out.println("Pair (" + array[i] + ", " + array[j] + ") took " + elapsedTime + " milliseconds.");
            }
        }

        // Clean up resources
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    static class UnionFind {
        private int[] parent;
        private boolean[] compressed;

        public UnionFind(int size) {
            parent = new int[size];
            compressed = new boolean[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                compressed[i] = false;
            }
        }

        public boolean isDisjoint(int a, int b) {
            return find(a) != find(b);
        }

        public void union(int a, int b) {
            int rootA = find(a), rootB = find(b);
            if (rootA == rootB) return;

            if (!compressed[rootA] && !compressed[rootB]) {
                if (rootA < rootB) {
                    parent[rootB] = rootA;
                    compressed[rootA] = true;
                } else {
                    parent[rootA] = rootB;
                    compressed[rootB] = true;
                }
            } else {
                int newRoot = (compressed[rootA] ? rootA : rootB);
                int oldRoot = (compressed[rootA] ? rootB : rootA);

                executor.submit(() -> {
                    while (parent[oldRoot] != oldRoot) {
                        int temp = parent[oldRoot];
                        parent[oldRoot] = newRoot;
                        oldRoot = temp;
                    }
                    parent[oldRoot] = newRoot;
                });
            }
        }

        private int find(int x) {
            if (x != parent[x]) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }
}
