import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.util.concurrent.*;
import java.util.regex.Pattern;

public class LogProcessingModule {
    private ExecutorService executor;
    private ConcurrentHashMap<String, String> reportCache;
    private ScheduledExecutorService scheduler;

    public LogProcessingModule() {
        this.executor = Executors.newFixedThreadPool(10);
        this.reportCache = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(2);
        setupCaching();
    }

    private void setupCaching() {
        scheduler.scheduleAtFixedRate(() -> {
            // Periodically clean up cache entries that haven't been accessed in a while
            reportCache.entrySet().removeIf(entry -> System.currentTimeMillis() - entry.getValue().lastAccessed > 60000);
        }, 0, 30, TimeUnit.MINUTES);
    }

    public void processLog(String serverURL, String logFile, String regex) {
        executor.submit(() -> {
            try {
                URL url = new URL(serverURL + "/" + logFile);
                BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    if (Pattern.compile(regex).matcher(line).find()) {
                        // Process matching lines
                        processMatchingLine(line, serverURL, logFile);
                    }
                }
            } catch (Exception e) {
                handleProcessingError(e, serverURL, logFile);
            }
        });
    }

    private void processMatchingLine(String line, String serverURL, String logFile) {
        // Generate report for matching line
        String report = generateReport(line, serverURL, logFile);

        // Cache the report to reduce redundant file reads
        reportCache.put(report, new ReportEntry(System.currentTimeMillis()));

        // Send report to external API
        sendReportToAPI(report);
    }

    private String generateReport(String line, String serverURL, String logFile) {
        try {
            Process process = Runtime.getRuntime().exec("detailed_insight_command " + line + " " + serverURL + " " + logFile);
            return new BufferedReader(new InputStreamReader(process.getInputStream())).readLine();
        } catch (Exception e) {
            handleReportGenerationError(e, line, serverURL, logFile);
            return null;
        }
    }

    private void sendReportToAPI(String report) {
        try {
            // Send report to external API
        } catch (Exception e) {
            handleAPISendError(e, report);
        }
    }

    private void handleProcessingError(Exception e, String serverURL, String logFile) {
        // Log and audit processing error
    }

    private void handleReportGenerationError(Exception e, String line, String serverURL, String logFile) {
        // Log and audit report generation error
    }

    private void handleAPISendError(Exception e, String report) {
        // Log and audit API send error
    }

    static class ReportEntry {
        long lastAccessed;

        public ReportEntry(long lastAccessed) {
            this.lastAccessed = lastAccessed;
        }
    }
}
