#include <memory>

namespace fs = std::filesystem;
using json = nlohmann::json;

class ConfigManager {
public:
    using ConfigMap = std::unordered_map<std::string, std::variant<int, double, std::string, bool>>;
    using MutexGuard = std::lock_guard<std::mutex>;

    static ConfigMap LoadConfig(const fs::path& configPath, const std::string& environment) {
        static std::mutex cacheMutex;
        auto pathWithEnv = GetEnvironmentFilePath(configPath, environment);
        MutexGuard guard(cacheMutex);

        if (cache.count(pathWithEnv)) {
            return cache[pathWithEnv];
        }

        ConfigMap config;
        try {
            json j = LoadJsonFile(pathWithEnv);
            FlattenJson(j, "", config);
            ValidateConfig(config, GetSchema(environment));
            cache[pathWithEnv] = config;
        } catch (const std::exception& e) {
            LogError("Failed to load configuration for " + environment + ": " + e.what());
            // Fallback to default values or throw an exception
            return {};
        }

        LogInfo("Configuration loaded successfully for " + environment);
        return config;
    }

private:
    static std::string GetEnvironmentFilePath(const fs::path& basePath, const std::string& environment) {
        return basePath / (environment + ".json");
    }

    static json LoadJsonFile(const fs::path& path) {
        if (!fs::exists(path)) {
            throw std::runtime_error("File does not exist: " + path.string());
        }
        std::ifstream file(path);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file: " + path.string());
        }
        return json::parse(file);
    }

    static void FlattenJson(const json& j, const std::string& prefix, ConfigMap& config) {
        for (const auto& [key, value] : j.items()) {
            std::string fullKey = prefix.empty() ? key : prefix + "." + key;
            if (value.is_object()) {
                FlattenJson(value, fullKey, config);
            } else if (value.is_array()) {
                throw std::runtime_error("Array values are not supported");
            } else {
                config[fullKey] = value.get<std::variant<int, double, std::string, bool>>();
            }
        }
    }

    static json GetSchema(const std::string& environment) {
        // Load or generate the schema based on the environment
        return json();
    }

    static void ValidateConfig(const ConfigMap& config, const json& schema) {
        // Implement validation logic here
    }

    static void LogInfo(const std::string& message) {
        // Log informational messages
    }

    static void LogError(const std::string& message) {
        // Log error messages
    }

    static constexpr int MaxConcurrentReads = 10;
    static int currentReads;

    static ConfigMap cache;
    static std::mutex resourceMutex;
};

ConfigManager::ConfigMap ConfigManager::cache;
std::mutex ConfigManager::resourceMutex;
int ConfigManager::currentReads = 0;

// Example usage
int main() {
    try {
        auto config = ConfigManager::LoadConfig("config", "DEV");
        // Use the configuration...
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
