import threading
from queue import Queue, LifoQueue
from time import sleep
import datetime
import requests

class OrderBook:
    def __init__(self):
        self.book = LifoQueue()

    def add_order(self, order_id, symbol, price, quantity, timestamp, source_api, order_type, metadata):
        if isinstance(price, float) and isinstance(quantity, int) and isinstance(timestamp, datetime.datetime) and isinstance(symbol, str) and isinstance(metadata, dict):
            self.book.put({'order_id': order_id, 'symbol': symbol, 'price': price, 'quantity': quantity, 'timestamp': timestamp, 'source_api': source_api, 'order_type': order_type, 'metadata': metadata})
        else:
            raise ValueError("Invalid data types for order book entry")

    def get_order(self):
        return self.book.get()

class HFTAlgorithm:
    def __init__(self, api_configs, cache_policy):
        self.order_book = OrderBook()
        self.api_configs = api_configs
        self.cache_policy = cache_policy
        self.api_locks = [threading.Lock() for _ in range(len(api_configs))]

    def fetch_data(self, url, params):
        try:
            response = requests.get(url, params=params)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"API Error: {e}")
            return None

    def update_order_book(self, order_id, symbol, price, quantity, timestamp, source_api, order_type, metadata):
        with self.api_locks[self.api_configs.index(source_api)]:
            # Implement logic to fetch and parse data from API
            data = self.fetch_data(self.api_configs[source_api]['url'], self.api_configs[source_api]['params'])
            if data:
                for item in data['orders']:
                    if item['order_id'] == order_id:
                        self.order_book.add_order(item['order_id'], symbol, price, quantity, timestamp, source_api, order_type, metadata)

    def process_orders(self):
        while True:
            order = self.order_book.get()
            # Implement logic to process the order
            print(f"Processing order: {order}")
            sleep(0.1)  # Simulate processing time

    def start_algorithm(self):
        threads = []
        for i in range(len(self.api_configs)):
            thread = threading.Thread(target=self.update_order_book, args=(i, 'AAPL', 150.75, 100, datetime.datetime.now(), 'api1.com', 'buy', {'source': 'api1'}))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

# Example usage
api_configs = [
    {'url': 'http://api1.com/orders', 'params': {'key': 'value1'}},
    {'url': 'http://api2.com/orders', 'params': {'key': 'value2'}}
]
cache_policy = {
    'max_size': 1000,
    'expiration_time': 3600
}
hft_algorithm = HFTAlgorithm(api_configs, cache_policy)
hft_algorithm.start_algorithm()
