#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_PROCESSES 1000
#define MAX_COMMAND_LENGTH 256
#define LOG_FILE "process_log.txt"

typedef struct {
    char command[MAX_COMMAND_LENGTH];
    pid_t pid;
    int status;
} Process;

Process processes[MAX_PROCESSES];
int process_count = 0;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void* run_command(void* arg) {
    int index = *(int*)arg;
    if (processes[index].pid == -1) {
        perror("Failed to create child process");
        return NULL;
    }

    int status;
    waitpid(processes[index].pid, &status, 0);
    processes[index].status = WEXITSTATUS(status);

    pthread_mutex_lock(&log_mutex);
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "Command '%s' exited with status %d\n", processes[index].command, processes[index].status);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
    pthread_mutex_unlock(&log_mutex);

    processes[index].pid = -1;
    process_count--;

    return NULL;
}

void load_commands_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return;
    }

    char command[MAX_COMMAND_LENGTH];
    while (fgets(command, sizeof(command), file)) {
        command[strcspn(command, "\n")] = 0; // Remove newline character

        int index = process_count++;
        if (index >= MAX_PROCESSES) {
            fprintf(stderr, "Too many processes. Increase MAX_PROCESSES.\n");
            break;
        }

        processes[index].pid = fork();
        if (processes[index].pid == -1) {
            perror("Failed to create child process");
            continue;
        } else if (processes[index].pid == 0) {
            // Child process
            execl("/bin/sh", "sh", "-c", command, NULL);
            perror("execl failed");
            exit(EXIT_FAILURE);
        }
    }

    fclose(file);

    // Create threads for each child process to monitor their status
    pthread_t threads[MAX_PROCESSES];
    int thread_indexes[MAX_PROCESSES];
    for (int i = 0; i < process_count; i++) {
        thread_indexes[i] = i;
        if (pthread_create(&threads[i], NULL, run_command, &thread_indexes[i]) != 0) {
            perror("Failed to create thread");
            processes[i].pid = -1;
            process_count--;
        }
    }

    // Join threads
    for (int i = 0; i < process_count; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    load_commands_from_file(argv[1]);

    return EXIT_SUCCESS;
}
