import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ImageToPdfConverter {
    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    private PdfGenerator pdfGenerator;
    private ImageMetadataService metadataService;

    public ImageToPdfConverter(PdfGenerator pdfGenerator, ImageMetadataService metadataService) {
        this.pdfGenerator = pdfGenerator;
        this.metadataService = metadataService;
    }

    public int convert(String inputDirectoryPath, String outputFileName) {
        File directory = new File(inputDirectoryPath);
        List<File> imageFiles = listImageFiles(directory);

        if (imageFiles.isEmpty()) {
            System.out.println("No image files found in the specified directory.");
            return 1;
        }

        long startTime = System.currentTimeMillis();

        for (File imageFile : imageFiles) {
            executorService.submit(() -> {
                try {
                    ImageMetadata metadata = metadataService.getImageMetadata(imageFile);
                    pdfGenerator.addPage(imageFile, metadata);
                } catch (IOException e) {
                    System.err.println("Error processing image: " + imageFile.getName());
                    e.printStackTrace();
                }
            });
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(10, TimeUnit.MINUTES)) {
                executorService.shutdownNow();
                System.out.println("Conversion timed out.");
                return 1;
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
            System.out.println("Conversion interrupted.");
            return 1;
        }

        long endTime = System.currentTimeMillis();

        try {
            pdfGenerator.save(outputFileName);
            System.out.println("PDF generated successfully. Total time: " + (endTime - startTime) + "ms");
        } catch (IOException e) {
            System.err.println("Error saving PDF file.");
            e.printStackTrace();
            return 1;
        }

        return 0;
    }

    private List<File> listImageFiles(File directory) {
        List<File> imageFiles = new ArrayList<>();
        File[] files = directory.listFiles((dir, name) -> name.endsWith(".jpg") || name.endsWith(".jpeg")
                || name.endsWith(".png") || name.endsWith(".gif"));
        if (files != null) {
            for (File file : files) {
                if (file.isFile()) {
                    imageFiles.add(file);
                }
            }
        }
        return imageFiles;
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java ImageToPdfConverter <input_directory_path> <output_file_name>");
            return;
        }

        String inputDirectoryPath = args[0];
        String outputFileName = args[1];

        PdfGenerator pdfGenerator = new PdfGenerator();
        ImageMetadataService metadataService = new ImageMetadataService();

        ImageToPdfConverter converter = new ImageToPdfConverter(pdfGenerator, metadataService);
        int result = converter.convert(inputDirectoryPath, outputFileName);

        System.exit(result);
    }
}

class PdfGenerator {
    public void addPage(File imageFile, ImageMetadata metadata) throws IOException {
        // Implementation to add page with optimization based on metadata
    }

    public void save(String fileName) throws IOException {
        // Implementation to save PDF file
    }
}

