import asyncio
from dataclasses import dataclass
from abc import ABC, abstractmethod

@dataclass
class Stock:
    symbol: str
    price: float

@dataclass
class Payment:
    id: str
    amount: float
    currency: str

class TradingStrategy(ABC):
    @abstractmethod
    async def decide_action(self, stock_data: Stock) -> str:
        pass

class PaymentValidationStrategy(ABC):
    @abstractmethod
    async def validate_payment(self, payment_details: Payment) -> bool:
        pass

class RealTimeMarketDataFetcher:
    async def fetch_stock_data(self) -> Stock:
        # Simulate fetching stock data
        return Stock(symbol="AAPL", price=150.75)

class AsyncPaymentProcessor:
    async def process_payment(self, payment_details: Payment):
        # Simulate processing a payment
        print(f"Processing payment {payment_details.id} for amount {payment_details.amount}")

class TradingBot:
    def __init__(self, strategy: TradingStrategy, payment_strategy: PaymentValidationStrategy):
        self.strategy = strategy
        self.payment_strategy = payment_strategy
        self.market_data_fetcher = RealTimeMarketDataFetcher()
        self.payment_processor = AsyncPaymentProcessor()

    async def run(self):
        while True:
            stock_data = await self.market_data_fetcher.fetch_stock_data()
            action = await self.strategy.decide_action(stock_data)
            if action == "buy":
                payment_details = Payment(id="12345", amount=100.0, currency="USD")
                valid_payment = await self.payment_strategy.validate_payment(payment_details)
                if valid_payment:
                    await self.payment_processor.process_payment(payment_details)

class DynamicStrategyLoader:
    @staticmethod
    def load_strategy(strategy_type: str) -> TradingStrategy:
        if strategy_type == "buy_high":
            return BuyHighStrategy()
        elif strategy_type == "sell_low":
            return SellLowStrategy()
        else:
            raise ValueError("Invalid strategy type")

class BuyHighStrategy(TradingStrategy):
    async def decide_action(self, stock_data: Stock) -> str:
        # Implement buy high logic
        if stock_data.price > 140.0:
            return "buy"
        return "hold"

class SellLowStrategy(TradingStrategy):
    async def decide_action(self, stock_data: Stock) -> str:
        # Implement sell low logic
        if stock_data.price < 130.0:
            return "sell"
        return "hold"

# Usage example
async def main():
    strategy_type = "buy_high"  # Can be changed to "sell_low" dynamically
    strategy = DynamicStrategyLoader.load_strategy(strategy_type)
    bot = TradingBot(strategy, PaymentValidationStrategy())
    await bot.run()

if __name__ == "__main__":
    asyncio.run(main())
