```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

#define KDF_ITERATIONS 100000
#define IV_LENGTH 12

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[IV_LENGTH];
} EncryptionContext;

int generate_iv(unsigned char *iv, int length) {
    return RAND_bytes(iv, length);
}

int derive_key(const char *password, const unsigned char *salt, size_t salt_len, unsigned char *key, int iterations) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, iterations, EVP_sha256(), sizeof(key), key);
}

EncryptionContext* create_encryption_context(const char *password, const unsigned char *salt) {
    EncryptionContext *ctx = malloc(sizeof(EncryptionContext));
    if (!ctx) return NULL;

    if (generate_iv(ctx->iv, IV_LENGTH) != 1) {
        free(ctx);
        return NULL;
    }

    if (derive_key(password, salt, sizeof(salt), ctx->key, KDF_ITERATIONS) <= 0) {
        free(ctx);
        return NULL;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    int ret = EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv);
    if (!ret) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int encrypt_data(EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext, unsigned char **tag) {
    int ciphertext_len;
    if (!EVP_EncryptUpdate(ctx->ctx, NULL, &ciphertext_len, plaintext, plaintext_len)) return -1;

    *ciphertext = malloc(plaintext_len + EVP_CIPHER_BLOCK_SIZE);
    if (!*ciphertext) return -1;

    if (!EVP_EncryptUpdate(ctx->ctx, *ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        free(*ciphertext);
        return -1;
    }

    int tag_len;
    if (!EVP_EncryptFinal_ex(ctx->ctx, *ciphertext + ciphertext_len, &tag_len)) {
        free(*ciphertext);
        return -1;
    }
    *ciphertext_len += tag_len;

    *tag = malloc(EVP_CIPHER_get_tag_length(ctx->ctx));
    if (!*tag) {
        free(*ciphertext);
        return -1;
    }

    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, tag_len, *tag)) {
        free(*ciphertext);
        free(*tag);
        return -1;
    }

    return 0;
}

int decrypt_data(EncryptionContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *tag, unsigned char **plaintext) {
    int plaintext_len;
    if (!EVP_DecryptUpdate(ctx->ctx, NULL, &plaintext_len, ciphertext, ciphertext_len)) return -1;

    *plaintext = malloc(plaintext_len);
    if (!*plaintext) return -1;

    if (!EVP_DecryptUpdate(ctx->ctx, *plaintext, &plaintext_len, ciphertext, plaintext_len)) {
        free(*plaintext);
        return -1;
    }

    int tag_len;
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, tag_len, (void *)tag)) {
        free(*plaintext);
        return -1;
    }

    if (!EVP_DecryptFinal_ex(ctx->ctx, *plaintext + plaintext_len, &tag_len)) {
        free(*plaintext);
        return -1;
    }
    *plaintext_len += tag_len;

    return 0;
}
```

