import java.util.concurrent.*;
import java.util.Map;
import java.util.HashMap;

public class ServiceManager {
    private final int numberOfServices;
    private final long maxDelayMs;
    private final BlockingQueue<String> messageQueue;
    private final ExecutorService executorService;
    private final Map<Integer, Future<?>> futures;
    private final Database database;

    public ServiceManager(int numberOfServices, long maxDelayMs) {
        this.numberOfServices = numberOfServices;
        this.maxDelayMs = maxDelayMs;
        this.messageQueue = new LinkedBlockingQueue<>();
        this.executorService = Executors.newFixedThreadPool(numberOfServices);
        this.futures = new HashMap<>();
        this.database = new Database();
    }

    public void start() {
        for (int i = 0; i < numberOfServices; i++) {
            int finalI = i;
            futures.put(i, executorService.submit(() -> runService(finalI)));
        }
    }

    private void runService(int serviceId) {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                if (startService(serviceId)) {
                    logStatus(serviceId, "Started");
                } else {
                    logStatus(serviceId, "Failed to start");
                }
                stopService(serviceId);
                sendStopMessage(serviceId);
                long delay = ThreadLocalRandom.current().nextLong(0, maxDelayMs);
                TimeUnit.MILLISECONDS.sleep(delay);
            } catch (InterruptedException | ExecutionException e) {
                System.err.println("Error in service " + serviceId + ": " + e.getMessage());
            }
        }
    }

    private boolean startService(int serviceId) {
        // Placeholder for actual service start logic
        return true;
    }

    private void stopService(int serviceId) {
        // Placeholder for actual service stop logic
    }

    private void sendStopMessage(int serviceId) throws ExecutionException, InterruptedException {
        String message = "Service " + serviceId + " has been stopped.";
        messageQueue.put(message);
        database.persistMessage(serviceId, message);
    }

    private void logStatus(int serviceId, String status) {
        System.out.println("Service " + serviceId + ": " + status);
        database.logStatus(serviceId, status);
    }

    public void stop() {
        for (Future<?> future : futures.values()) {
            future.cancel(true);
        }
        executorService.shutdown();
    }

