#include <stdio.h>
#include <string.h>

void dynamicStringCopy(const char* src, char* dest, size_t destSize) {
    if (dest == NULL || src == NULL || destSize == 0) {
        return;
    }

    size_t srcLength = strlen(src);
    if (srcLength >= destSize) {
        // Log truncation event
        printf("Truncating string from %zu to %zu\n", srcLength, destSize - 1);
    }

    strncpy(dest, src, destSize - 1);
    dest[destSize - 1] = '\0';
}
