public class FileHasher
{
    public string CalculateMd5HashFromFile(string filePath)
    {
        using (var hasher = MD5.Create())
        using (var stream = File.OpenRead(filePath))
        {
            return BitConverter.ToString(hasher.ComputeHash(stream)).Replace("-", "").ToLower();
        }
    }

    public DataTableReader ExecuteQueryAndReturnResult(byte[] byteArray)
    {
        string connectionString = "Server=localhost;Database=mydb;User Id=user;Password=password;";
        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (var command = new SqlCommand("SELECT * FROM mytable WHERE id = @id", connection))
            {
                command.Parameters.Add("@id", SqlDbType.VarBinary).Value = byteArray;
                using (var reader = command.ExecuteReader(CommandBehavior.SingleResult))
                {
                    return (DataTableReader)reader;
                }
            }
        }
    }
}
