import logging
from concurrent.futures import ThreadPoolExecutor
from requests.adapters import HTTPAdapter
from requests.packages.urllib3.util.retry import Retry
import time

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class UserProfileUpdater:
    def __init__(self):
        self.api_configs = {
            'api1': {'url': 'http://api1.com', 'auth_type': 'basic', 'timeout': 5},
            'api2': {'url': 'http://api2.com', 'auth_type': 'token', 'timeout': 3}
        }
        self.executor = ThreadPoolExecutor(max_workers=10)

    def update_profile(self, user_id, new_data):
        futures = []
        for api_name, config in self.api_configs.items():
            future = self.executor.submit(self._update_profile_for_api, api_name, user_id, new_data)
            futures.append(future)

        results = [future.result() for future in futures]
        return all(results)

    def _update_profile_for_api(self, api_name, user_id, new_data):
        config = self.api_configs[api_name]
        session = requests.Session()
        retries = Retry(total=5, backoff_factor=1, status_forcelist=[429, 503])
        adapter = HTTPAdapter(max_retries=retries)
        session.mount('http://', adapter)
        session.mount('https://', adapter)

        try:
            start_time = time.time()
            if config['auth_type'] == 'basic':
                response = session.put(f'{config["url"]}/user/{user_id}', json=new_data, auth=('username', 'password'), timeout=config['timeout'])
            elif config['auth_type'] == 'token':
                headers = {'Authorization': f'Bearer {new_data.get("access_token")}'}
                response = session.put(f'{config["url"]}/user/{user_id}', json=new_data, headers=headers, timeout=config['timeout'])

            response.raise_for_status()
            elapsed_time = time.time() - start_time
            logging.info(f'Successfully updated user {user_id} on {api_name} in {elapsed_time:.2f}s')
            return True
        except requests.RequestException as e:
            logging.error(f'Failed to update user {user_id} on {api_name}: {str(e)}')
            return False

# Example usage
if __name__ == '__main__':
    updater = UserProfileUpdater()
    result = updater.update_profile(123, {'name': 'John Doe', 'email': 'john.doe@example.com'})
    print(f'All updates successful: {result}')
```

