public class UserProfileUpdater
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<UserProfileUpdater> _logger;
    private readonly Dictionary<string, TenantConfig> _tenantConfigs;
    private readonly CacheService _cacheService;
    private readonly NotificationService _notificationService;

    public UserProfileUpdater(HttpClient httpClient, ILogger<UserProfileUpdater> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _tenantConfigs = LoadTenantConfigs();
        _cacheService = new CacheService(_logger);
        _notificationService = new NotificationService(_logger);
    }

    public async Task UpdateUserProfileAsync(string configFilePath, List<string> userIds, Dictionary<string, object> updatedProfile)
    {
        if (!File.Exists(configFilePath))
        {
            throw new FileNotFoundException("Configuration file not found.", configFilePath);
        }

        foreach (var userId in userIds)
        {
            if (!_cacheService.ValidateUserId(userId))
            {
                _logger.LogError($"Invalid user ID: {userId}");
                continue;
            }

            var tenantId = GetTenantIdFromUserId(userId);
            var tenantConfig = _tenantConfigs[tenantId];

            try
            {
                await UpdateProfileForUserAsync(tenantConfig, userId, updatedProfile);
                _notificationService.SendNotification(userId, updatedProfile);
                _logger.LogInformation($"Profile for user {userId} updated successfully.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to update profile for user {userId}");
            }
        }
    }

    private async Task UpdateProfileForUserAsync(TenantConfig tenantConfig, string userId, Dictionary<string, object> updatedProfile)
    {
        var restApi = new RestApiClient(_httpClient, tenantConfig.ApiEndpoint);
        var rateLimiter = new RateLimiter(tenantConfig.RateLimit);

        foreach (var field in GetUpdateOrder())
        {
            if (updatedProfile.ContainsKey(field))
            {
                await rateLimiter.AcquirePermission();
                try
                {
                    await restApi.UpdateUserProfileAsync(userId, field, updatedProfile[field]);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Failed to update {field} for user {userId}");
                }
            }
        }
    }

    private List<string> GetUpdateOrder()
    {
        // Define the order of fields based on priority
        return new List<string>
        {
            "email",
            "phoneNumber",
            "address",
            "dob",
            "employmentStatus"
        };
    }

