    private readonly string _apiEndpoint;

    public RestApiClient(HttpClient httpClient, string apiEndpoint)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _apiEndpoint = apiEndpoint ?? throw new ArgumentNullException(nameof(apiEndpoint));
    }

    public async Task UpdateUserProfileAsync(string userId, string field, object value)
    {
        // Implement logic to update user profile via REST API
        await _httpClient.PutAsJsonAsync($"{_apiEndpoint}/users/{userId}/{field}", value);
    }
}

public class RateLimiter
{
    private readonly int _rateLimit;
    private DateTime _lastRequestTime;

    public RateLimiter(int rateLimit)
    {
        _rateLimit = rateLimit;
        _lastRequestTime = DateTime.UtcNow;
    }

    public async Task AcquirePermission()
    {
        var now = DateTime.UtcNow;
        if ((now - _lastRequestTime).TotalSeconds < 1.0 / _rateLimit)
        {
            await Task.Delay((int)((1.0 / _rateLimit - (now - _lastRequestTime).TotalSeconds) * 1000));
        }
        _lastRequestTime = now;
    }
}
