```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to encrypt file using DES algorithm with specified cipher mode
EVP_CIPHER* encrypt_file(const char* inputFilePath, const char* outputFilePath, int cipherMode) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create context\n");
        return NULL;
    }

    // Initialize encryption with DES algorithm and specified mode
    if (1 != EVP_EncryptInit_ex(ctx, EVP_des_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Encryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Open input file and write encrypted data to output file
    FILE* inFile = fopen(inputFilePath, "rb");
    if (!inFile) {
        perror("Failed to open input file");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    FILE* outFile = fopen(outputFilePath, "wb");
    if (!outFile) {
        perror("Failed to open output file");
        fclose(inFile);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Read input file in chunks and encrypt
    char buffer[4096];
    int bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), inFile)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, buffer, &bytesRead, buffer, bytesRead)) {
            fprintf(stderr, "Encryption update failed\n");
            fclose(inFile);
            fclose(outFile);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        fwrite(buffer, 1, bytesRead, outFile);
    }

    // Finalize encryption and write any remaining data
    int finalBytesWritten;
    if (1 != EVP_EncryptFinal_ex(ctx, buffer, &finalBytesWritten)) {
        fprintf(stderr, "Encryption finalize failed\n");
        fclose(inFile);
        fclose(outFile);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    fwrite(buffer, 1, finalBytesWritten, outFile);

    // Clean up
    fclose(inFile);
    fclose(outFile);
    EVP_CIPHER_CTX_free(ctx);

    // Return pointer to the cipher structure representing the chosen mode
    switch (cipherMode) {
        case 0: return EVP_des_cbc();
        case 1: return EVP_des_ede3_cbc();
        case 2: return EVP_des_ecb();
        case 3: return EVP_des_ede_cbc();
        default: return NULL;
    }
}

// Function to calculate SHA-256 hash of a file
unsigned char* calculate_sha256(const char* filePath, size_t* digestLength) {
    unsigned char* digest = (unsigned char*)malloc(SHA256_DIGEST_LENGTH);
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        perror("Failed to open file for hash calculation");
        return NULL;
    }

    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        SHA256_Update(&sha256, buffer, bytesRead);
    }
    SHA256_Final(digest, &sha256);

    fclose(file);
    *digestLength = SHA256_DIGEST_LENGTH;
    return digest;
}

// Function to check if file exists at a specific path
int file_exists(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file) {
        fclose(file);
        return 1;
    }
    return 0;
}

// Function to upload file to cloud storage service
void upload_file_to_cloud(const char* bucketName, const char* directoryPath, const char* inputFilePath, int cipherMode) {
    // Validate file metadata and check if already exists in specified location
    size_t digestLength;
    unsigned char* sha256Digest = calculate_sha256(inputFilePath, &digestLength);
    if (file_exists(directoryPath)) {
        printf("File already exists at the specified location\n");
        return;
    }

    // Encrypt file and get pointer to cipher structure
    EVP_CIPHER* cipher = encrypt_file(inputFilePath, "encrypted_output", cipherMode);
    if (!cipher) {
        fprintf(stderr, "Failed to encrypt file\n");
        free(sha256Digest);
        return;
    }

    // Upload encrypted file to cloud storage service API
    // (Implementation depends on the specific cloud storage service API being used)

    // Clean up
    EVP_CIPHER_free(cipher);
    free(sha256Digest);
}

