// JWT generation function using a private key retrieved from KMS
public String generateJWT(HttpServletRequest request) {
    // Retrieve credentials from the request
    String username = request.getParameter("username");
    String password = request.getParameter("password");

    // Validate user credentials and roles/permissions
    if (!validateCredentials(username, password)) {
        throw new UnauthorizedAccessException("Invalid credentials or permissions");
    }

    // Retrieve private key from KMS
    PrivateKey privateKey = getPrivateKeyFromKMS();

    // Create JWT payload with user information and expiration time
    Map<String, Object> claims = new HashMap<>();
    claims.put("username", username);
    claims.put("roles", getUserRoles(username));
    long nowMillis = System.currentTimeMillis();
    Date now = new Date(nowMillis);
    long expiresAtMillis = nowMillis + (60 * 60 * 1000); // Token expires in 1 hour
    Date expiresAt = new Date(expiresAtMillis);

    // Sign the JWT with the private key
    String jwt = Jwts.builder()
        .setClaims(claims)
        .setIssuedAt(now)
        .setExpiration(expiresAt)
        .signWith(SignatureAlgorithm.RS256, privateKey)
        .compact();

    // Store JWT in cache for subsequent requests
    storeJWTInCache(username, jwt);

    return jwt;
}

// Sensor data processing method using Apache Kafka
public void processSensorData(InputStream inputStream) {
    // Create a JSON parser to validate incoming data against the schema
    SchemaParser schemaParser = new SchemaParser(new File("sensor_data_schema.json"));

    try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
        String line;
        while ((line = reader.readLine()) != null) {
            JsonNode jsonNode = mapper.readTree(line);

            // Validate JSON data against the schema
            if (!schemaParser.validate(jsonNode)) {
                logger.error("Invalid sensor data format");
                continue;
            }

            // Store valid data into Apache Kafka
            kafkaTemplate.send("sensor_data_topic", jsonNode.toString());
        }
    } catch (IOException e) {
        logger.error("Error processing sensor data", e);
    }
}

// Helper methods for JWT generation, validation, and KMS integration
private PrivateKey getPrivateKeyFromKMS() {
    // Retrieve private key from KMS
    return kmsClient.getPrivateKey();
}

private boolean validateCredentials(String username, String password) {
    // Validate user credentials against database or external service
    return userService.authenticate(username, password);
}

private Set<String> getUserRoles(String username) {
    // Retrieve user roles and permissions from database or external service
    return userService.getUserRoles(username);
}

private void storeJWTInCache(String username, String jwt) {
    // Store JWT in distributed cache for subsequent requests
    cache.put(username, jwt);
}
