using System;
using UnityEngine;
using System.Collections.Concurrent;
using System.Linq;

public enum DistributionType { Uniform, Gaussian, Exponential }

public class DynamicValueGenerator
{
    private ConcurrentDictionary<string, object> cache = new ConcurrentDictionary<string, object>();
    private Random random = new Random();

    public T GenerateRandom<T>(DistributionType distributionType, params float[] parameters)
    {
        var cacheKey = $"{distributionType}_{string.Join("_", parameters)}";
        return cache.GetOrAdd(cacheKey, key => GenerateRandomValue(distributionType, parameters));
    }

    private object GenerateRandomValue(DistributionType distributionType, float[] parameters)
    {
        switch (distributionType)
        {
            case DistributionType.Uniform:
                return GenerateUniform(parameters[0], parameters[1]);
            case DistributionType.Gaussian:
                return GenerateGaussian(parameters[0], parameters[1]);
            case DistributionType.Exponential:
                return GenerateExponential(parameters[0]);
            default:
                throw new ArgumentException("Unsupported distribution type");
        }
    }

    private float GenerateUniform(float min, float max)
    {
        return random.NextFloat() * (max - min) + min;
    }

    private float GenerateGaussian(float mean, float stdDeviation)
    {
        float u1 = random.NextFloat();
        float u2 = random.NextFloat();
        float z0 = Mathf.Sqrt(-2.0f * Mathf.Log(u1)) * Mathf.Cos(2.0f * Mathf.PI * u2);
        return z0 * stdDeviation + mean;
    }

    private float GenerateExponential(float lambda)
    {
        return -Mathf.Log(random.NextFloat()) / lambda;
    }

    public Vector3 GenerateRandomVector(DistributionType distributionType, params float[] parameters)
    {
        return new Vector3(
            (float)GenerateRandom(distributionType, parameters),
            (float)GenerateRandom(distributionType, parameters),
            (float)GenerateRandom(distributionType, parameters)
        );
    }

    public Matrix4x4 GenerateRandomMatrix(DistributionType distributionType, params float[] parameters)
    {
        return new Matrix4x4
        {
            m00 = (float)GenerateRandom(distributionType, parameters),
            m01 = (float)GenerateRandom(distributionType, parameters),
            m02 = (float)GenerateRandom(distributionType, parameters),
            m03 = (float)GenerateRandom(distributionType, parameters),
            m10 = (float)GenerateRandom(distributionType, parameters),
            m11 = (float)GenerateRandom(distributionType, parameters),
            m12 = (float)GenerateRandom(distributionType, parameters),
            m13 = (float)GenerateRandom(distributionType, parameters),
            m20 = (float)GenerateRandom(distributionType, parameters),
            m21 = (float)GenerateRandom(distributionType, parameters),
            m22 = (float)GenerateRandom(distributionType, parameters),
            m23 = (float)GenerateRandom(distributionType, parameters),
            m30 = (float)GenerateRandom(distributionType, parameters),
            m31 = (float)GenerateRandom(distributionType, parameters),
            m32 = (float)GenerateRandom(distributionType, parameters),
            m33 = (float)GenerateRandom(distributionType, parameters)
        };
    }
}
