import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class DistributedFileStorageSystem {

    private ExecutorService executorService;

    public DistributedFileStorageSystem(int numberOfThreads) {
        this.executorService = Executors.newFixedThreadPool(numberOfThreads);
    }

    public <T> Future<T> executeAsyncTaskWithRetry(Callable<T> task, List<BackendService> backendServices,
                                                   RetryStrategy retryStrategy, int maxRetries, long timeout) {
        return executorService.submit(() -> {
            int retries = 0;
            while (retries <= maxRetries) {
                for (BackendService service : backendServices) {
                    try {
                        return task.call();
                    } catch (Exception e) {
                        if (!retryStrategy.shouldRetry(e)) {
                            throw e;
                        }
                        Thread.sleep(retryStrategy.getRetryInterval(retries));
                        retries++;
                    }
                }
            }
            throw new RuntimeException("Task failed after maximum retries", task.call());
        });
    }

    public void shutdown() {
        executorService.shutdown();
    }

    // WebSocket stream data collection, filtering, and encryption code here
}

interface BackendService {
    <T> T execute(Callable<T> task) throws Exception;
}

class RetryStrategy {
    private int maxRetries;
    private long initialRetryInterval;

    public RetryStrategy(int maxRetries, long initialRetryInterval) {
        this.maxRetries = maxRetries;
        this.initialRetryInterval = initialRetryInterval;
    }

    public boolean shouldRetry(Exception e) {
        // Define retry conditions based on exception type
        return e instanceof TransientFailureException;
    }

    public long getRetryInterval(int retries) {
        // Implement exponential backoff algorithm
        return initialRetryInterval * (1 << retries);
    }
}

class TransientFailureException extends Exception {}
