import hashlib
import os
import time
from datetime import datetime, timedelta

class StorageBackend:
    def save_md5_hash(self, file_path, md5_hash):
        pass

class FileStorage(StorageBackend):
    def save_md5_hash(self, file_path, md5_hash):
        with open(file_path, 'w') as f:
            f.write(md5_hash)

def process_order_and_calculate_md5(order_id, customer_id, total_amount, file_path, storage_backend):
    rate_limiter = RateLimiter()
    if not rate_limiter.allow_request(customer_id):
        raise Exception("Rate limit exceeded")

    payment_gateway = PaymentGateway()
    payment_gateway.charge_customer(customer_id, total_amount)

    start_time = time.time()
    with open(file_path, 'rb') as f:
        md5_hash = hashlib.md5(f.read()).hexdigest()
    end_time = time.time()

    storage_backend.save_md5_hash(file_path, md5_hash)
    log_order_processing(order_id, customer_id, total_amount, file_path, start_time, end_time)

def log_order_processing(order_id, customer_id, total_amount, file_path, start_time, end_time):
    log_entry = f"Order ID: {order_id}, Customer ID: {customer_id}, Total Amount: {total_amount}, File Path: {file_path}, Start Time: {start_time}, End Time: {end_time}"
    with open("order_processing.log", "a") as log_file:
        log_file.write(log_entry + "\n")

def cleanup_old_logs():
    current_date = datetime.now()
    ninety_days_ago = current_date - timedelta(days=90)
    for file_name in os.listdir("."):
        if file_name.endswith(".log"):
            file_path = os.path.join(".", file_name)
            file_creation_time = datetime.fromtimestamp(os.path.getctime(file_path))
            if file_creation_time < ninety_days_ago:
                os.remove(file_path)

# Example usage
