import asyncio
import aiohttp
from typing import Type

class FileMetadataExtractor:
    def __init__(self, storage_service_url: str):
        self.storage_service_url = storage_service_url
        self.session = aiohttp.ClientSession()
        self.cache = {}

    async def extract_metadata(self, file_path: str, metadata_class: Type[Metadata], file_type: str) -> Metadata:
        try:
            if file_path in self.cache:
                return self.cache[file_path]

            response = await self.session.get(f"{self.storage_service_url}/metadata?file_path={file_path}&file_type={file_type}")
            response.raise_for_status()
            metadata_data = await response.json()

            if not isinstance(metadata_data, dict):
                raise ValueError("Invalid metadata format received from the storage service")

            metadata_instance = metadata_class(**metadata_data)
            self.cache[file_path] = metadata_instance
            return metadata_instance

        except aiohttp.ClientError as e:
            raise IOError(f"Failed to retrieve metadata for file {file_path}: {e}") from e
        except TypeError as e:
            raise ValueError(f"Invalid type encountered while extracting metadata: {e}") from e
        except Exception as e:
            raise RuntimeError(f"An unexpected error occurred while extracting metadata: {e}") from e

    async def __aenter__(self):
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.session.close()
