import java.net.InetSocketAddress;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ChatApplication {
    private ExecutorService ioExecutor;
    private MessagingServiceManager messagingServiceManager;
    private DatabaseConnector databaseConnector;
    private Configuration config;

    public ChatApplication(Configuration config) {
        this.config = config;
        this.ioExecutor = Executors.newCachedThreadPool();
        this.messagingServiceManager = new MessagingServiceManager(config);
        this.databaseConnector = new DatabaseConnector(config.getDatabaseUrl(), config.getDatabaseUser(), config.getDatabasePassword());
    }

    public void start() throws Exception {
        // Initialize all services
        messagingServiceManager.initializeServices();
        databaseConnector.connect();

        // Start listening for incoming connections
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(config.getServerPort()));
        serverSocketChannel.configureBlocking(false);

        ioExecutor.execute(() -> {
            try {
                while (true) {
                    SocketChannel clientChannel = serverSocketChannel.accept();
                    if (clientChannel != null) {
                        handleClientConnection(clientChannel);
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
    }

    private void handleClientConnection(SocketChannel clientChannel) throws IOException {
        // Handle client connection asynchronously
        ioExecutor.execute(() -> {
            try {
                // Read client request
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                int bytesRead = clientChannel.read(buffer);

                if (bytesRead == -1) {
                    clientChannel.close();
                    return;
                }

                // Process request
                String request = new String(buffer.array(), 0, bytesRead);
                Message message = parseMessage(request);

                // Dispatch message to appropriate messaging service
                ServiceResponse response = messagingServiceManager.dispatch(message);

                // Send response back to client
                ByteBuffer responseBuffer = ByteBuffer.wrap(response.getPayload());
                clientChannel.write(responseBuffer);

                // Close connection
                clientChannel.close();
            } catch (IOException e) {
                e.printStackTrace();
                try {
                    clientChannel.close();
                } catch (IOException ex) {
                    ex.printStackTrace();
                }
            }
        });
    }

    private Message parseMessage(String request) {
        // Parse message from request string
        // Implement parsing logic here
        return new Message();
    }

    public void stop() throws Exception {
        // Gracefully shut down all services
        messagingServiceManager.shutdownServices();
        databaseConnector.disconnect();

        // Shutdown I/O executor
        ioExecutor.shutdown();
        ioExecutor.awaitTermination(10, TimeUnit.SECONDS);
    }
}
