#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <random>

class RandomNumberGenerator {
private:
    std::mt19937 gen;
    std::uniform_int_distribution<> disInt;
    std::uniform_real_distribution<> disFloat;
    std::mutex mtx;

public:
    explicit RandomNumberGenerator(unsigned int seed) : gen(seed), disInt(), disFloat() {}

    void initializeSeed(unsigned int seed) {
        std::lock_guard<std::mutex> lock(mtx);
        gen.seed(seed);
    }

    int generateRandomInt(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Invalid range");
        disInt.param(std::uniform_int_distribution<>::param_type(min, max));
        return disInt(gen);
    }

    double generateRandomFloat(double min, double max) {
        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Invalid range");
        disFloat.param(std::uniform_real_distribution<>::param_type(min, max));
        return disFloat(gen);
    }

    ~RandomNumberGenerator() = default;
};

// Example usage
int main() {
    RandomNumberGenerator rng(42);

    // Initialize with a new seed value
    rng.initializeSeed(100);

    // Generate random integers and floats
    std::cout << "Random Int: " << rng.generateRandomInt(1, 100) << std::endl;
    std::cout << "Random Float: " << rng.generateRandomFloat(0.0, 1.0) << std::endl;

    return 0;
}
```

This code snippet provides a basic implementation of the `RandomNumberGenerator` class in C++ using the Mersenne Twister algorithm from `<random>`. The RNG is designed to be thread-safe by utilizing a mutex for synchronization during state updates and random number generation. The class includes methods to initialize the seed, generate random integers within a specified range, and generate random floating-point numbers within a specified range. Error handling is implemented to ensure that invalid ranges are not passed to the distribution objects.

