class PaymentCache {
private:
    static const int cacheExpiryTime = 30; // Cache expiry in seconds
    std::unordered_map<std::string, std::chrono::time_point<std::chrono::system_clock>> cache;

public:
    bool isProcessed(const std::string& paymentId) {
        auto now = std::chrono::system_clock::now();
        if (cache.find(paymentId) != cache.end()) {
            if ((now - cache[paymentId]).count() < cacheExpiryTime) {
                return true;
            }
        }
        return false;
    }

    void markProcessed(const std::string& paymentId) {
        cache[paymentId] = std::chrono::system_clock::now();
    }
};

class PaymentProcessor {
private:
    PaymentGateway gateway;
    PaymentCache cache;

public:
    bool processPaymentTransaction(const std::string& paymentData, int chunkSize, int timeout) {
        // Validate payment metadata
        if (!validatePaymentMetadata(paymentData)) {
            return false;
        }

        // Check if transaction is already processed
        if (cache.isProcessed(paymentData)) {
            std::cout << "Transaction already processed." << std::endl;
            return true;
        }

        // Process the transaction
        bool success = gateway.processTransaction(paymentData);

        if (success) {
            cache.markProcessed(paymentData);
            extendSessionTimeout(timeout);
        }

        return success;
    }

private:
    bool validatePaymentMetadata(const std::string& paymentData) {
        // Simulate validation logic
        return true;
    }

