```rust
use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use std::os::unix::fs::MetadataExt;
use sync_lazy::SyncLazy;
use rustc_driver::{self, catch_with_exit_code};
use build_server_api::{report_status, Error};
use retry::{retry_with_delay};
use parallel_processing::{compile_files_parallel};
use resource_monitoring::{monitor_rss, monitor_cpu};

pub fn compile_and_log(source_path: &str, max_rss: u64) -> Result<i32, Error> {
    let start_time = Instant::now();
    let metadata = std::fs::metadata(source_path)?;
    let initial_rss = monitor_rss()?;

    // Install custom logging hook
    let log_hook = SyncLazy::new(|| {
        CustomLogHook::new()
    });

    // Set up retry mechanism
    let retries = 3;
    let delay = Duration::from_secs(5);

    for attempt in 0..=retries {
        if attempt > 0 {
            std::thread::sleep(delay);
        }

        let exit_code = catch_with_exit_code(|| {
            rustc_driver::run_compiler(
                &[source_path],
                &mut log_hook.write_lock(),
                None,
                false
            )
        });

        if exit_code == 0 {
            break;
        }
    }

    let elapsed_time = start_time.elapsed();
    let final_rss = monitor_rss()?;
    let cpu_usage = monitor_cpu()?;

    report_status(&source_path, &metadata, exit_code, elapsed_time, initial_rss, final_rss, cpu_usage)?;

    if exit_code == 0 {
        Ok(exit_code)
    } else {
        Err(Error::CompilationFailed)
    }
}
