# Import necessary libraries
from threading import Lock
import datetime
import json
import requests

class IoTDataIngestion:
    def __init__(self, device_addresses, ingestion_params, cache_policy):
        self.device_addresses = device_addresses
        self.ingestion_params = ingestion_params
        self.cache_policy = cache_policy
        self.lock = Lock()
        self.data_cache = {}

    def ingest_data(self, data_point):
        # Validate data point format and handle exceptions
        try:
            if not isinstance(data_point, dict) or 'device_id' not in data_point:
                raise ValueError("Invalid data point format")

            with self.lock:
                self.data_cache[data_point['device_id']] = data_point
                # Cache management based on policy
                if len(self.data_cache) > self.cache_policy['max_size']:
                    oldest_device_id = min(self.data_cache, key=self.data_cache.get)
                    del self.data_cache[oldest_device_id]

            # Simulate API integration
            response = requests.post('http://analytics_api_url', json=data_point)
            response.raise_for_status()
        except Exception as e:
            print(f"Error processing data point: {e}")

    def scale_nodes(self, current_load):
        if current_load > self.ingestion_params['max_load']:
            # Logic to scale up
            pass
        elif current_load < self.ingestion_params['min_load']:
            # Logic to scale down
            pass

    def update_config(self, new_config):
        with self.lock:
            self.device_addresses = new_config['device_addresses']
            self.ingestion_params = new_config['ingestion_params']
            self.cache_policy = new_config['cache_policy']

# Example usage
if __name__ == "__main__":
    config = {
        'device_addresses': ['192.168.0.1', '192.168.0.2'],
        'ingestion_params': {'max_load': 1000, 'min_load': 500},
        'cache_policy': {'max_size': 1000}
    }

    ingestion_module = IoTDataIngestion(**config)

    data_point = {
        'device_id': 'device_001',
        'sensor_values': [23.4, 45.6],
        'timestamp': datetime.datetime.now(),
        'metadata': {'location': 'Room A'}
    }

    ingestion_module.ingest_data(data_point)
