    }

    const test = tests[testIndex];
    const { label, testFunction } = test;

    console.log(`Running test: ${label}`);

    try {
      blueslip.reset(); // Reset mocking library before each test
      testFunction(accumulator, (err, result) => {
        if (err) {
          callback(err);
          return;
        }

        const newAccumulator = accumulator;
        if (typeof newAccumulator !== 'undefined') {
          Object.assign(newAccumulator, result);
        }

        runTest(testIndex + 1, newAccumulator);
      });
    } catch (error) {
      callback(error);
    }
  }

  console.log(`Testing module: ${modulePath}`);
  blueslip.reset(); // Reset mocking library before starting
  runTest(0, initialValue);
}

// Sample usage:
const tests = [
  { label: 'test1', testFunction: (acc, cb) => { /* Test implementation */ } },
  { label: 'test2', testFunction: (acc, cb) => { /* Test implementation */ } }
];

runAsyncTests('path/to/module', tests, {}, (err, result) => {
  if (err) {
    console.error('Test failed:', err);
    return;
  }

  console.log('All tests passed:', result);
});
