public class DynamicDeserializer {

    private final Map<String, Class<?>> classCache = new ConcurrentHashMap<>();

    public <T> T deserialize(byte[] data, String className) throws CustomDeserializationException {
        try {
            if (!classCache.containsKey(className)) {
                synchronized (className.intern()) {
                    if (!classCache.containsKey(className)) {
                        Class<?> clazz = loadClassFromDataSource(className);
                        classCache.put(className, clazz);
                    }
                }
            }

            return (T) classCache.get(className).getConstructor().newInstance();
        } catch (ClassNotFoundException e) {
            logError("Class not found: " + className, e);
            throw new CustomDeserializationException("Failed to deserialize object", e);
        } catch (IOException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
            logError("Error during deserialization", e);
            throw new CustomDeserializationException("Failed to deserialize object", e);
        }
    }

