fn setup_logger(level: log::LevelFilter, file_path: Option<&str>) -> io::Result<()> {
    if let Some(file_path) = file_path {
        let log_file = OpenOptions::new()
            .write(true)
            .append(true)
            .create(true)
            .open(file_path)?;

        fern::Dispatch::new()
            .format(|out, message, record| {
                out.finish(format_args!(
                    "[{}][{}] {}",
                    chrono::Local::now().format("[%Y-%m-%d %H:%M:%S]"),
                    record.target(),
                    message
                ));
            })
            .level(level)
            .chain(fern::log4rs::Appender::builder()
                .build(Box::new(log_file)))
            .apply()?;
    } else {
        fern::Dispatch::new()
            .format(|out, message, record| {
                out.finish(format_args!(
                    "[{}][{}] {}",
                    chrono::Local::now().format("[%Y-%m-%d %H:%M:%S]"),
                    record.target(),
                    message
                ));
            })
            .level(level)
            .chain(fern::Dispatch::new())
            .apply()?;
    }

    Ok(())
}

async fn fetch_data(client: &Client, url: &str) -> Result<String, reqwest::Error> {
