```csharp
using System;
using System.IO;
using System.Net;
using System.Xml.XPath;

public class ElementNotFoundException : Exception
{
    public ElementNotFoundException(string message) : base(message) { }
}

public class MultipleElementsFoundException : Exception
{
    public MultipleElementsFoundException(int count) : base($"Multiple elements found with the given name. Count: {count}") { }
}

public static class XmlParser
{
    private static readonly ConcurrentDictionary<string, XPathDocument> cache = new ConcurrentDictionary<string, XPathDocument>();

    public static XPathNavigator GetFirstMatchingElement(string xpathQuery, string xmlSource)
    {
        try
        {
            XPathDocument doc;
            if (!cache.TryGetValue(xmlSource, out doc))
            {
                doc = LoadXmlDocument(xmlSource);
                cache[xmlSource] = doc;
            }

            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select(xpathQuery);

            if (nodes.Count == 0)
            {
                throw new ElementNotFoundException($"No element found with the given name.");
            }
            else if (nodes.Count > 1)
            {
                throw new MultipleElementsFoundException(nodes.Count);
            }

            return nodes.Current;
        }
        catch (XmlException ex)
        {
            throw new InvalidOperationException("The XML document is not well-formed.", ex);
        }
    }

    private static XPathDocument LoadXmlDocument(string source)
    {
        if (Uri.TryCreate(source, UriKind.Absolute, out Uri uri) && (uri.Scheme == "http" || uri.Scheme == "https"))
        {
            HttpWebRequest request = WebRequest.CreateHttp(uri);
            using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
            using (Stream stream = response.GetResponseStream())
            {
                return new XPathDocument(stream);
            }
        }
        else
        {
            using (XmlReader reader = XmlReader.Create(source))
            {
                return new XPathDocument(reader);
            }
        }
    }
}
```

To use the `GetFirstMatchingElement` function, you can call it with an XPath query and a source string that represents either a local file path or a remote URL. The function will automatically handle caching of parsed XML documents to improve performance.

