namespace RandomGenerator {

class MT19937Generator {
public:
    MT19937Generator(unsigned int seed) : mt(seed), uniform_dist(0, 1) {}

    ~MT19937Generator() noexcept = default;

    unsigned int generateRandomNumber(int min, int max) {
        if (min >= max) {
            throw std::invalid_argument("Invalid range: min must be less than max");
        }
        std::uniform_int_distribution<int> dist(min, max);
        return dist(mt);
    }

private:
    std::mt19937 mt;
    std::uniform_int_distribution<> uniform_dist;
};

} // namespace RandomGenerator

int main() {
    try {
        RandomGenerator::MT19937Generator gen(42);
        std::cout << "Random Number: " << gen.generateRandomNumber(1, 100) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
