import java.io.File;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class VideoTranscoder {

    private MetadataService metadataService;
    private TranscodingService transcodingService;
    private ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public List<TranscodeStatus> transcodeVideos(String inputDirPath, String outputDirPath) {
        File inputDir = new File(inputDirPath);
        File[] videoFiles = inputDir.listFiles((dir, name) -> name.toLowerCase().endsWith(".mp4"));
        if (videoFiles == null || videoFiles.length == 0) {
            return List.of(new TranscodeStatus("No video files found in the input directory."));
        }

        List<TranscodeTask> tasks = metadataService.queryMetadata(videoFiles)
                .stream()
                .map(metadata -> new TranscodeTask(metadata, outputDirPath))
                .toList();

        tasks.sort((task1, task2) -> {
            int durationCompare = Integer.compare(task1.getDuration(), task2.getDuration());
            return durationCompare != 0 ? durationCompare : Long.compare(task1.getSize(), task2.getSize());
        });

        List<TranscodeStatus> statuses = executorService.invokeAll(tasks)
                .stream()
                .map(future -> {
                    try {
                        return future.get();
                    } catch (Exception e) {
                        return new TranscodeStatus(e.getMessage());
                    }
                })
                .toList();

        executorService.shutdown();
        return statuses;
    }

    public void cancelTranscoding(TranscodeTask task) {
        transcodingService.cancelTranscoding(task);
    }
}
```

