import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

public class PokemonService {

    private static final String WEAKNESSES_API = "https://api.pokemonweaknesses.com/pokemon/{id}/";
    private static final String EVOLUTIONS_API = "https://evolutions.api.pokemon.com/v1/pokemon/{id}/evolution-chain/";
    private static final String HABITAT_API = "https://habitat.api.pokemon.com/v1/pokemon/{id}/habitat/";
    private static final String ABILITIES_API = "https://abilities.api.pokemon.com/v1/pokemon/{id}/abilities/";
    private static final String SIZE_API = "https://size.api.pokemon.com/v1/pokemon/{id}/size/";

    public Pokemon getPokemonDetails(int id) {
        HttpClient client = HttpClient.newHttpClient();
        CompletableFuture<String> weaknessesFuture = fetchWeaknesses(client, id);
        CompletableFuture<String> evolutionsFuture = fetchEvolutions(client, id);
        CompletableFuture<String> habitatFuture = fetchHabitat(client, id);
        CompletableFuture<String> abilitiesFuture = fetchAbilities(client, id);
        CompletableFuture<String> sizeFuture = fetchSize(client, id);

        try {
            String weaknesses = weaknessesFuture.get();
            String evolutions = evolutionsFuture.get();
            String habitat = habitatFuture.get();
            String abilities = abilitiesFuture.get();
            String size = sizeFuture.get();

            // Combine all data into a single Pokemon object
            return new Pokemon(weaknesses, evolutions, habitat, abilities, size);
        } catch (InterruptedException | ExecutionException e) {
            handleFailure(e);
            return new Pokemon(); // Return an empty or partial Pokemon object
        }
    }

    private CompletableFuture<String> fetchWeaknesses(HttpClient client, int id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(WEAKNESSES_API.replace("{id}", String.valueOf(id))))
                .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body);
    }

    private CompletableFuture<String> fetchEvolutions(HttpClient client, int id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(EVOLUTIONS_API.replace("{id}", String.valueOf(id))))
                .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body);
    }

    private CompletableFuture<String> fetchHabitat(HttpClient client, int id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(HABITAT_API.replace("{id}", String.valueOf(id))))
                .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body);
    }

    private CompletableFuture<String> fetchAbilities(HttpClient client, int id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(ABILITIES_API.replace("{id}", String.valueOf(id))))
                .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body);
    }

    private CompletableFuture<String> fetchSize(HttpClient client, int id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(SIZE_API.replace("{id}", String.valueOf(id))))
                .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body);
    }

    private void handleFailure(Exception e) {
        // Log the error or send it to an error tracking system
        System.err.println("Failed to fetch Pokemon data: " + e.getMessage());
    }
