#include <iostream>
#include <forward_list>

void insert_after_search(std::forward_list<std::string>& fl, const std::string& search, const std::string& insertion, int max_insertions) {
    auto it = fl.begin();
    while (it != fl.end() && max_insertions > 0) {
        if (*it == search) {
            *it += insertion;
            it++;
            max_insertions--;
        } else {
            it++;
        }
    }
    if (max_insertions > 0) {
        fl.push_back(search + insertion);
    }

    // Truncate strings to a maximum length
    for (auto& str : fl) {
        if (str.length() > 100) {
            str.resize(100);
        }
    }
}
