import java.util.concurrent.Executors;

public class ImageToPdfConverter {
    private static final int THREAD_POOL_SIZE = 10;

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java ImageToPdfConverter <output_file> <input_directory>");
            return;
        }

        String outputFile = args[0];
        File inputDirectory = new File(args[1]);

        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

        // Add tasks to the executor for processing each image file
        for (File file : inputDirectory.listFiles()) {
            if (isImage(file)) {
                executor.submit(new ImageProcessingTask(outputFile, file));
            }
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE);
        } catch (InterruptedException e) {
            System.err.println("Conversion process was interrupted");
        }

        System.exit(0);
    }

    private static boolean isImage(File file) {
        String name = file.getName().toLowerCase();
        return name.endsWith(".jpg") || name.endsWith(".jpeg") ||
               name.endsWith(".png") || name.endsWith(".gif");
    }
}

