#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORD_SIZE 100

typedef struct {
    int value;
    char* message;
} record;

record* initialize_records(int offset_size, int key_size, int min_value, int max_value, int message_size, int num_records) {
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return NULL;
    }

    int* keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    srand(time(0));

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = keys[i];
        records[i].message = (char*)malloc(message_size * sizeof(char));
        if (!records[i].message) {
            for (int j = 0; j < i; ++j) free(records[j].message);
            free(offsets);
            free(keys);
            free(records);
            fprintf(stderr, "Memory allocation failed for message at index %d.\n", i);
            return NULL;
        }
        snprintf(records[i].message, message_size, "Record %d", i + 1);
    }

    FILE* file = fopen("records.dat", "wb");
    if (!file) {
        for (int i = 0; i < num_records; ++i) free(records[i].message);
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Failed to open file for writing.\n");
        return NULL;
    }

    fwrite(&offsets[0], offset_size * sizeof(long), 1, file);
    fwrite(&keys[0], key_size * sizeof(int), 1, file);
    fwrite(records, num_records * sizeof(record), 1, file);

    fclose(file);

    free(offsets);
    free(keys);

    return records;
}

int main() {
    int offset_size = 8;
    int key_size = 4;
    int min_value = 10;
    int max_value = 100;
    int message_size = MAX_RECORD_SIZE + 1;
    int num_records = 1000;

    record* my_records = initialize_records(offset_size, key_size, min_value, max_value, message_size, num_records);

    if (my_records) {
        // Use the records...
        for (int i = 0; i < num_records; ++i) free(my_records[i].message);
        free(my_records);
    }

    return 0;
}
