public class DynamicCloudStorageManager {

    private Map<String, String> sha256Cache = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private JSONObject config;

    public DynamicCloudStorageManager(JSONObject config) {
        this.config = config;
    }

    public void processSensorData(Path filePath) throws IOException, InterruptedException {
        byte[] fileBytes = Files.readAllBytes(filePath);
        String sha256Hash = calculateSHA256(fileBytes);

        if (!sha256Cache.containsKey(sha256Hash)) {
            // Validate metadata (size, content type, etc.)
            boolean isValidMetadata = validateMetadata(fileBytes.length, "application/octet-stream", filePath.getFileName().toString());
            if (isValidMetadata) {
                sha256Cache.put(sha256Hash, filePath.toString());

                // Parse data according to configurable rules
                JSONObject parsingRules = config.getJSONObject("parsing_rules");
                String parsedData = parseData(fileBytes, parsingRules);

                // Upload file to cloud storage
                uploadToCloudStorage(parsedData, sha256Hash);
            }
        } else {
            System.out.println("File already processed: " + filePath);
        }

        executorService.shutdown();
    }

    private String calculateSHA256(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        return bytesToHex(digest.digest(data));
    }

    private boolean validateMetadata(long fileSize, String contentType, String fileName) {
        // Implement metadata validation logic here
        return true;
    }

    private String parseData(byte[] data, JSONObject rules) {
        // Implement data parsing logic here based on rules
        return new String(data);
    }

    private void uploadToCloudStorage(String data, String sha256Hash) throws InterruptedException {
        // Implement cloud storage upload logic here based on configuration
        executorService.submit(() -> {
            try {
                // Example using S3-like API for simplicity
                CloudStorageService s3 = new AmazonS3CloudStorageService(config.getString("s3_access_key"), config.getString("s3_secret_key"));
                s3.upload(data, sha256Hash);
                System.out.println("File uploaded to cloud storage: " + sha256Hash);
            } catch (Exception e) {
                handleUploadError(e, sha256Hash);
            }
        });
    }

    private void handleUploadError(Exception e, String sha256Hash) {
        // Implement error handling logic here for upload failures
        System.err.println("Failed to upload file: " + sha256Hash + ", error: " + e.getMessage());
        // Fallback strategy and retry mechanism can be implemented here
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

