    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method == "POST" && context.Request.Path.StartsWithSegments("/updateClinicStatus"))
        {
            try
            {
                var clinicId = await context.Request.ReadFormValueAsync("clinicId");
                var newStatus = await context.Request.ReadFormValueAsync("newStatus");
