#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>

class PaymentProcessor {
private:
    std::mutex mtx;
    std::condition_variable cv;
    bool processing = false;

public:
    void processPaymentTransaction(const std::string& paymentMetadata) {
        std::unique_lock<std::mutex> lock(mtx);
        if (processing) {
            cv.wait(lock, [this]{ return !processing; });
        }
        processing = true;

        // Simulate payment processing
        std::cout << "Processing payment transaction: " << paymentMetadata << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(2));

        processing = false;
        cv.notify_one();
    }
};
