        this.restTemplate = restTemplate;
    }

    public void processSensorData(String data) {
        // Validate JSON format against dynamically configurable schema
        if (isValidJsonFormat(data)) {
            // Correlate sensor data with environmental conditions using external API
            String weatherData = fetchWeatherData();
            if (weatherData != null) {
                // Forward valid data to fault-tolerant distributed streaming platform (e.g., Apache Kafka)
                kafkaTemplate.send("sensor-data-topic", data + "|" + weatherData);
            }
        } else {
            // Log error for invalid JSON format
            logError("Invalid JSON format: " + data);
        }
    }

    private boolean isValidJsonFormat(String json) {
        // Implement JSON validation logic here
        return true;
    }

