```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 50000

typedef struct {
    // Define task structure here
} Task;

Task* task_queue[MAX_THREADS];
int front = -1, rear = -1;
sem_t queue_mutex, empty, full;

void enqueue(Task *task) {
    sem_wait(&empty);
    sem_wait(&queue_mutex);
    if (front == -1)
        front = 0;
    rear = (rear + 1) % MAX_THREADS;
    task_queue[rear] = task;
    sem_post(&queue_mutex);
    sem_post(&full);
}

Task* dequeue() {
    Task *task;
    sem_wait(&full);
    sem_wait(&queue_mutex);
    if (front == rear)
        front = rear = -1;
    else
        front = (front + 1) % MAX_THREADS;
    task = task_queue[front];
    sem_post(&queue_mutex);
    sem_post(&empty);
    return task;
}

void* worker_thread(void *arg) {
    while (1) {
        Task *task = dequeue();
        // Process the task
    }
    pthread_exit(NULL);
}

int main() {
    int i;
    pthread_t threads[MAX_THREADS];

    sem_init(&queue_mutex, 0, 1);
    sem_init(&empty, 0, MAX_THREADS);
    sem_init(&full, 0, 0);

    for (i = 0; i < MAX_THREADS; i++)
        pthread_create(&threads[i], NULL, worker_thread, NULL);

    // Enqueue tasks here

    for (i = 0; i < MAX_THREADS; i++)
        pthread_join(threads[i], NULL);

    sem_destroy(&queue_mutex);
    sem_destroy(&empty);
    sem_destroy(&full);

    return 0;
}
