// Function to parse JSON configuration and populate the Config struct
Config parseConfig(const std::string& jsonPath) {
    std::ifstream configFile(jsonPath);
    if (!configFile.is_open()) {
        throw std::runtime_error("Failed to open config file: " + jsonPath);
    }
    std::stringstream buffer;
    buffer << configFile.rdbuf();
    configFile.close();

    Config config;
    try {
        auto jsonData = json::parse(buffer);
        config.arraySize = jsonData["arraySize"];
        config.apiEndpoint = jsonData["apiEndpoint"];
        config.communicationProtocols = jsonData["communicationProtocols"].get<std::vector<std::string>>();
        for (const auto& policy : jsonData["securityPolicies"]) {
            config.securityPolicies[policy.key()] = policy.value().get<bool>();
        }
    } catch (json::parse_error& e) {
        throw std::runtime_error("Failed to parse JSON configuration: " + e.what());
    }

    return config;
}

