#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <string.h>

typedef struct {
    const char* label;
    void (*testFunction)();
} TestObject;

void test_module_async(const char* filename, TestObject* tests, int initial_value, void (*callback)()) {
    void* handle = dlopen(filename, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error opening module: %s\n", dlerror());
        return;
    }

    for (int i = 0; tests[i].label != NULL; i++) {
        void (*testFunction)() = (void (*)())dlsym(handle, tests[i].label);
        if (!testFunction) {
            fprintf(stderr, "Error finding test function: %s\n", dlerror());
            continue;
        }

        printf("Running test: %s\n", tests[i].label);
        testFunction();
        blueslip_reset();

        initial_value = reduce(initial_value, (void (*)(int, void*))callback, NULL, 0);
    }

    dlclose(handle);
}

