// Import necessary libraries
const WebSocket = require('ws');
const express = require('express');
const cassandra = require('cassandra-driver');

// Initialize WebSocket server
const wss = new WebSocket.Server({ port: 8080 });

// Connect to Cassandra database
const client = new cassandra.Client({ contactPoints: ['127.0.0.1'], keyspace: 'iot_data' });
client.connect();

// Initialize Express application for REST API
const app = express();
app.use(express.json());

// Store connected devices and their WebSocket connections
const deviceConnections = new Map();

// Handle incoming WebSocket connections
wss.on('connection', (ws, req) => {
  const deviceId = req.headers['x-device-id'];

  // Store the connection for later use
  if (!deviceConnections.has(deviceId)) {
    deviceConnections.set(deviceId, ws);
  }

  // Handle incoming data from devices
  ws.on('message', async (data) => {
    try {
      const parsedData = JSON.parse(data);

      // Validate and cleanse the data
      const isValid = validateSensorData(parsedData);
      if (!isValid) {
        console.log(`Invalid data received from device ${deviceId}:`, parsedData);
        return;
      }

      // Store the data in Cassandra
      await storeDataInCassandra(parsedData);

      // Log successful data storage
      console.log(`Data stored successfully for device ${deviceId}:`, parsedData);
    } catch (error) {
      console.error(`Error processing data from device ${deviceId}:`, error);
    }
  });

  // Handle connection errors
  ws.on('close', () => {
    console.log(`Device ${deviceId} disconnected.`);
    deviceConnections.delete(deviceId);
  });
});

// Handle REST API requests for sensor data
app.get('/api/data', async (req, res) => {
  try {
    const page = req.query.page || 0;
    const limit = req.query.limit || 100;

    // Retrieve data from Cassandra with pagination
    const results = await client.execute('SELECT * FROM sensor_data LIMIT ? ALLOW FILTERING', [limit], { fetchSize: limit });

    // Send the data as a JSON response
    res.status(200).json({ page, limit, totalResults: results.rows.length, data: results.rows });
  } catch (error) {
    console.error('Error retrieving sensor data:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Start the Express application
app.listen(3000, () => {
  console.log('REST API listening on port 3000');
});

// Function to validate and cleanse sensor data
function validateSensorData(data) {
  // Implement validation rules here
  return true; // Replace with actual validation logic
}

// Function to store sensor data in Cassandra
async function storeDataInCassandra(data) {
  try {
    await client.execute('INSERT INTO sensor_data (device_id, timestamp, temperature, humidity) VALUES (?, ?, ?, ?)', [
      data.deviceId,
      new Date(),
      data.temperature,
      data.humidity
    ]);
  } catch (error) {
    console.error('Error storing data in Cassandra:', error);
  }
}
