import java.util.concurrent.TimeUnit;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;

@Service
public class TransactionService {

    private final PaymentGateway paymentGateway;
    private final LoggingService loggingService;

    public TransactionService(PaymentGateway paymentGateway, LoggingService loggingService) {
        this.paymentGateway = paymentGateway;
        this.loggingService = loggingService;
    }

    @Retryable(
        value = {TransactionProcessingException.class},
        maxAttempts = 5,
        backoff = @Backoff(delay = 1000, multiplier = 2)
    )
    public String batchProcessTransactions(List<Transaction> transactionBatch) {
        for (Transaction transaction : transactionBatch) {
            validateTransaction(transaction);
            try {
                paymentGateway.processPayment(transaction);
                loggingService.logSuccess(transaction);
            } catch (PaymentProcessingException e) {
                loggingService.logFailure(transaction, e.getMessage());
                throw new TransactionProcessingException("Failed to process transaction: " + transaction.getId(), e);
            }
        }
        return "All transactions processed successfully";
    }

    private void validateTransaction(Transaction transaction) throws InvalidTransactionException {
        if (transaction.getQuantity() <= 0 || transaction.getPrice() <= 0) {
            throw new InvalidTransactionException("Invalid transaction parameters");
        }
        // Add more validation logic as needed
    }
}

class Transaction {
    // Define transaction properties and methods
}

class PaymentGateway {
    public void processPayment(Transaction transaction) throws PaymentProcessingException {
        // Implementation of payment processing logic
    }
}

class LoggingService {
    public void logSuccess(Transaction transaction) {
        // Implementation for logging successful transactions
    }

    public void logFailure(Transaction transaction, String errorMessage) {
        // Implementation for logging failed transactions
    }
}

class TransactionProcessingException extends RuntimeException {
    public TransactionProcessingException(String message, Throwable cause) {
        super(message, cause);
    }
}

class InvalidTransactionException extends RuntimeException {
    public InvalidTransactionException(String message) {
        super(message);
    }
}
