package com.network.topology;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class NetworkTopologyManager {

    private final Map<Integer, Node> nodes = new ConcurrentHashMap<>();
    private final Map<String, Edge> edges = new ConcurrentHashMap<>();

    private final Lock lock = new ReentrantLock();

    public void addNode(int nodeId) {
        if (nodes.containsKey(nodeId)) {
            throw new IllegalArgumentException("Node already exists: " + nodeId);
        }
        Node newNode = new Node(nodeId);
        nodes.put(nodeId, newNode);
    }

    public void removeNode(int nodeId) {
        lock.lock();
        try {
            Node node = nodes.get(nodeId);
            if (node == null) {
                throw new IllegalArgumentException("Node does not exist: " + nodeId);
            }
            edges.values().removeIf(edge -> edge.getSource() == node || edge.getTarget() == node);
            nodes.remove(nodeId);
        } finally {
            lock.unlock();
        }
    }

    public void addEdge(int sourceNodeId, int targetNodeId) {
        if (!nodes.containsKey(sourceNodeId)) {
            throw new IllegalArgumentException("Source node does not exist: " + sourceNodeId);
        }
        if (!nodes.containsKey(targetNodeId)) {
            throw new IllegalArgumentException("Target node does not exist: " + targetNodeId);
        }

        lock.lock();
        try {
            Node sourceNode = nodes.get(sourceNodeId);
            Node targetNode = nodes.get(targetNodeId);

            Edge newEdge = new Edge(sourceNode, targetNode);
            edges.put(newEdge.getId(), newEdge);
        } finally {
            lock.unlock();
        }
    }

    public void removeEdge(int sourceNodeId, int targetNodeId) {
        if (!nodes.containsKey(sourceNodeId)) {
            throw new IllegalArgumentException("Source node does not exist: " + sourceNodeId);
        }
        if (!nodes.containsKey(targetNodeId)) {
            throw new IllegalArgumentException("Target node does not exist: " + targetNodeId);
        }

        lock.lock();
        try {
            Node sourceNode = nodes.get(sourceNodeId);
            Node targetNode = nodes.get(targetNodeId);

            edges.values().removeIf(edge -> edge.getSource() == sourceNode && edge.getTarget() == targetNode);
        } finally {
            lock.unlock();
        }
    }

    // Additional methods for path compression and lazy union can be implemented here
}

class Node {
    private final int id;
    private Node parent;

    public Node(int id) {
        this.id = id;
        this.parent = this;
    }

    public int getId() {
        return id;
    }

    public Node getParent() {
        return parent;
    }

    public void setParent(Node parent) {
        this.parent = parent;
    }
}

class Edge {
    private final String id;
    private final Node source;
    private final Node target;

    public Edge(Node source, Node target) {
        this.id = source.getId() + "-" + target.getId();
        this.source = source;
        this.target = target;
    }

    public String getId() {
        return id;
    }

    public Node getSource() {
        return source;
    }

    public Node getTarget() {
        return target;
    }
}
```

