const { Readable } = require('stream');
const { pipeline } = require('stream/promises');
const pino = require('pino');

// Initialize logger
const logger = pino();

async function processStreams(streams, byteCount) {
  const bufferList = [];
  let totalBytesRead = 0;

  const transformStream = new Readable({
    async read(size) {
      try {
        for (let stream of streams) {
          if (totalBytesRead >= byteCount) break;
          const chunk = await new Promise((resolve, reject) => {
            stream.once('data', data => resolve(data));
            stream.once('error', error => reject(error));
          });
          totalBytesRead += chunk.length;
          bufferList.push(chunk);
        }
        if (totalBytesRead >= byteCount) {
          this.push(Buffer.concat(bufferList.slice(0, Math.ceil(byteCount / 1024))));
        } else {
          this.push(null);
        }
      } catch (error) {
        logger.error('Error processing streams:', error);
        this.destroy(error);
      }
    },
    encoding: 'utf-8',
  });

  await pipeline(transformStream, process.stdout);

  return Buffer.concat(bufferList).toString();
}

module.exports = { processStreams };
```

