        List<Future<StockPrice>> futures = new ArrayList<>();
        for (String symbol : companySymbols) {
            Future<StockPrice> future = executor.submit(() -> fetchAndValidateStockData(symbol));
            futures.add(future);
        }

        List<StockPrice> stockPrices = new ArrayList<>();
        for (Future<StockPrice> future : futures) {
            try {
                StockPrice stockPrice = future.get();
                if (stockPrice != null) {
                    stockPrices.add(stockPrice);
                }
            } catch (InterruptedException | ExecutionException e) {
