        User user = users.get(deviceId);
        if (user == null) {
            return "User not registered";
        }

        WeatherData weather = getWeatherData(user.getLocation());
        NewsData news = getNewsData();

        if (isEmergency(weather, news)) {
            sendNotifications(user, weather, news);
        }

        logInteraction(deviceId, user, weather, news);

        return "Alert checked for device: " + deviceId;
