#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_STREAMS 10

typedef struct {
    char url[MAX_URL_LENGTH];
    void* data;
    size_t size;
} NetworkStream;

NetworkStream streams[MAX_STREAMS];

void* read_network_stream(void* arg) {
    int index = *(int*)arg;
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, streams[index].url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, streams[index].data);
        curl_easy_setopt(curl, CURLOPT_INFILESIZE, streams[index].size);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    return NULL;
}

int main() {
    int num_streams = 5;

    // Initialize streams
    for(int i = 0; i < num_streams; ++i) {
        snprintf(streams[i].url, MAX_URL_LENGTH, "http://example.com/stream%d", i);
        streams[i].data = malloc(1024 * 1024); // Allocate 1MB buffer
        streams[i].size = 1024 * 1024;
    }

    pthread_t threads[MAX_STREAMS];
    int indices[MAX_STREAMS];

    // Create threads to read network streams
    for(int i = 0; i < num_streams; ++i) {
        indices[i] = i;
        if(pthread_create(&threads[i], NULL, read_network_stream, &indices[i]) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    // Join threads
    for(int i = 0; i < num_streams; ++i) {
        pthread_join(threads[i], NULL);
        free(streams[i].data);
    }

    curl_global_cleanup();
    return 0;
}
