#include <iostream>
#include <forward_list>
#include <string>

enum class UpdateStatus {
    Success,
    KeyNotFound,
    EmptyValueWithoutKey
};

bool updateForwardList(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    if (value.empty()) {
        return UpdateStatus::EmptyValueWithoutKey;
    }

    auto it = list.begin();
    while (it != list.end()) {
        if (*it == key) {
            if (!value.empty()) {
                *it = value; // Replace with value
                return UpdateStatus::Success;
            } else {
                it = list.insert_after(it, value); // Insert after key
                ++it; // Move to the next element
                return UpdateStatus::Success;
            }
        }
        ++it;
    }

    if (!value.empty()) {
        list.push_back(value); // Append to the end
        return UpdateStatus::Success;
    } else {
        return UpdateStatus::KeyNotFound;
    }
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    UpdateStatus status;

    status = updateForwardList(myList, "banana", "blueberry");
    if (status == UpdateStatus::Success) {
        std::cout << "Update successful." << std::endl;
    } else if (status == UpdateStatus::KeyNotFound) {
        std::cout << "Key not found." << std::endl;
    }

    status = updateForwardList(myList, "cherry", "");
    if (status == UpdateStatus::Success) {
        std::cout << "Update successful." << std::endl;
    } else if (status == UpdateStatus::KeyNotFound) {
        std::cout << "Key not found." << std::endl;
    }

    status = updateForwardList(myList, "date", "");
    if (status == UpdateStatus::Success) {
        std::cout << "Update successful." << std::endl;
    } else if (status == UpdateStatus::KeyNotFound) {
        std::cout << "Key not found." << std::endl;
    }

    status = updateForwardList(myList, "", "");
    if (status == UpdateStatus::EmptyValueWithoutKey) {
        std::cout << "Empty value provided without a key." << std::endl;
    }

    return 0;
}
