```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Newtonsoft.Json;

public class ClinicStatusMiddleware
{
    private readonly RequestDelegate _next;
    private readonly HttpClient _httpClient;
    private readonly IRateLimiter _rateLimiter;
    private readonly ICMSIntegrationService _cmsIntegrationService;
    private readonly ILoggingService _loggingService;
    private readonly IAuditLogService _auditLogService;

    public ClinicStatusMiddleware(RequestDelegate next, HttpClient httpClient, IRateLimiter rateLimiter, ICMSIntegrationService cmsIntegrationService, ILoggingService loggingService, IAuditLogService auditLogService)
    {
        _next = next;
        _httpClient = httpClient;
        _rateLimiter = rateLimiter;
        _cmsIntegrationService = cmsIntegrationService;
        _loggingService = loggingService;
        _auditLogService = auditLogService;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method != HttpMethods.Post || !context.Request.Path.StartsWithSegments("/update-clinic-status"))
        {
            await _next(context);
            return;
        }

        var requestBody = await new StreamReader(context.Request.Body).ReadToEndAsync();
        var requestModel = JsonConvert.DeserializeObject<ClinicStatusRequestModel>(requestBody);

        try
        {
            if (!_rateLimiter.AllowUpdate(requestModel.LastModifiedIP))
            {
                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                await context.Response.WriteAsync("Rate limit exceeded. Please try again later.");
                _loggingService.LogWarning($"Rate limit exceeded for IP: {requestModel.LastModifiedIP}");
                return;
            }

            var oldStatus = await _cmsIntegrationService.GetClinicStatus(requestModel.ClinicID, requestModel.Language);
            if (oldStatus == requestModel.NewStatus && !requestModel.AllowIdenticalUpdate)
            {
                context.Response.StatusCode = StatusCodes.Status400BadRequest;
                await context.Response.WriteAsync("New status is identical to the old status.");
                _loggingService.LogWarning($"Attempted to update clinic status to same value for ClinicID: {requestModel.ClinicID}");
                return;
            }

            var validationErrors = ValidateStatusMessage(requestModel.NewStatus);
            if (validationErrors.Any())
            {
                context.Response.StatusCode = StatusCodes.Status400BadRequest;
                await context.Response.WriteAsync($"Validation errors: {string.Join(", ", validationErrors)}");
                _loggingService.LogWarning($"Validation errors for clinic status update: {string.Join(", ", validationErrors)}");
                return;
            }

            using (var transactionScope = new TransactionScope())
            {
                foreach (var cms in _cmsIntegrationService.GetSupportedCMSs())
                {
                    await cms.UpdateClinicStatus(requestModel.ClinicID, requestModel.NewStatus, DateTime.UtcNow, requestModel.LastModifiedIP, requestModel.LastModifiedByUserId, requestModel.Language);
                }

                transactionScope.Complete();
            }

            await _auditLogService.LogAuditEntry(requestModel.ClinicID, requestModel.LastModifiedByUserId, oldStatus, requestModel.NewStatus, requestModel.Language);

            var emailNotification = new EmailNotification
            {
                ClinicID = requestModel.ClinicID,
                NewStatus = requestModel.NewStatus,
                User = requestModel.LastModifiedByUserId,
                Language = requestModel.Language
            };

            await SendEmailNotification(emailNotification);
        }
        catch (HttpRequestException ex)
        {
            context.Response.StatusCode = StatusCodes.Status503ServiceUnavailable;
            await context.Response.WriteAsync("Failed to update clinic status due to network error.");
            _loggingService.LogError($"Network error updating clinic status: {ex.Message}");
        }
        catch (Exception ex)
        {
            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            await context.Response.WriteAsync("An unexpected error occurred while updating clinic status.");
            _loggingService.LogError($"Unexpected error updating clinic status: {ex.Message}");
        }

        _rateLimiter.UpdateRequestCount(requestModel.LastModifiedIP);
    }

    private List<string> ValidateStatusMessage(string newStatus)
    {
        var errors = new List<string>();

        if (newStatus.Contains("prohibited"))
        {
            errors.Add("Prohibited words found in the status message.");
        }

        // Add more validation rules as needed

        return errors;
    }

    private async Task SendEmailNotification(EmailNotification emailNotification)
    {
        try
        {
            for (int attempt = 0; attempt < 3; attempt++)
            {
                try
                {
                    await _cmsIntegrationService.SendEmail(emailNotification);
                    break;
                }
                catch (Exception ex)
                {
                    if (attempt == 2)
                    {
                        _loggingService.LogError($"Failed to send email notification after {attempt + 1} attempts: {ex.Message}");
                        throw;
                    }

                    // Exponential backoff before retrying
                    await Task.Delay((int)Math.Pow(2, attempt) * 100);
                }
            }
        }
        catch (Exception ex)
        {
            _loggingService.LogError($"Failed to send email notification: {ex.Message}");
        }
    }
}

public class ClinicStatusRequestModel
{
    public int ClinicID { get; set; }
    public string NewStatus { get; set; }
    public string LastModifiedIP { get; set; }
    public int LastModifiedByUserId { get; set; }
    public string Language { get; set; }
    public bool AllowIdenticalUpdate { get; set; }
}

public class EmailNotification
{
    public int ClinicID { get; set; }
    public string NewStatus { get; set; }
    public int User { get; set; }
    public string Language { get; set; }
}
