<?php

require_once 'vendor/autoload.php';

use Redis;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;
use Monolog\Processor\PsrLogMessageProcessor;

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    // Database connection details
    $db_config = [
        'host' => 'localhost',
        'dbname' => 'healthcare_db',
        'user' => 'username',
        'password' => 'password'
    ];

    // Redis configuration
    $redis_config = [
        'host' => 'localhost',
        'port' => 6379
    ];

    // External monitoring service details
    $monitoring_service_url = 'http://monitoring-service/track_error';

    // Initialize Redis and Logger
    $redis = new Redis();
    $redis->connect($redis_config['host'], $redis_config['port']);

    $logger = new Logger('update_clinic_status');
    $log_file_path = '/var/log/update_clinic_status.log';
    $logger->pushHandler(new StreamHandler($log_file_path, Logger::ERROR));
    $logger->pushProcessor(new PsrLogMessageProcessor());

    // Rate limiting logic
    $key = "ip:$last_modified_ip:update_count";
    $redis->incr($key);
    $redis->expireat($key, time() + 60); // Reset count every minute

    $update_count = (int)$redis->get($key);
    if ($update_count > 5) {
        $logger->error("Rate limit exceeded for IP: $last_modified_ip");
        return false;
    }

    try {
        // Connect to the database
        $pdo = new PDO("mysql:host={$db_config['host']};dbname={$db_config['dbname']}", $db_config['user'], $db_config['password']);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Start a transaction
        $pdo->beginTransaction();

        // Prepare and execute the update statement
        $stmt = $pdo->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE clinic_id = ?");
        $stmt->execute([$new_status, $last_modified_ip, $clinic_id]);

        // Commit the transaction
        $pdo->commit();

        return true;
    } catch (PDOException $e) {
        // Log the error to external monitoring service
        $logger->error("Error updating clinic status: " . $e->getMessage());
        file_put_contents('php_errors.log', $e->getMessage(), FILE_APPEND);

        // Rollback the transaction in case of an error
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }

        return false;
    }
}
