using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNet.SignalR;

public class ClinicStatusMiddleware : IHttpModule
{
    private readonly DbContext _context;
    private readonly IHubContext<ClinicStatusHub> _hubContext;
    private readonly RateLimiter _rateLimiter;
    private readonly CacheManager _cacheManager;
    private readonly EmailService _emailService;
    private readonly LogService _logService;

    public ClinicStatusMiddleware(DbContext context, IHubContext<ClinicStatusHub> hubContext)
    {
        _context = context;
        _hubContext = hubContext;
        _rateLimiter = new RateLimiter();
        _cacheManager = new CacheManager();
        _emailService = new EmailService();
        _logService = new LogService();
    }

    public void Init(HttpApplication context)
    {
        context.BeginRequest += OnBeginRequest;
    }

    private async void OnBeginRequest(object sender, EventArgs e)
    {
        var request = HttpContext.Current.Request;

        if (request.HttpMethod == "POST" && request.Url.AbsolutePath.StartsWith("/updateStatus"))
        {
            var clinicId = request.Form["clinicId"];
            var newStatus = request.Form["status"];
            var lastModifiedIP = request.UserHostAddress;
            var lastModifiedByUserId = request.Form["userId"];

            if (!_rateLimiter.AllowUpdate(lastModifiedIP))
            {
                _logService.LogWarning($"Rate limit exceeded for IP: {lastModifiedIP}");
                HttpContext.Current.Response.StatusCode = 429; // Too Many Requests
                return;
            }

            try
            {
                var clinicStatus = await _context.ClinicStatuses.FindAsync(clinicId);
                if (clinicStatus == null)
                {
                    clinicStatus = new ClinicStatus { ClinicId = clinicId, Status = newStatus };
                    await _context.ClinicStatuses.AddAsync(clinicStatus);
                }
                else
                {
                    clinicStatus.Status = newStatus;
                }

                clinicStatus.LastModifiedIP = lastModifiedIP;
                clinicStatus.LastModifiedByUserId = lastModifiedByUserId;
                clinicStatus.LastModifiedDate = DateTime.UtcNow;

                await _context.SaveChangesAsync();

                _cacheManager.InvalidateCache(clinicId);

                _hubContext.Clients.All.updateStatus(clinicId, newStatus, clinicStatus.LastModifiedDate, lastModifiedByUserId);
                _emailService.SendEmailToAdmins(clinicId, newStatus);

                _logService.LogInformation($"Clinic {clinicId} status updated to {newStatus}");
            }
            catch (Exception ex)
            {
                _logService.LogError(ex, $"Failed to update clinic {clinicId} status");
                HttpContext.Current.Response.StatusCode = 500; // Internal Server Error
            }
        }
    }

    public void Dispose()
    {
        // Cleanup code if needed
    }
}

public class RateLimiter
{
    private readonly Dictionary<string, DateTime> _lastUpdateTimes = new Dictionary<string, DateTime>();

    public bool AllowUpdate(string ip)
    {
        lock (_lastUpdateTimes)
        {
            if (!_lastUpdateTimes.ContainsKey(ip))
            {
                _lastUpdateTimes[ip] = DateTime.UtcNow;
                return true;
            }

            var timeSinceLastUpdate = DateTime.UtcNow - _lastUpdateTimes[ip];
            if (timeSinceLastUpdate.TotalMinutes < 1 || timeSinceLastUpdate.TotalSeconds > 60)
            {
                _lastUpdateTimes[ip] = DateTime.UtcNow;
                return true;
            }

            return false;
        }
    }
}

