import hashlib
import requests
from tqdm import tqdm

def calculate_sha256(file_path=None, file_url=None):
    hash_obj = hashlib.sha256()
    if file_path:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hash_obj.update(chunk)
    elif file_url:
        response = requests.get(file_url, stream=True)
        total_size_in_bytes = int(response.headers.get('content-length', 0))
        progress_bar = tqdm(total=total_size_in_bytes // 1024 + 1, unit='KB')
        for data in response.iter_content(chunk_size=4096):
            hash_obj.update(data)
            progress_bar.update(len(data) // 1024)

    return hash_obj.hexdigest()

def verify_checksum(calculated_hash, expected_hash):
    if calculated_hash == expected_hash:
        return "Success: Hashes match"
    else:
        return f"Error: Hash mismatch. Expected {expected_hash}, got {calculated_hash}"
