const fs = require('fs');
const path = require('path');

async function executeModules(modules, callback) {
  try {
    for (const module of modules) {
      const filePath = path.join(__dirname, `modules/${module}.js`);
      if (!fs.existsSync(filePath)) {
        console.error(`Module ${module} not found.`);
        continue;
      }

      const moduleFunction = require(filePath);
      await moduleFunction();
    }

    callback(null, 'All modules executed successfully.');
  } catch (error) {
    callback(error, null);
  }
}

