import os
from PIL import Image
import requests

class ImageProcessor:
    def __init__(self, output_dir, quality=85):
        self.output_dir = output_dir
        self.quality = quality
        self.cache = {}

    def process_images(self, file_paths):
        for path in file_paths:
            try:
                with Image.open(path) as img:
                    processed_img = self.resize_and_compress(img)
                    output_path = os.path.join(self.output_dir, os.path.basename(path))
                    processed_img.save(output_path, "JPEG", quality=self.quality)
                    print(f"Processed: {path}")
            except Exception as e:
                print(f"Failed to process {path}: {e}")

    def resize_and_compress(self, img):
        max_size = (800, 800)
        return img.resize(max_size, Image.ANTIALIAS)

# Example usage
output_dir = "processed_images"
processor = ImageProcessor(output_dir)
file_paths = ["image1.jpg", "image2.png"]
processor.process_images(file_paths)
```

