import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

public class CommandExecutor {

    public static Map<String, String> safeCommandExecutor(String command[], File workingDir) throws IOException {
        Map<String, String> results = new HashMap<>();
        Process process = Runtime.getRuntime().exec(command, null, workingDir);

        // Delete file if it exists
        deleteIfFileExists(workingDir);

        StringBuilder outputBuffer = new StringBuilder();
        StringBuilder errorBuffer = new StringBuilder();

        try (BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8));
             BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream(), StandardCharsets.UTF_8))) {

            String line;
            while ((line = outputReader.readLine()) != null) {
                outputBuffer.append(line).append("\n");
            }

            while ((line = errorReader.readLine()) != null) {
                errorBuffer.append(line).append("\n");
            }
        } catch (IOException e) {
            results.put("error", "Failed to read streams: " + e.getMessage());
            return results;
        }

        try {
            int exitCode = process.waitFor();
            results.put("exitCode", String.valueOf(exitCode));
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            results.put("error", "Command execution interrupted");
            return results;
        }

        results.put("output", outputBuffer.toString());
        results.put("error", errorBuffer.toString());

        logTruncation(outputBuffer, results);
        logTruncation(errorBuffer, results);

        return results;
    }

    private static void deleteIfFileExists(File directory) {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (!file.delete()) {
                    System.err.println("Failed to delete file: " + file.getAbsolutePath());
                }
            }
        }
    }

    private static void logTruncation(StringBuilder buffer, Map<String, String> results) {
        int maxLength = 1024; // Example maximum length
        if (buffer.length() > maxLength) {
            results.put("truncated", "true");
            results.put("originalLength", String.valueOf(buffer.length()));
            results.put("actualLength", String.valueOf(maxLength));
            buffer.setLength(maxLength);
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        File workingDir = new File("/path/to/working/dir");
        String command[] = {"ls", "-l"};
        Map<String, String> results = safeCommandExecutor(command, workingDir);

        // Print results for demonstration
        System.out.println("Output: " + results.get("output"));
        System.out.println("Error: " + results.get("error"));
        System.out.println("Exit Code: " + results.get("exitCode"));
        if (results.containsKey("truncated")) {
            System.out.println("Truncation Detected");
        }
    }
}
```

This code snippet provides a basic implementation of the `safeCommandExecutor` function, which safely executes a command while handling output and error streams. It includes logging for truncation events and deletion of files in the working directory. The `main` method demonstrates how to use this function and print its results.

