```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_DATA_SIZE 1000000

int data[MAX_DATA_SIZE];
int data_size = 0;
pthread_mutex_t data_lock;
sem_t empty_slots, full_slots;

void* read_data(void* arg) {
    // Simulate reading data from a network stream or file
    for (int i = 0; i < MAX_DATA_SIZE; i++) {
        sem_wait(&empty_slots);
        pthread_mutex_lock(&data_lock);
        data[data_size++] = rand() % 1000;
        pthread_mutex_unlock(&data_lock);
        sem_post(&full_slots);
    }
    return NULL;
}

void* process_data(void* arg) {
    // Simulate processing data
    for (int i = 0; i < MAX_DATA_SIZE; i++) {
        sem_wait(&full_slots);
        pthread_mutex_lock(&data_lock);
        int value = data[--data_size];
        printf("Processing: %d\n", value);
        pthread_mutex_unlock(&data_lock);
        sem_post(&empty_slots);
    }
    return NULL;
}

int main() {
    pthread_t reader, processor;

    if (sem_init(&empty_slots, 0, MAX_DATA_SIZE) != 0 ||
        sem_init(&full_slots, 0, 0) != 0 ||
        pthread_mutex_init(&data_lock, NULL) != 0) {
        fprintf(stderr, "Error initializing synchronization primitives\n");
        return EXIT_FAILURE;
    }

    if (pthread_create(&reader, NULL, read_data, NULL) != 0 ||
        pthread_create(&processor, NULL, process_data, NULL) != 0) {
        fprintf(stderr, "Error creating threads\n");
        return EXIT_FAILURE;
    }

    pthread_join(reader, NULL);
    pthread_join(processor, NULL);

    sem_destroy(&empty_slots);
    sem_destroy(&full_slots);
    pthread_mutex_destroy(&data_lock);

    return EXIT_SUCCESS;
}
```

